export function toModelMessages(input: WithParts[], model: Provider.Model): ModelMessage[] {
  const result: UIMessage[] = []

  for (const msg of input) {
    if (msg.parts.length === 0) continue

    if (msg.info.role === "user") {
      const userMessage: UIMessage = {
        id: msg.info.id,
        role: "user",
        parts: [],
      }
      result.push(userMessage)
      for (const part of msg.parts) {
        if (part.type === "text" && !part.ignored)
          userMessage.parts.push({
            type: "text",
            text: part.text,
          })
        if (part.type === "file" && part.mime !== "text/plain" && part.mime !== "application/x-directory")
          userMessage.parts.push({
            type: "file",
            url: part.url,
            mediaType: part.mime,
            filename: part.filename,
          })

        if (part.type === "compaction") {
          userMessage.parts.push({
            type: "text",
            text: "What did we do so far?",
          })
        }
        if (part.type === "subtask") {
          userMessage.parts.push({
            type: "text",
            text: "The following tool was executed by the user",
          })
        }
      }
    }

    if (msg.info.role === "assistant") {
      const differentModel = `${model.providerID}/${model.id}` !== `${msg.info.providerID}/${msg.info.modelID}`

      if (
        msg.info.error &&
        !(
          MessageV2.AbortedError.isInstance(msg.info.error) &&
          msg.parts.some((part) => part.type !== "step-start" && part.type !== "reasoning")
        )
      ) {
        continue
      }
      const assistantMessage: UIMessage = {
        id: msg.info.id,
        role: "assistant",
        parts: [],
      }
      for (const part of msg.parts) {
        if (part.type === "text")
          assistantMessage.parts.push({
            type: "text",
            text: part.text,
            ...(differentModel ? {} : { providerMetadata: part.metadata }),
          })
        if (part.type === "step-start")
          assistantMessage.parts.push({
            type: "step-start",
          })
        if (part.type === "tool") {
          if (part.state.status === "completed") {
            if (part.state.attachments?.length) {
              result.push({
                id: Identifier.ascending("message"),
                role: "user",
                parts: [
                  {
                    type: "text",
                    text: `The tool ${part.tool} returned the following attachments:`,
                  },
                  ...part.state.attachments.map((attachment) => ({
                    type: "file" as const,
                    url: attachment.url,
                    mediaType: attachment.mime,
                    filename: attachment.filename,
                  })),
                ],
              })
            }
            assistantMessage.parts.push({
              type: ("tool-" + part.tool) as `tool-${string}`,
              state: "output-available",
              toolCallId: part.callID,
              input: part.state.input,
              output: part.state.time.compacted ? "[Old tool result content cleared]" : part.state.output,
              ...(differentModel ? {} : { callProviderMetadata: part.metadata }),
            })
          }
          if (part.state.status === "error")
            assistantMessage.parts.push({
              type: ("tool-" + part.tool) as `tool-${string}`,
              state: "output-error",
              toolCallId: part.callID,
              input: part.state.input,
              errorText: part.state.error,
              ...(differentModel ? {} : { callProviderMetadata: part.metadata }),
            })
          if (part.state.status === "pending" || part.state.status === "running")
            assistantMessage.parts.push({
              type: ("tool-" + part.tool) as `tool-${string}`,
              state: "output-error",
              toolCallId: part.callID,
              input: part.state.input,
              errorText: "[Tool execution was interrupted]",
              ...(differentModel ? {} : { callProviderMetadata: part.metadata }),
            })
        }
        if (part.type === "reasoning") {
          assistantMessage.parts.push({
            type: "reasoning",
            text: part.text,
            ...(differentModel ? {} : { providerMetadata: part.metadata }),
          })
        }
      }
      if (assistantMessage.parts.length > 0) {
        result.push(assistantMessage)
      }
    }
  }

  return convertToModelMessages(result.filter((msg) => msg.parts.some((part) => part.type !== "step-start")))
}

export const stream = fn(Identifier.schema("session"), async function* (sessionID) {
  const list = await Array.fromAsync(await Storage.list(["message", sessionID]))
  for (let i = list.length - 1; i >= 0; i--) {
    yield await get({
      sessionID,
      messageID: list[i][2],
    })
  }
})

export const parts = fn(Identifier.schema("message"), async (messageID) => {
  const result = [] as MessageV2.Part[]
  for (const item of await Storage.list(["part", messageID])) {
    const read = await Storage.read<MessageV2.Part>(item)
    result.push(read)
  }
  result.sort((a, b) => (a.id > b.id ? 1 : -1))
  return result
})

export const get = fn(
  z.object({
    sessionID: Identifier.schema("session"),
    messageID: Identifier.schema("message"),
  }),
  async (input) => {
    return {
      info: await Storage.read<MessageV2.Info>(["message", input.sessionID, input.messageID]),
      parts: await parts(input.messageID),
    }
  },
)

  export async function filterCompacted(stream: AsyncIterable<MessageV2.WithParts>) {
    const result = [] as MessageV2.WithParts[]
    const completed = new Set<string>()
    for await (const msg of stream) {
      result.push(msg)
      if (
        msg.info.role === "user" &&
        completed.has(msg.info.id) &&
        msg.parts.some((part) => part.type === "compaction")
      )
        break
      if (msg.info.role === "assistant" && msg.info.summary && msg.info.finish) completed.add(msg.info.parentID)
    }
    result.reverse()
    return result
  }

  export function fromError(e: unknown, ctx: { providerID: string }) {
    switch (true) {
      case e instanceof DOMException && e.name === "AbortError":
        return new MessageV2.AbortedError(
          { message: e.message },
          {
            cause: e,
          },
        ).toObject()
      case MessageV2.OutputLengthError.isInstance(e):
        return e
      case LoadAPIKeyError.isInstance(e):
        return new MessageV2.AuthError(
          {
            providerID: ctx.providerID,
            message: e.message,
          },
          { cause: e },
        ).toObject()
      case (e as SystemError)?.code === "ECONNRESET":
        return new MessageV2.APIError(
          {
            message: "Connection reset by server",
            isRetryable: true,
            metadata: {
              code: (e as SystemError).code ?? "",
              syscall: (e as SystemError).syscall ?? "",
              message: (e as SystemError).message ?? "",
            },
          },
          { cause: e },
        ).toObject()
      case APICallError.isInstance(e):
        const message = iife(() => {
          let msg = e.message
          if (msg === "") {
            if (e.responseBody) return e.responseBody
            if (e.statusCode) {
              const err = STATUS_CODES[e.statusCode]
              if (err) return err
            }
            return "Unknown error"
          }
          const transformed = ProviderTransform.error(ctx.providerID, e)
          if (transformed !== msg) {
            return transformed
          }
          if (!e.responseBody || (e.statusCode && msg !== STATUS_CODES[e.statusCode])) {
            return msg
          }

          try {
            const body = JSON.parse(e.responseBody)
            const errMsg = body.message || body.error || body.error?.message
            if (errMsg && typeof errMsg === "string") {
              return `${msg}: ${errMsg}`
            }
          } catch {}

          return `${msg}: ${e.responseBody}`
        }).trim()

        const metadata = e.url ? { url: e.url } : undefined
        return new MessageV2.APIError(
          {
            message,
            statusCode: e.statusCode,
            isRetryable: e.isRetryable,
            responseHeaders: e.responseHeaders,
            responseBody: e.responseBody,
            metadata,
          },
          { cause: e },
        ).toObject()
      case e instanceof Error:
        return new NamedError.Unknown({ message: e.toString() }, { cause: e }).toObject()
      default:
        return new NamedError.Unknown({ message: JSON.stringify(e) }, { cause: e })
    }
  }
}

import { BusEvent } from "@/bus/bus-event"
import { Bus } from "@/bus"
import z from "zod"
import { Storage } from "../storage/storage"
import { Config } from "../config/config"
import { resolveCredential } from "../connectors/credentials"
import { Log } from "../util/log"
import { Flag } from "../flag/flag"

const log = Log.create({ service: "todo-notifications" })

export namespace Todo {
  export const Info = z
    .object({
      content: z.string().describe("Brief description of the task"),
      status: z.string().describe("Current status of the task: pending, in_progress, completed, cancelled"),
      priority: z.string().describe("Priority level of the task: high, medium, low"),
      id: z.string().describe("Unique identifier for the todo item"),
    })
    .meta({ ref: "Todo" })
  export type Info = z.infer<typeof Info>

  export const Event = {
    Updated: BusEvent.define(
      "todo.updated",
      z.object({
        sessionID: z.string(),
        todos: z.array(Info),
        diff: z.object({
          added: z.array(Info),
          completed: z.array(Info),
        }),
      }),
    ),
  }

  function done(status: string) {
    return status === "completed" || status === "cancelled"
  }

  function diff(prev: Info[], next: Info[]) {
    const prevMap = new Map(prev.map((todo) => [todo.id, todo]))
    const added = next.filter((todo) => !prevMap.has(todo.id))
    const completed = next.filter((todo) => {
      if (!done(todo.status)) return false
      const old = prevMap.get(todo.id)
      if (!old) return false
      return !done(old.status)
    })
    return { added, completed }
  }

  export async function update(input: { sessionID: string; todos: Info[] }) {
    const prev = await get(input.sessionID)
    const change = diff(prev, input.todos)
    await Storage.write(["todo", input.sessionID], input.todos)
    Bus.publish(Event.Updated, { ...input, diff: change })
  }

  export async function get(sessionID: string) {
    return Storage.read<Info[]>(["todo", sessionID])
      .then((todo) => todo || [])
      .catch(() => [])
  }

  type ConnectorEntry = NonNullable<Config.Info["connectors"]>[string]

  function isConnector(entry: ConnectorEntry | undefined): entry is Config.Connector {
    return typeof entry === "object" && entry !== null && "type" in entry
  }

  function list(todos: Info[]) {
    return todos.map((todo) => `- ${todo.content} (${todo.priority})`).join("\n")
  }

  async function macos(title: string, body: string) {
    if (process.platform !== "darwin") return
    const escapedTitle = title.replace(/"/g, '\\"')
    const escapedBody = body.replace(/"/g, '\\"')
    await Bun.$`osascript -e 'display notification "${escapedBody}" with title "${escapedTitle}"'`.nothrow().quiet()
  }

  async function slack(config: Config.Info, message: string) {
    const settings = config.notifications?.todo
    if (!settings) return
    const cfg = settings.slack
    if (!cfg) return
    if (cfg.enabled === false) return

    const enabled = cfg.enabled ?? Flag.NIKCLI_SLACK_TASK_NOTIFICATIONS
    if (!enabled) return

    if (!cfg.connector) return
    const name = cfg.connector
    const channel = cfg.channel || Flag.NIKCLI_SLACK_CHANNEL
    if (!channel) return
    const connectors = config.connectors ?? {}
    const entry = connectors[name]
    if (!isConnector(entry)) return
    if (entry.enabled === false) return
    if (entry.type !== "slack") return

    const credential = await resolveCredential(name, entry)
    if (!credential) return
    const api = await import("../connectors/api/slack")
    await api.SlackApi.sendMessage(credential, channel, message).catch((error) => {
      const text = error instanceof Error ? error.message : String(error)
      log.error("failed to send Slack notification", { error: text })
    })
  }

  async function discord(config: Config.Info, message: string) {
    const settings = config.notifications?.todo
    if (!settings) return
    const cfg = settings.discord
    if (!cfg) return
    if (cfg.enabled === false) return

    const enabled = cfg.enabled ?? Flag.NIKCLI_DISCORD_TASK_NOTIFICATIONS
    if (!enabled) return
    const webhook = cfg.webhook || Flag.NIKCLI_DISCORD_WEBHOOK_URL
    if (!webhook) return

    await fetch(webhook, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ content: message }),
    }).catch((error) => {
      const text = error instanceof Error ? error.message : String(error)
      log.error("failed to send Discord notification", { error: text })
    })
  }

  async function notify(change: { added: Info[]; completed: Info[] }) {
    const config = await Config.get()
    const settings = config.notifications?.todo
    if (!settings) return
    if (settings.enabled === false) return

    const envEnabled =
      Flag.NIKCLI_TODO_NOTIFICATIONS || Flag.NIKCLI_SLACK_TASK_NOTIFICATIONS || Flag.NIKCLI_DISCORD_TASK_NOTIFICATIONS
    const enabled = settings.enabled ?? envEnabled
    if (!enabled) return

    const added = change.added
    const completed = change.completed
    if (added.length === 0 && completed.length === 0) return

    if (added.length > 0) {
      const title = added.length === 1 ? "New Todo Created" : `${added.length} New Todos`
      const body = added.length === 1 ? added[0].content : list(added)
      const slackMessage =
        added.length === 1 ? `New todo: ${added[0].content}` : `${added.length} new todos:\n${list(added)}`
      const discordMessage = slackMessage

      if (settings.macos !== false) {
        await macos(title, body).catch(() => {})
      }
      await slack(config, slackMessage)
      await discord(config, discordMessage)
    }

    if (completed.length > 0) {
      const title = completed.length === 1 ? "Todo Completed" : `${completed.length} Todos Completed`
      const body = completed.length === 1 ? completed[0].content : list(completed)
      const slackMessage =
        completed.length === 1
          ? `Completed: ${completed[0].content}`
          : `${completed.length} todos completed:\n${list(completed)}`
      const discordMessage = slackMessage

      if (settings.macos !== false) {
        await macos(title, body).catch(() => {})
      }
      await slack(config, slackMessage)
      await discord(config, discordMessage)
    }
  }

  export function init() {
    Bus.subscribe(Event.Updated, async (evt) => {
      await notify(evt.properties.diff)
    })
  }
}

import { BusEvent } from "@/bus/bus-event"
import { Bus } from "@/bus"
import { Instance } from "@/project/instance"
import z from "zod"

export namespace SessionStatus {
  export const Info = z
    .union([
      z.object({
        type: z.literal("idle"),
      }),
      z.object({
        type: z.literal("retry"),
        attempt: z.number(),
        message: z.string(),
        next: z.number(),
      }),
      z.object({
        type: z.literal("busy"),
      }),
    ])
    .meta({
      ref: "SessionStatus",
    })
  export type Info = z.infer<typeof Info>

  export const Event = {
    Status: BusEvent.define(
      "session.status",
      z.object({
        sessionID: z.string(),
        status: Info,
      }),
    ),
    // deprecated
    Idle: BusEvent.define(
      "session.idle",
      z.object({
        sessionID: z.string(),
      }),
    ),
  }

  const state = Instance.state(() => {
    const data: Record<string, Info> = {}
    return data
  })

  export function get(sessionID: string) {
    return (
      state()[sessionID] ?? {
        type: "idle",
      }
    )
  }

  export function list() {
    return state()
  }

  export function set(sessionID: string, status: Info) {
    Bus.publish(Event.Status, {
      sessionID,
      status,
    })
    if (status.type === "idle") {
      // deprecated
      Bus.publish(Event.Idle, {
        sessionID,
      })
      delete state()[sessionID]
      return
    }
    state()[sessionID] = status
  }
}

import { Bus } from "@/bus"
import { Config } from "@/config/config"
import { ulid } from "ulid"
import { Provider } from "@/provider/provider"
import { Session } from "@/session"
import { MessageV2 } from "@/session/message-v2"
import { Storage } from "@/storage/storage"
import { Log } from "@/util/log"
import type * as SDK from "@nikcli-ai/sdk/v2"

export namespace ShareNext {
  const log = Log.create({ service: "share-next" })

  async function url() {
    return Config.get().then((x) => x.enterprise?.url ?? "https://nikcli.store")
  }

  const disabled = process.env["NIKCLI_DISABLE_SHARE"] === "true" || process.env["NIKCLI_DISABLE_SHARE"] === "1"

  export async function init() {
    if (disabled) return
    Bus.subscribe(Session.Event.Updated, async (evt) => {
      await sync(evt.properties.info.id, [
        {
          type: "session",
          data: evt.properties.info,
        },
      ])
    })
    Bus.subscribe(MessageV2.Event.Updated, async (evt) => {
      await sync(evt.properties.info.sessionID, [
        {
          type: "message",
          data: evt.properties.info,
        },
      ])
      if (evt.properties.info.role === "user") {
        await sync(evt.properties.info.sessionID, [
          {
            type: "model",
            data: [
              await Provider.getModel(evt.properties.info.model.providerID, evt.properties.info.model.modelID).then(
                (m) => m,
              ),
            ],
          },
        ])
      }
    })
    Bus.subscribe(MessageV2.Event.PartUpdated, async (evt) => {
      await sync(evt.properties.part.sessionID, [
        {
          type: "part",
          data: evt.properties.part,
        },
      ])
    })
    Bus.subscribe(Session.Event.Diff, async (evt) => {
      await sync(evt.properties.sessionID, [
        {
          type: "session_diff",
          data: evt.properties.diff,
        },
      ])
    })
  }

  export async function create(sessionID: string) {
    if (disabled) return { id: "", url: "", secret: "" }
    log.info("creating share", { sessionID })
    const result = await fetch(`${await url()}/api/share`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ sessionID: sessionID }),
    })
      .then((x) => x.json())
      .then((x) => x as { id: string; url: string; secret: string })
    await Storage.write(["session_share", sessionID], result)
    fullSync(sessionID)
    return result
  }

  function get(sessionID: string) {
    return Storage.read<{
      id: string
      secret: string
      url: string
    }>(["session_share", sessionID])
  }

  type Data =
    | {
        type: "session"
        data: SDK.Session
      }
    | {
        type: "message"
        data: SDK.Message
      }
    | {
        type: "part"
        data: SDK.Part
      }
    | {
        type: "session_diff"
        data: SDK.FileDiff[]
      }
    | {
        type: "model"
        data: SDK.Model[]
      }

  const queue = new Map<string, { timeout: NodeJS.Timeout; data: Map<string, Data> }>()
  async function sync(sessionID: string, data: Data[]) {
    if (disabled) return
    const existing = queue.get(sessionID)
    if (existing) {
      for (const item of data) {
        existing.data.set("id" in item ? (item.id as string) : ulid(), item)
      }
      return
    }

    const dataMap = new Map<string, Data>()
    for (const item of data) {
      dataMap.set("id" in item ? (item.id as string) : ulid(), item)
    }

    const timeout = setTimeout(async () => {
      const queued = queue.get(sessionID)
      if (!queued) return
      queue.delete(sessionID)
      const share = await get(sessionID).catch(() => undefined)
      if (!share) return

      await fetch(`${await url()}/api/share/${share.id}/sync`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          secret: share.secret,
          data: Array.from(queued.data.values()),
        }),
      })
    }, 1000)
    queue.set(sessionID, { timeout, data: dataMap })
  }

  export async function remove(sessionID: string) {
    if (disabled) return
    log.info("removing share", { sessionID })
    const share = await get(sessionID)
    if (!share) return
    await fetch(`${await url()}/api/share/${share.id}`, {
      method: "DELETE",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        secret: share.secret,
      }),
    })
    await Storage.remove(["session_share", sessionID])
  }

  async function fullSync(sessionID: string) {
    log.info("full sync", { sessionID })
    const session = await Session.get(sessionID)
    const diffs = await Session.diff(sessionID)
    const messages = await Array.fromAsync(MessageV2.stream(sessionID))
    const models = await Promise.all(
      messages
        .filter((m) => m.info.role === "user")
        .map((m) => (m.info as SDK.UserMessage).model)
        .map((m) => Provider.getModel(m.providerID, m.modelID).then((m) => m)),
    )
    await sync(sessionID, [
      {
        type: "session",
        data: session,
      },
      ...messages.map((x) => ({
        type: "message" as const,
        data: x.info,
      })),
      ...messages.flatMap((x) => x.parts.map((y) => ({ type: "part" as const, data: y }))),
      {
        type: "session_diff",
        data: diffs,
      },
      {
        type: "model",
        data: models,
      },
    ])
  }
}

import { Bus } from "../bus"
import { Installation } from "../installation"
import { Session } from "../session"
import { MessageV2 } from "../session/message-v2"
import { Log } from "../util/log"

export namespace Share {
  const log = Log.create({ service: "share" })

  let queue: Promise<void> = Promise.resolve()
  const pending = new Map<string, any>()

  export async function sync(key: string, content: any) {
    if (disabled) return
    const [root, ...splits] = key.split("/")
    if (root !== "session") return
    const [sub, sessionID] = splits
    if (sub === "share") return
    const share = await Session.getShare(sessionID).catch(() => {})
    if (!share) return
    const { secret } = share
    pending.set(key, content)
    queue = queue
      .then(async () => {
        const content = pending.get(key)
        if (content === undefined) return
        pending.delete(key)

        return fetch(`${URL}/share_sync`, {
          method: "POST",
          body: JSON.stringify({
            sessionID: sessionID,
            secret,
            key: key,
            content,
          }),
        })
      })
      .then((x) => {
        if (x) {
          log.info("synced", {
            key: key,
            status: x.status,
          })
        }
      })
  }

  export function init() {
    Bus.subscribe(Session.Event.Updated, async (evt) => {
      await sync("session/info/" + evt.properties.info.id, evt.properties.info)
    })
    Bus.subscribe(MessageV2.Event.Updated, async (evt) => {
      await sync("session/message/" + evt.properties.info.sessionID + "/" + evt.properties.info.id, evt.properties.info)
    })
    Bus.subscribe(MessageV2.Event.PartUpdated, async (evt) => {
      await sync(
        "session/part/" +
          evt.properties.part.sessionID +
          "/" +
          evt.properties.part.messageID +
          "/" +
          evt.properties.part.id,
        evt.properties.part,
      )
    })
  }

  export const URL =
    process.env["NIKCLI_API"] ??
    (Installation.isPreview() || Installation.isLocal() ? "https://api.dev.nikcli.store" : "https://api.nikcli.store")

  const disabled = process.env["NIKCLI_DISABLE_SHARE"] === "true" || process.env["NIKCLI_DISABLE_SHARE"] === "1"

  export async function create(sessionID: string) {
    if (disabled) return { url: "", secret: "" }
    return fetch(`${URL}/share_create`, {
      method: "POST",
      body: JSON.stringify({ sessionID: sessionID }),
    })
      .then((x) => x.json())
      .then((x) => x as { url: string; secret: string })
  }

  export async function remove(sessionID: string, secret: string) {
    if (disabled) return {}
    return fetch(`${URL}/share_delete`, {
      method: "POST",
      body: JSON.stringify({ sessionID, secret }),
    }).then((x) => x.json())
  }
}

