  .command(SessionCommand)
  .command(RagModelCommand)
  .command(RemoteCommand)
  .fail((msg, err) => {
    if (
      msg?.startsWith("Unknown argument") ||
      msg?.startsWith("Not enough non-option arguments") ||
      msg?.startsWith("Invalid values:")
    ) {
      if (err) throw err
      cli.showHelp("log")
    }
    if (err) throw err
    process.exit(1)
  })
  .strict()

try {
  await cli.parse()
} catch (e) {
  let data: Record<string, any> = {}
  if (e instanceof NamedError) {
    const obj = e.toObject()
    Object.assign(data, {
      ...obj.data,
    })
  }

  if (e instanceof Error) {
    Object.assign(data, {
      name: e.name,
      message: e.message,
      cause: e.cause?.toString(),
      stack: e.stack,
    })
  }

  if (e instanceof ResolveMessage) {
    Object.assign(data, {
      name: e.name,
      message: e.message,
      code: e.code,
      specifier: e.specifier,
      referrer: e.referrer,
      position: e.position,
      importKind: e.importKind,
    })
  }
  Log.Default.error("fatal", data)
  const formatted = FormatError(e)
  if (formatted) UI.error(formatted)
  if (formatted === undefined) {
    UI.error("Unexpected error, check log file at " + Log.file() + " for more details" + EOL)
    console.error(e instanceof Error ? e.message : String(e))
  }
  process.exitCode = 1
} finally {
  // Some subprocesses don't react properly to SIGTERM and similar signals.
  // Most notably, some docker-container-based MCP servers don't handle such signals unless
  // run using `docker run --init`.
  // Explicitly exit to avoid any hanging subprocesses.
  process.exit()
}

import { Instance } from "../project/instance"

export namespace Env {
  const state = Instance.state(() => {
    return process.env as Record<string, string | undefined>
  })

  export function get(key: string) {
    const env = state()
    return env[key]
  }

  export function all() {
    return state()
  }

  export function set(key: string, value: string) {
    const env = state()
    env[key] = value
  }

  export function remove(key: string) {
    const env = state()
    delete env[key]
  }
}

import path from "path"
import z from "zod"
import { Tool } from "./tool"
import { Skill } from "../skill"
import { ConfigMarkdown } from "../config/markdown"
import { PermissionNext } from "../permission/next"

export const SkillTool = Tool.define("skill", async (ctx) => {
  const skills = await Skill.all()

  // Filter skills by agent permissions if agent provided
  const agent = ctx?.agent
  const accessibleSkills = agent
    ? skills.filter((skill) => {
        const rule = PermissionNext.evaluate("skill", skill.name, agent.permission)
        return rule.action !== "deny"
      })
    : skills

  const description =
    accessibleSkills.length === 0
      ? "Load a skill to get detailed instructions for a specific task. No skills are currently available."
      : [
          "Load a skill to get detailed instructions for a specific task.",
          "Skills provide specialized knowledge and step-by-step guidance.",
          "Use this when a task matches an available skill's description.",
          "Only the skills listed here are available:",
          "<available_skills>",
          ...accessibleSkills.flatMap((skill) => [
            `  <skill>`,
            `    <name>${skill.name}</name>`,
            `    <description>${skill.description}</description>`,
            `  </skill>`,
          ]),
          "</available_skills>",
        ].join(" ")

  const examples = accessibleSkills
    .map((skill) => `'${skill.name}'`)
    .slice(0, 3)
    .join(", ")
  const hint = examples.length > 0 ? ` (e.g., ${examples}, ...)` : ""

  const parameters = z.object({
    name: z.string().describe(`The skill identifier from available_skills${hint}`),
  })

  return {
    description,
    parameters,
    async execute(params: z.infer<typeof parameters>, ctx) {
      const skill = await Skill.get(params.name)

      if (!skill) {
        const available = await Skill.all().then((x) => Object.keys(x).join(", "))
        throw new Error(`Skill "${params.name}" not found. Available skills: ${available || "none"}`)
      }

      await ctx.ask({
        permission: "skill",
        patterns: [params.name],
        always: [params.name],
        metadata: {},
      })
      // Load and parse skill content
      const parsed = await ConfigMarkdown.parse(skill.location)
      const dir = path.dirname(skill.location)

      // Format output similar to plugin pattern
      const output = [`## Skill: ${skill.name}`, "", `**Base directory**: ${dir}`, "", parsed.content.trim()].join("\n")

      return {
        title: `Loaded skill: ${skill.name}`,
        output,
        metadata: {
          name: skill.name,
          dir,
        },
      }
    },
  }
})

import z from "zod"
import { Tool } from "./tool"
import DESCRIPTION from "./docs_load.txt"
import { loadDocs } from "@/docs/context"

const parameters = z.object({
  ids: z.array(z.string()).min(1).describe("Documentation IDs to load"),
})

export const DocsLoadTool = Tool.define("docs_load", {
  description: DESCRIPTION,
  parameters,
  async execute(params, ctx) {
    await ctx.ask({
      permission: "docs_load",
      patterns: params.ids,
      always: ["*"],
      metadata: {
        ids: params.ids,
      },
    })

    const result = await loadDocs(params.ids)
    const loaded = result.loaded.map((entry) => `- ${entry.title} (${entry.id})`)
    const missing = result.missing.map((id) => `- ${id}`)
    const output = [
      loaded.length > 0 ? `Loaded:\n${loaded.join("\n")}` : "No documents loaded.",
      missing.length > 0 ? `Missing:\n${missing.join("\n")}` : "",
    ]
      .filter(Boolean)
      .join("\n\n")

    return {
      title: "Docs loaded",
      output,
      metadata: {
        count: result.loaded.length,
      },
    }
  },
})

import z from "zod"
import { Tool } from "./tool"
import DESCRIPTION from "./docs_context.txt"
import { getContextSummary, getFullContext, getLoadedDocs } from "@/docs/context"

const parameters = z.object({
  full: z.boolean().optional().describe("Include full documentation content"),
})

export const DocsContextTool = Tool.define("docs_context", {
  description: DESCRIPTION,
  parameters,
  async execute(params, ctx) {
    await ctx.ask({
      permission: "docs_context",
      patterns: ["*"],
      always: ["*"],
      metadata: {
        full: params.full,
      },
    })

    const docs = await getLoadedDocs()
    if (docs.length === 0) {
      return {
        title: "Docs context",
        output: "No documentation loaded.",
        metadata: {
          count: 0,
        },
      }
    }

    const summary = await getContextSummary()
    if (!params.full) {
      return {
        title: "Docs context",
        output: summary,
        metadata: {
          count: docs.length,
        },
      }
    }

    const full = await getFullContext()
    const output = [summary, "", full].join("\n")

    return {
      title: "Docs context",
      output,
      metadata: {
        count: docs.length,
      },
    }
  },
})

import { Tool } from "./tool"
import DESCRIPTION from "./task.txt"
import z from "zod"
import { Session } from "../session"
import { Bus } from "../bus"
import { MessageV2 } from "../session/message-v2"
import { Identifier } from "../id/id"
import { Agent } from "../agent/agent"
import { SessionPrompt } from "../session/prompt"
import { iife } from "@/util/iife"
import { defer } from "@/util/defer"
import { Config } from "../config/config"
import { PermissionNext } from "@/permission/next"

const parameters = z.object({
  description: z.string().describe("A short (3-5 words) description of the task"),
  prompt: z.string().describe("The task for the agent to perform"),
  subagent_type: z.string().describe("The type of specialized agent to use for this task"),
  session_id: z.string().describe("Existing Task session to continue").optional(),
  command: z.string().describe("The command that triggered this task").optional(),
})

export type TaskParams = z.infer<typeof parameters>

export async function runSubtask(params: TaskParams, ctx: Tool.Context) {
  const config = await Config.get()
  const bypass = Boolean(ctx.extra?.bypassAgentCheck)

  if (!bypass) {
    await ctx.ask({
      permission: "task",
      patterns: [params.subagent_type],
      always: ["*"],
      metadata: {
        description: params.description,
        subagent_type: params.subagent_type,
      },
    })
  }

  const agent = await Agent.get(params.subagent_type)
  if (!agent) throw new Error(`Unknown agent type: ${params.subagent_type} is not a valid agent type`)

  const hasTaskPermission = agent.permission.some((rule) => rule.permission === "task")

  const session = await iife(async () => {
    if (params.session_id) {
      const found = await Session.get(params.session_id).catch(() => {})
      if (found) return found
    }

    return await Session.create({
      parentID: ctx.sessionID,
      title: params.description + ` (@${agent.name} subagent)`,
      permission: [
        {
          permission: "todowrite",
          pattern: "*",
          action: "deny",
        },
        {
          permission: "todoread",
          pattern: "*",
          action: "deny",
        },
        ...(hasTaskPermission
          ? []
          : [
              {
                permission: "task" as const,
                pattern: "*" as const,
                action: "deny" as const,
              },
            ]),
        ...(config.experimental?.primary_tools?.map((t) => ({
          pattern: "*",
          action: "allow" as const,
          permission: t,
        })) ?? []),
      ],
    })
  })

  const msg = await MessageV2.get({ sessionID: ctx.sessionID, messageID: ctx.messageID })
  if (msg.info.role !== "assistant") throw new Error("Not an assistant message")

  ctx.metadata({
    title: params.description,
    metadata: {
      sessionId: session.id,
    },
  })

  const messageID = Identifier.ascending("message")
  const parts: Record<string, { id: string; tool: string; state: { status: string; title?: string } }> = {}
  const unsub = Bus.subscribe(MessageV2.Event.PartUpdated, async (evt) => {
    if (evt.properties.part.sessionID !== session.id) return
    if (evt.properties.part.messageID === messageID) return
    if (evt.properties.part.type !== "tool") return
    const part = evt.properties.part
    parts[part.id] = {
      id: part.id,
      tool: part.tool,
      state: {
        status: part.state.status,
        title: part.state.status === "completed" ? part.state.title : undefined,
      },
    }
    ctx.metadata({
      title: params.description,
      metadata: {
        summary: Object.values(parts).sort((a, b) => a.id.localeCompare(b.id)),
        sessionId: session.id,
      },
    })
  })

  const model = agent.model ?? {
    modelID: msg.info.modelID,
    providerID: msg.info.providerID,
  }

  function cancel() {
    SessionPrompt.cancel(session.id)
  }
  ctx.abort.addEventListener("abort", cancel)
  using _ = defer(() => ctx.abort.removeEventListener("abort", cancel))
  const promptParts = await SessionPrompt.resolvePromptParts(params.prompt)

  const result = await SessionPrompt.prompt({
    messageID,
    sessionID: session.id,
    model: {
      modelID: model.modelID,
      providerID: model.providerID,
    },
    agent: agent.name,
    tools: {
      todowrite: false,
      todoread: false,
      ...(hasTaskPermission ? {} : { task: false }),
      ...Object.fromEntries((config.experimental?.primary_tools ?? []).map((t) => [t, false])),
    },
    parts: promptParts,
  })
  unsub()
  const messages = await Session.messages({ sessionID: session.id })
  const summary = messages
    .filter((x) => x.info.role === "assistant")
    .flatMap((msg) => msg.parts.filter((x: any) => x.type === "tool") as MessageV2.ToolPart[])
    .map((part) => ({
      id: part.id,
      tool: part.tool,
      state: {
        status: part.state.status,
        title: part.state.status === "completed" ? part.state.title : undefined,
      },
    }))
  const text = result.parts.findLast((x) => x.type === "text")?.text ?? ""

  const output = text + "\n\n" + ["<task_metadata>", `session_id: ${session.id}`, "</task_metadata>"].join("\n")

  return {
    title: params.description,
    metadata: {
      summary,
      sessionId: session.id,
    },
    output,
  }
}

export const TaskTool = Tool.define("task", async (ctx) => {
  const agents = await Agent.list().then((x) => x.filter((a) => a.mode !== "primary"))

  const caller = ctx?.agent
  const accessibleAgents = caller
    ? agents.filter((a) => PermissionNext.evaluate("task", a.name, caller.permission).action !== "deny")
    : agents

  const description = DESCRIPTION.replace(
    "{agents}",
    accessibleAgents
      .map((a) => `- ${a.name}: ${a.description ?? "This subagent should only be called manually by the user."}`)
      .join("\n"),
  )
  return {
    description,
    parameters,
    async execute(params: z.infer<typeof parameters>, ctx) {
      return runSubtask(params, ctx)
    },
  }
})

import z from "zod"
import path from "path"
import { readdir, stat } from "fs/promises"
import { Tool } from "./tool"
import DESCRIPTION from "./tree.txt"
import { Instance } from "@/project/instance"
import { assertExternalDirectory } from "./external-directory"
import { IGNORE_PATTERNS } from "./ls"

type TreeNode = {
  name: string
  path: string
  isDirectory: boolean
  size: number
  depth: number
  children?: TreeNode[]
}

type TreeStats = {
  files: number
  directories: number
  size: number
  maxDepth: number
}

const TREE_CHARS = {
  branch: "├── ",
  last: "└── ",
  pipe: "│   ",
  space: "    ",
}

const parameters = z.object({
  path: z.string().optional(),
  maxDepth: z.number().int().min(0).optional(),
  showHidden: z.boolean().optional(),
  showSize: z.boolean().optional(),
  showFullPath: z.boolean().optional(),
  ignorePatterns: z.array(z.string()).optional(),
  onlyDirectories: z.boolean().optional(),
  sortBy: z.enum(["name", "size", "type"]).optional(),
})

export const TreeTool = Tool.define<typeof parameters, { stats: TreeStats }>("tree", {
  description: DESCRIPTION,
  parameters,
  async execute(params, ctx) {
    const base = params.path ? path.resolve(Instance.directory, params.path) : Instance.directory
    const maxDepth = params.maxDepth ?? 5
    const showHidden = params.showHidden ?? false
    const showSize = params.showSize ?? true
    const showFullPath = params.showFullPath ?? false
    await assertExternalDirectory(ctx, base, { kind: "directory" })

    await ctx.ask({
      permission: "tree",
      patterns: [base],
      always: ["*"],
      metadata: {
        path: base,
        maxDepth,
      },
    })

    const result = await buildTree({
      root: base,
      depth: 0,
      maxDepth,
      params: {
        showHidden,
        showSize,
        showFullPath,
        ignorePatterns: params.ignorePatterns ?? [],
        onlyDirectories: params.onlyDirectories ?? false,
        sortBy: params.sortBy ?? "name",
      },
    })

    const formatted = formatTree(result.node, "", true, showSize)
    const label = showFullPath ? base : path.relative(Instance.directory, base) || "."
    const summary = `${result.stats.directories} directories, ${result.stats.files} files, ${formatSize(result.stats.size)}`
    const output = [label, formatted, "", summary].filter(Boolean).join("\n")

    return {
      title: path.relative(Instance.worktree, base),
      output,
      metadata: {
        stats: result.stats,
      },
    }
  },
})

async function buildTree(input: {
  root: string
  depth: number
  maxDepth: number
  params: {
    showHidden: boolean
    showSize: boolean
    showFullPath: boolean
    ignorePatterns: string[]
    onlyDirectories: boolean
    sortBy: "name" | "size" | "type"
  }
}): Promise<{ node: TreeNode; stats: TreeStats }> {
  const info = await stat(input.root)
  const node: TreeNode = {
    name: path.basename(input.root),
    path: input.root,
    isDirectory: info.isDirectory(),
    size: info.size,
    depth: input.depth,
  }

  const baseStats: TreeStats = {
    files: node.isDirectory ? 0 : 1,
    directories: node.isDirectory ? 1 : 0,
    size: node.size,
    maxDepth: input.depth,
  }

  if (!node.isDirectory) return { node, stats: baseStats }
  if (input.depth >= input.maxDepth) return { node, stats: baseStats }

  const entries = await readdir(input.root)
  const filtered = entries.filter((entry) => {
    if (!input.params.showHidden && entry.startsWith(".")) return false
    const full = path.join(input.root, entry)
    const rel = path.relative(Instance.directory, full)
    return !shouldIgnore(rel, input.params.ignorePatterns)
  })

  const children = await Promise.all(
    filtered.map(async (entry) => {
      const full = path.join(input.root, entry)
      try {
        return await buildTree({
          root: full,
          depth: input.depth + 1,
          maxDepth: input.maxDepth,
          params: input.params,
        })
      } catch {
        return null
      }
    }),
  )

  const nodes = children.filter((item): item is { node: TreeNode; stats: TreeStats } => Boolean(item))
  const listed = input.params.onlyDirectories ? nodes.filter((item) => item.node.isDirectory) : nodes
  const sorted = sortNodes(listed, input.params.sortBy)
  const stats = sorted.reduce((acc, item) => {
    return {
      files: acc.files + item.stats.files,
      directories: acc.directories + item.stats.directories,
      size: acc.size + item.stats.size,
      maxDepth: Math.max(acc.maxDepth, item.stats.maxDepth),
    }
  }, baseStats)

  return {
    node: {
      ...node,
      children: sorted.map((item) => item.node),
    },
    stats,
  }
}

function sortNodes(items: Array<{ node: TreeNode; stats: TreeStats }>, sortBy: "name" | "size" | "type") {
  const sorted = [...items].sort((a, b) => {
    if (a.node.isDirectory !== b.node.isDirectory) return a.node.isDirectory ? -1 : 1
    if (sortBy === "size") return b.node.size - a.node.size
    if (sortBy === "type") return path.extname(a.node.name).localeCompare(path.extname(b.node.name))
    return a.node.name.localeCompare(b.node.name)
  })
  return sorted
}

function formatTree(node: TreeNode, prefix: string, isLast: boolean, showSize: boolean): string {
  const lines: string[] = []
  if (node.depth > 0) {
    const connector = isLast ? TREE_CHARS.last : TREE_CHARS.branch
    const sizeInfo = showSize && !node.isDirectory ? ` ${formatSize(node.size)}` : ""
    lines.push(`${prefix}${connector}${node.name}${sizeInfo}`)
  }

  if (!node.children) return lines.join("\n")
  const childPrefix = node.depth > 0 ? prefix + (isLast ? TREE_CHARS.space : TREE_CHARS.pipe) : ""
  const rendered = node.children.map((child, index) => {
    const lastChild = index === node.children!.length - 1
    return formatTree(child, childPrefix, lastChild, showSize)
  })
  return [...lines, ...rendered].filter(Boolean).join("\n")
}

function formatSize(bytes: number): string {
  if (bytes === 0) return "0 B"
  const base = 1024

  const units = ["B", "KB", "MB", "GB"]
  const index = Math.floor(Math.log(bytes) / Math.log(base))
  const value = bytes / base ** index
  return `${value.toFixed(1)} ${units[index]}`
}

function shouldIgnore(relPath: string, extra: string[]): boolean {
  const all = [...IGNORE_PATTERNS, ...extra]
  const lower = relPath.toLowerCase()
  return all.some((pattern) => {
    if (pattern.endsWith("/")) return lower.includes(pattern.toLowerCase())
    if (pattern.includes("*")) {
      const regex = new RegExp(pattern.replace(/\*/g, ".*"))
      return regex.test(lower)
    }
    return lower.includes(pattern.toLowerCase())
  })
}

import z from "zod"
import path from "path"
import { Tool } from "./tool"
import { Question } from "../question"
import { Session } from "../session"
import { MessageV2 } from "../session/message-v2"
import { Identifier } from "../id/id"
import { Provider } from "../provider/provider"
import { Instance } from "../project/instance"
import EXIT_DESCRIPTION from "./plan-exit.txt"
import ENTER_DESCRIPTION from "./plan-enter.txt"

async function getLastModel(sessionID: string) {
  for await (const item of MessageV2.stream(sessionID)) {
    if (item.info.role === "user" && item.info.model) return item.info.model
  }
  return Provider.defaultModel()
}

export const PlanExitTool = Tool.define("plan_exit", {
  description: EXIT_DESCRIPTION,
  parameters: z.object({}),
  async execute(_params, ctx) {
    const session = await Session.get(ctx.sessionID)
    const plan = path.relative(Instance.worktree, Session.plan(session))
    const answers = await Question.ask({
      sessionID: ctx.sessionID,
      questions: [
        {
          question: `Plan at ${plan} is complete. Would you like to switch to the build agent and start implementing?`,
          header: "Build Agent",
          custom: false,
          options: [
            { label: "Yes", description: "Switch to build agent and start implementing the plan" },
            { label: "No", description: "Stay with plan agent to continue refining the plan" },
          ],
        },
      ],
      tool: ctx.callID ? { messageID: ctx.messageID, callID: ctx.callID } : undefined,
    })

    const answer = answers[0]?.[0]
    if (answer === "No") throw new Question.RejectedError()

    const model = await getLastModel(ctx.sessionID)

    const userMsg: MessageV2.User = {
      id: Identifier.ascending("message"),
      sessionID: ctx.sessionID,
      role: "user",
      time: {
        created: Date.now(),
      },
      agent: "build",
      model,
    }
    await Session.updateMessage(userMsg)
    await Session.updatePart({
      id: Identifier.ascending("part"),
      messageID: userMsg.id,
      sessionID: ctx.sessionID,
      type: "text",
      text: `The plan at ${plan} has been approved, you can now edit files. Execute the plan`,
      synthetic: true,
    } satisfies MessageV2.TextPart)

    return {
      title: "Switching to build agent",
      output: "User approved switching to build agent. Wait for further instructions.",
      metadata: {},
    }
  },
})

export const PlanEnterTool = Tool.define("plan_enter", {
  description: ENTER_DESCRIPTION,
  parameters: z.object({}),
  async execute(_params, ctx) {
    const session = await Session.get(ctx.sessionID)
    const plan = path.relative(Instance.worktree, Session.plan(session))

    const answers = await Question.ask({
      sessionID: ctx.sessionID,
      questions: [
        {
          question: `Would you like to switch to the plan agent and create a plan saved to ${plan}?`,
          header: "Plan Mode",
          custom: false,
          options: [
            { label: "Yes", description: "Switch to plan agent for research and planning" },
            { label: "No", description: "Stay with build agent to continue making changes" },
          ],
        },
      ],
      tool: ctx.callID ? { messageID: ctx.messageID, callID: ctx.callID } : undefined,
    })

    const answer = answers[0]?.[0]

    if (answer === "No") throw new Question.RejectedError()

    const model = await getLastModel(ctx.sessionID)

    const userMsg: MessageV2.User = {
      id: Identifier.ascending("message"),
      sessionID: ctx.sessionID,
      role: "user",
      time: {
        created: Date.now(),
      },
      agent: "plan",
      model,
    }
    await Session.updateMessage(userMsg)
    await Session.updatePart({
      id: Identifier.ascending("part"),
      messageID: userMsg.id,
      sessionID: ctx.sessionID,
      type: "text",
      text: "User has requested to enter plan mode. Switch to plan mode and begin planning.",
      synthetic: true,
    } satisfies MessageV2.TextPart)

    return {
      title: "Switching to plan agent",
      output: `User confirmed to switch to plan mode. A new message has been created to switch you to plan mode. The plan file will be at ${plan}. Begin planning.`,
      metadata: {},
    }
  },
})

import z from "zod"
import { Tool } from "./tool"
import DESCRIPTION from "./subagents.txt"
import { Agent } from "@/agent/agent"
import { runSubtask } from "./task"

const parameters = z.object({
  agent: z.string().optional(),
  prompt: z.string().optional(),
  context: z.record(z.string(), z.unknown()).optional(),
  listAll: z.boolean().optional(),
})

type SubagentsMetadata = {
  summary?: Array<{ id: string; tool: string; state: { status: string; title?: string } }>
  sessionId?: string
  agent?: string
  tools?: string[]
  count?: number
}

function formatTools(items: string[]): string {
  if (items.length === 0) return "all"
  return items.join(", ")
}

function buildPrompt(prompt: string, context: Record<string, unknown> | undefined): string {
  if (!context) return prompt
  const payload = JSON.stringify(context, null, 2)
  return `Context:\n${payload}\n\nUser Task: ${prompt}`
}

export const SubagentsTool = Tool.define<typeof parameters, SubagentsMetadata>("subagents", {
  description: DESCRIPTION,
  parameters,
  async execute(params, ctx) {
    await ctx.ask({
      permission: "subagents",
      patterns: [params.agent ?? "*"],
      always: ["*"],
      metadata: {
        agent: params.agent,
        listAll: params.listAll,
        hasPrompt: Boolean(params.prompt),
      },
    })

    if (params.prompt) {
      if (!params.agent) throw new Error("subagents requires 'agent' when 'prompt' is provided")
      const prompt = buildPrompt(params.prompt, params.context)
      const description = `Subagent ${params.agent}`
      return runSubtask(
        {
          description,
          prompt,
          subagent_type: params.agent,
        },
        ctx,
      )
    }

    const agents = await Agent.list().then((items) => items.filter((item) => item.mode !== "primary"))
    const requested = params.agent?.trim()
    if (requested) {
      const agent = agents.find((item) => item.name === requested)
      if (!agent) throw new Error(`Subagent '${requested}' not found`)
      const tools = Agent.SUBAGENT_TOOLSETS[agent.name] ?? []
      const output = [
        `name: ${agent.name}`,
        `mode: ${agent.mode}`,
        `description: ${agent.description ?? ""}`,
        `tools: ${formatTools(tools)}`,
      ].join("\n")
      return {
        title: agent.name,
        output,
        metadata: {
          agent: agent.name,
          tools,
        },
      }
    }

    const visible = params.listAll ? agents : agents.filter((item) => !item.hidden)
    const lines = visible.map((agent) => {
      const tools = Agent.SUBAGENT_TOOLSETS[agent.name] ?? []
      const desc = agent.description ?? ""
      return `- ${agent.name}: ${desc} (tools: ${formatTools(tools)})`
    })
    const output = lines.length > 0 ? lines.join("\n") : "No subagents available"
    return {
      title: `Subagents (${visible.length})`,
      output,
      metadata: {
        count: visible.length,
      },
    }
  },
})

import z from "zod"
import * as path from "path"
import { Tool } from "./tool"
import { LSP } from "../lsp"
import { createTwoFilesPatch } from "diff"
import DESCRIPTION from "./write.txt"
import { Bus } from "../bus"
import { File } from "../file"
import { FileTime } from "../file/time"
import { Filesystem } from "../util/filesystem"
import { Instance } from "../project/instance"
import { trimDiff } from "./edit"
import { assertExternalDirectory } from "./external-directory"

const MAX_DIAGNOSTICS_PER_FILE = 20
const MAX_PROJECT_DIAGNOSTICS_FILES = 5

export const WriteTool = Tool.define("write", {
  description: DESCRIPTION,
  parameters: z.object({
    content: z.string().describe("The content to write to the file"),
    filePath: z.string().describe("The absolute path to the file to write (must be absolute, not relative)"),
  }),
  async execute(params, ctx) {
    const filepath = path.isAbsolute(params.filePath) ? params.filePath : path.join(Instance.directory, params.filePath)
    await assertExternalDirectory(ctx, filepath)

    const file = Bun.file(filepath)
    const exists = await file.exists()
    const contentOld = exists ? await file.text() : ""
    if (exists) await FileTime.assert(ctx.sessionID, filepath)

    const diff = trimDiff(createTwoFilesPatch(filepath, filepath, contentOld, params.content))
    await ctx.ask({
      permission: "edit",
      patterns: [path.relative(Instance.worktree, filepath)],
      always: ["*"],
      metadata: {
        filepath,
        diff,
      },
    })

    await Bun.write(filepath, params.content)
    await Bus.publish(File.Event.Edited, {
      file: filepath,
    })
    FileTime.read(ctx.sessionID, filepath)

    let output = "Wrote file successfully."
    await LSP.touchFile(filepath, true)
    const diagnostics = await LSP.diagnostics()
    const normalizedFilepath = Filesystem.normalizePath(filepath)
    let projectDiagnosticsCount = 0
    for (const [file, issues] of Object.entries(diagnostics)) {
      const errors = issues.filter((item) => item.severity === 1)
      if (errors.length === 0) continue
      const limited = errors.slice(0, MAX_DIAGNOSTICS_PER_FILE)
      const suffix =
        errors.length > MAX_DIAGNOSTICS_PER_FILE ? `\n... and ${errors.length - MAX_DIAGNOSTICS_PER_FILE} more` : ""
      if (file === normalizedFilepath) {
        output += `\n\nLSP errors detected in this file, please fix:\n<diagnostics file="${filepath}">\n${limited.map(LSP.Diagnostic.pretty).join("\n")}${suffix}\n</diagnostics>`
        continue
      }
      if (projectDiagnosticsCount >= MAX_PROJECT_DIAGNOSTICS_FILES) continue
      projectDiagnosticsCount++
      output += `\n\nLSP errors detected in other files:\n<diagnostics file="${file}">\n${limited.map(LSP.Diagnostic.pretty).join("\n")}${suffix}\n</diagnostics>`
    }

    return {
      title: path.relative(Instance.worktree, filepath),
      metadata: {
        diagnostics,
        filepath,
        exists: exists,
      },
      output,
    }
  },
})

import z from "zod"
import path from "path"
import { Tool } from "./tool"
import DESCRIPTION from "./context_diagnostics.txt"
import { LSP } from "@/lsp"
import { Instance } from "@/project/instance"
import { assertExternalDirectory } from "./external-directory"

const parameters = z.object({
  filePath: z.string().optional().describe("Optional file path to filter diagnostics"),
  limit: z.number().int().min(1).max(200).optional().describe("Maximum diagnostics per file"),
})

export const ContextDiagnosticsTool = Tool.define<typeof parameters, { count: number }>("context_diagnostics", {
  description: DESCRIPTION,
  parameters,
  async execute(params, ctx) {
    const limit = params.limit ?? 50

    await ctx.ask({
      permission: "context_diagnostics",
      patterns: [params.filePath ?? "*"],
      always: ["*"],
      metadata: {
        filePath: params.filePath,
        limit,
      },
    })

    if (params.filePath) {
      const target = path.isAbsolute(params.filePath)
        ? params.filePath
        : path.resolve(Instance.directory, params.filePath)
      await assertExternalDirectory(ctx, target, { kind: "file" })
      await LSP.touchFile(target, true)

      const all = await LSP.diagnostics()
      const issues = all[target] ?? []
      if (issues.length === 0) {
        return {
          title: path.relative(Instance.worktree, target),
          output: "No diagnostics found.",
          metadata: { count: 0 },
        }
      }

      const output = issues
        .slice(0, limit)
        .map((item) => LSP.Diagnostic.pretty(item))
        .join("\n")
      return {
        title: path.relative(Instance.worktree, target),
        output,
        metadata: { count: issues.length },
      }
    }

    const diagnostics = await LSP.diagnostics()
    const entries = Object.entries(diagnostics).filter(([, issues]) => issues.length > 0)
    if (entries.length === 0) {
      return {
        title: "Diagnostics",
        output: "No diagnostics found.",
        metadata: { count: 0 },
      }
    }

    const lines: string[] = []
    for (const [file, issues] of entries) {
      lines.push(`${file}:`)
      lines.push(...issues.slice(0, limit).map((item) => `  ${LSP.Diagnostic.pretty(item)}`))
      lines.push("")
    }

    return {
      title: "Diagnostics",
      output: lines.join("\n").trim(),
      metadata: { count: entries.length },
    }
  },
})

import z from "zod"
import * as path from "path"
import * as fs from "fs/promises"
import { Tool } from "./tool"
import { Bus } from "../bus"
import { FileWatcher } from "../file/watcher"
import { Instance } from "../project/instance"
import { Patch } from "../patch"
import { createTwoFilesPatch, diffLines } from "diff"
import { assertExternalDirectory } from "./external-directory"
import { trimDiff } from "./edit"
import { LSP } from "../lsp"
import { Filesystem } from "../util/filesystem"
import DESCRIPTION from "./apply_patch.txt"
import { File } from "../file"
import { isDBFile, readDBSchema } from "./db-diff"

const PatchParams = z.object({
  patchText: z.string().describe("The full patch text that describes all changes to be made"),
})

export const ApplyPatchTool = Tool.define("apply_patch", {
  description: DESCRIPTION,
  parameters: PatchParams,
  async execute(params, ctx) {
    if (!params.patchText) {
      throw new Error("patchText is required")
    }

    // Parse the patch to get hunks
    let hunks: Patch.Hunk[]
    try {
      const parseResult = Patch.parsePatch(params.patchText)
      hunks = parseResult.hunks
    } catch (error) {
      throw new Error(`apply_patch verification failed: ${error}`)
    }

    if (hunks.length === 0) {
      const normalized = params.patchText.replace(/\r\n/g, "\n").replace(/\r/g, "\n").trim()
      if (normalized === "*** Begin Patch\n*** End Patch") {
        throw new Error("patch rejected: empty patch")
      }
      throw new Error("apply_patch verification failed: no hunks found")
    }

    // Validate file paths and check permissions
    const fileChanges: Array<{
      filePath: string
      oldContent: string
      newContent: string
      type: "add" | "update" | "delete" | "move"
      movePath?: string
      diff: string
      additions: number
      deletions: number
    }> = []

    let totalDiff = ""

    for (const hunk of hunks) {
      const filePath = path.resolve(Instance.directory, hunk.path)
      await assertExternalDirectory(ctx, filePath)

      switch (hunk.type) {
        case "add": {
          const oldContent = ""
          const newContent =
            hunk.contents.length === 0 || hunk.contents.endsWith("\n") ? hunk.contents : `${hunk.contents}\n`
          const diff = trimDiff(createTwoFilesPatch(filePath, filePath, oldContent, newContent))

          let additions = 0
          let deletions = 0
          for (const change of diffLines(oldContent, newContent)) {
            if (change.added) additions += change.count || 0
            if (change.removed) deletions += change.count || 0
          }

          fileChanges.push({
            filePath,
            oldContent,
            newContent,
            type: "add",
            diff,
            additions,
            deletions,
          })

          totalDiff += diff + "\n"
          break
        }

        case "update": {
          // Check if file exists for update
          const stats = await fs.stat(filePath).catch(() => null)
          if (!stats || stats.isDirectory()) {
            throw new Error(`apply_patch verification failed: Failed to read file to update: ${filePath}`)
          }

          const oldContent = await fs.readFile(filePath, "utf-8")
          let newContent = oldContent

          // Apply the update chunks to get new content
          try {
            const fileUpdate = Patch.deriveNewContentsFromChunks(filePath, hunk.chunks)
            newContent = fileUpdate.content
          } catch (error) {
            throw new Error(`apply_patch verification failed: ${error}`)
          }

          const diff = trimDiff(createTwoFilesPatch(filePath, filePath, oldContent, newContent))

          let additions = 0
          let deletions = 0
          for (const change of diffLines(oldContent, newContent)) {
            if (change.added) additions += change.count || 0
            if (change.removed) deletions += change.count || 0
          }

          const movePath = hunk.move_path ? path.resolve(Instance.directory, hunk.move_path) : undefined
          await assertExternalDirectory(ctx, movePath)

          fileChanges.push({
            filePath,
            oldContent,
            newContent,
            type: hunk.move_path ? "move" : "update",
            movePath,
            diff,
            additions,
            deletions,
          })

          totalDiff += diff + "\n"
          break
        }

        case "delete": {
          const contentToDelete = await fs.readFile(filePath, "utf-8").catch((error) => {
            throw new Error(`apply_patch verification failed: ${error}`)
          })
          const deleteDiff = trimDiff(createTwoFilesPatch(filePath, filePath, contentToDelete, ""))

          const deletions = contentToDelete.split("\n").length

          fileChanges.push({
            filePath,
            oldContent: contentToDelete,
            newContent: "",
            type: "delete",
            diff: deleteDiff,
            additions: 0,
            deletions,
          })

          totalDiff += deleteDiff + "\n"
          break
        }
      }
    }

    // Check permissions if needed
    await ctx.ask({
      permission: "edit",
      patterns: fileChanges.map((c) => path.relative(Instance.worktree, c.filePath)),
      always: ["*"],
      metadata: {
        diff: totalDiff,
      },
    })

    // Apply the changes
    const changedFiles: string[] = []

    for (const change of fileChanges) {
      const edited = change.type === "delete" ? undefined : (change.movePath ?? change.filePath)
      switch (change.type) {
        case "add":
          // Create parent directories (recursive: true is safe on existing/root dirs)
          await fs.mkdir(path.dirname(change.filePath), { recursive: true })
          await fs.writeFile(change.filePath, change.newContent, "utf-8")
          changedFiles.push(change.filePath)
          break

        case "update":
          await fs.writeFile(change.filePath, change.newContent, "utf-8")
          changedFiles.push(change.filePath)
          break

        case "move":
          if (change.movePath) {
            // Create parent directories (recursive: true is safe on existing/root dirs)
            await fs.mkdir(path.dirname(change.movePath), { recursive: true })
            await fs.writeFile(change.movePath, change.newContent, "utf-8")
            await fs.unlink(change.filePath)
            changedFiles.push(change.movePath)
          }
          break

        case "delete":

          await fs.unlink(change.filePath)
          changedFiles.push(change.filePath)
          break
      }

      if (edited) {
        await Bus.publish(File.Event.Edited, {
          file: edited,
        })
      }
    }

    // Publish file change events
    for (const filePath of changedFiles) {
      await Bus.publish(FileWatcher.Event.Updated, { file: filePath, event: "change" })
    }

    // Notify LSP of file changes and collect diagnostics
    for (const change of fileChanges) {
      if (change.type === "delete") continue
      const target = change.movePath ?? change.filePath
      await LSP.touchFile(target, true)
    }
    const diagnostics = await LSP.diagnostics()

    // Generate output summary
    const summaryLines = fileChanges.map((change) => {
      if (change.type === "add") {
        return `A ${path.relative(Instance.worktree, change.filePath)}`
      }
      if (change.type === "delete") {
        return `D ${path.relative(Instance.worktree, change.filePath)}`
      }
      const target = change.movePath ?? change.filePath
      return `M ${path.relative(Instance.worktree, target)}`
    })
    let output = `Success. Updated the following files:\n${summaryLines.join("\n")}`

    // Report LSP errors for changed files
    const MAX_DIAGNOSTICS_PER_FILE = 20
    for (const change of fileChanges) {
      if (change.type === "delete") continue
      const target = change.movePath ?? change.filePath
      const normalized = Filesystem.normalizePath(target)
      const issues = diagnostics[normalized] ?? []
      const errors = issues.filter((item) => item.severity === 1)
      if (errors.length > 0) {
        const limited = errors.slice(0, MAX_DIAGNOSTICS_PER_FILE)
        const suffix =
          errors.length > MAX_DIAGNOSTICS_PER_FILE ? `\n... and ${errors.length - MAX_DIAGNOSTICS_PER_FILE} more` : ""
        output += `\n\nLSP errors detected in ${path.relative(Instance.worktree, target)}, please fix:\n<diagnostics file="${target}">\n${limited.map(LSP.Diagnostic.pretty).join("\n")}${suffix}\n</diagnostics>`
      }
    }

    // Build per-file metadata for UI rendering
    const files = await Promise.all(
      fileChanges.map(async (change) => {
        const targetPath = change.movePath ?? change.filePath
        const isDb = isDBFile(targetPath)
        const dbSchema = isDb ? await readDBSchema(targetPath) : null

        return {
          filePath: change.filePath,
          relativePath: path.relative(Instance.worktree, targetPath),
          type: change.type,
          diff: change.diff,
          before: change.oldContent,
          after: change.newContent,
          additions: change.additions,
          deletions: change.deletions,
          movePath: change.movePath,
          isDB: isDb,
          dbSchema,
        }
      }),
    )

    return {
      title: output,
      metadata: {
        diff: totalDiff,
        files,
        diagnostics,
      },
      output,
    }
  },
})

import z from "zod"
import { Tool } from "./tool"
import DESCRIPTION from "./docs_search.txt"
import { searchDocs } from "@/docs/library"

const parameters = z.object({
  query: z.string().describe("Search query"),
  category: z.string().optional().describe("Optional category filter"),
  limit: z.number().int().min(1).max(20).optional().describe("Result limit"),
})

export const DocsSearchTool = Tool.define("docs_search", {
  description: DESCRIPTION,
  parameters,
  async execute(params, ctx) {
    await ctx.ask({
      permission: "docs_search",
      patterns: [params.query],
      always: ["*"],
      metadata: {
        query: params.query,
        category: params.category,
      },
    })

    const results = await searchDocs(params.query, params.category, params.limit ?? 5)
    if (results.length === 0) {
      return {
        title: `Docs search: ${params.query}`,
        output: "No documentation matches found.",
        metadata: {
          count: 0,
        },
      }
    }

    const lines = results.map((result) => {
      const score = result.score.toFixed(2)
      return `- ${result.entry.title} (id: ${result.entry.id}, score: ${score})`
    })
    const output = lines.join("\n")

    return {
      title: `Docs search: ${params.query}`,
      output,
      metadata: {
        count: results.length,
      },
    }
  },
})

