export const SmartDocsTool = Tool.define("smart_docs", {
  description: DESCRIPTION,
  parameters,
  async execute(params, ctx) {
    const limit = params.limit ?? 5
    const autoLoad = params.autoLoad ?? true

    await ctx.ask({
      permission: "smart_docs",
      patterns: [params.query],
