import { Tool } from "./tool"
import { Config } from "../config/config"
import { executeOperation } from "../connectors/registry"
import { listConnectorTypes, getConnectorSpec } from "../connectors/registry"
import { invalidateConnectorCache } from "../connectors/cache"
import z from "zod"

const allOperations = listConnectorTypes().flatMap((type) => {
  const spec = getConnectorSpec(type)
  return spec?.operations.map((op) => op.name) ?? []
})

export const UseConnectorTool = Tool.define("use_connector", async () => {
  return {
    description: "Execute operations on external services (Figma, Slack, GitHub, Lovable)",
    parameters: z.object({
      connector: z.string().describe("Connector name"),
      operation: z.enum(allOperations as [string, ...string[]]).describe("Operation to perform"),
      args: z.record(z.string(), z.any()).describe("Operation arguments"),
    }),
    async execute({ connector, operation, args }) {
      const config = await Config.get()
      const connectorConfig = config.connectors?.[connector]

      if (!connectorConfig || typeof connectorConfig !== "object" || !("type" in connectorConfig)) {
        throw new Error(`Connector "${connector}" not found`)
      }

      try {
        const result = await executeOperation(connector, connectorConfig, operation, args)

        return {
          title: `${connector} ${operation}`,
          metadata: {},
          output: typeof result === "string" ? result : JSON.stringify(result, null, 2),
        }
      } catch (error) {
        invalidateConnectorCache(connector)

        if (error instanceof Error) {
          throw new Error(`${connector} ${operation} failed: ${error.message}`)
        }
        throw new Error(`${connector} ${operation} failed: ${String(error)}`)
      }
    },
  }
})

import path from "path"
import type { Tool } from "./tool"
import { Instance } from "../project/instance"

type Kind = "file" | "directory"

type Options = {
  bypass?: boolean
  kind?: Kind
}

export async function assertExternalDirectory(ctx: Tool.Context, target?: string, options?: Options) {
  if (!target) return

  if (options?.bypass) return

  if (Instance.containsPath(target)) return

  const kind = options?.kind ?? "file"
  const parentDir = kind === "directory" ? target : path.dirname(target)
  const glob = path.join(parentDir, "*")

  await ctx.ask({
    permission: "external_directory",
    patterns: [glob],
    always: [glob],
    metadata: {
      filepath: target,
      parentDir,
    },
  })
}

import * as fs from "fs/promises"
import * as path from "path"
import { detectDBType, DB_EXTENSIONS } from "../cli/cmd/tui/component/table-db/db/types"
import { tableRenderer } from "../cli/cmd/tui/component/table-db/ui/table-renderer"
import type { DBSchema, DBTable, DBColumn, DBForeignKey, TableChange } from "../cli/cmd/tui/component/table-db/db/types"

const DB_EXTENSIONS_LIST = Object.values(DB_EXTENSIONS).flat()

export function isDBFile(filePath: string): boolean {
  const ext = path.extname(filePath).toLowerCase()
  return DB_EXTENSIONS_LIST.includes(ext) || ext === ".sql"
}

export async function readDBSchema(filePath: string): Promise<DBSchema | null> {
  try {
    const bunSqlite = require("bun:sqlite")
    const db = new bunSqlite.Database(filePath)

    const tables: DBTable[] = []
    const sqliteMaster = db
      .prepare(
        `
      SELECT name, sql FROM sqlite_master 
      WHERE type='table' AND name NOT LIKE 'sqlite_%'
      ORDER BY name
    `,
      )
      .all() as Array<{ name: string; sql: string | null }>

    for (const row of sqliteMaster) {
      const tableName = row.name
      const columns = db.prepare(`PRAGMA table_info('${tableName}')`).all() as Array<{
        name: string
        type: string
        notnull: number
        dflt_value: string | null
        pk: number
      }>

      const primaryKey = columns.filter((c) => c.pk > 0).map((c) => c.name)
      const rowCount = db.prepare(`SELECT COUNT(*) as count FROM '${tableName}'`).get() as { count: number } | undefined

      tables.push({
        name: tableName,
        columns: columns.map((c) => ({
          name: c.name,
          type: c.type || "TEXT",
          notNull: c.notnull > 0,
          defaultValue: c.dflt_value ?? undefined,
          primaryKey: c.pk > 0,
        })),
        primaryKey,
        rowCount: rowCount?.count ?? 0,
        sql: row.sql ?? undefined,
      })
    }

    db.close()
    return { tables, views: [], indexes: [] }
  } catch {
    return null
  }
}

export async function generateDBDiff(
  filePath: string,
  newContent?: string,
): Promise<{ schema: DBSchema | null; diff: string; changes: TableChange[] } | null> {
  if (!isDBFile(filePath)) return null

  const oldSchema = await readDBSchema(filePath)

  let newSchema: DBSchema | null = null
  let changes: TableChange[] = []

  if (newContent) {
    if (filePath.endsWith(".sql") || filePath.endsWith(".prisma")) {
      newSchema = await createDBSchemaFromSQL(newContent)
    }
  } else if (oldSchema) {
    newSchema = oldSchema
  }

  if (!oldSchema && !newSchema) {
    return { schema: null, diff: "", changes: [] }
  }

  const schema = oldSchema ?? newSchema!

  if (oldSchema && newSchema) {
    changes = calculateTableChanges(oldSchema.tables, newSchema.tables)
  }

  const diff = oldSchema ? tableRenderer.renderSchemaOverview(oldSchema.tables) : ""

  return { schema, diff, changes }
}

function calculateTableChanges(oldTables: DBTable[], newTables: DBTable[]): TableChange[] {
  const changes: TableChange[] = []
  const oldTableNames = new Set(oldTables.map((t) => t.name))
  const newTableNames = new Set(newTables.map((t) => t.name))

  for (const newTable of newTables) {
    const oldTable = oldTables.find((t) => t.name === newTable.name)

    if (!oldTable) {
      changes.push({ type: "add_table", tableName: newTable.name })

      for (const col of newTable.columns) {
        changes.push({
          type: "add_column",
          tableName: newTable.name,
          columnName: col.name,
          newDefinition: col,
        })
      }
    } else {
      const oldColumns = new Set(oldTable.columns.map((c) => c.name))
      const newColumns = new Set(newTable.columns.map((c) => c.name))

      for (const col of newTable.columns) {
        if (!oldColumns.has(col.name)) {
          changes.push({
            type: "add_column",
            tableName: newTable.name,
            columnName: col.name,
            newDefinition: col,
          })
        }
      }

      for (const oldCol of oldTable.columns) {
        if (!newColumns.has(oldCol.name)) {
          changes.push({
            type: "drop_column",
            tableName: newTable.name,
            columnName: oldCol.name,
            oldDefinition: oldCol,
          })
        }
      }
    }
  }

  for (const oldTable of oldTables) {
    if (!newTableNames.has(oldTable.name)) {
      changes.push({ type: "drop_table", tableName: oldTable.name })
    }
  }

  return changes
}

export async function createDBSchemaFromSQL(sqlContent: string): Promise<DBSchema> {
  const tables: DBTable[] = []

  const createTableRegex = /CREATE\s+TABLE\s+["`]?(\w+)["`]?\s*\(\s*([^;]*)\s*\)/gi
  let match

  while ((match = createTableRegex.exec(sqlContent)) !== null) {
    const tableName = match[1]
    const columnsDef = match[2]
    const { columns, foreignKeys } = parseColumnsFromDefinition(columnsDef, tableName)
    tables.push({
      name: tableName,
      columns,
      primaryKey: columns.filter((c) => c.primaryKey).map((c) => c.name),
      foreignKeys,
    })
  }

  if (tables.length === 0) {
    const prismaModels = parsePrismaSchema(sqlContent)
    for (const model of prismaModels) {
      tables.push({
        name: model.name,
        columns: model.columns,
        primaryKey: model.columns.filter((c) => c.primaryKey).map((c) => c.name),
        foreignKeys: model.foreignKeys,
      })
    }
  }

  return { tables, views: [], indexes: [] }
}

function parseColumnsFromDefinition(
  columnsDef: string,
  tableName: string,
): { columns: DBColumn[]; foreignKeys: DBForeignKey[] } {
  const columns: DBColumn[] = []
  const foreignKeys: DBForeignKey[] = []

  if (!columnsDef.trim()) {
    return { columns, foreignKeys }
  }

  const columnLines = columnsDef.split(",")

  for (const line of columnLines) {
    const trimmed = line.trim()
    if (!trimmed) continue

    const colMatch = trimmed.match(/^["`]?(\w+)["`]?\s+(\w+)(?:\([^)]+\))?/i)
    if (colMatch) {
      const colName = colMatch[1]
      const colType = colMatch[2].toUpperCase()
      const isNotNull = trimmed.toUpperCase().includes("NOT NULL")
      const isPk = trimmed.toUpperCase().includes("PRIMARY KEY")

      const defaultMatch = trimmed.match(/DEFAULT\s+(?:'([^']*)'|"([^"]*)"|(\S+))/i)
      const defaultValue = defaultMatch ? defaultMatch[1] || defaultMatch[2] || defaultMatch[3] : undefined

      columns.push({
        name: colName,
        type: colType,
        notNull: isNotNull,
        primaryKey: isPk,
        defaultValue,
      })

      const fkMatch = trimmed.match(
        /REFERENCES\s+["`]?(\w+)["`]?\s*\(\s*["`]?(\w+)["`]?\s*\)(?:\s+ON\s+DELETE\s+(\w+(?:\s+\w+)?))?/i,
      )
      if (fkMatch) {
        const refTable = fkMatch[1]
        const refColumn = fkMatch[2]
        const onDeleteStr = fkMatch[3]?.toUpperCase().replace(/\s+/g, " ") || "NO ACTION"
        const onDelete =
          onDeleteStr === "CASCADE"
            ? "CASCADE"
            : onDeleteStr === "RESTRICT"
              ? "RESTRICT"
              : onDeleteStr === "SET NULL"
                ? "SET NULL"
                : "NO ACTION"

        foreignKeys.push({
          table: tableName,
          column: colName,
          referencedTable: refTable,
          referencedColumn: refColumn,
          onDelete,
        })
      }
    }
  }

  return { columns, foreignKeys }
}

interface PrismaModel {
  name: string
  columns: DBColumn[]
  foreignKeys: DBForeignKey[]
}

function parsePrismaSchema(content: string): PrismaModel[] {
  const models: PrismaModel[] = []
  const relations: Array<{
    fromModel: string
    fromField: string
    toModel: string
    toField: string
    onDelete?: "CASCADE" | "RESTRICT" | "SET NULL" | "NO ACTION"
  }> = []

  const modelRegex = /model\s+(\w+)\s*\{([^}]+)\}/gi
  let match

  while ((match = modelRegex.exec(content)) !== null) {
    const modelName = match[1]
    const body = match[2]
    const columns: DBColumn[] = []

    const lines = body.split("\n")
    for (const line of lines) {
      const trimmed = line.trim()
      if (!trimmed || trimmed.startsWith("//")) continue

      if (trimmed.startsWith("@@")) {
        const tableLevelMatch = trimmed.match(/@@\s*(\w+)(?:\([^)]+\))?/)
        if (tableLevelMatch) {
          if (tableLevelMatch[1] === "id") {
            const idFields = extractFieldsFromAttribute(trimmed)
            for (const field of idFields) {
              const col = columns.find((c) => c.name === field)
              if (col) col.primaryKey = true
            }
          } else if (tableLevelMatch[1] === "unique") {
            const uniqueFields = extractFieldsFromAttribute(trimmed)
            for (const field of uniqueFields) {
              const col = columns.find((c) => c.name === field)
              if (col) col.defaultValue = "(unique)"
            }
          }
        }
        continue
      }

      const fieldMatch = trimmed.match(/^(\w+)\s+(\w+(?:\[\])?)(?:\??)(?:\s+@.*)?$/)
      if (fieldMatch) {
        const name = fieldMatch[1]
        const originalType = fieldMatch[2]
        let type = originalType.toUpperCase()
        const isArray = type.includes("[]")
        type = type.replace("[]", "")

        const isId = trimmed.includes("@id")
        const hasDefault = trimmed.includes("@default")
        const isOptional = trimmed.includes("?")

        const relationMatch = trimmed.match(/@relation\("([^"]+)"\)/)
        const relationName = relationMatch?.[1]

        const fieldsMatch = trimmed.match(/fields\s*[:=]\s*\[([^\]]+)\]/i)
        const relationParts = relationName ? relationName.split(",").map((s) => s.trim()) : []

        columns.push({
          name,
          type: mapPrismaType(type),
          notNull: !isOptional || hasDefault || isArray,
          primaryKey: isId,
          defaultValue: hasDefault ? "(default)" : undefined,
        })

        if (relationName && !relationName.includes("fields=") && !relationName.includes("fields:")) {
          const toModel = relationParts.find((p: string) => p.startsWith("to="))?.slice(3) || originalType
          const toField = relationParts.find((p: string) => p.startsWith("references="))?.slice(11) || "id"
          const onDeleteStr = relationParts.find((p: string) => p.startsWith("onDelete="))?.slice(9) || "NO ACTION"
          const onDelete = mapOnDeleteAction(onDeleteStr)

          relations.push({
            fromModel: modelName,
            fromField: name,
            toModel,
            toField,
            onDelete,
          })
        }

        if (fieldsMatch && !isArray) {
          const referencedModel = originalType
          const referencedField = relationParts.find((p: string) => p.startsWith("references="))?.slice(11) || "id"
          const onDeleteStr = relationParts.find((p: string) => p.startsWith("onDelete="))?.slice(9) || "NO ACTION"
          const onDelete = mapOnDeleteAction(onDeleteStr)

          const fkFieldName = fieldsMatch[1].split(",")[0].trim()
          relations.push({
            fromModel: modelName,
            fromField: fkFieldName,
            toModel: referencedModel,
            toField: referencedField,
            onDelete,
          })
        }
      }
    }

    models.push({ name: modelName, columns, foreignKeys: [] })
  }

  for (const rel of relations) {
    const fromModel = models.find((m) => m.name === rel.fromModel)
    if (fromModel) {
      fromModel.foreignKeys.push({
        table: rel.fromModel,
        column: rel.fromField,
        referencedTable: rel.toModel,
        referencedColumn: rel.toField,
        onDelete: rel.onDelete || "NO ACTION",
      })
    }
  }

  return models
}

function extractFieldsFromAttribute(attr: string): string[] {
  const match = attr.match(/\(([^)]+)\)/)
  if (!match) return []
  return match[1].split(",").map((s) => s.trim().replace(/[\[\]"]/g, ""))
}

function mapOnDeleteAction(action: string): "CASCADE" | "RESTRICT" | "SET NULL" | "NO ACTION" {
  switch (action.toUpperCase()) {
    case "CASCADE":
      return "CASCADE"
    case "RESTRICT":
      return "RESTRICT"
    case "SET NULL":
      return "SET NULL"
    default:
      return "NO ACTION"
  }
}

function mapPrismaType(prismaType: string): string {
  const typeMap: Record<string, string> = {

import z from "zod"
import { Tool } from "./tool"
import TurndownService from "turndown"
import DESCRIPTION from "./webfetch.txt"

const MAX_RESPONSE_SIZE = 5 * 1024 * 1024 // 5MB
const DEFAULT_TIMEOUT = 30 * 1000 // 30 seconds
const MAX_TIMEOUT = 120 * 1000 // 2 minutes

export const WebFetchTool = Tool.define("webfetch", {
  description: DESCRIPTION,
  parameters: z.object({
    url: z.string().describe("The URL to fetch content from"),
    format: z
      .enum(["text", "markdown", "html"])
      .default("markdown")
      .describe("The format to return the content in (text, markdown, or html). Defaults to markdown."),
    timeout: z.number().describe("Optional timeout in seconds (max 120)").optional(),
  }),
  async execute(params, ctx) {
    // Validate URL
    if (!params.url.startsWith("http://") && !params.url.startsWith("https://")) {
      throw new Error("URL must start with http:// or https://")
    }

    await ctx.ask({
      permission: "webfetch",
      patterns: [params.url],
      always: ["*"],
      metadata: {
        url: params.url,
        format: params.format,
        timeout: params.timeout,
      },
    })

    const timeout = Math.min((params.timeout ?? DEFAULT_TIMEOUT / 1000) * 1000, MAX_TIMEOUT)

    const controller = new AbortController()
    const timeoutId = setTimeout(() => controller.abort(), timeout)

    // Build Accept header based on requested format with q parameters for fallbacks
    let acceptHeader = "*/*"
    switch (params.format) {
      case "markdown":
        acceptHeader = "text/markdown;q=1.0, text/x-markdown;q=0.9, text/plain;q=0.8, text/html;q=0.7, */*;q=0.1"
        break
      case "text":
        acceptHeader = "text/plain;q=1.0, text/markdown;q=0.9, text/html;q=0.8, */*;q=0.1"
        break
      case "html":
        acceptHeader = "text/html;q=1.0, application/xhtml+xml;q=0.9, text/plain;q=0.8, text/markdown;q=0.7, */*;q=0.1"
        break
      default:
        acceptHeader =
          "text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,image/apng,*/*;q=0.8"
    }

    const response = await fetch(params.url, {
      signal: AbortSignal.any([controller.signal, ctx.abort]),
      headers: {
        "User-Agent":
          "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/143.0.0.0 Safari/537.36",
        Accept: acceptHeader,
        "Accept-Language": "en-US,en;q=0.9",
      },
    })

    clearTimeout(timeoutId)

    if (!response.ok) {
      throw new Error(`Request failed with status code: ${response.status}`)
    }

    // Check content length
    const contentLength = response.headers.get("content-length")
    if (contentLength && parseInt(contentLength) > MAX_RESPONSE_SIZE) {
      throw new Error("Response too large (exceeds 5MB limit)")
    }

    const arrayBuffer = await response.arrayBuffer()
    if (arrayBuffer.byteLength > MAX_RESPONSE_SIZE) {
      throw new Error("Response too large (exceeds 5MB limit)")
    }

    const content = new TextDecoder().decode(arrayBuffer)
    const contentType = response.headers.get("content-type") || ""

    const title = `${params.url} (${contentType})`

    // Handle content based on requested format and actual content type
    switch (params.format) {
      case "markdown":
        if (contentType.includes("text/html")) {
          const markdown = convertHTMLToMarkdown(content)
          return {
            output: markdown,
            title,
            metadata: {},
          }
        }
        return {
          output: content,
          title,
          metadata: {},
        }

      case "text":
        if (contentType.includes("text/html")) {
          const text = await extractTextFromHTML(content)
          return {
            output: text,
            title,
            metadata: {},
          }
        }
        return {
          output: content,
          title,
          metadata: {},
        }

      case "html":
        return {
          output: content,
          title,
          metadata: {},
        }

      default:
        return {
          output: content,
          title,
          metadata: {},
        }
    }
  },
})

async function extractTextFromHTML(html: string) {
  let text = ""
  let skipContent = false

  const rewriter = new HTMLRewriter()
    .on("script, style, noscript, iframe, object, embed", {
      element() {
        skipContent = true
      },
      text() {
        // Skip text content inside these elements
      },
    })
    .on("*", {
      element(element) {
        // Reset skip flag when entering other elements
        if (!["script", "style", "noscript", "iframe", "object", "embed"].includes(element.tagName)) {
          skipContent = false
        }
      },
      text(input) {
        if (!skipContent) {
          text += input.text
        }
      },
    })
    .transform(new Response(html))

  await rewriter.text()
  return text.trim()
}

function convertHTMLToMarkdown(html: string): string {
  const turndownService = new TurndownService({
    headingStyle: "atx",
    hr: "---",
    bulletListMarker: "-",
    codeBlockStyle: "fenced",
    emDelimiter: "*",
  })
  turndownService.remove(["script", "style", "meta", "link"])
  return turndownService.turndown(html)
}

import z from "zod"
import path from "path"
import { pathToFileURL } from "url"
import { Tool } from "./tool"
import DESCRIPTION from "./context_collect.txt"
import { Instance } from "@/project/instance"
import { Ripgrep } from "@/file/ripgrep"
import { assertExternalDirectory } from "./external-directory"
import { FileIgnore } from "@/file/ignore"
import { LSP } from "@/lsp"

const parameters = z.object({
  paths: z.array(z.string()).optional().describe("Files or directories to include"),
  pattern: z.string().optional().describe("Optional regex filter for lines"),
  maxFiles: z.number().int().min(1).max(100).optional().describe("Maximum files to collect"),
  maxLines: z.number().int().min(1).max(2000).optional().describe("Maximum lines per file"),
  includeSymbols: z.boolean().optional().describe("Include LSP symbols for files"),
  includeDiagnostics: z.boolean().optional().describe("Include LSP diagnostics for files"),
})

export const ContextCollectTool = Tool.define<typeof parameters, { count: number; truncated: boolean }>(
  "context_collect",
  {
    description: DESCRIPTION,
    parameters,
    async execute(params, ctx) {
      const roots = params.paths?.length ? params.paths : [Instance.directory]
      const limitFiles = params.maxFiles ?? 20
      const limitLines = params.maxLines ?? 200
      const includeSymbols = params.includeSymbols ?? false
      const includeDiagnostics = params.includeDiagnostics ?? false
      const resolved = roots.map((item) => (path.isAbsolute(item) ? item : path.resolve(Instance.directory, item)))
      const regex = params.pattern ? new RegExp(params.pattern) : undefined

      await ctx.ask({
        permission: "context_collect",
        patterns: resolved,
        always: ["*"],
        metadata: {
          paths: resolved,
          pattern: params.pattern,
          maxFiles: limitFiles,
          maxLines: limitLines,
        },
      })

      for (const item of resolved) {
        const info = await Bun.file(item)
          .stat()
          .catch(() => undefined)
        const kind = info && info.isDirectory() ? "directory" : "file"
        await assertExternalDirectory(ctx, item, { kind })
      }

      const files = await collectFiles(resolved, limitFiles)
      const diagnostics = includeDiagnostics ? await LSP.diagnostics() : undefined
      const lines: string[] = []

      if (files.length === 0) {
        return {
          title: "Context collect",
          output: "No files found.",
          metadata: {
            count: 0,
            truncated: false,
          },
        }
      }

      lines.push(`Collected ${files.length} files`)

      for (const file of files) {
        const rel = path.relative(Instance.directory, file) || file
        const body = await readSnippet(file, limitLines, regex)
        const snippet = body || "(no matching content)"
        lines.push("")
        lines.push(`file: ${rel}`)
        lines.push(snippet)

        if (includeSymbols) {
          const symbols = await collectSymbols(file)
          if (symbols.length > 0) {
            lines.push("")
            lines.push("symbols:")
            lines.push(...symbols.map((item) => `- ${item}`))
          }
        }

        if (includeDiagnostics && diagnostics) {
          const issues = diagnostics[file] ?? []
          if (issues.length > 0) {
            lines.push("")
            lines.push("diagnostics:")
            lines.push(...issues.slice(0, 10).map((item) => `- ${LSP.Diagnostic.pretty(item)}`))
          }
        }
      }

      return {
        title: "Context collect",
        output: lines.join("\n"),
        metadata: {
          count: files.length,
          truncated: files.length >= limitFiles,
        },
      }
    },
  },
)

async function collectFiles(roots: string[], limit: number) {
  const files: string[] = []
  for (const root of roots) {
    if (files.length >= limit) break
    const info = await Bun.file(root)
      .stat()
      .catch(() => undefined)
    if (!info) continue
    if (info.isFile()) {
      files.push(root)
      continue
    }
    if (!info.isDirectory()) continue

    for await (const entry of Ripgrep.files({ cwd: root })) {
      if (files.length >= limit) break
      const full = path.join(root, entry)
      const rel = path.relative(Instance.directory, full)
      if (FileIgnore.match(rel)) continue
      files.push(full)
    }
  }
  return files
}

async function readSnippet(filePath: string, limit: number, regex?: RegExp) {
  const file = Bun.file(filePath)
  if (file.type.startsWith("image/") || file.type === "application/pdf") {
    return ""
  }
  const text = await file.text().catch(() => "")
  if (!text) return ""
  const lines = text.split("\n")
  const filtered = regex ? lines.filter((line) => regex.test(line)) : lines
  return filtered.slice(0, limit).join("\n")
}

async function collectSymbols(filePath: string) {
  const uri = pathToFileURL(filePath).href
  const symbols = await LSP.documentSymbol(uri).catch(() => [])
  return symbols.map((item) => item.name).slice(0, 20)
}

import z from "zod"
import { Tool } from "./tool"
import DESCRIPTION from "./rag_status.txt"
import { Rag } from "@/rag"

const parameters = z.object({})

export const RagStatusTool = Tool.define("rag_status", {
  description: DESCRIPTION,
  parameters,
  async execute(_params, ctx) {
    await ctx.ask({
      permission: "rag_status",
      patterns: ["*"],
      always: ["*"],
      metadata: {},
    })

    const status = await Rag.status()
    if (!status.ready) {
      return {
        title: "RAG status",
        output: `No RAG index found at ${status.path}`,
        metadata: { ready: false },
      }
    }

    const state = status.state
    const output = [
      `Index path: ${status.path}`,
      state?.model ? `Model: ${state.model}` : "",
      state?.files !== undefined ? `Files: ${state.files}` : "",
      state?.chunks !== undefined ? `Chunks: ${state.chunks}` : "",
      state?.updated ? `Updated: ${new Date(state.updated).toISOString()}` : "",
    ]
      .filter(Boolean)
      .join("\n")

    return {
      title: "RAG status",
      output,
      metadata: { ready: true },
    }
  },
})

