export namespace DBEditNext {
  const log = Log.create({ service: "dbedit" })

  export const Request = z
    .object({
      id: Identifier.schema("dbedit"),
      sessionID: Identifier.schema("session"),
      type: z.enum(["db_create", "db_edit", "db_query"]),
      filePath: z.string(),
      schema: z
        .object({
          tables: z.array(
            z.object({
              name: z.string(),
              columns: z.array(
                z.object({
                  name: z.string(),
                  type: z.string(),
                  notNull: z.boolean(),
                  defaultValue: z.string().optional(),
                  primaryKey: z.boolean(),
                }),
              ),
              primaryKey: z.string().array(),
              foreignKeys: z
                .array(
                  z.object({
                    table: z.string(),
                    column: z.string(),
                    referencedTable: z.string(),
                    referencedColumn: z.string(),
                    onDelete: z.enum(["CASCADE", "RESTRICT", "SET NULL", "NO ACTION"]),
                  }),
                )
                .optional(),
              rowCount: z.number().optional(),
              sql: z.string().optional(),
            }),
          ),
          views: z
            .array(
              z.object({
                name: z.string(),
                sql: z.string(),
              }),
            )
            .optional(),
          indexes: z
            .array(
              z.object({
                name: z.string(),
                tableName: z.string(),
                columns: z.string().array(),
                unique: z.boolean(),
              }),
            )
            .optional(),
        })
        .optional(),
      preview: z
        .array(
          z.object({
            tableName: z.string(),
            columns: z.array(
              z.object({
                name: z.string(),
                type: z.string(),
                notNull: z.boolean(),
                defaultValue: z.string().optional(),
                primaryKey: z.boolean(),
              }),
            ),
            sampleData: z.array(z.record(z.string(), z.any())),
            rowCount: z.number(),
          }),
        )
        .optional(),
      changes: z
        .array(
          z.object({
            type: z.enum(["add_table", "drop_table", "add_column", "drop_column", "modify_column"]),
            tableName: z.string(),
            columnName: z.string().optional(),
            oldDefinition: z
              .object({
                name: z.string(),
                type: z.string(),
                notNull: z.boolean(),
                defaultValue: z.string().optional(),
                primaryKey: z.boolean(),
              })
              .optional(),
            newDefinition: z
              .object({
                name: z.string(),
                type: z.string(),
                notNull: z.boolean(),
                defaultValue: z.string().optional(),
                primaryKey: z.boolean(),
              })
              .optional(),
          }),
        )
        .optional(),
      sql: z.string().optional(),
      always: z.string().array(),
      tool: z
        .object({
          messageID: z.string(),
          callID: z.string(),
        })
        .optional(),
    })
    .meta({
      ref: "DBEditRequest",
    })

  export type Request = DBEditRequest

  export const Reply = z.enum(["accept", "edit", "reject"])
  export type Reply = z.infer<typeof Reply>

  export const Event = {
    Asked: BusEvent.define("dbedit.asked", Request),
    Replied: BusEvent.define(
      "dbedit.replied",
      z.object({
        sessionID: z.string(),
        requestID: z.string(),
        reply: Reply,
      }),
    ),
  }

  const state = Instance.state(async () => {
    const projectID = Instance.project.id
    return {
      pending: {} as Record<
        string,
        {
          info: Request
          resolve: (modified?: Request) => void
          reject: (e: any) => void
        }
      >,
    }
  })

  export const ask = fn(Request.partial({ id: true }), async (input) => {
    const s = await state()
    const id = input.id ?? Identifier.ascending("dbedit")

    return new Promise<Request | undefined>((resolve, reject) => {
      const info: Request = {
        id,
        ...input,
      }
      s.pending[id] = {
        info,
        resolve: (modified) => resolve(modified ?? info),
        reject,
      }
      Bus.publish(Event.Asked, info)
    })
  })

  export const reply = fn(
    z.object({
      requestID: Identifier.schema("dbedit"),
      reply: Reply,
      modified: Request.optional(),
      message: z.string().optional(),
    }),
    async (input) => {
      const s = await state()
      const existing = s.pending[input.requestID]
      if (!existing) return

      delete s.pending[input.requestID]

      if (input.reply === "reject") {
        Bus.publish(Event.Replied, {
          sessionID: existing.info.sessionID,
          requestID: existing.info.id,
          reply: "reject",
        })
        existing.reject(new RejectedError(input.message))
        return
      }

      if (input.reply === "accept") {
        Bus.publish(Event.Replied, {
          sessionID: existing.info.sessionID,
          requestID: existing.info.id,
          reply: "accept",
        })
        existing.resolve()
        return
      }

      if (input.reply === "edit" && input.modified) {
        Bus.publish(Event.Replied, {
          sessionID: existing.info.sessionID,
          requestID: existing.info.id,
          reply: "edit",
        })
        existing.resolve(input.modified)
        return
      }
    },
  )

  export async function list() {
    return state().then((x) => Object.values(x.pending).map((x) => x.info))
  }

  export class RejectedError extends Error {
    constructor(message?: string) {
      super(
        message
          ? `The user rejected database changes with feedback: ${message}`
          : `The user rejected the database changes.`,
      )
    }
  }
}

import { RequestError, type McpServer } from "@agentclientprotocol/sdk"
import type { ACPSessionState } from "./types"
import { Log } from "@/util/log"
import type { NikcliClient } from "@nikcli-ai/sdk/v2"

const log = Log.create({ service: "acp-session-manager" })

export class ACPSessionManager {
  private sessions = new Map<string, ACPSessionState>()
  private sdk: NikcliClient

  constructor(sdk: NikcliClient) {
    this.sdk = sdk
  }

  tryGet(sessionId: string): ACPSessionState | undefined {
    return this.sessions.get(sessionId)
  }

  async create(cwd: string, mcpServers: McpServer[], model?: ACPSessionState["model"]): Promise<ACPSessionState> {
    const session = await this.sdk.session
      .create(
        {
          title: `ACP Session ${crypto.randomUUID()}`,
          directory: cwd,
        },
        { throwOnError: true },
      )
      .then((x) => x.data!)

    const sessionId = session.id
    const resolvedModel = model

    const state: ACPSessionState = {
      id: sessionId,
      cwd,
      mcpServers,
      createdAt: new Date(),
      model: resolvedModel,
    }
    log.info("creating_session", { state })

    this.sessions.set(sessionId, state)
    return state
  }

  async load(
    sessionId: string,
    cwd: string,
    mcpServers: McpServer[],
    model?: ACPSessionState["model"],
  ): Promise<ACPSessionState> {
    const session = await this.sdk.session
      .get(
        {
          sessionID: sessionId,
          directory: cwd,
        },
        { throwOnError: true },
      )
      .then((x) => x.data!)

    const resolvedModel = model

    const state: ACPSessionState = {
      id: sessionId,
      cwd,
      mcpServers,
      createdAt: new Date(session.time.created),
      model: resolvedModel,
    }
    log.info("loading_session", { state })

    this.sessions.set(sessionId, state)
    return state
  }

  get(sessionId: string): ACPSessionState {
    const session = this.sessions.get(sessionId)
    if (!session) {
      log.error("session not found", { sessionId })
      throw RequestError.invalidParams(JSON.stringify({ error: `Session not found: ${sessionId}` }))
    }
    return session
  }

  getModel(sessionId: string) {
    const session = this.get(sessionId)
    return session.model
  }

  setModel(sessionId: string, model: ACPSessionState["model"]) {
    const session = this.get(sessionId)
    session.model = model
    this.sessions.set(sessionId, session)
    return session
  }

  setMode(sessionId: string, modeId: string) {
    const session = this.get(sessionId)
    session.modeId = modeId
    this.sessions.set(sessionId, session)
    return session
  }
}

import { BusEvent } from "@/bus/bus-event"
import { Bus } from "@/bus"
import z from "zod"
import { Log } from "../util/log"
import { Identifier } from "../id/id"
import { Plugin } from "../plugin"
import { Instance } from "../project/instance"
import { Wildcard } from "../util/wildcard"

export namespace Permission {
  const log = Log.create({ service: "permission" })

  function toKeys(pattern: Info["pattern"], type: string): string[] {
    return pattern === undefined ? [type] : Array.isArray(pattern) ? pattern : [pattern]
  }

  function covered(keys: string[], approved: Record<string, boolean>): boolean {
    const pats = Object.keys(approved)
    return keys.every((k) => pats.some((p) => Wildcard.match(k, p)))
  }

  export const Info = z
    .object({
      id: z.string(),
      type: z.string(),
      pattern: z.union([z.string(), z.array(z.string())]).optional(),
      sessionID: z.string(),
      messageID: z.string(),
      callID: z.string().optional(),
      message: z.string(),
      metadata: z.record(z.string(), z.any()),
      time: z.object({
        created: z.number(),
      }),
    })
    .meta({
      ref: "Permission",
    })
  export type Info = z.infer<typeof Info>

  export const Event = {
    Updated: BusEvent.define("permission.updated", Info),
    Replied: BusEvent.define(
      "permission.replied",
      z.object({
        sessionID: z.string(),
        permissionID: z.string(),
        response: z.string(),
      }),
    ),
  }

  const state = Instance.state(
    () => {
      const pending: {
        [sessionID: string]: {
          [permissionID: string]: {
            info: Info
            resolve: () => void
            reject: (e: any) => void
          }
        }
      } = {}

      const approved: {
        [sessionID: string]: {
          [permissionID: string]: boolean
        }
      } = {}

      return {
        pending,
        approved,
      }
    },
    async (state) => {
      for (const pending of Object.values(state.pending)) {
        for (const item of Object.values(pending)) {
          item.reject(new RejectedError(item.info.sessionID, item.info.id, item.info.callID, item.info.metadata))
        }
      }
    },
  )

  export function pending() {
    return state().pending
  }

  export function list() {
    const { pending } = state()
    const result: Info[] = []
    for (const items of Object.values(pending)) {
      for (const item of Object.values(items)) {
        result.push(item.info)
      }
    }
    return result.sort((a, b) => a.id.localeCompare(b.id))
  }

  export async function ask(input: {
    type: Info["type"]
    message: Info["message"]
    pattern?: Info["pattern"]
    callID?: Info["callID"]
    sessionID: Info["sessionID"]
    messageID: Info["messageID"]
    metadata: Info["metadata"]
  }) {
    const { pending, approved } = state()
    log.info("asking", {
      sessionID: input.sessionID,
      messageID: input.messageID,
      toolCallID: input.callID,
      pattern: input.pattern,
    })
    const approvedForSession = approved[input.sessionID] || {}
    const keys = toKeys(input.pattern, input.type)
    if (covered(keys, approvedForSession)) return
    const info: Info = {
      id: Identifier.ascending("permission"),
      type: input.type,
      pattern: input.pattern,
      sessionID: input.sessionID,
      messageID: input.messageID,
      callID: input.callID,
      message: input.message,
      metadata: input.metadata,
      time: {
        created: Date.now(),
      },
    }

    switch (
      await Plugin.trigger("permission.ask", info, {
        status: "ask",
      }).then((x) => x.status)
    ) {
      case "deny":
        throw new RejectedError(info.sessionID, info.id, info.callID, info.metadata)
      case "allow":
        return
    }

    pending[input.sessionID] = pending[input.sessionID] || {}
    return new Promise<void>((resolve, reject) => {
      pending[input.sessionID][info.id] = {
        info,
        resolve,
        reject,
      }
      Bus.publish(Event.Updated, info)
    })
  }

  export const Response = z.enum(["once", "always", "reject"])
  export type Response = z.infer<typeof Response>

  export function respond(input: { sessionID: Info["sessionID"]; permissionID: Info["id"]; response: Response }) {
    log.info("response", input)
    const { pending, approved } = state()
    const match = pending[input.sessionID]?.[input.permissionID]
    if (!match) return
    delete pending[input.sessionID][input.permissionID]
    Bus.publish(Event.Replied, {
      sessionID: input.sessionID,
      permissionID: input.permissionID,
      response: input.response,
    })
    if (input.response === "reject") {
      match.reject(new RejectedError(input.sessionID, input.permissionID, match.info.callID, match.info.metadata))
      return
    }
    match.resolve()
    if (input.response === "always") {
      approved[input.sessionID] = approved[input.sessionID] || {}
      const approveKeys = toKeys(match.info.pattern, match.info.type)
      for (const k of approveKeys) {
        approved[input.sessionID][k] = true
      }
      const items = pending[input.sessionID]
      if (!items) return
      for (const item of Object.values(items)) {
        const itemKeys = toKeys(item.info.pattern, item.info.type)
        if (covered(itemKeys, approved[input.sessionID])) {
          respond({
            sessionID: item.info.sessionID,
            permissionID: item.info.id,
            response: input.response,
          })
        }
      }
    }
  }

  export class RejectedError extends Error {
    constructor(
      public readonly sessionID: string,
      public readonly permissionID: string,
      public readonly toolCallID?: string,
      public readonly metadata?: Record<string, any>,

      public readonly reason?: string,
    ) {
      super(
        reason !== undefined
          ? reason
          : `The user rejected permission to use this specific tool call. You may try again with different parameters.`,
      )
    }
  }
}

