export type Info = z.output<typeof Info>

export const global = lazy(async () => {
  let result: Info = pipe(
    {},
    mergeDeep(await loadFile(path.join(Global.Path.config, "config.json"))),
    mergeDeep(await loadFile(path.join(Global.Path.config, "nikcli.json"))),
    mergeDeep(await loadFile(path.join(Global.Path.config, "nikcli.jsonc"))),
  )

  await import(path.join(Global.Path.config, "config"), {
    with: {
      type: "toml",
    },
  })
    .then(async (mod) => {
      const { provider, model, ...rest } = mod.default
      if (provider && model) result.model = `${provider}/${model}`
      result["$schema"] = "https://nikcli.store/config.json"
      result = mergeDeep(result, rest)
      await Bun.write(path.join(Global.Path.config, "config.json"), JSON.stringify(result, null, 2))
      await fs.unlink(path.join(Global.Path.config, "config"))
    })
    .catch(() => {})

  return result
})

async function loadFile(filepath: string): Promise<Info> {
  log.info("loading", { path: filepath })
  let text = await Bun.file(filepath)
    .text()
    .catch((err) => {
      if (err.code === "ENOENT") return
      throw new JsonError({ path: filepath }, { cause: err })
    })
  if (!text) return {}
  return load(text, filepath)
}

async function load(text: string, configFilepath: string) {
  const original = text
  text = text.replace(/\{env:([^}]+)\}/g, (_, varName) => {
    return process.env[varName] || ""
  })

  const fileMatches = text.match(/\{file:[^}]+\}/g)
  if (fileMatches) {
    const configDir = path.dirname(configFilepath)
    const lines = text.split("\n")

    for (const match of fileMatches) {
      const lineIndex = lines.findIndex((line) => line.includes(match))
      if (lineIndex !== -1 && lines[lineIndex].trim().startsWith("//")) {
        continue // Skip if line is commented
      }
      let filePath = match.replace(/^\{file:/, "").replace(/\}$/, "")
      if (filePath.startsWith("~/")) {
        filePath = path.join(os.homedir(), filePath.slice(2))
      }
      const resolvedPath = path.isAbsolute(filePath) ? filePath : path.resolve(configDir, filePath)
      const fileContent = (
        await Bun.file(resolvedPath)
          .text()
          .catch((error) => {
            const errMsg = `bad file reference: "${match}"`
            if (error.code === "ENOENT") {
              throw new InvalidError(
                {
                  path: configFilepath,
                  message: errMsg + ` ${resolvedPath} does not exist`,
                },
                { cause: error },
              )
            }
            throw new InvalidError({ path: configFilepath, message: errMsg }, { cause: error })
          })
      ).trim()
      // escape newlines/quotes, strip outer quotes
      text = text.replace(match, JSON.stringify(fileContent).slice(1, -1))
    }
  }

  const errors: JsoncParseError[] = []
  const data = parseJsonc(text, errors, { allowTrailingComma: true })
  if (errors.length) {
    const lines = text.split("\n")
    const errorDetails = errors
      .map((e) => {
        const beforeOffset = text.substring(0, e.offset).split("\n")
        const line = beforeOffset.length
        const column = beforeOffset[beforeOffset.length - 1].length + 1
        const problemLine = lines[line - 1]

        const error = `${printParseErrorCode(e.error)} at line ${line}, column ${column}`
        if (!problemLine) return error

        return `${error}\n   Line ${line}: ${problemLine}\n${"".padStart(column + 9)}^`
      })
      .join("\n")

    throw new JsonError({
      path: configFilepath,
      message: `\n--- JSONC Input ---\n${text}\n--- Errors ---\n${errorDetails}\n--- End ---`,
    })
  }

  const parsed = Info.safeParse(data)
  if (parsed.success) {
    if (!parsed.data.$schema) {
      parsed.data.$schema = "https://nikcli.store/config.json"
      // Write the $schema to the original text to preserve variables like {env:VAR}
      const updated = original.replace(/^\s*\{/, '{\n  "$schema": "https://nikcli.store/config.json",')
      await Bun.write(configFilepath, updated).catch(() => {})
    }
    const data = parsed.data
    if (data.plugin) {
      for (let i = 0; i < data.plugin.length; i++) {
        const plugin = data.plugin[i]
        try {
          data.plugin[i] = import.meta.resolve!(plugin, configFilepath)
        } catch (err) {}
      }
    }
    return data
  }

  throw new InvalidError({
    path: configFilepath,
    issues: parsed.error.issues,
  })
}
export const JsonError = NamedError.create(
  "ConfigJsonError",
  z.object({
    path: z.string(),
    message: z.string().optional(),
  }),
)

