import { resolver } from "hono-openapi"
import z from "zod"
import { Storage } from "../storage/storage"

export const ERRORS = {
  400: {
    description: "Bad request",
    content: {
      "application/json": {
        schema: resolver(
          z
            .object({
              data: z.any(),
              errors: z.array(z.record(z.string(), z.any())),
              success: z.literal(false),
            })
            .meta({
              ref: "BadRequestError",
            }),
        ),
      },
    },
  },
  404: {
    description: "Not found",
    content: {
      "application/json": {
        schema: resolver(Storage.NotFoundError.Schema),
      },
    },
  },
} as const

export function errors(...codes: number[]) {
  return Object.fromEntries(codes.map((code) => [code, ERRORS[code as keyof typeof ERRORS]]))
}

import { Log } from "@/util/log"
import { Bonjour } from "bonjour-service"

const log = Log.create({ service: "mdns" })

export namespace MDNS {
  let bonjour: Bonjour | undefined
  let currentPort: number | undefined

  export function publish(port: number) {
    if (currentPort === port) return
    if (bonjour) unpublish()

    try {
      const name = `nikcli-${port}`
      bonjour = new Bonjour()
      const service = bonjour.publish({
        name,
        type: "http",
        host: "nikcli.local",
        port,
        txt: { path: "/" },
      })

      service.on("up", () => {
        log.info("mDNS service published", { name, port })
      })

      service.on("error", (err) => {
        log.error("mDNS service error", { error: err })
      })

      currentPort = port
    } catch (err) {
      log.error("mDNS publish failed", { error: err })
      if (bonjour) {
        try {
          bonjour.destroy()
        } catch {}
      }
      bonjour = undefined
      currentPort = undefined
    }
  }

  export function unpublish() {
    if (bonjour) {
      try {
        bonjour.unpublishAll()
        bonjour.destroy()
      } catch (err) {
        log.error("mDNS unpublish failed", { error: err })
      }
      bonjour = undefined
      currentPort = undefined
      log.info("mDNS service unpublished")
    }
  }
}

import { EventEmitter } from "node:events"
import fs from "node:fs"
import path from "node:path"
import os from "node:os"
import { SessionManager } from "./session-manager"
import type {
  BroadcastMessage,
  RemoteNotification,
  RemoteServiceConfig,
  RemoteSession,
  RemoteSessionPersistence,
  SessionOptions,
  TaskInfo,
} from "./types"

export class RemoteService extends EventEmitter {
  private static instance: RemoteService
  private initialized = false
  private sessionManager: SessionManager | null = null
  private config: RemoteServiceConfig
  private configPath: string
  private sessionsDir: string

  private constructor() {
    super()
    this.configPath = path.join(os.homedir(), ".nikcli", "remote-config.json")
    this.sessionsDir = path.join(os.homedir(), ".nikcli", "remote-sessions")
    this.config = this.getDefaultConfig()
  }

  static getInstance(): RemoteService {
    if (!RemoteService.instance) {
      RemoteService.instance = new RemoteService()
    }
    return RemoteService.instance
  }

  async init(): Promise<void> {
    if (this.initialized) return

    try {
      await this.ensureDirectories()
      this.config = await this.loadConfig()
      await this.checkRemotoshAvailable()

      if (this.config.autoRecoverSession) {
        await this.recoverPreviousSessions()
      }

      this.initialized = true
      this.emit("ready")
    } catch (error: any) {
      this.emit("error", error)
    }
  }

  isInitialized(): boolean {
    return this.initialized
  }

  async startSession(options?: SessionOptions): Promise<RemoteSession> {
    if (!this.initialized) {
      throw new Error("RemoteService not initialized. Call init() first.")
    }

    if (this.sessionManager?.isActive()) {
      throw new Error('Session already active. Stop it first with "nikcli remote stop"')
    }

    this.sessionManager = new SessionManager(this.config)

    this.sessionManager.on("status:change", (session: RemoteSession) => {
      this.emit("session:status", session)
    })

    this.sessionManager.on("device:connected", (session: RemoteSession, device: any) => {
      this.emit("device:connected", session, device)
    })

    this.sessionManager.on("device:disconnected", (session: RemoteSession, device: any) => {
      this.emit("device:disconnected", session, device)
    })

    this.sessionManager.on("error", (error: Error) => {
      this.emit("session:error", error)
    })

    this.sessionManager.on("terminal:output", (data: string) => {
      this.broadcastToClients(data)
    })

    const session = await this.sessionManager.start(options)
    await this.persistSession(session)

    this.emit("session:started", session)
    return session
  }

  async stopSession(): Promise<void> {
    if (!this.sessionManager?.isActive()) {
      throw new Error("No active session")
    }

    const session = this.sessionManager.getSession()
    await this.sessionManager.stop()

    if (session) {
      await this.cleanupPersistedSession(session.id)
    }

    this.emit("session:stopped")
  }

  getSession(): RemoteSession | null {
    return this.sessionManager?.getSession() ?? null
  }

  hasActiveSession(): boolean {
    return this.sessionManager?.isActive() ?? false
  }

  hasRemoteClients(): boolean {
    const session = this.sessionManager?.getSession()
    return (session?.connectedDevices?.length ?? 0) > 0
  }

  private sanitizeForTunnel(data: string): string {
    return data
  }

  writeToTerminal(data: string): void {
    if (!this.sessionManager?.isActive()) return
    const sanitized = this.sanitizeForTunnel(data)
    this.sessionManager.writeToTerminal(sanitized)
  }

  private broadcastToClients(data: string): void {
    if (!this.sessionManager?.isActive()) return
    const sanitized = this.sanitizeForTunnel(data)
    this.sessionManager.writeToTerminal(sanitized)
  }

  resizeTerminal(cols: number, rows: number): void {
    if (!this.sessionManager?.isActive()) return
    this.sessionManager.resizeTerminal(cols, rows)
  }

  getServerPort(): number {
    return this.sessionManager?.getSession()?.port ?? 0
  }

  getSessionSecret(): string {
    const session = this.sessionManager?.getSession()
    if (session?.qrUrl) {
      try {
        const url = new URL(session.qrUrl)
        return url.searchParams.get("t") || ""
      } catch {
        return ""
      }
    }
    return ""
  }

  broadcast(message: BroadcastMessage): void {
    if (!this.sessionManager?.isActive()) return
    this.sessionManager.broadcast({
      ...message,
      timestamp: message.timestamp ?? Date.now(),
    })
  }

  notify(notification: RemoteNotification): void {
    if (!this.config.notificationsEnabled) return
    this.sessionManager?.notify(notification)
  }

  notifyTaskComplete(task: TaskInfo): void {
    if (!this.config.notificationsEnabled) return
    this.notify({
      type: "task_complete",
      title: `Task Completed: ${task.name}`,
      body: task.summary,
      data: task,
    })
  }

  notifyError(agentName: string, error: string): void {
    if (!this.config.notificationsEnabled) return
    this.notify({
      type: "error",
      title: `Error in ${agentName}`,
      body: error,
    })
  }

  notifyInputRequired(agentName: string, message: string): void {
    if (!this.config.notificationsEnabled) return
    this.notify({
      type: "action_required",

      title: `${agentName} needs input`,
      body: message,
    })
  }

  getConfig(): RemoteServiceConfig {
    return { ...this.config }
  }

  async updateConfig(config: Partial<RemoteServiceConfig>): Promise<void> {
    this.config = { ...this.config, ...config }
    await this.saveConfig()
  }

  private async ensureDirectories(): Promise<void> {
    const dirs = [path.dirname(this.configPath), this.sessionsDir]

    for (const dir of dirs) {
      if (!fs.existsSync(dir)) {
        fs.mkdirSync(dir, { recursive: true })
      }
    }
  }

  private async loadConfig(): Promise<RemoteServiceConfig> {
    try {
      if (fs.existsSync(this.configPath)) {
        const data = fs.readFileSync(this.configPath, "utf-8")
        const loaded = JSON.parse(data)
        return { ...this.getDefaultConfig(), ...loaded }
      }
    } catch {
      // ignore
    }
    return this.getDefaultConfig()
  }

  private async saveConfig(): Promise<void> {
    try {
      fs.writeFileSync(this.configPath, JSON.stringify(this.config, null, 2))
    } catch {
      // ignore
    }
  }

  private getDefaultConfig(): RemoteServiceConfig {
    return {
      notificationsEnabled: true,
      sessionExpiry: 86400,
      maxDevices: 5,
      autoRecoverSession: true,
    }
  }

  private async checkRemotoshAvailable(): Promise<boolean> {
    try {
      const { execSync } = await import("node:child_process")
      execSync("remoto --version", { stdio: "pipe", timeout: 10000 })
      return true
    } catch {
      return false
    }
  }

  private async recoverPreviousSessions(): Promise<void> {
    try {
      if (!fs.existsSync(this.sessionsDir)) return
      const files = fs.readdirSync(this.sessionsDir)
      for (const file of files) {
        if (!file.endsWith(".json")) continue
        const filePath = path.join(this.sessionsDir, file)
        try {
          const data = fs.readFileSync(filePath, "utf-8")
          const session: RemoteSessionPersistence = JSON.parse(data)
          const startedAt = new Date(session.startedAt)
          const now = new Date()
          const ageSeconds = (now.getTime() - startedAt.getTime()) / 1000
          if (ageSeconds > this.config.sessionExpiry) {
            fs.unlinkSync(filePath)
          }
        } catch {
          fs.unlinkSync(filePath)
        }
      }
    } catch {
      // ignore
    }
  }

  private async persistSession(session: RemoteSession): Promise<void> {
    try {
      const data: RemoteSessionPersistence = {
        sessionId: session.id,
        name: session.name,
        qrUrl: session.qrUrl,
        tunnelPassword: session.tunnelPassword,
        startedAt: session.startedAt.toISOString(),
        lastActivity: session.lastActivity.toISOString(),
        status: session.status,
        port: session.port,
      }

      const filePath = path.join(this.sessionsDir, `${session.id}.json`)
      fs.writeFileSync(filePath, JSON.stringify(data, null, 2))
    } catch {
      // ignore
    }
  }

  private async cleanupPersistedSession(sessionId: string): Promise<void> {
    try {
      const filePath = path.join(this.sessionsDir, `${sessionId}.json`)
      if (fs.existsSync(filePath)) {
        fs.unlinkSync(filePath)
      }
    } catch {
      // ignore
    }
  }
}

export const remoteService = RemoteService.getInstance()

import { EventEmitter } from "node:events"
import type {
  BroadcastMessage,
  DeviceInfo,
  RemoteNotification,
  RemoteServiceConfig,
  RemoteSession,
  SessionOptions,
  SessionStatus,
} from "./types"

type RemoteServer = import("@nikcli-ai/remote").RemoteServer
type NativeSession = import("@nikcli-ai/remote").RemoteSession

export class SessionManager extends EventEmitter {
  private server: RemoteServer | null = null
  private session: RemoteSession | null = null
  private config: RemoteServiceConfig

  constructor(config: RemoteServiceConfig) {
    super()
    this.config = config
  }

  async start(options?: SessionOptions): Promise<RemoteSession> {
    const { RemoteServer } = await import("@nikcli-ai/remote")

    this.server = new RemoteServer({
      port: 0,
      enableTunnel: true,
      tunnelProvider: "localtunnel",
      maxConnections: options?.maxDevices ?? this.config.maxDevices,
      sessionTimeout: this.config.sessionExpiry * 1000,
      enableTerminal: false,
    })

    this.server.on("client:connected", (device: DeviceInfo) => {
      if (!this.session) return
      this.session.connectedDevices.push(device)
      this.session.status = "connected"
      this.session.lastActivity = new Date()
      this.emit("status:change", this.session)
      this.emit("device:connected", this.session, device)
    })

    this.server.on("client:disconnected", (device: DeviceInfo) => {
      if (!this.session) return
      this.session.connectedDevices = this.session.connectedDevices.filter((d) => d.id !== device.id)
      if (this.session.connectedDevices.length === 0) {
        this.session.status = "waiting"
      }
      this.emit("status:change", this.session)
      this.emit("device:disconnected", this.session, device)
    })

    this.server.on("tunnel:connected", (url: string) => {
      if (this.session) {
        this.session.qrUrl = url
        this.emit("tunnel:connected", url)
      }
    })

    this.server.on("tunnel:error", (error: Error) => {
      this.emit("tunnel:error", error)
    })

    this.server.on("error", (error: Error) => {
      this.emit("error", error)
    })

    this.server.on("terminal:resize", (cols: number, rows: number) => {
      this.emit("terminal:resize", cols, rows)
    })

    const nativeSession: NativeSession = await this.server.start({
      name: options?.name,
      processForStreaming: {
        stdout: process.stdout,
        stdin: process.stdin,
        input: (data: Buffer) => {
          process.stdin.emit("data", data)
        },
      },
    })

    this.session = {
      id: nativeSession.id,
      name: nativeSession.name,
      qrCode: "",
      qrUrl: nativeSession.qrUrl,
      localUrl: nativeSession.localUrl,
      tunnelUrl: nativeSession.tunnelUrl,
      status: nativeSession.status as SessionStatus,
      connectedDevices: [],
      startedAt: nativeSession.startedAt,
      lastActivity: nativeSession.lastActivity,
      port: nativeSession.port,
    }

    return this.session
  }

  async stop(): Promise<void> {
    if (this.server) {
      await this.server.stop()
      this.server = null
    }

    if (this.session) {
      this.session.status = "stopped"
    }
  }

  isActive(): boolean {
    return this.server?.isActive() ?? false
  }

  getSession(): RemoteSession | null {
    return this.session
  }

  broadcast(message: BroadcastMessage): void {
    this.server?.broadcast(message)
  }

  notify(notification: RemoteNotification): void {
    this.server?.notify({
      type:
        notification.type === "task_complete"
          ? "success"
          : notification.type === "error"
            ? "error"
            : notification.type === "action_required"
              ? "warning"
              : "info",
      title: notification.title,
      body: notification.body,
      data: notification.data,
    })
  }

  writeToTerminal(data: string): void {
    this.server?.writeToTerminal(data)
  }

  resizeTerminal(cols: number, rows: number): void {
    this.server?.resizeTerminal(cols, rows)
  }

  getConnectedCount(): number {
    return this.server?.getConnectedCount() ?? 0
  }
}

import { generateQR, renderSessionCard } from "@nikcli-ai/remote"
import type { RemoteSession, SessionStatus } from "./types"

export class QRRenderer {
  async render(session: RemoteSession): Promise<void> {
    console.clear()
    const url = this.addSessionToUrl(this.getSessionUrl(session), session.id)
    const localUrlWithSession = this.addSessionToUrl(session.localUrl || "", session.id)
    const renderSession = {
      ...session,
      qrUrl: url,
      tunnelUrl: session.tunnelUrl ? url : session.tunnelUrl,
      localUrl: session.tunnelUrl ? session.localUrl : localUrlWithSession,
    }

    const card = await renderSessionCard(renderSession as any)
    console.log(card)

    const qr = await generateQR(url)
    console.log(qr)
  }

  updateStatus(session: RemoteSession): void {
    const statusIcon = this.getStatusIcon(session.status)
    const statusText = this.formatStatus(session.status)
    const devices = session.connectedDevices.length

    console.log("")
    console.log(`  Status: ${statusIcon} ${statusText}`)
    console.log(`  Devices: ${devices} connected`)
  }

  renderCompact(session: RemoteSession): string {
    const statusIcon = this.getStatusIcon(session.status)
    const devices = session.connectedDevices.length
    return `${statusIcon} Remote: ${session.id} (${devices} device${devices !== 1 ? "s" : ""})`
  }

  createStatusBadge(session: RemoteSession | null): string {
    if (!session) {
      return "- No remote session"
    }
    const icon = this.getStatusIcon(session.status)
    return `${icon} Remote: ${session.id}`
  }

  private addSessionToUrl(url: string, sessionId: string): string {
    try {
      const parsed = new URL(url)
      if (!parsed.searchParams.has("s")) {
        parsed.searchParams.set("s", sessionId)
      }
      return parsed.toString()
    } catch {
      return url
    }
  }

  private getSessionUrl(session: RemoteSession): string {
    return session.tunnelUrl || session.qrUrl || session.localUrl || ""
  }

  private getStatusIcon(status: SessionStatus): string {
    const icons: Record<SessionStatus, string> = {
      starting: ".",
      waiting: "o",
      connected: "*",
      stopped: "-",
      error: "x",
    }
    return icons[status] ?? "?"
  }

  private formatStatus(status: SessionStatus): string {
    const labels: Record<SessionStatus, string> = {
      starting: "Starting",
      waiting: "Waiting for connection",
      connected: "Connected",
      stopped: "Stopped",
      error: "Error",
    }
    return labels[status] ?? status
  }
}

