export namespace Scheduler {
  const log = Log.create({ service: "scheduler" })

  export type Task = {
    id: string
    interval: number
    run: () => Promise<void>
    scope?: "instance" | "global"
  }

  type Timer = ReturnType<typeof setInterval>
  type Entry = {
    tasks: Map<string, Task>
    timers: Map<string, Timer>
  }

  const create = (): Entry => {
    const tasks = new Map<string, Task>()
    const timers = new Map<string, Timer>()
    return { tasks, timers }
  }

  const shared = create()

  const state = Instance.state(
    () => create(),
    async (entry) => {
      for (const timer of entry.timers.values()) {
        clearInterval(timer)
      }
      entry.tasks.clear()
      entry.timers.clear()
    },
  )

  export function register(task: Task) {
    const scope = task.scope ?? "instance"
    const entry = scope === "global" ? shared : state()
    const current = entry.timers.get(task.id)
    if (current && scope === "global") return
    if (current) clearInterval(current)

    entry.tasks.set(task.id, task)
    void run(task)
    const timer = setInterval(() => {
      void run(task)
    }, task.interval)
    timer.unref()
    entry.timers.set(task.id, timer)
  }

  async function run(task: Task) {
    log.info("run", { id: task.id })
    await task.run().catch((error) => {
      log.error("run failed", { id: task.id, error })
    })
  }
}

import { $ } from "bun"
import fs from "fs/promises"
import path from "path"
import z from "zod"
import { NamedError } from "@nikcli-ai/util/error"
import { Global } from "../global"
import { Instance } from "../project/instance"
import { Project } from "../project/project"
import { fn } from "../util/fn"
import { Config } from "@/config/config"

export namespace Worktree {
  export const Info = z
    .object({
      name: z.string(),
      branch: z.string(),
      directory: z.string(),
    })
    .meta({
      ref: "Worktree",
    })

  export type Info = z.infer<typeof Info>

  export const CreateInput = z
    .object({
      name: z.string().optional(),
      startCommand: z.string().optional(),
    })
    .meta({
      ref: "WorktreeCreateInput",
    })

  export type CreateInput = z.infer<typeof CreateInput>

  export const RemoveInput = z
    .object({
      directory: z.string(),
    })
    .meta({
      ref: "WorktreeRemoveInput",
    })

  export type RemoveInput = z.infer<typeof RemoveInput>

  export const ResetInput = z
    .object({
      directory: z.string(),
    })
    .meta({
      ref: "WorktreeResetInput",
    })

  export type ResetInput = z.infer<typeof ResetInput>

  export const NotGitError = NamedError.create(
    "WorktreeNotGitError",
    z.object({
      message: z.string(),
    }),
  )

  export const NameGenerationFailedError = NamedError.create(
    "WorktreeNameGenerationFailedError",
    z.object({
      message: z.string(),
    }),
  )

  export const CreateFailedError = NamedError.create(
    "WorktreeCreateFailedError",
    z.object({
      message: z.string(),
    }),
  )

  export const StartCommandFailedError = NamedError.create(
    "WorktreeStartCommandFailedError",
    z.object({
      message: z.string(),
    }),
  )

  export const RemoveFailedError = NamedError.create(
    "WorktreeRemoveFailedError",
    z.object({
      message: z.string(),
    }),
  )

  export const ResetFailedError = NamedError.create(
    "WorktreeResetFailedError",
    z.object({
      message: z.string(),
    }),
  )

  const ADJECTIVES = [
    "brave",
    "calm",
    "clever",
    "cosmic",
    "crisp",
    "curious",
    "eager",
    "gentle",
    "glowing",
    "happy",
    "hidden",
    "jolly",
    "kind",
    "lucky",
    "mighty",
    "misty",
    "neon",
    "nimble",
    "playful",
    "proud",
    "quick",
    "quiet",
    "shiny",
    "silent",
    "stellar",
    "sunny",
    "swift",
    "tidy",
    "witty",
  ] as const

  const NOUNS = [
    "cabin",
    "cactus",
    "canyon",
    "circuit",
    "comet",
    "eagle",
    "engine",
    "falcon",
    "forest",
    "garden",
    "harbor",
    "island",
    "knight",
    "lagoon",
    "meadow",
    "moon",
    "mountain",
    "nebula",
    "orchid",
    "otter",
    "panda",
    "pixel",
    "planet",
    "river",
    "rocket",
    "sailor",
    "squid",
    "star",
    "tiger",
    "wizard",
    "wolf",
  ] as const

  function pick<const T extends readonly string[]>(list: T) {
    return list[Math.floor(Math.random() * list.length)]
  }

  function slug(input: string) {
    return input
      .trim()
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-+/, "")
      .replace(/-+$/, "")
  }

  function randomName() {
    return `${pick(ADJECTIVES)}-${pick(NOUNS)}`
  }

  async function exists(target: string) {
    return fs
      .stat(target)
      .then(() => true)
      .catch(() => false)
  }

  function outputText(input: Uint8Array | undefined) {
    if (!input?.length) return ""
    return new TextDecoder().decode(input).trim()
  }

  function errorText(result: { stdout?: Uint8Array; stderr?: Uint8Array }) {
    return [outputText(result.stderr), outputText(result.stdout)].filter(Boolean).join("\n")
  }

  async function candidate(root: string, base?: string) {
    for (const attempt of Array.from({ length: 26 }, (_, i) => i)) {
      const name = base ? (attempt === 0 ? base : `${base}-${randomName()}`) : randomName()
      const branch = `nikcli/${name}`

    const directory = path.join(root, name)

    if (await exists(directory)) continue

    const ref = `refs/heads/${branch}`
    const branchCheck = await $`git show-ref --verify --quiet ${ref}`.quiet().nothrow().cwd(Instance.worktree)
    if (branchCheck.exitCode === 0) continue

    return Info.parse({ name, branch, directory })
  }

  throw new NameGenerationFailedError({ message: "Failed to generate a unique worktree name" })
}

async function runStartCommand(directory: string, cmd: string) {
  if (process.platform === "win32") {
    return $`cmd /c ${cmd}`.nothrow().cwd(directory)
  }
  return $`bash -lc ${cmd}`.nothrow().cwd(directory)
}

export const create = fn(CreateInput.optional(), async (input) => {
  if (Instance.project.vcs !== "git") {
    throw new NotGitError({ message: "Worktrees are only supported for git projects" })
  }

  const root = path.join(Global.Path.data, "worktree", Instance.project.id)
  await fs.mkdir(root, { recursive: true })

  const base = input?.name ? slug(input.name) : ""
  const info = await candidate(root, base || undefined)

  const created = await $`git worktree add -b ${info.branch} ${info.directory}`
    .quiet()
    .nothrow()
    .cwd(Instance.worktree)
  if (created.exitCode !== 0) {
    throw new CreateFailedError({ message: errorText(created) || "Failed to create git worktree" })
  }

  const cmd = input?.startCommand?.trim()
  if (!cmd) return info

  const ran = await runStartCommand(info.directory, cmd)
  if (ran.exitCode !== 0) {
    throw new StartCommandFailedError({ message: errorText(ran) || "Worktree start command failed" })
  }

  return info
})

export const remove = fn(RemoveInput, async (input) => {
  if (Instance.project.vcs !== "git") {
    throw new NotGitError({ message: "Worktrees are only supported for git projects" })
  }

  const directory = path.resolve(input.directory)
  const list = await $`git worktree list --porcelain`.quiet().nothrow().cwd(Instance.worktree)
  if (list.exitCode !== 0) {
    throw new RemoveFailedError({ message: errorText(list) || "Failed to read git worktrees" })
  }

  const lines = outputText(list.stdout)
    .split("\n")
    .map((line) => line.trim())
  const entries = lines.reduce<{ path?: string; branch?: string }[]>((acc, line) => {
    if (!line) return acc
    if (line.startsWith("worktree ")) {
      acc.push({ path: line.slice("worktree ".length).trim() })
      return acc
    }
    const current = acc[acc.length - 1]
    if (!current) return acc
    if (line.startsWith("branch ")) {
      current.branch = line.slice("branch ".length).trim()
    }
    return acc
  }, [])

  const entry = entries.find((item) => item.path && path.resolve(item.path) === directory)
  if (!entry?.path) {
    throw new RemoveFailedError({ message: "Worktree not found" })
  }

  const removed = await $`git worktree remove --force ${entry.path}`.quiet().nothrow().cwd(Instance.worktree)
  if (removed.exitCode !== 0) {
    throw new RemoveFailedError({ message: errorText(removed) || "Failed to remove git worktree" })
  }

  const branch = entry.branch?.replace(/^refs\/heads\//, "")
  if (branch) {
    const deleted = await $`git branch -D ${branch}`.quiet().nothrow().cwd(Instance.worktree)
    if (deleted.exitCode !== 0) {
      throw new RemoveFailedError({ message: errorText(deleted) || "Failed to delete worktree branch" })
    }
  }

  return true
})

export const reset = fn(ResetInput, async (input) => {
  if (Instance.project.vcs !== "git") {
    throw new NotGitError({ message: "Worktrees are only supported for git projects" })
  }

  const directory = path.resolve(input.directory)
  if (directory === path.resolve(Instance.worktree)) {
    throw new ResetFailedError({ message: "Cannot reset the primary workspace" })
  }

  const list = await $`git worktree list --porcelain`.quiet().nothrow().cwd(Instance.worktree)
  if (list.exitCode !== 0) {
    throw new ResetFailedError({ message: errorText(list) || "Failed to read git worktrees" })
  }

  const lines = outputText(list.stdout)
    .split("\n")
    .map((line) => line.trim())
  const entries = lines.reduce<{ path?: string; branch?: string }[]>((acc, line) => {
    if (!line) return acc
    if (line.startsWith("worktree ")) {
      acc.push({ path: line.slice("worktree ".length).trim() })
      return acc
    }
    const current = acc[acc.length - 1]
    if (!current) return acc
    if (line.startsWith("branch ")) {
      current.branch = line.slice("branch ".length).trim()
    }
    return acc
  }, [])

  const entry = entries.find((item) => item.path && path.resolve(item.path) === directory)
  if (!entry?.path) {
    throw new ResetFailedError({ message: "Worktree not found" })
  }

  const remoteList = await $`git remote`.quiet().nothrow().cwd(Instance.worktree)
  if (remoteList.exitCode !== 0) {
    throw new ResetFailedError({ message: errorText(remoteList) || "Failed to list git remotes" })
  }

  const remotes = outputText(remoteList.stdout)
    .split("\n")
    .map((line) => line.trim())
    .filter(Boolean)

  const remote = remotes.includes("origin")
    ? "origin"
    : remotes.length === 1
      ? remotes[0]
      : remotes.includes("upstream")
        ? "upstream"
        : ""

  const remoteHead = remote
    ? await $`git symbolic-ref refs/remotes/${remote}/HEAD`.quiet().nothrow().cwd(Instance.worktree)
    : { exitCode: 1, stdout: undefined, stderr: undefined }

  const remoteRef = remoteHead.exitCode === 0 ? outputText(remoteHead.stdout) : ""
  const remoteTarget = remoteRef ? remoteRef.replace(/^refs\/remotes\//, "") : ""
  const remoteBranch = remote && remoteTarget.startsWith(`${remote}/`) ? remoteTarget.slice(`${remote}/`.length) : ""

  const mainCheck = await $`git show-ref --verify --quiet refs/heads/main`.quiet().nothrow().cwd(Instance.worktree)
  const masterCheck = await $`git show-ref --verify --quiet refs/heads/master`
    .quiet()
    .nothrow()
    .cwd(Instance.worktree)
  const localBranch = mainCheck.exitCode === 0 ? "main" : masterCheck.exitCode === 0 ? "master" : ""

  const target = remoteBranch ? `${remote}/${remoteBranch}` : localBranch
  if (!target) {
    throw new ResetFailedError({ message: "Default branch not found" })
  }

  if (remoteBranch) {
    const fetch = await $`git fetch ${remote} ${remoteBranch}`.quiet().nothrow().cwd(Instance.worktree)
    if (fetch.exitCode !== 0) {
      throw new ResetFailedError({ message: errorText(fetch) || `Failed to fetch ${target}` })
    }
  }

  if (!entry.path) {
    throw new ResetFailedError({ message: "Worktree path not found" })
  }

  const worktreePath = entry.path

  const resetToTarget = await $`git reset --hard ${target}`.quiet().nothrow().cwd(worktreePath)
  if (resetToTarget.exitCode !== 0) {
    throw new ResetFailedError({ message: errorText(resetToTarget) || "Failed to reset worktree to target" })
  }

  const clean = await $`git clean -fdx`.quiet().nothrow().cwd(worktreePath)
  if (clean.exitCode !== 0) {
    throw new ResetFailedError({ message: errorText(clean) || "Failed to clean worktree" })
  }

  const update = await $`git submodule update --init --recursive --force`.quiet().nothrow().cwd(worktreePath)
  if (update.exitCode !== 0) {

      throw new ResetFailedError({ message: errorText(update) || "Failed to update submodules" })
    }

    const subReset = await $`git submodule foreach --recursive git reset --hard`.quiet().nothrow().cwd(worktreePath)
    if (subReset.exitCode !== 0) {
      throw new ResetFailedError({ message: errorText(subReset) || "Failed to reset submodules" })
    }

    const subClean = await $`git submodule foreach --recursive git clean -fdx`.quiet().nothrow().cwd(worktreePath)
    if (subClean.exitCode !== 0) {
      throw new ResetFailedError({ message: errorText(subClean) || "Failed to clean submodules" })
    }

    const status = await $`git status --porcelain=v1`.quiet().nothrow().cwd(worktreePath)
    if (status.exitCode !== 0) {
      throw new ResetFailedError({ message: errorText(status) || "Failed to read git status" })
    }

    const dirty = outputText(status.stdout)
    if (!dirty) return true

    throw new ResetFailedError({ message: `Worktree reset left local changes:\n${dirty}` })
  })
}

import path from "path"
import fs from "fs/promises"
import z from "zod"
import { Global } from "../global"

export namespace ConnectorAuth {
  export const Entry = z.object({
    token: z.string().optional(),
    botToken: z.string().optional(),
    apiKey: z.string().optional(),
    teamId: z.string().optional(),
    expiresAt: z.number().optional(),
  })
  export type Entry = z.infer<typeof Entry>

  const filepath = path.join(Global.Path.data, "connectors-auth.json")

  export async function get(connectorName: string): Promise<Entry | undefined> {
    const data = await all()
    return data[connectorName]
  }

  export async function all(): Promise<Record<string, Entry>> {
    const file = Bun.file(filepath)
    return file.json().catch(() => ({}))
  }

  export async function set(connectorName: string, entry: Entry): Promise<void> {
    const file = Bun.file(filepath)
    const data = await all()
    await Bun.write(file, JSON.stringify({ ...data, [connectorName]: entry }, null, 2))
    await fs.chmod(file.name!, 0o600)
  }

  export async function remove(connectorName: string): Promise<void> {
    const file = Bun.file(filepath)
    const data = await all()
    delete data[connectorName]
    await Bun.write(file, JSON.stringify(data, null, 2))
    await fs.chmod(file.name!, 0o600)
  }

  export async function updateToken(connectorName: string, token: string, expiresAt?: number): Promise<void> {
    const entry = (await get(connectorName)) ?? {}
    entry.token = token
    if (expiresAt) entry.expiresAt = expiresAt
    await set(connectorName, entry)
  }

  export async function updateBotToken(connectorName: string, botToken: string, teamId?: string): Promise<void> {
    const entry = (await get(connectorName)) ?? {}
    entry.botToken = botToken
    if (teamId) entry.teamId = teamId
    await set(connectorName, entry)
  }

  export async function updateApiKey(connectorName: string, apiKey: string): Promise<void> {
    const entry = (await get(connectorName)) ?? {}
    entry.apiKey = apiKey
    await set(connectorName, entry)
  }

  export async function isTokenExpired(connectorName: string): Promise<boolean | null> {
    const entry = await get(connectorName)
    if (!entry?.expiresAt) return null
    return entry.expiresAt < Date.now() / 1000
  }
}

import { type Tool } from "ai"
import z from "zod"
import { Config } from "../config/config"
import { Log } from "../util/log"
import { ConnectorAuth } from "./auth"
import { createTools, getHealthCheck, getPrompts } from "./registry"
import { resolveCredential, resolveCredentialType } from "./credentials"
import {
  getCachedStatus,
  getCachedTools,
  invalidateConnectorCache,
  invalidateToolsCache,
  invalidateStatusCache,
} from "./cache"

export namespace Connectors {
  const log = Log.create({ service: "connectors" })

  export const StatusSchema = z
    .discriminatedUnion("status", [
      z
        .object({
          status: z.literal("connected"),
        })
        .meta({ ref: "ConnectorStatusConnected" }),
      z
        .object({
          status: z.literal("disabled"),
        })
        .meta({ ref: "ConnectorStatusDisabled" }),
      z
        .object({
          status: z.literal("failed"),
          error: z.string(),
        })
        .meta({ ref: "ConnectorStatusFailed" }),
      z
        .object({
          status: z.literal("needs_auth"),
        })
        .meta({ ref: "ConnectorStatusNeedsAuth" }),
    ])
    .meta({ ref: "ConnectorStatus" })
  export type Status = z.infer<typeof StatusSchema>

  type ConnectorEntry = NonNullable<Config.Info["connectors"]>[string]
  export function isConnectorConfigured(entry: ConnectorEntry): entry is Config.Connector {
    return typeof entry === "object" && entry !== null && "type" in entry && typeof entry.type === "string"
  }

  function getRequiredCredentialType(type: string): "token" | "botToken" | "apiKey" | null {
    return resolveCredentialType(type)
  }

  async function checkConnector(name: string, config: Config.Connector): Promise<Status> {
    try {
      const credential = await resolveCredential(name, config)
      if (!credential) return { status: "needs_auth" }

      const healthCheck = getHealthCheck(config.type)
      if (!healthCheck) return { status: "failed", error: "Unknown connector type" }

      await healthCheck(credential)
      return { status: "connected" }
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error)
      return { status: "failed", error: message }
    }
  }

  async function resolveStatuses(): Promise<Record<string, Status>> {
    const cfg = await Config.get()
    const config = cfg.connectors ?? {}
    const statuses: Record<string, Status> = {}

    await Promise.all(
      Object.entries(config).map(async ([key, connector]) => {
        if (!isConnectorConfigured(connector)) {
          log.error("Ignoring connector config entry without type", { key })
          return
        }

        if (connector.enabled === false) {
          statuses[key] = { status: "disabled" }
          return
        }

        const result = await checkConnector(key, connector).catch(() => undefined)
        if (!result) return

        statuses[key] = result
      }),
    )

    return statuses
  }

  export async function status(): Promise<Record<string, Status>> {
    const cfg = await Config.get()
    const cacheKey = "connectors_status"

    return getCachedStatus(cacheKey, resolveStatuses, cfg)
  }

  export function invalidateStatus(): void {
    invalidateStatusCache()
  }

  export function invalidateTools(): void {
    invalidateToolsCache()
  }

  export function invalidateConnector(name: string): void {
    invalidateConnectorCache(name)
  }

  export async function hasStoredCredentials(name: string, type?: string): Promise<boolean> {
    const auth = await ConnectorAuth.get(name)
    if (!auth) return false
    if (!type) {
      return !!auth.token || !!auth.botToken || !!auth.apiKey
    }
    const requiredType = getRequiredCredentialType(type)
    if (!requiredType) return false
    switch (requiredType) {
      case "token":
        if (auth.token) return true
        if (type === "lovable") return !!auth.apiKey
        return false
      case "botToken":
        return !!auth.botToken
      case "apiKey":
        return !!auth.apiKey
    }
    return false
  }

  export async function tools(): Promise<Record<string, Tool>> {
    const cfg = await Config.get()
    const cacheKey = "connectors_tools"

    const compute = async (): Promise<Record<string, Tool>> => {
      const config = cfg.connectors ?? {}
      const tools: Record<string, Tool> = {}

      await Promise.all(
        Object.entries(config).map(async ([name, connector]) => {
          if (!isConnectorConfigured(connector)) return
          if (connector.enabled === false) return

          try {
            const connectorTools = await createTools(name, connector)
            Object.assign(tools, connectorTools)
          } catch (error) {
            log.error("Failed to load connector tools", { name, connector: connector.type, error })
          }
        }),
      )

      return tools
    }

    return getCachedTools(cacheKey, compute, cfg)
  }

  type ConnectorPrompt = {
    name: string
    description: string
    type: string
    arguments?: Array<{ name: string; description: string }>
  }

  export async function prompts(): Promise<Record<string, ConnectorPrompt & { client: string }>> {
    const cfg = await Config.get()
    const config = cfg.connectors ?? {}
    const connectorStatuses = await status()

    const prompts: Record<string, ConnectorPrompt & { client: string }> = {}

    for (const [connectorName, connector] of Object.entries(config)) {
      if (!isConnectorConfigured(connector)) continue
      if (connector.enabled === false) continue

      const connStatus = connectorStatuses[connectorName]
      if (connStatus?.status !== "connected") continue

      const operationPrompts = getPrompts(connector.type)

      for (const op of operationPrompts) {
        prompts[`${connectorName}_${op.name}`] = {
          name: `${connectorName}_${op.name}`,
          description: op.description,
          type: connector.type,
          arguments: op.args.map((arg) => ({ name: arg.name, description: arg.description })),
          client: connectorName,
        }
      }
    }

    return prompts

import { Config } from "../config/config"
import { Flag } from "../flag/flag"
import { getToken as getFigmaToken } from "./api/figma"
import { getToken as getGithubToken } from "./api/github"
import { getBotToken as getSlackBotToken } from "./api/slack"
import { getToken as getLovableToken } from "./api/lovable"

type CredentialType = "token" | "botToken" | "apiKey"

const credentialTypeMap: Record<string, CredentialType> = {
  figma: "token",
  github: "token",
  slack: "botToken",
  lovable: "token",
}

function getCredentialType(type: string): CredentialType | null {
  return credentialTypeMap[type] ?? null
}

function getCredentialFlag(type: string): string | null {
  switch (type) {
    case "figma":
      return Flag.NIKCLI_FIGMA_TOKEN ?? null
    case "github":
      return Flag.NIKCLI_GITHUB_TOKEN ?? null
    case "slack":
      return Flag.NIKCLI_SLACK_BOT_TOKEN ?? null
    case "lovable":
      return Flag.NIKCLI_LOVABLE_TOKEN ?? null
    default:
      return null
  }
}

function getCredentialFromAuth(name: string, type: string): Promise<string | null> {
  switch (type) {
    case "figma":
      return getFigmaToken(name)
    case "github":
      return getGithubToken(name)
    case "slack":
      return getSlackBotToken(name)
    case "lovable":
      return getLovableToken(name)
    default:
      return Promise.resolve(null)
  }
}

function getCredentialFromConfig(connector: Config.Connector): string | null {
  switch (connector.type) {
    case "figma":
      return connector.token ?? null
    case "github":
      return connector.token ?? null
    case "slack":
      return connector.botToken ?? null
    case "lovable":
      return connector.token ?? connector.apiKey ?? null
    default:
      return null
  }
}

export async function resolveCredential(name: string, connector: Config.Connector): Promise<string | null> {
  const flag = getCredentialFlag(connector.type)
  if (flag) return flag

  const configCredential = getCredentialFromConfig(connector)
  if (configCredential) return configCredential

  const authCredential = await getCredentialFromAuth(name, connector.type)
  if (authCredential) return authCredential

  return null
}

export function resolveCredentialType(type: string): CredentialType | null {
  return getCredentialType(type)
}

