interface PendingOAuth {
  pkce: PkceCodes
  state: string
  resolve: (tokens: TokenResponse) => void
  reject: (error: Error) => void
}

let oauthServer: ReturnType<typeof Bun.serve> | undefined
let pendingOAuth: PendingOAuth | undefined

async function startOAuthServer(): Promise<{ port: number; redirectUri: string }> {
  if (oauthServer) {
    return { port: OAUTH_PORT, redirectUri: `http://localhost:${OAUTH_PORT}/auth/callback` }
  }

  oauthServer = Bun.serve({
    port: OAUTH_PORT,
    fetch(req) {
      const url = new URL(req.url)

      if (url.pathname === "/auth/callback") {
        const code = url.searchParams.get("code")
        const state = url.searchParams.get("state")
        const error = url.searchParams.get("error")
        const errorDescription = url.searchParams.get("error_description")

        if (error) {
          const errorMsg = errorDescription || error
          pendingOAuth?.reject(new Error(errorMsg))
          pendingOAuth = undefined
          return new Response(HTML_ERROR(errorMsg), {
            headers: { "Content-Type": "text/html" },
          })
        }

        if (!code) {
          const errorMsg = "Missing authorization code"
          pendingOAuth?.reject(new Error(errorMsg))
          pendingOAuth = undefined
          return new Response(HTML_ERROR(errorMsg), {
            status: 400,
            headers: { "Content-Type": "text/html" },
          })
        }

        if (!pendingOAuth || state !== pendingOAuth.state) {
          const errorMsg = "Invalid state - potential CSRF attack"
          pendingOAuth?.reject(new Error(errorMsg))
          pendingOAuth = undefined
          return new Response(HTML_ERROR(errorMsg), {
            status: 400,
            headers: { "Content-Type": "text/html" },
          })
        }

        const current = pendingOAuth
        pendingOAuth = undefined

        exchangeCodeForTokens(code, `http://localhost:${OAUTH_PORT}/auth/callback`, current.pkce)
          .then((tokens) => current.resolve(tokens))
          .catch((err) => current.reject(err))

        return new Response(HTML_SUCCESS, {
          headers: { "Content-Type": "text/html" },
        })
      }

      if (url.pathname === "/cancel") {
        pendingOAuth?.reject(new Error("Login cancelled"))
        pendingOAuth = undefined
        return new Response("Login cancelled", { status: 200 })
      }

      return new Response("Not found", { status: 404 })
    },
  })

  log.info("codex oauth server started", { port: OAUTH_PORT })
  return { port: OAUTH_PORT, redirectUri: `http://localhost:${OAUTH_PORT}/auth/callback` }
}

function stopOAuthServer() {
  if (oauthServer) {
    oauthServer.stop()
    oauthServer = undefined
    log.info("codex oauth server stopped")
  }
}

function waitForOAuthCallback(pkce: PkceCodes, state: string): Promise<TokenResponse> {
  return new Promise((resolve, reject) => {
    const timeout = setTimeout(
      () => {
        if (pendingOAuth) {
          pendingOAuth = undefined
          reject(new Error("OAuth callback timeout - authorization took too long"))
        }
      },
      5 * 60 * 1000,
    )

    pendingOAuth = {
      pkce,
      state,
      resolve: (tokens) => {
        clearTimeout(timeout)
        resolve(tokens)
      },
      reject: (error) => {
        clearTimeout(timeout)
        reject(error)
      },
    }
  })
}

export async function CodexAuthPlugin(input: PluginInput): Promise<Hooks> {
  return {
    auth: {
      provider: "openai",
      async loader(getAuth, provider) {
        const auth = await getAuth()
        if (auth.type !== "oauth") return {}

        const allowedModels = new Set(["gpt-5.1-codex-max", "gpt-5.1-codex-mini", "gpt-5.2", "gpt-5.2-codex"])
        for (const modelId of Object.keys(provider.models)) {
          if (!allowedModels.has(modelId)) {
            delete provider.models[modelId]
          }
        }

        for (const model of Object.values(provider.models)) {
          model.cost = {
            input: 0,
            output: 0,
            cache: { read: 0, write: 0 },
          }
        }

        return {
          apiKey: OAUTH_DUMMY_KEY,
          async fetch(requestInput: RequestInfo | URL, init?: RequestInit) {
            if (init?.headers) {
              if (init.headers instanceof Headers) {
                init.headers.delete("authorization")
                init.headers.delete("Authorization")
              } else if (Array.isArray(init.headers)) {
                init.headers = init.headers.filter(([key]) => key.toLowerCase() !== "authorization")
              } else {
                delete init.headers["authorization"]
                delete init.headers["Authorization"]
              }
            }

            const currentAuth = await getAuth()
            if (currentAuth.type !== "oauth") return fetch(requestInput, init)

            const authWithAccount = currentAuth as typeof currentAuth & { accountId?: string }

            if (!currentAuth.access || currentAuth.expires < Date.now()) {
              log.info("refreshing codex access token")
              const tokens = await refreshAccessToken(currentAuth.refresh)
              const newAccountId = extractAccountId(tokens) || authWithAccount.accountId
              await input.client.auth.set({
                path: { id: "codex" },
                body: {
                  type: "oauth",
                  refresh: tokens.refresh_token,
                  access: tokens.access_token,

                  expires: Date.now() + (tokens.expires_in ?? 3600) * 1000,
                  ...(newAccountId && { accountId: newAccountId }),
                },
              })
              currentAuth.access = tokens.access_token
              authWithAccount.accountId = newAccountId
            }

            const headers = new Headers()
            if (init?.headers) {
              if (init.headers instanceof Headers) {
                init.headers.forEach((value, key) => headers.set(key, value))
              } else if (Array.isArray(init.headers)) {
                for (const [key, value] of init.headers) {
                  if (value !== undefined) headers.set(key, String(value))
                }
              } else {
                for (const [key, value] of Object.entries(init.headers)) {
                  if (value !== undefined) headers.set(key, String(value))
                }
              }
            }

            headers.set("authorization", `Bearer ${currentAuth.access}`)

            if (authWithAccount.accountId) {
              headers.set("ChatGPT-Account-Id", authWithAccount.accountId)
            }

            const parsed =
              requestInput instanceof URL
                ? requestInput
                : new URL(typeof requestInput === "string" ? requestInput : requestInput.url)
            const url =
              parsed.pathname.includes("/v1/responses") || parsed.pathname.includes("/chat/completions")
                ? new URL(CODEX_API_ENDPOINT)
                : parsed

            return fetch(url, {
              ...init,
              headers,
            })
          },
        }
      },
      methods: [
        {
          label: "ChatGPT Pro/Plus",
          type: "oauth",
          authorize: async () => {
            const { redirectUri } = await startOAuthServer()
            const pkce = await generatePKCE()
            const state = generateState()
            const authUrl = buildAuthorizeUrl(redirectUri, pkce, state)

            const callbackPromise = waitForOAuthCallback(pkce, state)

            return {
              url: authUrl,
              instructions: "Complete authorization in your browser. This window will close automatically.",
              method: "auto" as const,
              callback: async () => {
                const tokens = await callbackPromise
                stopOAuthServer()
                const accountId = extractAccountId(tokens)
                return {
                  type: "success" as const,
                  refresh: tokens.refresh_token,
                  access: tokens.access_token,
                  expires: Date.now() + (tokens.expires_in ?? 3600) * 1000,
                  accountId,
                }
              },
            }
          },
        },
        {
          label: "Manually enter API Key",
          type: "api",
        },
      ],
    },
  }
}

import type { Hooks, PluginInput } from "@nikcli-ai/plugin"
import { Installation } from "@/installation"
import { iife } from "@/util/iife"

const CLIENT_ID = "Ov23li8tweQw6odWQebz"
const OAUTH_POLLING_SAFETY_MARGIN_MS = 3000

function normalizeDomain(url: string) {
  return url.replace(/^https?:\/\//, "").replace(/\/$/, "")
}

function getUrls(domain: string) {
  return {
    DEVICE_CODE_URL: `https://${domain}/login/device/code`,
    ACCESS_TOKEN_URL: `https://${domain}/login/oauth/access_token`,
  }
}

export async function CopilotAuthPlugin(input: PluginInput): Promise<Hooks> {
  return {
    auth: {
      provider: "github-copilot",
      async loader(getAuth, provider) {
        const info = await getAuth()
        if (!info || info.type !== "oauth") return {}

        if (provider && provider.models) {
          for (const model of Object.values(provider.models)) {
            model.cost = {
              input: 0,
              output: 0,
              cache: {
                read: 0,
                write: 0,
              },
            }
          }
        }

        const enterpriseUrl = info.enterpriseUrl
        const baseURL = enterpriseUrl
          ? `https://copilot-api.${normalizeDomain(enterpriseUrl)}`
          : "https://api.githubcopilot.com"

        return {
          baseURL,
          apiKey: "",
          async fetch(request: RequestInfo | URL, init?: RequestInit) {
            const info = await getAuth()
            if (info.type !== "oauth") return fetch(request, init)

            const { isVision, isAgent } = iife(() => {
              try {
                const body = typeof init?.body === "string" ? JSON.parse(init.body) : init?.body

                if (body?.messages) {
                  const last = body.messages[body.messages.length - 1]
                  return {
                    isVision: body.messages.some(
                      (msg: any) =>
                        Array.isArray(msg.content) && msg.content.some((part: any) => part.type === "image_url"),
                    ),
                    isAgent: last?.role !== "user",
                  }
                }

                if (body?.input) {
                  const last = body.input[body.input.length - 1]
                  return {
                    isVision: body.input.some(
                      (item: any) =>
                        Array.isArray(item?.content) && item.content.some((part: any) => part.type === "input_image"),
                    ),
                    isAgent: last?.role !== "user",
                  }
                }
              } catch {}
              return { isVision: false, isAgent: false }
            })

            const headers: Record<string, string> = {
              ...(init?.headers as Record<string, string>),
              "User-Agent": `nikcli/${Installation.VERSION}`,
              Authorization: `Bearer ${info.refresh}`,
              "Openai-Intent": "conversation-edits",
              "X-Initiator": isAgent ? "agent" : "user",
            }

            if (isVision) {
              headers["Copilot-Vision-Request"] = "true"
            }

            delete headers["x-api-key"]
            delete headers["authorization"]

            return fetch(request, {
              ...init,
              headers,
            })
          },
        }
      },
      methods: [
        {
          type: "oauth",
          label: "Login with GitHub Copilot",
          prompts: [
            {
              type: "select",
              key: "deploymentType",
              message: "Select GitHub deployment type",
              options: [
                {
                  label: "GitHub.com",
                  value: "github.com",
                  hint: "Public",
                },
                {
                  label: "GitHub Enterprise",
                  value: "enterprise",
                  hint: "Data residency or self-hosted",
                },
              ],
            },
            {
              type: "text",
              key: "enterpriseUrl",
              message: "Enter your GitHub Enterprise URL or domain",
              placeholder: "company.ghe.com or https://company.ghe.com",
              condition: (inputs) => inputs.deploymentType === "enterprise",
              validate: (value) => {
                if (!value) return "URL or domain is required"
                try {
                  const url = value.includes("://") ? new URL(value) : new URL(`https://${value}`)
                  if (!url.hostname) return "Please enter a valid URL or domain"
                  return undefined
                } catch {
                  return "Please enter a valid URL (e.g., company.ghe.com or https://company.ghe.com)"
                }
              },
            },
          ],
          async authorize(inputs = {}) {
            const deploymentType = inputs.deploymentType || "github.com"

            let domain = "github.com"
            let actualProvider = "github-copilot"

            if (deploymentType === "enterprise") {
              const enterpriseUrl = inputs.enterpriseUrl
              domain = normalizeDomain(enterpriseUrl!)
              actualProvider = "github-copilot-enterprise"
            }

            const urls = getUrls(domain)

            const deviceResponse = await fetch(urls.DEVICE_CODE_URL, {
              method: "POST",
              headers: {
                Accept: "application/json",
                "Content-Type": "application/json",
                "User-Agent": `nikcli/${Installation.VERSION}`,
              },
              body: JSON.stringify({
                client_id: CLIENT_ID,
                scope: "read:user",
              }),
            })

            if (!deviceResponse.ok) {
              throw new Error("Failed to initiate device authorization")
            }

            const deviceData = (await deviceResponse.json()) as {
              verification_uri: string
              user_code: string
              device_code: string
              interval: number
            }

            return {
              url: deviceData.verification_uri,
              instructions: `Enter code: ${deviceData.user_code}`,
              method: "auto" as const,
              async callback() {
                while (true) {
                  const response = await fetch(urls.ACCESS_TOKEN_URL, {
                    method: "POST",
                    headers: {
                      Accept: "application/json",
                      "Content-Type": "application/json",
                      "User-Agent": `nikcli/${Installation.VERSION}`,
                    },
                    body: JSON.stringify({
                      client_id: CLIENT_ID,
                      device_code: deviceData.device_code,
                      grant_type: "urn:ietf:params:oauth:grant-type:device_code",
                    }),
                  })

                  if (!response.ok) return { type: "failed" as const }

                  const data = (await response.json()) as {
                    access_token?: string
                    error?: string
                    interval?: number
                  }

                  if (data.access_token) {
                    const result: {
                      type: "success"
                      refresh: string
                      access: string
                      expires: number
                      provider?: string
                      enterpriseUrl?: string
                    } = {
                      type: "success",
                      refresh: data.access_token,
                      access: data.access_token,
                      expires: 0,
                    }

                    if (actualProvider === "github-copilot-enterprise") {
                      result.provider = "github-copilot-enterprise"
                      result.enterpriseUrl = domain
                    }

                    return result
                  }

                  if (data.error === "authorization_pending") {
                    await Bun.sleep(deviceData.interval * 1000 + OAUTH_POLLING_SAFETY_MARGIN_MS)
                    continue
                  }

                  if (data.error === "slow_down") {
                    let newInterval = (deviceData.interval + 5) * 1000

                    const serverInterval = data.interval
                    if (serverInterval && typeof serverInterval === "number" && serverInterval > 0) {
                      newInterval = serverInterval * 1000
                    }

                    await Bun.sleep(newInterval + OAUTH_POLLING_SAFETY_MARGIN_MS)
                    continue
                  }

                  if (data.error) return { type: "failed" as const }

                  await Bun.sleep(deviceData.interval * 1000 + OAUTH_POLLING_SAFETY_MARGIN_MS)
                  continue
                }
              },
            }
          },
        },
      ],
    },
  }
}

import { BusEvent } from "@/bus/bus-event"
import path from "path"
import { $ } from "bun"
import z from "zod"
import { NamedError } from "@nikcli-ai/util/error"
import { Log } from "../util/log"
import { iife } from "@/util/iife"
import { Flag } from "../flag/flag"

declare global {
  const NIKCLI_VERSION: string
  const NIKCLI_CHANNEL: string
}

export namespace Installation {
  const log = Log.create({ service: "installation" })

  export type Method = Awaited<ReturnType<typeof method>>

  export const Event = {
    Updated: BusEvent.define(
      "installation.updated",
      z.object({
        version: z.string(),
      }),
    ),
    UpdateAvailable: BusEvent.define(
      "installation.update-available",
      z.object({
        version: z.string(),
      }),
    ),
  }

  export const Info = z
    .object({
      version: z.string(),
      latest: z.string(),
    })
    .meta({
      ref: "InstallationInfo",
    })
  export type Info = z.infer<typeof Info>

  export async function info() {
    return {
      version: VERSION,
      latest: await latest(),
    }
  }

  export function isPreview() {
    return CHANNEL !== "latest"
  }

  export function isLocal() {
    return CHANNEL === "local"
  }

  export async function method() {
    if (process.execPath.includes(path.join(".nikcli", "bin"))) return "curl"
    if (process.execPath.includes(path.join(".local", "bin"))) return "curl"
    const exec = process.execPath.toLowerCase()

    const checks = [
      {
        name: "npm" as const,
        command: () => $`npm list -g --depth=0`.throws(false).quiet().text(),
      },
      {
        name: "yarn" as const,
        command: () => $`yarn global list`.throws(false).quiet().text(),
      },
      {
        name: "pnpm" as const,
        command: () => $`pnpm list -g --depth=0`.throws(false).quiet().text(),
      },
      {
        name: "bun" as const,
        command: () => $`bun pm ls -g`.throws(false).quiet().text(),
      },
      {
        name: "brew" as const,
        command: () => $`brew list --formula nikcli`.throws(false).quiet().text(),
      },
      {
        name: "scoop" as const,
        command: () => $`scoop list nikcli`.throws(false).quiet().text(),
      },
      {
        name: "choco" as const,
        command: () => $`choco list --limit-output nikcli`.throws(false).quiet().text(),
      },
    ]

    checks.sort((a, b) => {
      const aMatches = exec.includes(a.name)
      const bMatches = exec.includes(b.name)
      if (aMatches && !bMatches) return -1
      if (!aMatches && bMatches) return 1
      return 0
    })

    for (const check of checks) {
      const output = await check.command()
      const installedName =
        check.name === "brew" || check.name === "choco" || check.name === "scoop" ? "nikcli" : "nikcli-ai"
      if (output.includes(installedName)) {
        return check.name
      }
    }

    return "unknown"
  }

  export const UpgradeFailedError = NamedError.create(
    "UpgradeFailedError",
    z.object({
      stderr: z.string(),
    }),
  )

  async function getBrewFormula() {
    const tapFormula = await $`brew list --formula nikomatt69/tap/nikcli`.throws(false).quiet().text()
    if (tapFormula.includes("nikcli")) return "nikomatt69/tap/nikcli"
    const coreFormula = await $`brew list --formula nikcli`.throws(false).quiet().text()
    if (coreFormula.includes("nikcli")) return "nikcli"
    return "nikcli"
  }

  export async function upgrade(method: Method, target: string) {
    let cmd
    switch (method) {
      case "curl":
        cmd = $`curl -fsSL https://nikcli.store/install | bash`.env({
          ...process.env,
          VERSION: target,
        })
        break
      case "npm":
        cmd = $`npm install -g nikcli-ai@${target}`
        break
      case "pnpm":
        cmd = $`pnpm install -g nikcli-ai@${target}`
        break
      case "bun":
        cmd = $`bun install -g nikcli-ai@${target}`
        break
      case "brew": {
        const formula = await getBrewFormula()
        cmd = $`brew upgrade ${formula}`.env({
          HOMEBREW_NO_AUTO_UPDATE: "1",
          ...process.env,
        })
        break
      }
      case "choco":
        cmd = $`echo Y | choco upgrade nikcli --version=${target}`
        break
      case "scoop":
        cmd = $`scoop install nikcli@${target}`
        break
      default:
        throw new Error(`Unknown method: ${method}`)
    }
    const result = await cmd.quiet().throws(false)
    if (result.exitCode !== 0) {
      const stderr = method === "choco" ? "not running from an elevated command shell" : result.stderr.toString("utf8")
      throw new UpgradeFailedError({
        stderr: stderr,
      })
    }
    log.info("upgraded", {
      method,
      target,
      stdout: result.stdout.toString(),
      stderr: result.stderr.toString(),
    })
    await $`${process.execPath} --version`.nothrow().quiet().text()
  }

  export const VERSION = typeof NIKCLI_VERSION === "string" ? NIKCLI_VERSION : "local"
  export const CHANNEL = typeof NIKCLI_CHANNEL === "string" ? NIKCLI_CHANNEL : "local"
  export const USER_AGENT = `nikcli/${CHANNEL}/${VERSION}/${Flag.NIKCLI_CLIENT}`

  export async function latest(installMethod?: Method) {
    const detectedMethod = installMethod || (await method())

    if (detectedMethod === "brew") {
      const formula = await getBrewFormula()
      if (formula === "nikcli") {
        return fetch("https://formulae.brew.sh/api/formula/nikcli.json")
          .then((res) => {
            if (!res.ok) throw new Error(res.statusText)
            return res.json()
          })
          .then((data: any) => data.versions.stable)
      }
    }

    if (detectedMethod === "npm" || detectedMethod === "bun" || detectedMethod === "pnpm") {
      const registry = await iife(async () => {
        const r = (await $`npm config get registry`.quiet().nothrow().text()).trim()
        const reg = r || "https://registry.npmjs.org"
        return reg.endsWith("/") ? reg.slice(0, -1) : reg
      })
      const channel = CHANNEL
      return fetch(`${registry}/nikcli-ai/${channel}`)
        .then((res) => {
          if (!res.ok) throw new Error(res.statusText)
          return res.json()
        })
        .then((data: any) => data.version)
    }

    if (detectedMethod === "choco") {
      return fetch(
        "https://community.chocolatey.org/api/v2/Packages?$filter=Id%20eq%20%27nikcli%27%20and%20IsLatestVersion&$select=Version",
        { headers: { Accept: "application/json;odata=verbose" } },
      )
        .then((res) => {
          if (!res.ok) throw new Error(res.statusText)
          return res.json()
        })
        .then((data: any) => data.d.results[0].Version)
    }

    if (detectedMethod === "scoop") {
      return fetch("https://raw.githubusercontent.com/ScoopInstaller/Main/master/bucket/nikcli.json", {
        headers: { Accept: "application/json" },
      })
        .then((res) => {
          if (!res.ok) throw new Error(res.statusText)
          return res.json()
        })
        .then((data: any) => data.version)
    }

    return fetch("https://api.github.com/repos/nikomatt69/nikcli/releases/latest")
      .then((res) => {
        if (!res.ok) throw new Error(res.statusText)
        return res.json()
      })
      .then((data: any) => data.tag_name.replace(/^v/, ""))
  }
}

import { Flag } from "@/flag/flag"
import { lazy } from "@/util/lazy"
import path from "path"
import { spawn, type ChildProcess } from "child_process"

const SIGKILL_TIMEOUT_MS = 200

export namespace Shell {
  export async function killTree(proc: ChildProcess, opts?: { exited?: () => boolean }): Promise<void> {
    const pid = proc.pid
    if (!pid || opts?.exited?.()) return

    if (process.platform === "win32") {
      await new Promise<void>((resolve) => {
        const killer = spawn("taskkill", ["/pid", String(pid), "/f", "/t"], { stdio: "ignore" })
        killer.once("exit", () => resolve())
        killer.once("error", () => resolve())
      })
      return
    }

    try {
      process.kill(-pid, "SIGTERM")
      await Bun.sleep(SIGKILL_TIMEOUT_MS)
      if (!opts?.exited?.()) {
        process.kill(-pid, "SIGKILL")
      }
    } catch (_e) {
      proc.kill("SIGTERM")
      await Bun.sleep(SIGKILL_TIMEOUT_MS)
      if (!opts?.exited?.()) {
        proc.kill("SIGKILL")
      }
    }
  }
  const BLACKLIST = new Set(["fish", "nu"])

  function fallback() {
    if (process.platform === "win32") {
      if (Flag.NIKCLI_GIT_BASH_PATH) return Flag.NIKCLI_GIT_BASH_PATH
      const git = Bun.which("git")
      if (git) {
        const bash = path.join(git, "..", "..", "bin", "bash.exe")
        if (Bun.file(bash).size) return bash
      }
      return process.env.COMSPEC || "cmd.exe"
    }
    if (process.platform === "darwin") return "/bin/zsh"
    const bash = Bun.which("bash")
    if (bash) return bash
    return "/bin/sh"
  }

  export const preferred = lazy(() => {
    const s = process.env.SHELL
    if (s) return s
    return fallback()
  })

  export const acceptable = lazy(() => {
    const s = process.env.SHELL
    if (s && !BLACKLIST.has(process.platform === "win32" ? path.win32.basename(s) : path.basename(s))) return s
    return fallback()
  })
}

import path from "path"
import { mkdir } from "fs/promises"
import { randomUUID } from "crypto"
import TurndownService from "turndown"
import { Global } from "@/global"

export type DocEntry = {
  id: string
  url: string
  title: string
  content: string
  category: string
  tags: string[]
  addedAt: number
}

export type DocSearchResult = {
  entry: DocEntry
  score: number
  snippet: string
  terms: string[]
}

const DIR = path.join(Global.Path.data, "docs")
const LIB = path.join(DIR, "library.json")
const MAX_CONTENT = 60000
const MIN_CONTENT = 200

const turndown = new TurndownService({
  codeBlockStyle: "fenced",
  headingStyle: "atx",
})

async function ensureDir() {
  await mkdir(DIR, { recursive: true })
}

async function readAll(): Promise<DocEntry[]> {
  const file = Bun.file(LIB)
  const exists = await file.exists()
  if (!exists) return []
  const data = await file.json()
  const list = Array.isArray(data) ? data : []
  return list as DocEntry[]
}

async function writeAll(list: DocEntry[]): Promise<void> {
  await ensureDir()
  await Bun.write(LIB, JSON.stringify(list, null, 2))
}

function cleanHtml(html: string): string {
  const noScript = html.replace(/<script[^>]*>[\s\S]*?<\/script>/gi, " ")
  const noStyle = noScript.replace(/<style[^>]*>[\s\S]*?<\/style>/gi, " ")
  return noStyle
}

function toText(html: string): string {
  const cleaned = cleanHtml(html)
  const text = turndown.turndown(cleaned)
  return text.replace(/\n{3,}/g, "\n\n").trim()
}

function getTitle(html: string, url: string): string {
  const match = html.match(/<title[^>]*>([^<]+)<\/title>/i)
  if (match?.[1]) return match[1].trim().slice(0, 120)
  return url
}

function normalize(text: string): string {
  return text
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, " ")
    .replace(/\s+/g, " ")
    .trim()
}

function terms(text: string): string[] {
  const list = normalize(text).split(" ").filter(Boolean)
  if (list.length === 0) return []
  return Array.from(new Set(list))
}

function score(entry: DocEntry, query: string): { score: number; terms: string[] } {
  const items = terms(query)
  if (items.length === 0) return { score: 0, terms: [] }
  const title = normalize(entry.title)
  const body = normalize(entry.content)
  const tags = entry.tags.map((tag) => normalize(tag)).join(" ")
  const base = items.reduce((sum, item) => {
    const inTitle = title.includes(item) ? 2 : 0
    const inBody = body.includes(item) ? 1 : 0
    const inTags = tags.includes(item) ? 1 : 0
    return sum + inTitle + inBody + inTags
  }, 0)
  const value = base / items.length
  return { score: value, terms: items }
}

function snippet(entry: DocEntry, query: string): string {
  const items = terms(query)
  const text = entry.content
  const lower = text.toLowerCase()
  const idx = items
    .map((item) => lower.indexOf(item))
    .filter((val) => val >= 0)
    .sort((a, b) => a - b)[0]
  if (idx === undefined) return text.slice(0, 200)
  const start = Math.max(0, idx - 80)
  const end = Math.min(text.length, idx + 140)
  return text.slice(start, end).replace(/\s+/g, " ").trim()
}

function match(entry: DocEntry, key: string): boolean {
  const lower = key.toLowerCase()
  if (entry.id === key) return true
  if (entry.url.toLowerCase().includes(lower)) return true
  if (entry.title.toLowerCase().includes(lower)) return true
  if (entry.tags.some((tag) => tag.toLowerCase().includes(lower))) return true
  return false
}

export async function addDoc(input: { url: string; category?: string; tags?: string[] }): Promise<DocEntry> {
  const res = await fetch(input.url)
  if (!res.ok) {
    throw new Error(`Docs fetch failed: ${res.status} ${res.statusText}`)
  }
  const html = await res.text()
  const title = getTitle(html, input.url)
  const text = toText(html)
  if (text.length < MIN_CONTENT) {
    throw new Error("Docs content too short to index")
  }

  const entry: DocEntry = {
    id: randomUUID(),
    url: input.url,
    title,
    content: text.slice(0, MAX_CONTENT),
    category: input.category || "general",
    tags: (input.tags ?? []).filter(Boolean),
    addedAt: Date.now(),
  }

  await ensureDir()
  const list = await readAll()
  const next = [entry, ...list]
  await writeAll(next)
  return entry
}

export async function listDocs(category?: string): Promise<DocEntry[]> {
  const list = await readAll()
  if (!category) return list
  return list.filter((item) => item.category === category)
}

export async function getAllDocs(): Promise<DocEntry[]> {
  return readAll()
}

export async function getDoc(key: string): Promise<DocEntry | undefined> {
  const list = await readAll()
  return list.find((entry) => match(entry, key))
}

export async function getDocs(keys: string[]): Promise<DocEntry[]> {
  const list = await readAll()
  return list.filter((entry) => keys.some((key) => match(entry, key)))
}

export async function searchDocs(query: string, category?: string, limit = 5): Promise<DocSearchResult[]> {
  const list = await readAll()
  const items = category ? list.filter((item) => item.category === category) : list
  const scored = items
    .map((entry) => {
      const result = score(entry, query)
      return {
        entry,
        score: result.score,
        snippet: snippet(entry, query),
        terms: result.terms,
      }
    })
    .filter((item) => item.score > 0)
    .sort((a, b) => b.score - a.score)
    .slice(0, limit)
  return scored
}

import path from "path"
import { mkdir } from "fs/promises"
import { Global } from "@/global"
import { getAllDocs, type DocEntry } from "./library"

type DocsContext = {
  ids: string[]
  updatedAt: number
}

const DIR = path.join(Global.Path.data, "docs")
const FILE = path.join(DIR, "context.json")
const MAX_SUMMARY_CHARS = 4000
const MAX_FULL_CHARS = 20000

async function ensureDir() {
  await mkdir(DIR, { recursive: true })
}

async function readContext(): Promise<DocsContext> {
  const file = Bun.file(FILE)
  const exists = await file.exists()
  if (!exists) return { ids: [], updatedAt: Date.now() }
  const data = await file.json().catch(() => null)
  if (!data || !Array.isArray(data.ids)) return { ids: [], updatedAt: Date.now() }
  return {
    ids: data.ids,
    updatedAt: typeof data.updatedAt === "number" ? data.updatedAt : Date.now(),
  }
}

async function writeContext(context: DocsContext): Promise<void> {
  await ensureDir()
  await Bun.write(FILE, JSON.stringify(context, null, 2))
}

function unique(ids: string[]): string[] {
  return Array.from(new Set(ids))
}

export async function loadDocs(ids: string[]): Promise<{ loaded: DocEntry[]; missing: string[] }> {
  const ctx = await readContext()
  const all = await getAllDocs()
  const valid = all.filter((entry) => ids.some((id) => matches(entry, id)))
  const foundIds = valid.map((entry) => entry.id)
  const missing = ids.filter((id) => !all.some((entry) => matches(entry, id)))
  const next = unique([...ctx.ids, ...foundIds])
  await writeContext({ ids: next, updatedAt: Date.now() })
  return { loaded: valid, missing }
}

export async function unloadDocs(ids?: string[]): Promise<{ removed: string[] }> {
  const ctx = await readContext()
  if (!ids || ids.length === 0) {
    await writeContext({ ids: [], updatedAt: Date.now() })
    return { removed: ctx.ids }
  }
  const all = await getAllDocs()
  const loaded = ctx.ids
    .map((id) => all.find((entry) => entry.id === id))
    .filter((entry): entry is DocEntry => Boolean(entry))
  const toRemove = loaded.filter((entry) => ids.some((id) => matches(entry, id))).map((entry) => entry.id)
  const removed = ctx.ids.filter((id) => toRemove.includes(id))
  const next = ctx.ids.filter((id) => !toRemove.includes(id))
  await writeContext({ ids: next, updatedAt: Date.now() })
  return { removed }
}

export async function getLoadedDocs(): Promise<DocEntry[]> {
  const ctx = await readContext()
  if (ctx.ids.length === 0) return []
  const docs = await getAllDocs()
  const sorted = ctx.ids
    .map((id) => docs.find((entry) => entry.id === id))
    .filter((entry): entry is DocEntry => Boolean(entry))
  return sorted
}

function summaryLine(entry: DocEntry): string {
  const tags = entry.tags.length > 0 ? ` tags: ${entry.tags.join(", ")}` : ""
  return `- ${entry.title} (${entry.category})${tags}`
}

function matches(entry: DocEntry, key: string): boolean {
  const lower = key.toLowerCase()
  if (entry.id === key) return true
  if (entry.url.toLowerCase().includes(lower)) return true
  if (entry.title.toLowerCase().includes(lower)) return true
  if (entry.tags.some((tag) => tag.toLowerCase().includes(lower))) return true
  return false
}

export async function getContextSummary(): Promise<string> {
  const docs = await getLoadedDocs()
  if (docs.length === 0) return "No documentation loaded."
  const lines = docs.map(summaryLine)
  const summary = `Documentation context (${docs.length} docs)\n` + lines.join("\n")
  if (summary.length <= MAX_SUMMARY_CHARS) return summary
  return summary.slice(0, MAX_SUMMARY_CHARS) + "\n[summary truncated]"
}

export async function getFullContext(): Promise<string> {
  const docs = await getLoadedDocs()
  if (docs.length === 0) return ""
  const chunks = docs.map((entry) => {
    return [
      `## ${entry.title}`,
      `Category: ${entry.category}`,
      entry.tags.length > 0 ? `Tags: ${entry.tags.join(", ")}` : "",
      entry.url ? `Source: ${entry.url}` : "",
      "",
      entry.content,
    ]
      .filter(Boolean)
      .join("\n")
  })
  const content = `# DOCUMENTATION CONTEXT\n\n` + chunks.join("\n\n---\n\n")
  if (content.length <= MAX_FULL_CHARS) return content
  return content.slice(0, MAX_FULL_CHARS) + "\n[context truncated]"
}

