export const RagModelCommand = cmd({
  command: "rag-model [provider] [model]",
  describe: "list or set RAG embedding models",
  builder: (yargs: Argv) => {
    return yargs
      .positional("provider", {
        describe: "provider ID to filter embedding models by (e.g., ollama, openai, google)",
        type: "string",
      })
      .positional("model", {
        describe: "embedding model to set (e.g., nomic-embed-text for Ollama, text-embedding-3-small for OpenAI)",
        type: "string",
      })
      .option("reset", {
        describe: "reset RAG config to defaults",
        type: "boolean",
        default: false,
      })
      .option("global", {
        describe: "edit global config instead of project config",
        type: "boolean",
        default: false,
      })
      .option("refresh", {
        describe: "refresh the models cache from models.dev",
        type: "boolean",
        default: false,
      })
  },
  handler: async (args) => {
    await Instance.provide({
      directory: process.cwd(),
      async fn() {
        if (args.refresh) {
          await ModelsDev.refresh()
          UI.println(UI.Style.TEXT_SUCCESS_BOLD + "Models cache refreshed" + UI.Style.TEXT_NORMAL)
        }

        const configState = await Config.state()
        const config = configState.config

        if (args.reset) {
          delete config.rag
          await saveConfig(config, args.global)
          UI.println(UI.Style.TEXT_SUCCESS_BOLD + "RAG config reset to defaults" + UI.Style.TEXT_NORMAL)
          return
        }

        if (args.model || args.provider) {
          config.rag = {
            model: args.model ?? config.rag?.model,
            provider: args.provider ?? config.rag?.provider,
          }
          await saveConfig(config, args.global)
          UI.println(UI.Style.TEXT_SUCCESS_BOLD + "RAG config updated" + UI.Style.TEXT_NORMAL)
          UI.println(`  model: ${config.rag.model}`)
          if (config.rag.provider) {
            UI.println(`  provider: ${config.rag.provider}`)
          }
          return
        }

        const providers = await Provider.list()
        const current = config.rag

        UI.println("Current RAG config:")
        UI.println(`  model: ${current?.model ?? "(default: all-minilm)"}`)
        UI.println(`  provider: ${current?.provider ?? "(default: ollama)"}`)
        UI.println("")

        const embedProviders = Object.entries(providers).filter(([, p]) =>
          Object.keys(p.models).some((m) => m.includes("embed") || m.includes("embedding")),
        )

        const hasCloudModels = embedProviders.length > 0
        const hasOllama = OLLAMA_EMBED_MODELS.length > 0
        const hasLocal = LOCAL_EMBED_MODELS.length > 0
        const hasAnyModels = hasCloudModels || hasOllama || hasLocal

        if (!hasAnyModels) {
          UI.println("No embedding models found in cache. Use --refresh to fetch from models.dev")
          return
        }

        UI.println("Available embedding models:")
        UI.println("")

        for (const [providerID, provider] of embedProviders.sort((a, b) => a[0].localeCompare(b[0]))) {
          const embedModels = Object.entries(provider.models)
            .filter(([m]) => m.includes("embed") || m.includes("embedding"))
            .sort(([a], [b]) => a.localeCompare(b))

          for (const [modelID, model] of embedModels) {
            const isCurrent = providerID === current?.provider && modelID === current?.model
            const prefix = isCurrent ? "* " : "  "
            UI.println(`${prefix}${providerID}/${modelID}`)
          }
        }

        for (const { provider, models } of LOCAL_EMBED_MODELS) {
          const alreadyShown = embedProviders.some(([p]) => p === provider)
          if (alreadyShown) continue

          UI.println(`  ${provider}`)
          for (const model of models) {
            const isCurrent = current?.provider === provider && current?.model === model
            const prefix = isCurrent ? "  * " : "    "
            UI.println(`${prefix}${model}`)
          }
        }

        if (hasOllama) {
          UI.println("  ollama")
          for (const model of OLLAMA_EMBED_MODELS) {
            const isCurrent = current?.provider === "ollama" && current?.model === model
            const prefix = isCurrent ? "  * " : "    "
            UI.println(`${prefix}${model}`)
          }
        }
      },
    })
  },
})

async function saveConfig(config: Config.Info, globalFlag: boolean) {
  const configPath = globalFlag
    ? path.join(Global.Path.config, "nikcli.jsonc")
    : path.join(process.cwd(), "nikcli.jsonc")

  const current = await Bun.file(configPath)
    .text()
    .catch(() => "{}")
  const parsed = JSON.parse(current || "{}")

  parsed.rag = config.rag

  await Bun.write(configPath, JSON.stringify(parsed, null, 2))
}

import type { Argv } from "yargs"
import { Session } from "../../session"
import { cmd } from "./cmd"
import { bootstrap } from "../bootstrap"
import { Storage } from "../../storage/storage"
import { Instance } from "../../project/instance"
import { EOL } from "os"

export const ImportCommand = cmd({
  command: "import <file>",
  describe: "import session data from JSON file or URL",
  builder: (yargs: Argv) => {
    return yargs.positional("file", {
      describe: "path to JSON file or nikcli.store share URL",
      type: "string",
      demandOption: true,
    })
  },
  handler: async (args) => {
    await bootstrap(process.cwd(), async () => {
      let exportData:
        | {
            info: Session.Info
            messages: Array<{
              info: any
              parts: any[]
            }>
          }
        | undefined

      const isUrl = args.file.startsWith("http://") || args.file.startsWith("https://")

      if (isUrl) {
        const urlMatch = args.file.match(/https?:\/\/nikcli\.store\/share\/([a-zA-Z0-9_-]+)/)
        if (!urlMatch) {
          process.stdout.write(`Invalid URL format. Expected: https://nikcli.store/share/<slug>`)
          process.stdout.write(EOL)
          return
        }

        const slug = urlMatch[1]
        const response = await fetch(`https://nikcli.store/api/share/${slug}`)

        if (!response.ok) {
          process.stdout.write(`Failed to fetch share data: ${response.statusText}`)
          process.stdout.write(EOL)
          return
        }

        const data = await response.json()

        if (!data.info || !data.messages || Object.keys(data.messages).length === 0) {
          process.stdout.write(`Share not found: ${slug}`)
          process.stdout.write(EOL)
          return
        }

        exportData = {
          info: data.info,
          messages: Object.values(data.messages).map((msg: any) => {
            const { parts, ...info } = msg
            return {
              info,
              parts,
            }
          }),
        }
      } else {
        const file = Bun.file(args.file)
        exportData = await file.json().catch(() => {})
        if (!exportData) {
          process.stdout.write(`File not found: ${args.file}`)
          process.stdout.write(EOL)
          return
        }
      }

      if (!exportData) {
        process.stdout.write(`Failed to read session data`)
        process.stdout.write(EOL)
        return
      }

      await Storage.write(["session", Instance.project.id, exportData.info.id], exportData.info)

      for (const msg of exportData.messages) {
        await Storage.write(["message", exportData.info.id, msg.info.id], msg.info)

        for (const part of msg.parts) {
          await Storage.write(["part", msg.info.id, part.id], part)
        }
      }

      process.stdout.write(`Imported session: ${exportData.info.id}`)
      process.stdout.write(EOL)
    })
  },
})

export interface CacheEntry<T> {
  value: T
  expiresAt: number
}

const STATUS_CACHE_TTL = 5 * 60 * 1000
const TOOLS_CACHE_TTL = 2 * 60 * 1000

class Cache<T> {
  private cache: Map<string, CacheEntry<T>> = new Map()

  set(key: string, value: T, ttl: number): void {
    this.cache.set(key, {
      value,
      expiresAt: Date.now() + ttl,
    })
  }

  get(key: string): T | null {
    const entry = this.cache.get(key)
    if (!entry) return null

    if (Date.now() > entry.expiresAt) {
      this.cache.delete(key)
      return null
    }

    return entry.value
  }

  invalidate(key: string): void {
    this.cache.delete(key)
  }

  clear(): void {
    this.cache.clear()
  }
}

const statusCache = new Cache<Record<string, any>>()
const toolsCache = new Cache<Record<string, any>>()
const configHashCache = new Cache<string>()

function normalize(value: unknown): unknown {
  if (Array.isArray(value)) {
    return value.map((item) => normalize(item))
  }

  if (value && typeof value === "object") {
    const entries = Object.entries(value as Record<string, unknown>).sort(([a], [b]) => a.localeCompare(b))
    return Object.fromEntries(entries.map(([key, entry]) => [key, normalize(entry)]))
  }

  return value
}

function getConfigHash(config: any): string {
  return JSON.stringify(normalize(config?.connectors ?? {}))
}

async function getCachedOrCompute<T>(
  cache: Cache<T>,
  key: string,
  compute: () => Promise<T>,
  ttl: number,
  config?: any,
): Promise<T> {
  const currentHash = config ? getConfigHash(config) : null

  if (currentHash) {
    const cachedHash = configHashCache.get(key)

    if (cachedHash && cachedHash !== currentHash) {
      cache.invalidate(key)
      configHashCache.invalidate(key)
    }
  }

  const cached = cache.get(key)
  if (cached !== null) return cached

  const result = await compute()
  cache.set(key, result, ttl)

  if (currentHash) {
    configHashCache.set(key, currentHash, ttl)
  }

  return result
}

export function invalidateStatusCache(): void {
  statusCache.clear()
}

export function invalidateToolsCache(): void {
  toolsCache.clear()
}

export function invalidateConnectorCache(_connectorName: string): void {
  statusCache.invalidate("connectors_status")
  toolsCache.invalidate("connectors_tools")
}

export function getCachedStatus(
  key: string,
  compute: () => Promise<Record<string, any>>,
  config?: any,
): Promise<Record<string, any>> {
  return getCachedOrCompute(statusCache, key, compute, STATUS_CACHE_TTL, config)
}

export function getCachedTools(
  key: string,
  compute: () => Promise<Record<string, any>>,
  config?: any,
): Promise<Record<string, any>> {
  return getCachedOrCompute(toolsCache, key, compute, TOOLS_CACHE_TTL, config)
}

