zenmux: async () => {
  return {
    autoload: false,
    options: {

        headers: {
          "HTTP-Referer": "https://nikcli.store/",
          "X-Title": "nikcli",
        },
      },
    }
  },
  gitlab: async (input) => {
    const instanceUrl = Env.get("GITLAB_INSTANCE_URL") || "https://gitlab.com"

    const auth = await Auth.get(input.id)
    const apiKey = await (async () => {
      if (auth?.type === "oauth") return auth.access
      if (auth?.type === "api") return auth.key
      return Env.get("GITLAB_TOKEN")
    })()

    const config = await Config.get()
    const providerConfig = config.provider?.["gitlab"]

    return {
      autoload: !!apiKey,
      options: {
        instanceUrl,
        apiKey,
        featureFlags: {
          duo_agent_platform_agentic_chat: true,
          duo_agent_platform: true,
          ...(providerConfig?.options?.featureFlags || {}),
        },
      },
      async getModel(sdk: ReturnType<typeof createGitLab>, modelID: string) {
        return sdk.agenticChat(modelID, {
          featureFlags: {
            duo_agent_platform_agentic_chat: true,
            duo_agent_platform: true,
            ...(providerConfig?.options?.featureFlags || {}),
          },
        })
      },
    }
  },
  "cloudflare-ai-gateway": async (input) => {
    const accountId = Env.get("CLOUDFLARE_ACCOUNT_ID")
    const gateway = Env.get("CLOUDFLARE_GATEWAY_ID")

    if (!accountId || !gateway) return { autoload: false }

    // Get API token from env or auth prompt
    const apiToken = await (async () => {
      const envToken = Env.get("CLOUDFLARE_API_TOKEN")
      if (envToken) return envToken
      const auth = await Auth.get(input.id)
      if (auth?.type === "api") return auth.key
      return undefined
    })()

    return {
      autoload: true,
      async getModel(sdk: any, modelID: string, _options?: Record<string, any>) {
        return sdk.languageModel(modelID)
      },
      options: {
        baseURL: `https://gateway.ai.cloudflare.com/v1/${accountId}/${gateway}/compat`,
        headers: {
          // Cloudflare AI Gateway uses cf-aig-authorization for authenticated gateways
          // This enables Unified Billing where Cloudflare handles upstream provider auth
          ...(apiToken ? { "cf-aig-authorization": `Bearer ${apiToken}` } : {}),
          "HTTP-Referer": "https://nikcli.store/",
          "X-Title": "nikcli",
        },
        // Custom fetch to handle parameter transformation and auth
        fetch: async (input: RequestInfo | URL, init?: RequestInit) => {
          const headers = new Headers(init?.headers)
          // Strip Authorization header - AI Gateway uses cf-aig-authorization instead
          headers.delete("Authorization")

          // Transform max_tokens to max_completion_tokens for newer models
          if (init?.body && init.method === "POST") {
            try {
              const body = JSON.parse(init.body as string)
              if (body.max_tokens !== undefined && !body.max_completion_tokens) {
                body.max_completion_tokens = body.max_tokens
                delete body.max_tokens
                init = { ...init, body: JSON.stringify(body) }
              }
            } catch (e) {
              // If body parsing fails, continue with original request
            }
          }

          return fetch(input, { ...init, headers })
        },
      },
    }
  },
  cerebras: async () => {
    return {
      autoload: false,
      options: {
        headers: {
          "X-Cerebras-3rd-Party-Integration": "nikcli",
        },
      },
    }
  },
}

export const Model = z
  .object({
    id: z.string(),
    providerID: z.string(),
    api: z.object({
      id: z.string(),
      url: z.string(),
      npm: z.string(),
    }),
    name: z.string(),
    family: z.string().optional(),
    capabilities: z.object({
      temperature: z.boolean(),
      reasoning: z.boolean(),
      attachment: z.boolean(),
      toolcall: z.boolean(),
      input: z.object({
        text: z.boolean(),
        audio: z.boolean(),
        image: z.boolean(),
        video: z.boolean(),
        pdf: z.boolean(),
      }),
      output: z.object({
        text: z.boolean(),
        audio: z.boolean(),
        image: z.boolean(),
        video: z.boolean(),
        pdf: z.boolean(),
      }),
      interleaved: z.union([
        z.boolean(),
        z.object({
          field: z.enum(["reasoning_content", "reasoning_details"]),
        }),
      ]),
    }),
    cost: z.object({
      input: z.number(),
      output: z.number(),
      cache: z.object({
        read: z.number(),
        write: z.number(),
      }),
      experimentalOver200K: z
        .object({
          input: z.number(),
          output: z.number(),
          cache: z.object({
            read: z.number(),
            write: z.number(),
          }),
        })
        .optional(),
    }),
    limit: z.object({
      context: z.number(),
      input: z.number().optional(),
      output: z.number(),
    }),
    status: z.enum(["alpha", "beta", "deprecated", "active"]),
    options: z.record(z.string(), z.any()),
    headers: z.record(z.string(), z.string()),
    release_date: z.string(),
    variants: z.record(z.string(), z.record(z.string(), z.any())).optional(),
  })
  .meta({
    ref: "Model",
  })
export type Model = z.infer<typeof Model>

export const Info = z
  .object({
    id: z.string(),
    name: z.string(),
    source: z.enum(["env", "config", "custom", "api"]),
    env: z.string().array(),
    key: z.string().optional(),
    options: z.record(z.string(), z.any()),
    models: z.record(z.string(), Model),
  })
  .meta({
    ref: "Provider",
  })
export type Info = z.infer<typeof Info>

function fromModelsDevModel(provider: ModelsDev.Provider, model: ModelsDev.Model): Model {
  const m: Model = {
    id: model.id,
    providerID: provider.id,
    name: model.name,
    family: model.family,

    api: {
      id: model.id,
      url: provider.api!,
      npm: iife(() => {
        if (provider.id.startsWith("github-copilot")) return "@ai-sdk/github-copilot"
        return model.provider?.npm ?? provider.npm ?? "@ai-sdk/openai-compatible"
      }),
    },
    status: model.status ?? "active",
    headers: model.headers ?? {},
    options: model.options ?? {},
    cost: {
      input: model.cost?.input ?? 0,
      output: model.cost?.output ?? 0,
      cache: {
        read: model.cost?.cache_read ?? 0,
        write: model.cost?.cache_write ?? 0,
      },
      experimentalOver200K: model.cost?.context_over_200k
        ? {
            cache: {
              read: model.cost.context_over_200k.cache_read ?? 0,
              write: model.cost.context_over_200k.cache_write ?? 0,
            },
            input: model.cost.context_over_200k.input,
            output: model.cost.context_over_200k.output,
          }
        : undefined,
    },
    limit: {
      context: model.limit.context,
      input: model.limit.input,
      output: model.limit.output,
    },
    capabilities: {
      temperature: model.temperature,
      reasoning: model.reasoning,
      attachment: model.attachment,
      toolcall: model.tool_call,
      input: {
        text: model.modalities?.input?.includes("text") ?? false,
        audio: model.modalities?.input?.includes("audio") ?? false,
        image: model.modalities?.input?.includes("image") ?? false,
        video: model.modalities?.input?.includes("video") ?? false,
        pdf: model.modalities?.input?.includes("pdf") ?? false,
      },
      output: {
        text: model.modalities?.output?.includes("text") ?? false,
        audio: model.modalities?.output?.includes("audio") ?? false,
        image: model.modalities?.output?.includes("image") ?? false,
        video: model.modalities?.output?.includes("video") ?? false,
        pdf: model.modalities?.output?.includes("pdf") ?? false,
      },
      interleaved: model.interleaved ?? false,
    },
    release_date: model.release_date,
    variants: {},
  }

  m.variants = mapValues(ProviderTransform.variants(m), (v) => v)

  return m
}

export function fromModelsDevProvider(provider: ModelsDev.Provider): Info {
  return {
    id: provider.id,
    source: "custom",
    name: provider.name,
    env: provider.env ?? [],
    options: {},
    models: mapValues(provider.models, (model) => fromModelsDevModel(provider, model)),
  }
}

const state = Instance.state(async () => {
  using _ = log.time("state")
  const config = await Config.get()
  const modelsDev = await ModelsDev.get()
  const database = mapValues(modelsDev, fromModelsDevProvider)

  const disabled = new Set(config.disabled_providers ?? [])
  const enabled = config.enabled_providers ? new Set(config.enabled_providers) : null

  function isProviderAllowed(providerID: string): boolean {
    if (enabled && !enabled.has(providerID)) return false
    if (disabled.has(providerID)) return false
    return true
  }

  const providers: { [providerID: string]: Info } = {}
  const languages = new Map<string, LanguageModelV2>()
  const modelLoaders: {
    [providerID: string]: CustomModelLoader
  } = {}
  const sdk = new Map<number, SDK>()

  log.info("init")

  const configProviders = Object.entries(config.provider ?? {})

  // Add GitHub Copilot Enterprise provider that inherits from GitHub Copilot
  if (database["github-copilot"]) {
    const githubCopilot = database["github-copilot"]
    database["github-copilot-enterprise"] = {
      ...githubCopilot,
      id: "github-copilot-enterprise",
      name: "GitHub Copilot Enterprise",
      models: mapValues(githubCopilot.models, (model) => ({
        ...model,
        providerID: "github-copilot-enterprise",
      })),
    }
  }

  function mergeProvider(providerID: string, provider: Partial<Info>) {
    const existing = providers[providerID]
    if (existing) {
      // @ts-expect-error
      providers[providerID] = mergeDeep(existing, provider)
      return
    }
    const match = database[providerID]
    if (!match) return
    // @ts-expect-error
    providers[providerID] = mergeDeep(match, provider)
  }

  // extend database from config
  for (const [providerID, provider] of configProviders) {
    const existing = database[providerID]
    const parsed: Info = {
      id: providerID,
      name: provider.name ?? existing?.name ?? providerID,
      env: provider.env ?? existing?.env ?? [],
      options: mergeDeep(existing?.options ?? {}, provider.options ?? {}),
      source: "config",
      models: existing?.models ?? {},
    }

    for (const [modelID, model] of Object.entries(provider.models ?? {})) {
      const existingModel = parsed.models[model.id ?? modelID]
      const name = iife(() => {
        if (model.name) return model.name
        if (model.id && model.id !== modelID) return modelID
        return existingModel?.name ?? modelID
      })
      const parsedModel: Model = {
        id: modelID,
        api: {
          id: model.id ?? existingModel?.api.id ?? modelID,
          npm:
            model.provider?.npm ??
            provider.npm ??
            existingModel?.api.npm ??
            modelsDev[providerID]?.npm ??
            "@ai-sdk/openai-compatible",
          url: provider?.api ?? existingModel?.api.url ?? modelsDev[providerID]?.api,
        },
        status: model.status ?? existingModel?.status ?? "active",
        name,
        providerID,
        capabilities: {
          temperature: model.temperature ?? existingModel?.capabilities.temperature ?? false,
          reasoning: model.reasoning ?? existingModel?.capabilities.reasoning ?? false,
          attachment: model.attachment ?? existingModel?.capabilities.attachment ?? false,
          toolcall: model.tool_call ?? existingModel?.capabilities.toolcall ?? true,
          input: {
            text: model.modalities?.input?.includes("text") ?? existingModel?.capabilities.input.text ?? true,
            audio: model.modalities?.input?.includes("audio") ?? existingModel?.capabilities.input.audio ?? false,
            image: model.modalities?.input?.includes("image") ?? existingModel?.capabilities.input.image ?? false,
            video: model.modalities?.input?.includes("video") ?? existingModel?.capabilities.input.video ?? false,
            pdf: model.modalities?.input?.includes("pdf") ?? existingModel?.capabilities.input.pdf ?? false,
          },
          output: {
            text: model.modalities?.output?.includes("text") ?? existingModel?.capabilities.output.text ?? true,
            audio: model.modalities?.output?.includes("audio") ?? existingModel?.capabilities.output.audio ?? false,
            image: model.modalities?.output?.includes("image") ?? existingModel?.capabilities.output.image ?? false,
            video: model.modalities?.output?.includes("video") ?? existingModel?.capabilities.output.video ?? false,
            pdf: model.modalities?.output?.includes("pdf") ?? existingModel?.capabilities.output.pdf ?? false,
          },
          interleaved: model.interleaved ?? false,
        },
        cost: {
          input: model?.cost?.input ?? existingModel?.cost?.input ?? 0,
          output: model?.cost?.output ?? existingModel?.cost?.output ?? 0,
          cache: {
            read: model?.cost?.cache_read ?? existingModel?.cost?.cache.read ?? 0,
            write: model?.cost?.cache_write ?? existingModel?.cost?.cache.write ?? 0,
          },
        },
        options: mergeDeep(existingModel?.options ?? {}, model.options ?? {}),
        limit: {
          context: model.limit?.context ?? existingModel?.limit?.context ?? 0,
          output: model.limit?.output ?? existingModel?.limit?.output ?? 0,
        },
        headers: mergeDeep(existingModel?.headers ?? {}, model.headers ?? {}),
        family: model.family ?? existingModel?.family ?? "",
        release_date: model.release_date ?? existingModel?.release_date ?? "",
        variants: {},

      }
      const merged = mergeDeep(ProviderTransform.variants(parsedModel), model.variants ?? {})
      parsedModel.variants = mapValues(
        pickBy(merged, (v) => !v.disabled),
        (v) => omit(v, ["disabled"]),
      )
      parsed.models[modelID] = parsedModel
    }
    database[providerID] = parsed
  }

  // load env
  const env = Env.all()
  for (const [providerID, provider] of Object.entries(database)) {
    if (disabled.has(providerID)) continue
    const apiKey = provider.env.map((item) => env[item]).find(Boolean)
    if (!apiKey) continue
    mergeProvider(providerID, {
      source: "env",
      key: provider.env.length === 1 ? apiKey : undefined,
    })
  }

  // load apikeys
  for (const [providerID, provider] of Object.entries(await Auth.all())) {
    if (disabled.has(providerID)) continue
    if (provider.type === "api") {
      mergeProvider(providerID, {
        source: "api",
        key: provider.key,
      })
    }
  }

  for (const plugin of await Plugin.list()) {
    if (!plugin.auth) continue
    const providerID = plugin.auth.provider
    if (disabled.has(providerID)) continue

    // For github-copilot plugin, check if auth exists for either github-copilot or github-copilot-enterprise
    let hasAuth = false
    const auth = await Auth.get(providerID)
    if (auth) hasAuth = true

    // Special handling for github-copilot: also check for enterprise auth
    if (providerID === "github-copilot" && !hasAuth) {
      const enterpriseAuth = await Auth.get("github-copilot-enterprise")
      if (enterpriseAuth) hasAuth = true
    }

    if (!hasAuth) continue
    if (!plugin.auth.loader) continue

    // Load for the main provider if auth exists
    if (auth) {
      const options = await plugin.auth.loader(() => Auth.get(providerID) as any, database[plugin.auth.provider])
      mergeProvider(plugin.auth.provider, {
        source: "custom",
        options: options,
      })
    }

    // If this is github-copilot plugin, also register for github-copilot-enterprise if auth exists
    if (providerID === "github-copilot") {
      const enterpriseProviderID = "github-copilot-enterprise"
      if (!disabled.has(enterpriseProviderID)) {
        const enterpriseAuth = await Auth.get(enterpriseProviderID)
        if (enterpriseAuth) {
          const enterpriseOptions = await plugin.auth.loader(
            () => Auth.get(enterpriseProviderID) as any,
            database[enterpriseProviderID],
          )
          mergeProvider(enterpriseProviderID, {
            source: "custom",
            options: enterpriseOptions,
          })
        }
      }
    }
  }

  for (const [providerID, fn] of Object.entries(CUSTOM_LOADERS)) {
    if (disabled.has(providerID)) continue
    const data = database[providerID]
    if (!data) {
      log.error("Provider does not exist in model list " + providerID)
      continue
    }
    const result = await fn(data)
    if (result && (result.autoload || providers[providerID])) {
      if (result.getModel) modelLoaders[providerID] = result.getModel
      mergeProvider(providerID, {
        source: "custom",
        options: result.options,
      })
    }
  }

  // load config
  for (const [providerID, provider] of configProviders) {
    const partial: Partial<Info> = { source: "config" }
    if (provider.env) partial.env = provider.env
    if (provider.name) partial.name = provider.name
    if (provider.options) partial.options = provider.options
    mergeProvider(providerID, partial)
  }

  for (const [providerID, provider] of Object.entries(providers)) {
    if (!isProviderAllowed(providerID)) {
      delete providers[providerID]
      continue
    }

    const configProvider = config.provider?.[providerID]

    for (const [modelID, model] of Object.entries(provider.models)) {
      model.api.id = model.api.id ?? model.id ?? modelID
      if (modelID === "gpt-5-chat-latest" || (providerID === "openrouter" && modelID === "openai/gpt-5-chat"))
        delete provider.models[modelID]
      if (model.status === "alpha" && !Flag.NIKCLI_ENABLE_EXPERIMENTAL_MODELS) delete provider.models[modelID]
      if (model.status === "deprecated") delete provider.models[modelID]
      if (
        (configProvider?.blacklist && configProvider.blacklist.includes(modelID)) ||
        (configProvider?.whitelist && !configProvider.whitelist.includes(modelID))
      )
        delete provider.models[modelID]

      // Filter out disabled variants from config
      const configVariants = configProvider?.models?.[modelID]?.variants
      if (configVariants && model.variants) {
        const merged = mergeDeep(model.variants, configVariants)
        model.variants = mapValues(
          pickBy(merged, (v) => !v.disabled),
          (v) => omit(v, ["disabled"]),
        )
      }
    }

    if (Object.keys(provider.models).length === 0) {
      delete providers[providerID]
      continue
    }

    log.info("found", { providerID })
  }

  return {
    models: languages,
    providers,
    sdk,
    modelLoaders,
  }
})

export async function list() {
  return state().then((state) => state.providers)
}

async function getSDK(model: Model) {
  try {
    using _ = log.time("getSDK", {
      providerID: model.providerID,
    })
    const s = await state()
    const provider = s.providers[model.providerID]
    const options = { ...provider.options }

    if (model.api.npm.includes("@ai-sdk/openai-compatible") && options["includeUsage"] !== false) {
      options["includeUsage"] = true
    }

    if (!options["baseURL"]) options["baseURL"] = model.api.url
    if (options["apiKey"] === undefined && provider.key) options["apiKey"] = provider.key
    if (model.headers)
      options["headers"] = {
        ...options["headers"],
        ...model.headers,
      }

    const key = Bun.hash.xxHash32(JSON.stringify({ npm: model.api.npm, options }))
    const existing = s.sdk.get(key)
    if (existing) return existing

    const customFetch = options["fetch"]

    options["fetch"] = async (input: any, init?: BunFetchRequestInit) => {
      // Preserve custom fetch if it exists, wrap it with timeout logic
      const fetchFn = customFetch ?? fetch
      const opts = init ?? {}

      if (options["timeout"] !== undefined && options["timeout"] !== null) {
        const signals: AbortSignal[] = []
        if (opts.signal) signals.push(opts.signal)
        if (options["timeout"] !== false) signals.push(AbortSignal.timeout(options["timeout"]))

        const combined = signals.length > 1 ? AbortSignal.any(signals) : signals[0]

        opts.signal = combined
      }

      // Strip openai itemId metadata following what codex does
      // Codex uses #[serde(skip_serializing)] on id fields for all item types:
      // Message, Reasoning, FunctionCall, LocalShellCall, CustomToolCall, WebSearchCall
      // IDs are only re-attached for Azure with store=true
      if (model.api.npm === "@ai-sdk/openai" && opts.body && opts.method === "POST") {
        const body = JSON.parse(opts.body as string)
        const isAzure = model.providerID.includes("azure")
        const keepIds = isAzure && body.store === true
        if (!keepIds && Array.isArray(body.input)) {
          for (const item of body.input) {
            if ("id" in item) {
              delete item.id
            }
          }
          opts.body = JSON.stringify(body)
        }
      }

      return fetchFn(input, {
        ...opts,
        // @ts-ignore see here: https://github.com/oven-sh/bun/issues/16682
        timeout: false,
      })
    }

    // Special case: google-vertex-anthropic uses a subpath import
    const bundledKey =
      model.providerID === "google-vertex-anthropic" ? "@ai-sdk/google-vertex/anthropic" : model.api.npm
    const bundledFn = BUNDLED_PROVIDERS[bundledKey]
    if (bundledFn) {
      log.info("using bundled provider", { providerID: model.providerID, pkg: bundledKey })
      const loaded = bundledFn({
        name: model.providerID,
        ...options,
      })
      s.sdk.set(key, loaded)
      return loaded as SDK
    }

    let installedPath: string
    if (!model.api.npm.startsWith("file://")) {
      installedPath = await BunProc.install(model.api.npm, "latest")
    } else {
      log.info("loading local provider", { pkg: model.api.npm })
      installedPath = model.api.npm
    }

    const mod = await import(installedPath)

    const fn = mod[Object.keys(mod).find((key) => key.startsWith("create"))!]
    const loaded = fn({
      name: model.providerID,
      ...options,
    })
    s.sdk.set(key, loaded)
    return loaded as SDK
  } catch (e) {
    throw new InitError({ providerID: model.providerID }, { cause: e })
  }
}

export async function getProvider(providerID: string) {
  return state().then((s) => s.providers[providerID])
}

export async function getModel(providerID: string, modelID: string) {
  const s = await state()
  const provider = s.providers[providerID]
  if (!provider) {
    const availableProviders = Object.keys(s.providers)
    const matches = fuzzysort.go(providerID, availableProviders, { limit: 3, threshold: -10000 })
    const suggestions = matches.map((m) => m.target)
    throw new ModelNotFoundError({ providerID, modelID, suggestions })
  }

  const info = provider.models[modelID]
  if (!info) {
    const availableModels = Object.keys(provider.models)
    const matches = fuzzysort.go(modelID, availableModels, { limit: 3, threshold: -10000 })
    const suggestions = matches.map((m) => m.target)
    throw new ModelNotFoundError({ providerID, modelID, suggestions })
  }
  return info
}

export async function getLanguage(model: Model): Promise<LanguageModelV2> {
  const s = await state()
  const key = `${model.providerID}/${model.id}`
  if (s.models.has(key)) return s.models.get(key)!

  const provider = s.providers[model.providerID]
  const sdk = await getSDK(model)

  try {
    const language = s.modelLoaders[model.providerID]
      ? await s.modelLoaders[model.providerID](sdk, model.api.id, provider.options)
      : sdk.languageModel(model.api.id)
    s.models.set(key, language)
    return language
  } catch (e) {
    if (e instanceof NoSuchModelError)
      throw new ModelNotFoundError(
        {
          modelID: model.id,
          providerID: model.providerID,
        },
        { cause: e },
      )
    throw e
  }
}

export async function closest(providerID: string, query: string[]) {
  const s = await state()
  const provider = s.providers[providerID]
  if (!provider) return undefined
  for (const item of query) {
    for (const modelID of Object.keys(provider.models)) {
      if (modelID.includes(item))
        return {
          providerID,
          modelID,
        }
    }
  }
}

export async function getSmallModel(providerID: string) {
  const cfg = await Config.get()

  if (cfg.small_model) {
    const parsed = parseModel(cfg.small_model)
    return getModel(parsed.providerID, parsed.modelID)
  }

  const provider = await state().then((state) => state.providers[providerID])
  if (provider) {
    let priority = [
      "claude-haiku-4-5",
      "claude-haiku-4.5",
      "3-5-haiku",
      "3.5-haiku",
      "gemini-3-flash",
      "gemini-2.5-flash",
      "gpt-5-nano",
    ]
    if (providerID.startsWith("nikcli")) {
      priority = ["gpt-5-nano"]
    }
    if (providerID.startsWith("github-copilot")) {
      // prioritize free models for github copilot
      priority = ["gpt-5-mini", "claude-haiku-4.5", ...priority]
    }
    for (const item of priority) {
      for (const model of Object.keys(provider.models)) {
        if (model.includes(item)) return getModel(providerID, model)
      }
    }
  }

  // Check if nikcli provider is available before using it
  const nikcliProvider = await state().then((state) => state.providers["nikcli"])
  if (nikcliProvider && nikcliProvider.models["gpt-5-nano"]) {
    return getModel("nikcli", "gpt-5-nano")
  }

  return undefined
}

const priority = ["gpt-5", "claude-sonnet-4", "big-pickle", "gemini-3-pro"]
export function sort(models: Model[]) {
  return sortBy(
    models,
    [(model) => priority.findIndex((filter) => model.id.includes(filter)), "desc"],
    [(model) => (model.id.includes("latest") ? 0 : 1), "asc"],
    [(model) => model.id, "desc"],
  )
}

export async function defaultModel() {
  const cfg = await Config.get()
  if (cfg.model) return parseModel(cfg.model)

  const provider = await list()
    .then((val) => Object.values(val))
    .then((x) => x.find((p) => !cfg.provider || Object.keys(cfg.provider).includes(p.id)))
  if (!provider) throw new Error("no providers found")
  const [model] = sort(Object.values(provider.models))
  if (!model) throw new Error("no models found")
  return {
    providerID: provider.id,
    modelID: model.id,
  }
}

export function parseModel(model: string) {
  const [providerID, ...rest] = model.split("/")
  return {
    providerID: providerID,
    modelID: rest.join("/"),

    }
  }

