import { TuiEvent } from "@/cli/cmd/tui/event"
import open from "open"

export namespace MCP {
  const log = Log.create({ service: "mcp" })
  const DEFAULT_TIMEOUT = 30_000

  export const Resource = z
    .object({
      name: z.string(),
      uri: z.string(),
      description: z.string().optional(),
      mimeType: z.string().optional(),
      client: z.string(),
    })
    .meta({ ref: "McpResource" })
  export type Resource = z.infer<typeof Resource>

  export const ToolsChanged = BusEvent.define(
    "mcp.tools.changed",
    z.object({
      server: z.string(),
    }),
  )

  export const BrowserOpenFailed = BusEvent.define(
    "mcp.browser.open.failed",
    z.object({
      mcpName: z.string(),
      url: z.string(),
    }),
  )

  export const Failed = NamedError.create(
    "MCPFailed",
    z.object({
      name: z.string(),
    }),
  )

  type MCPClient = Client

  export const Status = z
    .discriminatedUnion("status", [
      z
        .object({
          status: z.literal("connected"),
        })
        .meta({
          ref: "MCPStatusConnected",
        }),
      z
        .object({
          status: z.literal("disabled"),
        })
        .meta({
          ref: "MCPStatusDisabled",
        }),
      z
        .object({
          status: z.literal("failed"),
          error: z.string(),
        })
        .meta({
          ref: "MCPStatusFailed",
        }),
      z
        .object({
          status: z.literal("needs_auth"),
        })
        .meta({
          ref: "MCPStatusNeedsAuth",
        }),
      z
        .object({
          status: z.literal("needs_client_registration"),
          error: z.string(),
        })
        .meta({
          ref: "MCPStatusNeedsClientRegistration",
        }),
    ])
    .meta({
      ref: "MCPStatus",
    })
  export type Status = z.infer<typeof Status>

  function registerNotificationHandlers(client: MCPClient, serverName: string) {
    client.setNotificationHandler(ToolListChangedNotificationSchema, async () => {
      log.info("tools list changed notification received", { server: serverName })
      Bus.publish(ToolsChanged, { server: serverName })
    })
  }

  async function convertMcpTool(mcpTool: MCPToolDef, client: MCPClient, timeout?: number): Promise<Tool> {
    const inputSchema = mcpTool.inputSchema

    const schema: JSONSchema7 = {
      ...(inputSchema as JSONSchema7),
      type: "object",
      properties: (inputSchema.properties ?? {}) as JSONSchema7["properties"],
      additionalProperties: false,
    }

    return dynamicTool({
      description: mcpTool.description ?? "",
      inputSchema: jsonSchema(schema),
      execute: async (args: unknown) => {
        return client.callTool(
          {
            name: mcpTool.name,
            arguments: args as Record<string, unknown>,
          },
          CallToolResultSchema,
          {
            resetTimeoutOnProgress: true,
            timeout,
          },
        )
      },
    })
  }

  type TransportWithAuth = StreamableHTTPClientTransport | SSEClientTransport
  const pendingOAuthTransports = new Map<string, TransportWithAuth>()

  type PromptInfo = Awaited<ReturnType<MCPClient["listPrompts"]>>["prompts"][number]
  type ResourceInfo = Awaited<ReturnType<MCPClient["listResources"]>>["resources"][number]
  type McpEntry = NonNullable<Config.Info["mcp"]>[string]
  function isMcpConfigured(entry: McpEntry): entry is Config.Mcp {
    return typeof entry === "object" && entry !== null && "type" in entry
  }

  const state = Instance.state(
    async () => {
      const cfg = await Config.get()
      const config = cfg.mcp ?? {}
      const clients: Record<string, MCPClient> = {}
      const status: Record<string, Status> = {}

      await Promise.all(
        Object.entries(config).map(async ([key, mcp]) => {
          if (!isMcpConfigured(mcp)) {
            log.error("Ignoring MCP config entry without type", { key })
            return
          }

          if (mcp.enabled === false) {
            status[key] = { status: "disabled" }
            return
          }

          const result = await create(key, mcp).catch(() => undefined)
          if (!result) return

          status[key] = result.status

          if (result.mcpClient) {
            clients[key] = result.mcpClient
          }
        }),
      )
      return {
        status,
        clients,
      }
    },
    async (state) => {
      await Promise.all(
        Object.values(state.clients).map((client) =>
          client.close().catch((error) => {
            log.error("Failed to close MCP client", {
              error,
            })
          }),
        ),
      )

    pendingOAuthTransports.clear()
  },
)

async function fetchPromptsForClient(clientName: string, client: Client) {
  const prompts = await client.listPrompts().catch((e) => {
    log.error("failed to get prompts", { clientName, error: e.message })
    return undefined
  })

  if (!prompts) {
    return
  }

  const commands: Record<string, PromptInfo & { client: string }> = {}

  for (const prompt of prompts.prompts) {
    const sanitizedClientName = clientName.replace(/[^a-zA-Z0-9_-]/g, "_")
    const sanitizedPromptName = prompt.name.replace(/[^a-zA-Z0-9_-]/g, "_")
    const key = sanitizedClientName + ":" + sanitizedPromptName

    commands[key] = { ...prompt, client: clientName }
  }
  return commands
}

async function fetchResourcesForClient(clientName: string, client: Client) {
  const resources = await client.listResources().catch((e) => {
    log.error("failed to get prompts", { clientName, error: e.message })
    return undefined
  })

  if (!resources) {
    return
  }

  const commands: Record<string, ResourceInfo & { client: string }> = {}

  for (const resource of resources.resources) {
    const sanitizedClientName = clientName.replace(/[^a-zA-Z0-9_-]/g, "_")
    const sanitizedResourceName = resource.name.replace(/[^a-zA-Z0-9_-]/g, "_")
    const key = sanitizedClientName + ":" + sanitizedResourceName

    commands[key] = { ...resource, client: clientName }
  }
  return commands
}

export async function add(name: string, mcp: Config.Mcp) {
  const s = await state()
  const result = await create(name, mcp)
  if (!result) {
    const status = {
      status: "failed" as const,
      error: "unknown error",
    }
    s.status[name] = status
    return {
      status,
    }
  }
  if (!result.mcpClient) {
    s.status[name] = result.status
    return {
      status: s.status,
    }
  }
  const existingClient = s.clients[name]
  if (existingClient) {
    await existingClient.close().catch((error) => {
      log.error("Failed to close existing MCP client", { name, error })
    })
  }
  s.clients[name] = result.mcpClient
  s.status[name] = result.status

  return {
    status: s.status,
  }
}

async function create(key: string, mcp: Config.Mcp) {
  if (mcp.enabled === false) {
    log.info("mcp server disabled", { key })
    return {
      mcpClient: undefined,
      status: { status: "disabled" as const },
    }
  }

  log.info("found", { key, type: mcp.type })
  let mcpClient: MCPClient | undefined
  let status: Status | undefined = undefined

  if (mcp.type === "remote") {
    const oauthDisabled = mcp.oauth === false
    const oauthConfig = typeof mcp.oauth === "object" ? mcp.oauth : undefined
    let authProvider: McpOAuthProvider | undefined

    if (!oauthDisabled) {
      authProvider = new McpOAuthProvider(
        key,
        mcp.url,
        {
          clientId: oauthConfig?.clientId,
          clientSecret: oauthConfig?.clientSecret,
          scope: oauthConfig?.scope,
        },
        {
          onRedirect: async (url) => {
            log.info("oauth redirect requested", { key, url: url.toString() })
          },
        },
      )
    }

    const transports: Array<{ name: string; transport: TransportWithAuth }> = [
      {
        name: "StreamableHTTP",
        transport: new StreamableHTTPClientTransport(new URL(mcp.url), {
          authProvider,
          requestInit: mcp.headers ? { headers: mcp.headers } : undefined,
        }),
      },
      {
        name: "SSE",
        transport: new SSEClientTransport(new URL(mcp.url), {
          authProvider,
          requestInit: mcp.headers ? { headers: mcp.headers } : undefined,
        }),
      },
    ]

    let lastError: Error | undefined
    const connectTimeout = mcp.timeout ?? DEFAULT_TIMEOUT
    for (const { name, transport } of transports) {
      try {
        const client = new Client({
          name: "nikcli",
          version: Installation.VERSION,
        })
        await withTimeout(client.connect(transport), connectTimeout)
        registerNotificationHandlers(client, key)
        mcpClient = client
        log.info("connected", { key, transport: name })
        status = { status: "connected" }
        break
      } catch (error) {
        lastError = error instanceof Error ? error : new Error(String(error))

        if (error instanceof UnauthorizedError) {
          log.info("mcp server requires authentication", { key, transport: name })

          if (lastError.message.includes("registration") || lastError.message.includes("client_id")) {
            status = {
              status: "needs_client_registration" as const,
              error: "Server does not support dynamic client registration. Please provide clientId in config.",
            }
            Bus.publish(TuiEvent.ToastShow, {
              title: "MCP Authentication Required",
              message: `Server "${key}" requires a pre-registered client ID. Add clientId to your config.`,
              variant: "warning",
              duration: 8000,
            }).catch((e) => log.debug("failed to show toast", { error: e }))
          } else {
            pendingOAuthTransports.set(key, transport)
            status = { status: "needs_auth" as const }
            Bus.publish(TuiEvent.ToastShow, {
              title: "MCP Authentication Required",
              message: `Server "${key}" requires authentication. Run: nikcli mcp auth ${key}`,
              variant: "warning",
              duration: 8000,
            }).catch((e) => log.debug("failed to show toast", { error: e }))
          }
          break
        }

        log.debug("transport connection failed", {
          key,
          transport: name,
          url: mcp.url,
          error: lastError.message,
        })
        status = {
          status: "failed" as const,
          error: lastError.message,
        }
      }
    }
  }

  if (mcp.type === "local") {
    const [cmd, ...args] = mcp.command
    const cwd = Instance.directory
    const transport = new StdioClientTransport({
      stderr: "ignore",
      command: cmd,
      args,
      cwd,
      env: {

        ...process.env,
        ...(cmd === "nikcli" ? { BUN_BE_BUN: "1" } : {}),
        ...mcp.environment,
      },
    })

    const connectTimeout = mcp.timeout ?? DEFAULT_TIMEOUT
    try {
      const client = new Client({
        name: "nikcli",
        version: Installation.VERSION,
      })
      await withTimeout(client.connect(transport), connectTimeout)
      registerNotificationHandlers(client, key)
      mcpClient = client
      status = {
        status: "connected",
      }
    } catch (error) {
      log.error("local mcp startup failed", {
        key,
        command: mcp.command,
        cwd,
        error: error instanceof Error ? error.message : String(error),
      })
      status = {
        status: "failed" as const,
        error: error instanceof Error ? error.message : String(error),
      }
    }
  }

  if (!status) {
    status = {
      status: "failed" as const,
      error: "Unknown error",
    }
  }

  if (!mcpClient) {
    return {
      mcpClient: undefined,
      status,
    }
  }

  const result = await withTimeout(mcpClient.listTools(), mcp.timeout ?? DEFAULT_TIMEOUT).catch((err) => {
    log.error("failed to get tools from client", { key, error: err })
    return undefined
  })
  if (!result) {
    await mcpClient.close().catch((error) => {
      log.error("Failed to close MCP client", {
        error,
      })
    })
    status = {
      status: "failed",
      error: "Failed to get tools",
    }
    return {
      mcpClient: undefined,
      status: {
        status: "failed" as const,
        error: "Failed to get tools",
      },
    }
  }

  log.info("create() successfully created client", { key, toolCount: result.tools.length })
  return {
    mcpClient,
    status,
  }
}

export async function status() {
  const s = await state()
  const cfg = await Config.get()
  const config = cfg.mcp ?? {}
  const result: Record<string, Status> = {}

  for (const [key, mcp] of Object.entries(config)) {
    if (!isMcpConfigured(mcp)) continue
    result[key] = s.status[key] ?? { status: "disabled" }
  }

  return result
}

export async function clients() {
  return state().then((state) => state.clients)
}

export async function connect(name: string) {
  const cfg = await Config.get()
  const config = cfg.mcp ?? {}
  const mcp = config[name]
  if (!mcp) {
    log.error("MCP config not found", { name })
    return
  }

  if (!isMcpConfigured(mcp)) {
    log.error("Ignoring MCP connect request for config without type", { name })
    return
  }

  const result = await create(name, { ...mcp, enabled: true })

  if (!result) {
    const s = await state()
    s.status[name] = {
      status: "failed",
      error: "Unknown error during connection",
    }
    return
  }

  const s = await state()
  s.status[name] = result.status
  if (result.mcpClient) {
    const existingClient = s.clients[name]
    if (existingClient) {
      await existingClient.close().catch((error) => {
        log.error("Failed to close existing MCP client", { name, error })
      })
    }
    s.clients[name] = result.mcpClient
  }
}

export async function disconnect(name: string) {
  const s = await state()
  const client = s.clients[name]
  if (client) {
    await client.close().catch((error) => {
      log.error("Failed to close MCP client", { name, error })
    })
    delete s.clients[name]
  }
  s.status[name] = { status: "disabled" }
}

export async function tools() {
  const result: Record<string, Tool> = {}
  const s = await state()
  const cfg = await Config.get()
  const config = cfg.mcp ?? {}
  const clientsSnapshot = await clients()
  const defaultTimeout = cfg.experimental?.mcp_timeout

  for (const [clientName, client] of Object.entries(clientsSnapshot)) {
    if (s.status[clientName]?.status !== "connected") {
      continue
    }

    const toolsResult = await client.listTools().catch((e) => {
      log.error("failed to get tools", { clientName, error: e.message })
      const failedStatus = {
        status: "failed" as const,
        error: e instanceof Error ? e.message : String(e),
      }
      s.status[clientName] = failedStatus
      delete s.clients[clientName]
      return undefined
    })
    if (!toolsResult) {
      continue
    }
    const mcpConfig = config[clientName]
    const entry = isMcpConfigured(mcpConfig) ? mcpConfig : undefined
    const timeout = entry?.timeout ?? defaultTimeout
    for (const mcpTool of toolsResult.tools) {
      const sanitizedClientName = clientName.replace(/[^a-zA-Z0-9_-]/g, "_")
      const sanitizedToolName = mcpTool.name.replace(/[^a-zA-Z0-9_-]/g, "_")
      result[sanitizedClientName + "_" + sanitizedToolName] = await convertMcpTool(mcpTool, client, timeout)
    }
  }
  return result
}

export async function prompts() {
  const s = await state()
  const clientsSnapshot = await clients()

  const prompts = Object.fromEntries<PromptInfo & { client: string }>(
    (
      await Promise.all(
        Object.entries(clientsSnapshot).map(async ([clientName, client]) => {
          if (s.status[clientName]?.status !== "connected") {
            return []
          }

          return Object.entries((await fetchPromptsForClient(clientName, client)) ?? {})
        }),
      )
    ).flat(),
  )

  return prompts
}

export async function resources() {
  const s = await state()
  const clientsSnapshot = await clients()

  const result = Object.fromEntries<ResourceInfo & { client: string }>(
    (
      await Promise.all(
        Object.entries(clientsSnapshot).map(async ([clientName, client]) => {
          if (s.status[clientName]?.status !== "connected") {
            return []
          }

          return Object.entries((await fetchResourcesForClient(clientName, client)) ?? {})
        }),
      )
    ).flat(),
  )

  return result
}

export async function getPrompt(clientName: string, name: string, args?: Record<string, string>) {
  const clientsSnapshot = await clients()
  const client = clientsSnapshot[clientName]

  if (!client) {
    log.warn("client not found for prompt", {
      clientName,
    })
    return undefined
  }

  const result = await client
    .getPrompt({
      name: name,
      arguments: args,
    })
    .catch((e) => {
      log.error("failed to get prompt from MCP server", {
        clientName,
        promptName: name,
        error: e.message,
      })
      return undefined
    })

  return result
}

export async function readResource(clientName: string, resourceUri: string) {
  const clientsSnapshot = await clients()
  const client = clientsSnapshot[clientName]

  if (!client) {
    log.warn("client not found for prompt", {
      clientName: clientName,
    })
    return undefined
  }

  const result = await client
    .readResource({
      uri: resourceUri,
    })
    .catch((e) => {
      log.error("failed to get prompt from MCP server", {
        clientName: clientName,
        resourceUri: resourceUri,
        error: e.message,
      })
    })

  return result
}

export async function
  startAuth(mcpName: string): Promise<{ authorizationUrl: string }> {
  const cfg = await Config.get()
  const mcpConfig = cfg.mcp?.[mcpName]

  if (!mcpConfig) {
    throw new Error(`MCP server not found: ${mcpName}`)
  }

  if (!isMcpConfigured(mcpConfig)) {
    throw new Error(`MCP server ${mcpName} is disabled or missing configuration`)
  }

  if (mcpConfig.type !== "remote") {
    throw new Error(`MCP server ${mcpName} is not a remote server`)
  }

  if (mcpConfig.oauth === false) {
    throw new Error(`MCP server ${mcpName} has OAuth explicitly disabled`)
  }

  await McpOAuthCallback.ensureRunning()

  const oauthState = Array.from(crypto.getRandomValues(new Uint8Array(32)))
    .map((b) => b.toString(16).padStart(2, "0"))
    .join("")
  await McpAuth.updateOAuthState(mcpName, oauthState)

  const oauthConfig = typeof mcpConfig.oauth === "object" ? mcpConfig.oauth : undefined
  let capturedUrl: URL | undefined
  const authProvider = new McpOAuthProvider(
    mcpName,
    mcpConfig.url,
    {
      clientId: oauthConfig?.clientId,
      clientSecret: oauthConfig?.clientSecret,
      scope: oauthConfig?.scope,
    },
    {
      onRedirect: async (url) => {
        capturedUrl = url
      },
    },
  )

  const transport = new StreamableHTTPClientTransport(new URL(mcpConfig.url), {
    authProvider,
  })

  try {
    const client = new Client({
      name: "nikcli",
      version: Installation.VERSION,
    })
    await client.connect(transport)
    return { authorizationUrl: "" }
  } catch (error) {
    if (error instanceof UnauthorizedError && capturedUrl) {
      pendingOAuthTransports.set(mcpName, transport)
      return { authorizationUrl: capturedUrl.toString() }
    }
    throw error
  }
}

export async function authenticate(mcpName: string): Promise<Status> {
  const { authorizationUrl } = await startAuth(mcpName)

  if (!authorizationUrl) {
    const s = await state()
    return s.status[mcpName] ?? { status: "connected" }
  }

  const oauthState = await McpAuth.getOAuthState(mcpName)
  if (!oauthState) {
    throw new Error("OAuth state not found - this should not happen")
  }

  log.info("opening browser for oauth", { mcpName, url: authorizationUrl, state: oauthState })

  const callbackPromise = McpOAuthCallback.waitForCallback(oauthState)

  try {
    const subprocess = await open(authorizationUrl)
    await new Promise<void>((resolve, reject) => {
      const timeout = setTimeout(() => resolve(), 500)
      subprocess.on("error", (error) => {
        clearTimeout(timeout)
        reject(error)
      })
      subprocess.on("exit", (code) => {
        if (code !== null && code !== 0) {
          clearTimeout(timeout)
          reject(new Error(`Browser open failed with exit code ${code}`))
        }
      })
    })
  } catch (error) {
    log.warn("failed to open browser, user must open URL manually", { mcpName, error })
    Bus.publish(BrowserOpenFailed, { mcpName, url: authorizationUrl })
  }

  const code = await callbackPromise

  const storedState = await McpAuth.getOAuthState(mcpName)
  if (storedState !== oauthState) {
    await McpAuth.clearOAuthState(mcpName)
    throw new Error("OAuth state mismatch - potential CSRF attack")
  }

  await McpAuth.clearOAuthState(mcpName)

  return finishAuth(mcpName, code)
}

export async function finishAuth(mcpName: string, authorizationCode: string): Promise<Status> {
  const transport = pendingOAuthTransports.get(mcpName)

  if (!transport) {
    throw new Error(`No pending OAuth flow for MCP server: ${mcpName}`)
  }

    try {
      await transport.finishAuth(authorizationCode)

      await McpAuth.clearCodeVerifier(mcpName)

      const cfg = await Config.get()
      const mcpConfig = cfg.mcp?.[mcpName]

      if (!mcpConfig) {
        throw new Error(`MCP server not found: ${mcpName}`)
      }

      if (!isMcpConfigured(mcpConfig)) {
        throw new Error(`MCP server ${mcpName} is disabled or missing configuration`)
      }

      pendingOAuthTransports.delete(mcpName)
      const result = await add(mcpName, mcpConfig)

      const statusRecord = result.status as Record<string, Status>
      return statusRecord[mcpName] ?? { status: "failed", error: "Unknown error after auth" }
    } catch (error) {
      log.error("failed to finish oauth", { mcpName, error })
      return {
        status: "failed",
        error: error instanceof Error ? error.message : String(error),
      }
    }
  }

  export async function removeAuth(mcpName: string): Promise<void> {
    await McpAuth.remove(mcpName)
    McpOAuthCallback.cancelPending(mcpName)
    pendingOAuthTransports.delete(mcpName)
    await McpAuth.clearOAuthState(mcpName)
    log.info("removed oauth credentials", { mcpName })
  }

  export async function supportsOAuth(mcpName: string): Promise<boolean> {
    const cfg = await Config.get()
    const mcpConfig = cfg.mcp?.[mcpName]
    if (!mcpConfig) return false
    if (!isMcpConfigured(mcpConfig)) return false
    return mcpConfig.type === "remote" && mcpConfig.oauth !== false
  }

  export async function hasStoredTokens(mcpName: string): Promise<boolean> {
    const entry = await McpAuth.get(mcpName)
    return !!entry?.tokens
  }

  export type AuthStatus = "authenticated" | "expired" | "not_authenticated"

  export async function getAuthStatus(mcpName: string): Promise<AuthStatus> {
    const hasTokens = await hasStoredTokens(mcpName)
    if (!hasTokens) return "not_authenticated"
    const expired = await McpAuth.isTokenExpired(mcpName)
    return expired ? "expired" : "authenticated"
  }
}

import { Log } from "../util/log"
import { OAUTH_CALLBACK_PORT, OAUTH_CALLBACK_PATH } from "./oauth-provider"

const log = Log.create({ service: "mcp.oauth-callback" })

const HTML_SUCCESS = `<!DOCTYPE html>
<html>
<head>
  <title>Nikcli - Authorization Successful</title>
  <style>
    body { font-family: system-ui, -apple-system, sans-serif; display: flex; justify-content: center; align-items: center; height: 100vh; margin: 0; background: #1a1a2e; color: #eee; }
    .container { text-align: center; padding: 2rem; }
    h1 { color: #4ade80; margin-bottom: 1rem; }
    p { color: #aaa; }
  </style>
</head>
<body>
  <div class="container">
    <h1>Authorization Successful</h1>
    <p>You can close this window and return to Nikcli.</p>
  </div>
  <script>setTimeout(() => window.close(), 2000);</script>
</body>
</html>`

const HTML_ERROR = (error: string) => `<!DOCTYPE html>
<html>
<head>
  <title>Nikcli - Authorization Failed</title>
  <style>
    body { font-family: system-ui, -apple-system, sans-serif; display: flex; justify-content: center; align-items: center; height: 100vh; margin: 0; background: #1a1a2e; color: #eee; }
    .container { text-align: center; padding: 2rem; }
    h1 { color: #f87171; margin-bottom: 1rem; }
    p { color: #aaa; }
    .error { color: #fca5a5; font-family: monospace; margin-top: 1rem; padding: 1rem; background: rgba(248,113,113,0.1); border-radius: 0.5rem; }
  </style>
</head>
<body>
  <div class="container">
    <h1>Authorization Failed</h1>
    <p>An error occurred during authorization.</p>
    <div class="error">${error}</div>
  </div>
</body>
</html>`

interface PendingAuth {
  resolve: (code: string) => void
  reject: (error: Error) => void
  timeout: ReturnType<typeof setTimeout>
}

export namespace McpOAuthCallback {
  let server: ReturnType<typeof Bun.serve> | undefined
  const pendingAuths = new Map<string, PendingAuth>()

  const CALLBACK_TIMEOUT_MS = 5 * 60 * 1000

  export async function ensureRunning(): Promise<void> {
    if (server) return

    const running = await isPortInUse()
    if (running) {
      log.info("oauth callback server already running on another instance", { port: OAUTH_CALLBACK_PORT })
      return
    }

    server = Bun.serve({
      port: OAUTH_CALLBACK_PORT,
      fetch(req) {
        const url = new URL(req.url)

        if (url.pathname !== OAUTH_CALLBACK_PATH) {
          return new Response("Not found", { status: 404 })
        }

        const code = url.searchParams.get("code")
        const state = url.searchParams.get("state")
        const error = url.searchParams.get("error")
        const errorDescription = url.searchParams.get("error_description")

        log.info("received oauth callback", { hasCode: !!code, state, error })

        if (!state) {
          const errorMsg = "Missing required state parameter - potential CSRF attack"
          log.error("oauth callback missing state parameter", { url: url.toString() })
          return new Response(HTML_ERROR(errorMsg), {
            status: 400,
            headers: { "Content-Type": "text/html" },
          })
        }

        if (error) {
          const errorMsg = errorDescription || error
          if (pendingAuths.has(state)) {
            const pending = pendingAuths.get(state)!
            clearTimeout(pending.timeout)
            pendingAuths.delete(state)
            pending.reject(new Error(errorMsg))
          }
          return new Response(HTML_ERROR(errorMsg), {
            headers: { "Content-Type": "text/html" },
          })
        }

        if (!code) {
          return new Response(HTML_ERROR("No authorization code provided"), {
            status: 400,
            headers: { "Content-Type": "text/html" },
          })
        }

        if (!pendingAuths.has(state)) {
          const errorMsg = "Invalid or expired state parameter - potential CSRF attack"
          log.error("oauth callback with invalid state", { state, pendingStates: Array.from(pendingAuths.keys()) })
          return new Response(HTML_ERROR(errorMsg), {
            status: 400,
            headers: { "Content-Type": "text/html" },
          })
        }

        const pending = pendingAuths.get(state)!

        clearTimeout(pending.timeout)
        pendingAuths.delete(state)
        pending.resolve(code)

        return new Response(HTML_SUCCESS, {
          headers: { "Content-Type": "text/html" },
        })
      },
    })

    log.info("oauth callback server started", { port: OAUTH_CALLBACK_PORT })
  }

  export function waitForCallback(oauthState: string): Promise<string> {
    return new Promise((resolve, reject) => {
      const timeout = setTimeout(() => {
        if (pendingAuths.has(oauthState)) {
          pendingAuths.delete(oauthState)
          reject(new Error("OAuth callback timeout - authorization took too long"))
        }
      }, CALLBACK_TIMEOUT_MS)

      pendingAuths.set(oauthState, { resolve, reject, timeout })
    })
  }

  export function cancelPending(mcpName: string): void {
    const pending = pendingAuths.get(mcpName)
    if (pending) {
      clearTimeout(pending.timeout)
      pendingAuths.delete(mcpName)
      pending.reject(new Error("Authorization cancelled"))
    }
  }

  export async function isPortInUse(): Promise<boolean> {
    return new Promise((resolve) => {
      Bun.connect({
        hostname: "127.0.0.1",
        port: OAUTH_CALLBACK_PORT,
        socket: {
          open(socket) {
            socket.end()
            resolve(true)
          },
          error() {
            resolve(false)
          },
          data() {},
          close() {},
        },
      }).catch(() => {
        resolve(false)
      })
    })
  }

  export async function stop(): Promise<void> {
    if (server) {
      server.stop()
      server = undefined
      log.info("oauth callback server stopped")
    }

    for (const [name, pending] of pendingAuths) {
      clearTimeout(pending.timeout)
      pending.reject(new Error("OAuth callback server stopped"))
    }
    pendingAuths.clear()
  }

  export function isRunning(): boolean {
    return server !== undefined
  }
}

import type { OAuthClientProvider } from "@modelcontextprotocol/sdk/client/auth.js"
import type {
  OAuthClientMetadata,
  OAuthTokens,
  OAuthClientInformation,
  OAuthClientInformationFull,
} from "@modelcontextprotocol/sdk/shared/auth.js"
import { McpAuth } from "./auth"
import { Log } from "../util/log"

const log = Log.create({ service: "mcp.oauth" })

const OAUTH_CALLBACK_PORT = 19876
const OAUTH_CALLBACK_PATH = "/mcp/oauth/callback"

export interface McpOAuthConfig {
  clientId?: string
  clientSecret?: string
  scope?: string
}

export interface McpOAuthCallbacks {
  onRedirect: (url: URL) => void | Promise<void>
}

export class McpOAuthProvider implements OAuthClientProvider {
  constructor(
    private mcpName: string,
    private serverUrl: string,
    private config: McpOAuthConfig,
    private callbacks: McpOAuthCallbacks,
  ) {}

  get redirectUrl(): string {
    return `http://127.0.0.1:${OAUTH_CALLBACK_PORT}${OAUTH_CALLBACK_PATH}`
  }

  get clientMetadata(): OAuthClientMetadata {
    return {
      redirect_uris: [this.redirectUrl],
      client_name: "Nikcli",
      client_uri: "https://nikcli.store",
      grant_types: ["authorization_code", "refresh_token"],
      response_types: ["code"],
      token_endpoint_auth_method: this.config.clientSecret ? "client_secret_post" : "none",
    }
  }

  async clientInformation(): Promise<OAuthClientInformation | undefined> {
    if (this.config.clientId) {
      return {
        client_id: this.config.clientId,
        client_secret: this.config.clientSecret,
      }
    }

    const entry = await McpAuth.getForUrl(this.mcpName, this.serverUrl)
    if (entry?.clientInfo) {
      if (entry.clientInfo.clientSecretExpiresAt && entry.clientInfo.clientSecretExpiresAt < Date.now() / 1000) {
        log.info("client secret expired, need to re-register", { mcpName: this.mcpName })
        return undefined
      }
      return {
        client_id: entry.clientInfo.clientId,
        client_secret: entry.clientInfo.clientSecret,
      }
    }

    return undefined
  }

  async saveClientInformation(info: OAuthClientInformationFull): Promise<void> {
    await McpAuth.updateClientInfo(
      this.mcpName,
      {
        clientId: info.client_id,
        clientSecret: info.client_secret,
        clientIdIssuedAt: info.client_id_issued_at,
        clientSecretExpiresAt: info.client_secret_expires_at,
      },
      this.serverUrl,
    )
    log.info("saved dynamically registered client", {
      mcpName: this.mcpName,
      clientId: info.client_id,
    })
  }

  async tokens(): Promise<OAuthTokens | undefined> {
    const entry = await McpAuth.getForUrl(this.mcpName, this.serverUrl)
    if (!entry?.tokens) return undefined

    return {
      access_token: entry.tokens.accessToken,
      token_type: "Bearer",
      refresh_token: entry.tokens.refreshToken,
      expires_in: entry.tokens.expiresAt
        ? Math.max(0, Math.floor(entry.tokens.expiresAt - Date.now() / 1000))
        : undefined,
      scope: entry.tokens.scope,
    }
  }

  async saveTokens(tokens: OAuthTokens): Promise<void> {
    await McpAuth.updateTokens(
      this.mcpName,
      {
        accessToken: tokens.access_token,
        refreshToken: tokens.refresh_token,
        expiresAt: tokens.expires_in ? Date.now() / 1000 + tokens.expires_in : undefined,
        scope: tokens.scope,
      },
      this.serverUrl,
    )
    log.info("saved oauth tokens", { mcpName: this.mcpName })
  }

  async redirectToAuthorization(authorizationUrl: URL): Promise<void> {
    log.info("redirecting to authorization", { mcpName: this.mcpName, url: authorizationUrl.toString() })
    await this.callbacks.onRedirect(authorizationUrl)
  }

  async saveCodeVerifier(codeVerifier: string): Promise<void> {
    await McpAuth.updateCodeVerifier(this.mcpName, codeVerifier)
  }

  async codeVerifier(): Promise<string> {
    const entry = await McpAuth.get(this.mcpName)
    if (!entry?.codeVerifier) {
      throw new Error(`No code verifier saved for MCP server: ${this.mcpName}`)
    }
    return entry.codeVerifier
  }

  async saveState(state: string): Promise<void> {
    await McpAuth.updateOAuthState(this.mcpName, state)
  }

  async state(): Promise<string> {
    const entry = await McpAuth.get(this.mcpName)
    if (!entry?.oauthState) {
      throw new Error(`No OAuth state saved for MCP server: ${this.mcpName}`)
    }
    return entry.oauthState
  }
}

