import { createMemo, createSignal } from "solid-js"
import open from "open"
import { useLocal } from "@tui/context/local"
import { useSync } from "@tui/context/sync"
import { map, pipe, entries, sortBy } from "remeda"
import { DialogSelect, type DialogSelectOption } from "@tui/ui/dialog-select"
import { useTheme } from "../context/theme"
import { Keybind } from "@/util/keybind"
import { TextAttributes } from "@opentui/core"
import { useSDK } from "@tui/context/sdk"
import { useDialog } from "@tui/ui/dialog"
import { DialogPrompt } from "../ui/dialog-prompt"
import { useToast } from "../ui/toast"
import { Connectors } from "@/connectors"

const DEFAULT_CONNECTORS = [
  { name: "figma", type: "figma" as const, description: "Design files and components" },
  { name: "slack", type: "slack" as const, description: "Messages and channels" },
  { name: "github", type: "github" as const, description: "Repositories and issues" },
  { name: "lovable", type: "lovable" as const, description: "AI projects and chats" },
]

const LOVABLE_BASE_URL = "https://lovable.dev/"
const LOVABLE_PROMPT_MAX = 50000
const LOVABLE_IMAGES_MAX = 10

function buildLovableUrl(prompt: string, images: string[]) {
  const url = new URL(LOVABLE_BASE_URL)
  url.searchParams.set("autosubmit", "true")
  const params = new URLSearchParams()
  params.set("prompt", prompt)
  for (const image of images) {
    params.append("images", image)
  }
  url.hash = params.toString()
  return url.toString()
}

function parseLovableImages(value: string) {
  return value
    .split(/[\n,]+/)
    .map((item) => item.trim())
    .filter((item) => item.length > 0)
}

function findInvalidLovableImage(images: string[]) {
  return images.find((item) => !item.startsWith("http://") && !item.startsWith("https://"))
}

function Status(props: { enabled: boolean; configured: boolean; status?: string; loading: boolean }) {
  const { theme } = useTheme()
  if (props.loading) {
    return <span style={{ fg: theme.textMuted }}>⋯ Loading</span>
  }
  if (!props.configured) {
    return <span style={{ fg: theme.textMuted }}>○ Not configured</span>
  }
  if (!props.enabled) {
    return <span style={{ fg: theme.textMuted }}>○ Disabled</span>
  }
  if (props.status === "needs_auth") {
    return <span style={{ fg: theme.warning }}>⚠ Needs auth</span>
  }
  if (props.status === "failed") {
    return <span style={{ fg: theme.error }}>✗ Failed</span>
  }
  return <span style={{ fg: theme.success, attributes: TextAttributes.BOLD }}>✓ Enabled</span>
}

function authConfigForType(type: string) {
  switch (type) {
    case "slack":
      return { title: "Slack bot token", placeholder: "xoxb-...", field: "botToken" as const }
    case "lovable":
      return { title: "Lovable API key", placeholder: "token", field: "token" as const }
    case "figma":
      return { title: "Figma personal access token", placeholder: "figma_...", field: "token" as const }
    case "github":
      return { title: "GitHub personal access token", placeholder: "ghp_...", field: "token" as const }
    default:
      return { title: "Connector token", placeholder: "token", field: "token" as const }
  }
}

export function DialogConnectors() {
  const local = useLocal()
  const sync = useSync()
  const sdk = useSDK()
  const dialog = useDialog()
  const toast = useToast()
  const [loading, setLoading] = createSignal<string | null>(null)
  const reopen = () => setTimeout(() => dialog.replace(() => <DialogConnectors />), 0)

  async function refreshStatus() {
    const status = await sdk.client.connectors.status()
    if (status.data) {
      sync.set("connectors", status.data)
    }
  }

  async function addConnectorWithPreset(name: string, type: string) {
    const nextConfig = {
      ...sync.data.config,
      connectors: {
        ...(sync.data.config.connectors ?? {}),
        [name]: {
          type,
          enabled: true,
        },
      },
    }
    await sdk.client.config.update({ config: { connectors: nextConfig.connectors } })
    sync.set("config", nextConfig)
    await refreshStatus()
  }

  async function openLovableBuild() {
    const promptValue = await DialogPrompt.show(dialog, "Lovable prompt (required)")
    if (promptValue === null) {
      reopen()
      return
    }
    const prompt = promptValue.trim()
    if (!prompt) {
      toast.show({
        variant: "warning",
        message: "Prompt is required",
        duration: 4000,
      })
      reopen()
      return
    }
    if (prompt.length > LOVABLE_PROMPT_MAX) {
      toast.show({
        variant: "warning",
        message: `Prompt exceeds ${LOVABLE_PROMPT_MAX} characters`,
        duration: 5000,
      })
      reopen()
      return
    }

    const imagesValue = await DialogPrompt.show(dialog, "Lovable images (optional, comma-separated URLs)")
    if (imagesValue === null) {
      reopen()
      return
    }
    const images = parseLovableImages(imagesValue)
    if (images.length > LOVABLE_IMAGES_MAX) {
      toast.show({
        variant: "warning",
        message: `Use up to ${LOVABLE_IMAGES_MAX} image URLs`,
        duration: 5000,
      })
      reopen()
      return
    }
    const invalid = findInvalidLovableImage(images)
    if (invalid) {
      toast.show({
        variant: "warning",
        message: `Invalid image URL: ${invalid}`,
        duration: 5000,
      })
      reopen()
      return
    }

    const url = buildLovableUrl(prompt, images)
    toast.show({
      variant: "warning",
      message: "Do not paste API keys in the prompt. Lovable will warn about secrets.",
      duration: 6000,
    })
    toast.show({
      variant: "info",
      message: "If you are not logged in, Lovable will ask you to sign in and choose a workspace.",
      duration: 6000,
    })

    const opened = await open(url)
      .then(() => true)
      .catch(() => false)

    if (!opened) {
      toast.show({
        variant: "warning",
        message: `Open this URL to build: ${url}`,
        duration: 8000,
      })
    }
    if (opened) {
      toast.show({
        variant: "success",
        message: "Lovable build opened in your browser.",
        duration: 4000,
      })
    }

    reopen()

}

async function openAuth(name: string, presetType?: string) {
  const entry = sync.data.config.connectors?.[name]
  const resolvedType = entry && Connectors.isConnectorConfigured(entry) ? entry.type : presetType
  if (!resolvedType) {
    toast.show({
      variant: "warning",
      message: `Connector not found: ${name}`,
      duration: 3000,
    })
    return
  }
  const auth = authConfigForType(resolvedType)
  const value = await DialogPrompt.show(dialog, auth.title, {
    placeholder: auth.placeholder,
  })
  if (!value) {
    if (value === "") {
      toast.show({
        variant: "warning",
        message: "Credential is required",
        duration: 3000,
      })
    }
    reopen()
    return
  }
  if (!entry || !Connectors.isConnectorConfigured(entry)) {
    await addConnectorWithPreset(name, resolvedType)
  }
  await local.connectors.auth(name, { [auth.field]: value })
  await refreshStatus()
  reopen()
}

async function logout(name: string) {
  const entry = sync.data.config.connectors?.[name]
  if (!entry || !Connectors.isConnectorConfigured(entry)) {
    toast.show({
      variant: "warning",
      message: `Connector not found: ${name}`,
      duration: 3000,
    })
    return
  }
  await local.connectors.logout(name)
  await refreshStatus()
}

async function selectConnectorType() {
  return new Promise<string | null>((resolve) => {
    dialog.replace(
      () => (
        <DialogSelect
          title="Select connector type"
          options={[
            { title: "Figma", value: "figma", description: "Design files and components" },
            { title: "Slack", value: "slack", description: "Messages and channels" },
            { title: "GitHub", value: "github", description: "Repositories and issues" },
            { title: "Lovable", value: "lovable", description: "AI projects and chats" },
          ]}
          onSelect={(option) => resolve(option.value)}
        />
      ),
      () => resolve(null),
    )
  })
}

async function addConnector() {
  const name = await DialogPrompt.show(dialog, "Connector name", {
    placeholder: "my-connector",
  })
  if (!name) {
    reopen()
    return
  }
  if (!/^[a-zA-Z][a-zA-Z0-9_-]*$/.test(name)) {
    toast.show({
      variant: "warning",
      message: "Name must be alphanumeric (letters, numbers, _, -)",
      duration: 3000,
    })
    reopen()
    return
  }
  const existing = sync.data.config.connectors?.[name]
  if (existing && Connectors.isConnectorConfigured(existing)) {
    toast.show({
      variant: "warning",
      message: `Connector already exists: ${name}`,
      duration: 3000,
    })
    reopen()
    return
  }

  const type = await selectConnectorType()
  if (!type) {
    reopen()
    return
  }

  const nextConfig = {
    ...sync.data.config,
    connectors: {
      ...(sync.data.config.connectors ?? {}),
      [name]: {
        type,
        enabled: true,
      },
    },
  }
  await sdk.client.config.update({ config: { connectors: nextConfig.connectors } })
  sync.set("config", nextConfig)
  await refreshStatus()
  reopen()
}

const options = createMemo(() => {
  const config = sync.data.config.connectors ?? {}
  const statusMap = sync.data.connectors ?? {}
  const loadingName = loading()

  const configured = pipe(
    config,
    entries(),
    sortBy(([name]) => name),
    map(([name, entry]) => {
      if (!Connectors.isConnectorConfigured(entry)) return undefined
      const status = statusMap[name]
      const enabled = entry.enabled !== false
      const description = status?.status ?? (enabled ? "not initialized" : "disabled")
      return {
        value: name,
        title: name,
        description,
        footer: <Status enabled={enabled} configured={true} loading={loadingName === name} status={status?.status} />,
        category: entry.type,
      } satisfies DialogSelectOption<string>
    }),
  ).filter(Boolean) as DialogSelectOption<string>[]

  const missingDefaults = DEFAULT_CONNECTORS.filter((item) => {
    const entry = config[item.name]
    return !entry || !Connectors.isConnectorConfigured(entry)
  }).map(
    (item) =>
      ({
        value: item.name,
        title: item.name,
        description: item.description,
        footer: <Status enabled={false} configured={false} loading={loadingName === item.name} status={undefined} />,
        category: item.type,
      }) satisfies DialogSelectOption<string>,
  )

  return [...configured, ...missingDefaults]
})

const keybinds = createMemo(() => [
  {
    keybind: Keybind.parse("space")[0],
    title: "toggle",
    onTrigger: async (option: DialogSelectOption<string>) => {
      if (loading() !== null) return
      const entry = sync.data.config.connectors?.[option.value]
      if (!entry || !Connectors.isConnectorConfigured(entry)) {
        const preset = DEFAULT_CONNECTORS.find((item) => item.name === option.value)
        if (preset) {
          await openAuth(option.value, preset.type)
          return
        }
        return
      }
      setLoading(option.value)
      try {
        await local.connectors.toggle(option.value)
        await refreshStatus()
      } catch (error) {
        console.error("Failed to toggle connector:", error)
      } finally {
        setLoading(null)
      }
    },
  },
  {
    keybind: Keybind.parse("ctrl+a")[0],
    title: "auth/build",
    onTrigger: async (option: DialogSelectOption<string>) => {
      const entry = sync.data.config.connectors?.[option.value]
      const preset = DEFAULT_CONNECTORS.find((item) => item.name === option.value)
      const type = entry && Connectors.isConnectorConfigured(entry) ? entry.type : preset?.type
      if (type === "lovable") {
        await openLovableBuild()
        return
      }
      await openAuth(option.value, type)
    },

    },
    {
      keybind: Keybind.parse("x")[0],
      title: "logout",
      onTrigger: async (option: DialogSelectOption<string>) => {
        if (loading() !== null) return
        setLoading(option.value)
        try {
          await logout(option.value)
        } catch (error) {
          console.error("Failed to logout connector:", error)
        } finally {
          setLoading(null)
        }
      },
    },
    {
      keybind: Keybind.parse("ctrl+n")[0],
      title: "add",
      onTrigger: async () => {
        await addConnector()
      },
    },
  ])

  return (
    <DialogSelect
      title="Connectors"
      options={options()}
      keybind={keybinds()}
      onSelect={() => {
        // Don't close on select; align with MCP dialog behavior
      }}
    />
  )
}

import { DialogSelect, type DialogSelectRef } from "../ui/dialog-select"
import { useTheme } from "../context/theme"
import { useDialog } from "../ui/dialog"
import { onCleanup, onMount } from "solid-js"

export function DialogThemeList() {
  const theme = useTheme()
  const options = Object.keys(theme.all())
    .sort((a, b) => a.localeCompare(b, undefined, { sensitivity: "base" }))
    .map((value) => ({
      title: value,
      value: value,
    }))
  const dialog = useDialog()
  let confirmed = false
  let ref: DialogSelectRef<string>
  const initial = theme.selected

  onCleanup(() => {
    if (!confirmed) theme.set(initial)
  })

  return (
    <DialogSelect
      title="Themes"
      options={options}
      current={initial}
      onMove={(opt) => {
        theme.set(opt.value)
      }}
      onSelect={(opt) => {
        theme.set(opt.value)
        confirmed = true
        dialog.clear()
      }}
      ref={(r) => {
        ref = r
      }}
      onFilter={(query) => {
        if (query.length === 0) {
          theme.set(initial)
          return
        }

        const first = ref.filtered[0]
        if (first) theme.set(first.value)
      }}
    />
  )
}

import { useDialog } from "@tui/ui/dialog"
import { DialogSelect } from "@tui/ui/dialog-select"
import { useRoute } from "@tui/context/route"
import { useSync } from "@tui/context/sync"
import { createMemo, createSignal, createResource, onMount, Show } from "solid-js"
import { Locale } from "@/util/locale"
import { useKeybind } from "../context/keybind"
import { useTheme } from "../context/theme"
import { useSDK } from "../context/sdk"
import { DialogSessionRename } from "./dialog-session-rename"
import { useKV } from "../context/kv"
import { createDebouncedSignal } from "../util/signal"
import "opentui-spinner/solid"

export function DialogSessionList() {
  const dialog = useDialog()
  const route = useRoute()
  const sync = useSync()
  const keybind = useKeybind()
  const { theme } = useTheme()
  const sdk = useSDK()
  const kv = useKV()

  const [toDelete, setToDelete] = createSignal<string>()
  const [search, setSearch] = createDebouncedSignal("", 150)

  const [searchResults] = createResource(search, async (query) => {
    if (!query) return undefined
    const result = await sdk.client.session.list({ search: query, limit: 30 })
    return result.data ?? []
  })

  const currentSessionID = createMemo(() => (route.data.type === "session" ? route.data.sessionID : undefined))

  const spinnerFrames = ["⠋", "⠙", "⠹", "⠸", "⠼", "⠴", "⠦", "⠧", "⠇", "⠏"]

  const sessions = createMemo(() => searchResults() ?? sync.data.session)

  const options = createMemo(() => {
    const today = new Date().toDateString()
    return sessions()
      .filter((x) => x.parentID === undefined)
      .toSorted((a, b) => b.time.updated - a.time.updated)
      .map((x) => {
        const date = new Date(x.time.updated)
        let category = date.toDateString()
        if (category === today) {
          category = "Today"
        }
        const isDeleting = toDelete() === x.id
        const status = sync.data.session_status?.[x.id]
        const isWorking = status?.type === "busy"
        return {
          title: isDeleting ? `Press ${keybind.print("session_delete")} again to confirm` : x.title,
          bg: isDeleting ? theme.error : undefined,
          value: x.id,
          category,
          footer: Locale.time(x.time.updated),
          gutter: isWorking ? (
            <Show when={kv.get("animations_enabled", true)} fallback={<text fg={theme.textMuted}>[⋯]</text>}>
              <spinner frames={spinnerFrames} interval={80} color={theme.primary} />
            </Show>
          ) : undefined,
        }
      })
  })

  onMount(() => {
    dialog.setSize("large")
  })

  return (
    <DialogSelect
      title="Sessions"
      options={options()}
      skipFilter={true}
      current={currentSessionID()}
      onFilter={setSearch}
      onMove={() => {
        setToDelete(undefined)
      }}
      onSelect={(option) => {
        route.navigate({
          type: "session",
          sessionID: option.value,
        })
        dialog.clear()
      }}
      keybind={[
        {
          keybind: keybind.all.session_delete?.[0],
          title: "delete",
          onTrigger: async (option) => {
            if (toDelete() === option.value) {
              sdk.client.session.delete({
                sessionID: option.value,
              })
              setToDelete(undefined)
              return
            }
            setToDelete(option.value)
          },
        },
        {
          keybind: keybind.all.session_rename?.[0],
          title: "rename",
          onTrigger: async (option) => {
            dialog.replace(() => <DialogSessionRename session={option.value} />)
          },
        },
      ]}
    />
  )
}

import { TextAttributes } from "@opentui/core"
import { useTheme } from "../context/theme"
import { useSync } from "@tui/context/sync"
import { For, Match, Switch, Show, createMemo } from "solid-js"
import { Installation } from "@/installation"

export type DialogStatusProps = {}

export function DialogStatus() {
  const sync = useSync()
  const { theme } = useTheme()

  const enabledFormatters = createMemo(() => sync.data.formatter.filter((f) => f.enabled))

  const plugins = createMemo(() => {
    const list = sync.data.config.plugin ?? []
    const result = list.map((value) => {
      if (value.startsWith("file://")) {
        const path = value.substring("file://".length)
        const parts = path.split("/")
        const filename = parts.pop() || path
        if (!filename.includes(".")) return { name: filename }
        const basename = filename.split(".")[0]
        if (basename === "index") {
          const dirname = parts.pop()
          const name = dirname || basename
          return { name }
        }
        return { name: basename }
      }
      const index = value.lastIndexOf("@")
      if (index <= 0) return { name: value, version: "latest" }
      const name = value.substring(0, index)
      const version = value.substring(index + 1)
      return { name, version }
    })
    return result.toSorted((a, b) => a.name.localeCompare(b.name))
  })

  return (
    <box paddingLeft={2} paddingRight={2} gap={1} paddingBottom={1}>
      <box flexDirection="row" justifyContent="space-between">
        <text fg={theme.text} attributes={TextAttributes.BOLD}>
          Status
        </text>
        <text fg={theme.textMuted}>esc</text>
      </box>
      <text fg={theme.textMuted}>Nikcli v{Installation.VERSION}</text>
      <Show when={Object.keys(sync.data.mcp).length > 0} fallback={<text fg={theme.text}>No MCP Servers</text>}>
        <box>
          <text fg={theme.text}>{Object.keys(sync.data.mcp).length} MCP Servers</text>
          <For each={Object.entries(sync.data.mcp)}>
            {([key, item]) => (
              <box flexDirection="row" gap={1}>
                <text
                  flexShrink={0}
                  style={{
                    fg: (
                      {
                        connected: theme.success,
                        failed: theme.error,
                        disabled: theme.textMuted,
                        needs_auth: theme.warning,
                        needs_client_registration: theme.error,
                      } as Record<string, typeof theme.success>
                    )[item.status],
                  }}
                >
                  •
                </text>
                <text fg={theme.text} wrapMode="word">
                  <b>{key}</b>{" "}
                  <span style={{ fg: theme.textMuted }}>
                    <Switch fallback={item.status}>
                      <Match when={item.status === "connected"}>Connected</Match>
                      <Match when={item.status === "failed" && item}>{(val) => val().error}</Match>
                      <Match when={item.status === "disabled"}>Disabled in configuration</Match>
                      <Match when={(item.status as string) === "needs_auth"}>
                        Needs authentication (run: nikcli mcp auth {key})
                      </Match>
                      <Match when={(item.status as string) === "needs_client_registration" && item}>
                        {(val) => (val() as { error: string }).error}
                      </Match>
                    </Switch>
                  </span>
                </text>
              </box>
            )}
          </For>
        </box>
      </Show>
      {sync.data.lsp.length > 0 && (
        <box>
          <text fg={theme.text}>{sync.data.lsp.length} LSP Servers</text>
          <For each={sync.data.lsp}>
            {(item) => (
              <box flexDirection="row" gap={1}>
                <text
                  flexShrink={0}
                  style={{
                    fg: {
                      connected: theme.success,
                      error: theme.error,
                    }[item.status],
                  }}
                >
                  •
                </text>
                <text fg={theme.text} wrapMode="word">
                  <b>{item.id}</b> <span style={{ fg: theme.textMuted }}>{item.root}</span>
                </text>
              </box>
            )}
          </For>
        </box>
      )}
      <Show when={enabledFormatters().length > 0} fallback={<text fg={theme.text}>No Formatters</text>}>
        <box>
          <text fg={theme.text}>{enabledFormatters().length} Formatters</text>
          <For each={enabledFormatters()}>
            {(item) => (
              <box flexDirection="row" gap={1}>
                <text
                  flexShrink={0}
                  style={{
                    fg: theme.success,
                  }}
                >
                  •
                </text>
                <text wrapMode="word" fg={theme.text}>
                  <b>{item.name}</b>
                </text>
              </box>
            )}
          </For>
        </box>
      </Show>
      <Show when={plugins().length > 0} fallback={<text fg={theme.text}>No Plugins</text>}>
        <box>
          <text fg={theme.text}>{plugins().length} Plugins</text>
          <For each={plugins()}>
            {(item) => (
              <box flexDirection="row" gap={1}>
                <text
                  flexShrink={0}
                  style={{
                    fg: theme.success,
                  }}
                >
                  •
                </text>
                <text wrapMode="word" fg={theme.text}>
                  <b>{item.name}</b>
                  {item.version && <span style={{ fg: theme.textMuted }}> @{item.version}</span>}
                </text>
              </box>
            )}
          </For>
        </box>
      </Show>
    </box>
  )
}

import { TextAttributes, RGBA } from "@opentui/core"
