import {
  type LanguageModelV2CallWarning,
  type LanguageModelV2Prompt,
  type LanguageModelV2ToolCallPart,
  UnsupportedFunctionalityError,
} from "@ai-sdk/provider"
import { convertToBase64, parseProviderOptions } from "@ai-sdk/provider-utils"
import { z } from "zod/v4"
import type { OpenAIResponsesInput, OpenAIResponsesReasoning } from "./openai-responses-api-types"
import { localShellInputSchema, localShellOutputSchema } from "./tool/local-shell"

/**
 * Check if a string is a file ID based on the given prefixes
 * Returns false if prefixes is undefined (disables file ID detection)
 */
function isFileId(data: string, prefixes?: readonly string[]): boolean {
  if (!prefixes) return false
  return prefixes.some((prefix) => data.startsWith(prefix))
}

export async function convertToOpenAIResponsesInput({
  prompt,
  systemMessageMode,
  fileIdPrefixes,
  store,
  hasLocalShellTool = false,
}: {
  prompt: LanguageModelV2Prompt
  systemMessageMode: "system" | "developer" | "remove"
  fileIdPrefixes?: readonly string[]
  store: boolean
  hasLocalShellTool?: boolean
}): Promise<{
  input: OpenAIResponsesInput
  warnings: Array<LanguageModelV2CallWarning>
}> {
  const input: OpenAIResponsesInput = []
  const warnings: Array<LanguageModelV2CallWarning> = []

  for (const { role, content } of prompt) {
    switch (role) {
      case "system": {
        switch (systemMessageMode) {
          case "system": {
            input.push({ role: "system", content })
            break
          }
          case "developer": {
            input.push({ role: "developer", content })
            break
          }
          case "remove": {
            warnings.push({
              type: "other",
              message: "system messages are removed for this model",
            })
            break
          }
          default: {
            const _exhaustiveCheck: never = systemMessageMode
            throw new Error(`Unsupported system message mode: ${_exhaustiveCheck}`)
          }
        }
        break
      }

      case "user": {
        input.push({
          role: "user",
          content: content.map((part, index) => {
            switch (part.type) {
              case "text": {
                return { type: "input_text", text: part.text }
              }
              case "file": {
                if (part.mediaType.startsWith("image/")) {
                  const mediaType = part.mediaType === "image/*" ? "image/jpeg" : part.mediaType

                  return {
                    type: "input_image",
                    ...(part.data instanceof URL
                      ? { image_url: part.data.toString() }
                      : typeof part.data === "string" && isFileId(part.data, fileIdPrefixes)
                        ? { file_id: part.data }
                        : {
                            image_url: `data:${mediaType};base64,${convertToBase64(part.data)}`,
                          }),
                    detail: part.providerOptions?.openai?.imageDetail,
                  }
                } else if (part.mediaType === "application/pdf") {
                  if (part.data instanceof URL) {
                    return {
                      type: "input_file",
                      file_url: part.data.toString(),
                    }
                  }
                  return {
                    type: "input_file",
                    ...(typeof part.data === "string" && isFileId(part.data, fileIdPrefixes)
                      ? { file_id: part.data }
                      : {
                          filename: part.filename ?? `part-${index}.pdf`,
                          file_data: `data:application/pdf;base64,${convertToBase64(part.data)}`,
                        }),
                  }
                } else {
                  throw new UnsupportedFunctionalityError({
                    functionality: `file part media type ${part.mediaType}`,
                  })
                }
              }
            }
          }),
        })

        break
      }

      case "assistant": {
        const reasoningMessages: Record<string, OpenAIResponsesReasoning> = {}
        const toolCallParts: Record<string, LanguageModelV2ToolCallPart> = {}

        for (const part of content) {
          switch (part.type) {
            case "text": {
              input.push({
                role: "assistant",
                content: [{ type: "output_text", text: part.text }],
                id: (part.providerOptions?.openai?.itemId as string) ?? undefined,
              })
              break
            }
            case "tool-call": {
              toolCallParts[part.toolCallId] = part

              if (part.providerExecuted) {
                break
              }

              if (hasLocalShellTool && part.toolName === "local_shell") {
                const parsedInput = localShellInputSchema.parse(part.input)
                input.push({
                  type: "local_shell_call",
                  call_id: part.toolCallId,
                  id: (part.providerOptions?.openai?.itemId as string) ?? undefined,
                  action: {
                    type: "exec",
                    command: parsedInput.action.command,
                    timeout_ms: parsedInput.action.timeoutMs,
                    user: parsedInput.action.user,
                    working_directory: parsedInput.action.workingDirectory,
                    env: parsedInput.action.env,
                  },
                })

                break
              }

              input.push({
                type: "function_call",
                call_id: part.toolCallId,
                name: part.toolName,
                arguments: JSON.stringify(part.input),
                id: (part.providerOptions?.openai?.itemId as string) ?? undefined,
              })
              break
            }

            // assistant tool result parts are from provider-executed tools:
            case "tool-result": {
              if (store) {
                // use item references to refer to tool results from built-in tools
                input.push({ type: "item_reference", id: part.toolCallId })
              } else {
                warnings.push({
                  type: "other",
                  message: `Results for OpenAI tool ${part.toolName} are not sent to the API when store is false`,
                })
              }

              break
            }

            case "reasoning": {
              const providerOptions = await parseProviderOptions({
                provider: "openai",
                providerOptions: part.providerOptions,
                schema: openaiResponsesReasoningProviderOptionsSchema,
              })

              const reasoningId = providerOptions?.itemId

              if (reasoningId != null) {
                const reasoningMessage = reasoningMessages[reasoningId]

                if (store) {
                  if (reasoningMessage === undefined) {
                    // use item references to refer to reasoning (single reference)
                    input.push({ type: "item_reference", id: reasoningId })

                    // store unused reasoning message to mark id as used
                    reasoningMessages[reasoningId] = {
                      type: "reasoning",
                      id: reasoningId,
                      summary: [],
                    }
                  }
                } else {
                  const summaryParts: Array<{
                    type: "summary_text"
                    text: string
                  }> = []

                  if (part.text.length > 0) {
                    summaryParts.push({
                      type: "summary_text",
                      text: part.text,
                    })
                  } else if (reasoningMessage !== undefined) {
                    warnings.push({
                      type: "other",
                      message: `Cannot append empty reasoning part to existing reasoning sequence. Skipping reasoning part: ${JSON.stringify(part)}.`,
                    })
                  }

                  if (reasoningMessage === undefined) {
                    reasoningMessages[reasoningId] = {
                      type: "reasoning",
                      id: reasoningId,
                      encrypted_content: providerOptions?.reasoningEncryptedContent,
                      summary: summaryParts,
                    }
                    input.push(reasoningMessages[reasoningId])
                  } else {
                    reasoningMessage.summary.push(...summaryParts)
                  }
                }
              } else {
                warnings.push({
                  type: "other",
                  message: `Non-OpenAI reasoning parts are not supported. Skipping reasoning part: ${JSON.stringify(part)}.`,
                })
              }
              break
            }
          }
        }

        break
      }

      case "tool": {
        for (const part of content) {
          const output = part.output

          if (hasLocalShellTool && part.toolName === "local_shell" && output.type === "json") {
            input.push({
              type: "local_shell_call_output",
              call_id: part.toolCallId,
              output: localShellOutputSchema.parse(output.value).output,
            })
            break
          }

          let contentValue: string
          switch (output.type) {
            case "text":
            case "error-text":
              contentValue = output.value
              break
            case "content":
            case "json":
            case "error-json":
              contentValue = JSON.stringify(output.value)
              break
          }

          input.push({
            type: "function_call_output",
            call_id: part.toolCallId,
            output: contentValue,
          })
        }

        break
      }

      default: {
        const _exhaustiveCheck: never = role
        throw new Error(`Unsupported role: ${_exhaustiveCheck}`)
      }
    }
  }

  return { input, warnings }
}

const openaiResponsesReasoningProviderOptionsSchema = z.object({
  itemId: z.string().nullish(),
  reasoningEncryptedContent: z.string().nullish(),
})

export type OpenAIResponsesReasoningProviderOptions = z.infer<typeof openaiResponsesReasoningProviderOptionsSchema>

import type { LanguageModelV2FinishReason } from "@ai-sdk/provider"

export function mapOpenAIResponseFinishReason({
  finishReason,
  hasFunctionCall,
}: {
  finishReason: string | null | undefined
  // flag that checks if there have been client-side tool calls (not executed by openai)
  hasFunctionCall: boolean
}): LanguageModelV2FinishReason {
  switch (finishReason) {
    case undefined:
    case null:
      return hasFunctionCall ? "tool-calls" : "stop"
    case "max_output_tokens":
      return "length"
    case "content_filter":
      return "content-filter"
    default:
      return hasFunctionCall ? "tool-calls" : "unknown"
  }
}

import { createMemo, Show } from "solid-js"
import { useTerminalDimensions } from "@opentui/solid"
import { useTheme } from "../../../context/theme"
import { useSync } from "../../../context/sync"
import { tableRenderer } from "./table-renderer"
import type { DBTable, TablePreview, TableChange } from "../db/types"

interface DBVisualizerProps {
  tables?: DBTable[]
  preview?: TablePreview[]
  changes?: TableChange[]
  mode: "schema" | "preview" | "diff"
  filePath?: string
}

export function DBVisualizer(props: DBVisualizerProps) {
  const { theme } = useTheme()
  const dimensions = useTerminalDimensions()
  const sync = useSync()

  const tables = createMemo(() => {
    if (props.filePath && sync.data.dbschema[props.filePath]) {
      return sync.data.dbschema[props.filePath].tables
    }
    return props.tables || []
  })

  const renderedContent = createMemo(() => {
    const width = dimensions().width
    const tableList = tables()

    switch (props.mode) {
      case "schema":
        return tableRenderer.renderSchemaOverview(tableList, width)
      case "preview":
        if (props.preview && props.preview.length > 0) {
          return props.preview
            .map((p) => `=== ${p.tableName} ===\n${tableRenderer.renderPreview(p, width)}`)
            .join("\n\n")
        }
        return tableRenderer.renderSchemaOverview(tableList, width)
      case "diff":
        return tableRenderer.renderDiffSummary(props.changes || [], width)
      default:
        return tableRenderer.renderSchemaOverview(tableList, width)
    }
  })

  const stats = createMemo(() => tableRenderer.renderStats(tables()))

  return (
    <box flexDirection="column" gap={1}>
      <box flexDirection="row" gap={2}>
        <text fg={theme.success}>◈ {stats().tables} tables</text>
        <text fg={theme.primary}>→ {stats().columns} columns</text>
        <Show when={stats().rows > 0}>
          <text fg={theme.warning}>▒ {stats().rows} rows</text>
        </Show>
        <Show when={stats().pks > 0}>
          <text fg={theme.textMuted}>⚿ {stats().pks} with PK</text>
        </Show>
      </box>

      <scrollbox height="100%">
        <box flexDirection="column" gap={0}>
          <text fg={theme.text}>{renderedContent()}</text>
        </box>
      </scrollbox>
    </box>
  )
}

import { table, getBorderCharacters } from "table"
import type { DBTable, DBColumn, TablePreview, TableChange, DBSchema } from "../db/types"

export class TableRenderer {
  private config: Parameters<typeof table>[1]
  private defaultTerminalWidth: number = 80

  constructor() {
    this.config = {
      border: getBorderCharacters("honeywell"),
      columnDefault: {
        paddingLeft: 1,
        paddingRight: 1,
      },
      drawHorizontalLine: (rowIndex, rowCount) => {
        return rowIndex === 0 || rowIndex === 1 || rowIndex === rowCount - 1 || rowIndex === rowCount
      },
    }
  }

  private green(text: string): string {
    return `\x1b[32m${text}\x1b[0m`
  }

  private red(text: string): string {
    return `\x1b[31m${text}\x1b[0m`
  }

  private yellow(text: string): string {
    return `\x1b[33m${text}\x1b[0m`
  }

  private cyan(text: string): string {
    return `\x1b[36m${text}\x1b[0m`
  }

  private magenta(text: string): string {
    return `\x1b[35m${text}\x1b[0m`
  }

  private white(text: string): string {
    return `\x1b[37m${text}\x1b[0m`
  }

  private gray(text: string): string {
    return `\x1b[90m${text}\x1b[0m`
  }

  private truncate(text: string, maxWidth: number): string {
    if (text.length <= maxWidth) return text
    return text.slice(0, maxWidth - 3) + "..."
  }

  private getTerminalWidth(): number {
    return process.stdout.columns || this.defaultTerminalWidth
  }

  renderTableList(tables: DBTable[], maxTables: number = 10, terminalWidth?: number): string {
    const width = terminalWidth || this.getTerminalWidth()
    const nameWidth = Math.min(20, Math.max(10, width - 50))

    const data: string[][] = [[this.cyan("Table"), this.cyan("Cols"), this.cyan("Rows"), this.cyan("Type")]]

    for (const t of tables.slice(0, maxTables)) {
      data.push([
        this.green("▦ ") + this.white(this.truncate(t.name, nameWidth)),
        String(t.columns.length),
        this.yellow(String(t.rowCount || "?")),
        this.gray("Table"),
      ])
    }

    return table(data, {
      ...this.config,
      columns: {
        0: { width, alignment: "left" as const },
        1: { width: 5, alignment: "center" as const },
        2: { width: 6, alignment: "center" as const },
        3: { width: 7 },
      },
    })
  }

  renderColumns(tableName: string, columns: DBColumn[], terminalWidth?: number): string {
    const width = terminalWidth || this.getTerminalWidth()
    const nameWidth = Math.min(15, Math.max(8, width - 45))

    const data: string[][] = [[this.cyan("Column"), this.cyan("Type"), this.cyan("Nullable"), this.cyan("Key")]]

    for (const col of columns) {
      const type = this.white(col.type)
      const nullable = col.notNull ? this.red("NOT NULL") : this.green("nullable")
      const key = col.primaryKey ? this.magenta("PRI") : this.gray("")

      data.push([this.truncate(col.name, nameWidth), type, nullable, key])
    }

    return table(data, {
      ...this.config,
      columns: {
        0: { width: nameWidth + 2 },
        1: { width: 10 },
        2: { width: 12 },
        3: { width: 5, alignment: "center" as const },
      },
    })
  }

  renderPreview(preview: TablePreview, terminalWidth?: number): string {
    const width = terminalWidth || this.getTerminalWidth()
    const colWidth = Math.max(8, Math.min(15, Math.floor((width - 10) / preview.columns.length)))

    const data: string[][] = [preview.columns.map((c) => this.cyan(this.truncate(c.name, colWidth)))]

    for (const row of preview.sampleData.slice(0, 5)) {
      data.push(preview.columns.map((c) => this.truncate(String(row[c.name] ?? "NULL"), colWidth)))
    }

    return table(data, {
      ...this.config,
      columns: preview.columns.map(() => ({ width: colWidth, alignment: "left" as const })),
    })
  }

  renderSchemaOverview(tables: DBTable[], terminalWidth?: number): string {
    if (!tables.length) return this.gray("Empty database")

    const width = terminalWidth || this.getTerminalWidth()
    const isCompact = width < 70
    const nameWidth = isCompact ? 12 : 18

    const headers = isCompact
      ? [this.cyan("▦"), this.cyan("Table"), this.cyan("Cols"), this.cyan("PK")]
      : [this.cyan("▦"), this.cyan("Table Name"), this.cyan("Columns"), this.cyan("Primary Key"), this.cyan("FKs")]

    const data: string[][] = [headers]

    for (const t of tables) {
      if (isCompact) {
        data.push([
          this.green("◈"),
          this.white(this.truncate(t.name, nameWidth)),
          String(t.columns.length),
          t.primaryKey.length > 0 ? this.yellow(t.primaryKey.join(",")) : this.gray("-"),
        ])
      } else {
        data.push([
          this.green("◈"),
          this.white(this.truncate(t.name, nameWidth)),
          String(t.columns.length),
          t.primaryKey.length > 0 ? this.yellow(this.truncate(t.primaryKey.join(","), 12)) : this.gray("-"),
          t.foreignKeys?.length ? this.cyan(String(t.foreignKeys.length)) : this.gray("-"),
        ])
      }
    }

    const columnConfig: Record<number, any> = { 0: { alignment: "center" as const } }
    if (!isCompact) {
      columnConfig[4] = { alignment: "center" as const }
    }

    return table(data, { ...this.config, columns: columnConfig })
  }

  renderDiffSummary(changes: TableChange[], terminalWidth?: number): string {
    const width = terminalWidth || this.getTerminalWidth()
    const objWidth = Math.min(40, width - 25)

    const data: string[][] = [[this.cyan("Action"), this.cyan("Object")]]

    for (const c of changes) {
      let icon = ""
      let color = (s: string) => this.white(s)

      switch (c.type) {
        case "add_table":
          icon = "+"
          color = (s: string) => this.green(s)
          break
        case "drop_table":
          icon = "-"
          color = (s: string) => this.red(s)
          break
        case "add_column":
          icon = "+"
          color = (s: string) => this.green(s)
          break
        case "drop_column":
          icon = "-"
          color = (s: string) => this.red(s)
          break
        case "modify_column":
          icon = "~"
          color = (s: string) => this.yellow(s)
          break
      }

      const obj = c.columnName ? `${c.tableName}.${c.columnName}` : c.tableName

      data.push([color(icon + " " + c.type), color(this.truncate(obj, objWidth))])

  }

  return table(data, {
    ...this.config,
    columns: {
      0: { width: 20 },
      1: { width: objWidth },
    },
  })
}

renderSQLContent(sql: string, maxLines: number = 15, terminalWidth?: number): string {
  const width = terminalWidth || this.getTerminalWidth()
  const result: string[] = []

  const lines = sql.split("\n").slice(0, maxLines)
  for (const line of lines) {
    const truncated = this.truncate(line, width - 5)
    const trimmed = truncated.trim()

    if (trimmed.startsWith("CREATE")) {
      result.push(this.green(truncated))
    } else if (trimmed.startsWith("DROP")) {
      result.push(this.red(truncated))
    } else if (trimmed.startsWith("ALTER")) {
      result.push(this.yellow(truncated))
    } else {
      result.push(this.white(truncated))
    }
  }

  if (sql.split("\n").length > maxLines) {
    result.push(this.gray("... more lines"))
  }

  return result.join("\n")
}

renderStats(tables: DBTable[]): { tables: number; columns: number; rows: number; pks: number } {
  return {
    tables: tables.length,
    columns: tables.reduce((sum, t) => sum + t.columns.length, 0),
    rows: tables.reduce((sum, t) => sum + (t.rowCount || 0), 0),
    pks: tables.filter((t) => t.primaryKey.length > 0).length,
  }
}

renderCompact(tables: DBTable[], terminalWidth?: number): string {
  const width = terminalWidth || this.getTerminalWidth()
  const isSmall = width < 50

  if (isSmall) {
    const data: string[][] = [[this.cyan("▦"), this.cyan("Table")]]
    for (const t of tables) {
      data.push([this.green("◈"), this.white(this.truncate(t.name, 15))])
    }
    return table(data, { ...this.config, columns: { 0: { alignment: "center" as const } } })
  }

  return this.renderSchemaOverview(tables, width)
}

renderForeignKeys(
  foreignKeys: Array<{
    column: string
    referencedTable: string
    referencedColumn: string
    onDelete: "CASCADE" | "RESTRICT" | "SET NULL" | "NO ACTION"
  }>,
  terminalWidth?: number,
): string {
  if (!foreignKeys.length) return this.gray("No foreign keys")

  const width = terminalWidth || this.getTerminalWidth()
  const colWidth = Math.min(20, Math.max(12, Math.floor((width - 30) / 3)))

  const data: string[][] = [[this.cyan("Column"), this.cyan("References"), this.cyan("On Delete")]]

  for (const fk of foreignKeys) {
    const col = this.white(this.truncate(fk.column, colWidth))
    const ref = this.cyan(`${this.truncate(fk.referencedTable, colWidth)}.${fk.referencedColumn}`)
    const onDelete =
      fk.onDelete === "CASCADE"
        ? this.yellow(fk.onDelete)
        : fk.onDelete === "RESTRICT"
          ? this.red(fk.onDelete)
          : fk.onDelete === "SET NULL"
            ? this.cyan(fk.onDelete)
            : this.gray(fk.onDelete)

    data.push([col, ref, onDelete])
  }

  return table(data, {
    ...this.config,
    columns: {
      0: { width: colWidth + 2 },
      1: { width: colWidth + 15 },
      2: { width: 12, alignment: "center" as const },
    },
  })
}

renderERDiagram(schema: DBSchema, terminalWidth?: number): string {
  if (!schema.tables.length) return "Empty schema"

  const width = terminalWidth || this.getTerminalWidth()
  const tableWidth = Math.min(30, Math.max(28, Math.floor((width - 10) / 2)))
  const lines: string[] = []

  for (const table of schema.tables) {
    const titleLine = this.cyan(table.name)
    const pkCols = table.columns.filter((c) => c.primaryKey)
    const pkDisplay = pkCols.length > 0 ? this.yellow(`[${pkCols.map((c) => c.name).join(", ")}]`) : ""

    lines.push(this.cyan("┌" + "═".repeat(tableWidth - 2) + "┐"))
    lines.push(this.cyan("│") + " " + this.padToWidth(titleLine, tableWidth - 4) + this.cyan(" │"))
    if (pkDisplay) {
      lines.push(this.cyan("│") + " " + this.padToWidth(pkDisplay, tableWidth - 4) + this.cyan(" │"))
    }
    lines.push(this.cyan("├" + "─".repeat(tableWidth - 2) + "┤"))

    for (const col of table.columns) {
      const isPk = col.primaryKey ? this.yellow("◉") : " "
      const isNotNull = col.notNull ? this.red("*") : " "
      const name = this.white(this.truncate(col.name, 10))
      const type = this.gray(this.truncate(col.type, 6))
      const nullable = col.notNull ? "" : this.green("?")
      const defaultVal = col.defaultValue ? this.cyan(`=${this.truncate(col.defaultValue, 4)}`) : ""

      const colLine = `${isPk}${isNotNull} ${name} ${type}${nullable}${defaultVal}`
      lines.push(this.cyan("│") + " " + this.padToWidth(colLine, tableWidth - 4) + this.cyan(" │"))
    }

    if (table.foreignKeys && table.foreignKeys.length > 0) {
      lines.push(this.cyan("├" + "─".repeat(tableWidth - 2) + "┤"))
      for (const fk of table.foreignKeys) {
        const arrow = this.magenta("→")
        const fkLine = `${arrow} ${this.truncate(fk.referencedTable, 10)}.${fk.referencedColumn}`
        const onDelete = fk.onDelete !== "NO ACTION" ? this.yellow(` (${fk.onDelete})`) : ""

        const fullLine = `${fkLine}${onDelete}`
        lines.push(this.cyan("│") + " " + this.padToWidth(fullLine, tableWidth - 4) + this.cyan(" │"))
      }
    }

    lines.push(this.cyan("└" + "─".repeat(tableWidth - 2) + "┘"))
    lines.push("")
  }

  const relLines = this._renderRelations(schema, width, tableWidth)
  lines.push(...relLines)

  lines.push(this.gray("\nLegend: ◉ PK  * NOT NULL  ? Optional  → FK Reference"))

  return lines.join("\n")
}

private _renderRelations(schema: DBSchema, width: number, tableWidth: number): string[] {
  const lines: string[] = []
  const relations: string[] = []

  for (const table of schema.tables) {
    if (table.foreignKeys) {
      for (const fk of table.foreignKeys) {
        const rel = `${table.name}.${fk.column} → ${fk.referencedTable}.${fk.referencedColumn}`
        relations.push(rel)
      }
    }
  }

  if (relations.length > 0) {
    lines.push(this.cyan("═".repeat(40)))
    lines.push(this.cyan(" Relationships "))
    lines.push(this.cyan("═".repeat(40)))

    for (const rel of relations) {
      lines.push(this.magentalight(`  ${rel}`))
    }
  }

  return lines
}

private magentalight(text: string): string {
  return `\x1b[95m${text}\x1b[0m`
}

renderCompactDiagram(schema: DBSchema, terminalWidth?: number): string {
  if (!schema.tables.length) return "Empty schema"

  const width = terminalWidth || this.getTerminalWidth()
  const lines: string[] = []
  lines.push(this.cyan("═".repeat(width)))

  for (const table of schema.tables) {
    const pk = table.primaryKey.length > 0 ? this.yellow(`PK:${table.primaryKey[0]}`) : this.gray("PK:-")
    const fkCount = table.foreignKeys?.length || 0
    const fks = fkCount > 0 ? this.cyan(`${fkCount} FKs`) : this.gray("0 FKs")

    const name = this.white(table.name)
    const cols = this.gray(`${table.columns.length} cols`)

    const line = `│ ${name} │ ${cols} │ ${pk} │ ${fks} │`
    lines.push(line)
  }

  lines.push(this.cyan("═".repeat(width)))

  return lines.join("\n")
}

private stripAnsi(text: string): string {
  return text.replace(/\x1b\[[0-9;]*m/g, "")
}

private visibleLength(text: string): number {
  return this.stripAnsi(text).length
}

private padToWidth(text: string, width: number): string {
  const visibleLen = this.visibleLength(text)
  const padding = Math.max(0, width - visibleLen)
  return text + " ".repeat(padding)
}

renderFullERDiagram(schema: DBSchema, terminalWidth?: number): string {
  if (!schema.tables.length) return "Empty schema"

  const tableWidth = 52
  const colWidth = 14
  const typeWidth = 10
  const attrWidth = 10

  const lines: string[] = []

  for (const table of schema.tables) {
    const pkCols = table.columns.filter((c) => c.primaryKey)
    const fkCols = table.columns.filter((c) => table.foreignKeys?.some((fk) => fk.column === c.name))

    const titleLine = this.white(table.name)
    const pkLine = pkCols.length > 0 ? this.yellow(`[${pkCols.map((c) => c.name).join(", ")}]`) : ""

    lines.push(this.cyan("┌" + "═".repeat(tableWidth - 2) + "┐"))
    lines.push(this.cyan("│") + " " + this.padToWidth(titleLine, tableWidth - 4) + this.cyan(" │"))
    if (pkLine) {
      lines.push(this.cyan("│") + " " + this.padToWidth(pkLine, tableWidth - 4) + this.cyan(" │"))
    }
    lines.push(this.cyan("├" + "─".repeat(tableWidth - 2) + "┤"))

    const header =
      " " +
      this.yellow("COLUMN").padEnd(colWidth) +
      " " +
      this.cyan("TYPE").padEnd(typeWidth) +
      " " +
      this.cyan("ATTRS")
    lines.push(this.cyan("│") + this.padToWidth(header, tableWidth - 2) + this.cyan("│"))

    for (const col of table.columns) {
      const isPk = col.primaryKey ? this.yellow("PK") : "  "
      const isFk = fkCols.includes(col) ? this.magenta("FK") : "  "
      const nn = col.notNull ? this.red(" NN") : "   "
      const attrs = `${isPk}${isFk}${nn}`.trimEnd()
      const name = this.white(col.name)
      const type = this.gray(col.type)

      const colPart = this.padToWidth(name, colWidth)
      const typePart = this.padToWidth(type, typeWidth)
      const content = ` ${colPart} ${typePart} ${attrs}`
      lines.push(this.cyan("│") + this.padToWidth(content, tableWidth - 2) + this.cyan("│"))
    }

    if (table.foreignKeys && table.foreignKeys.length > 0) {
      lines.push(this.cyan("├" + "─".repeat(tableWidth - 2) + "┤"))
      for (const fk of table.foreignKeys) {
        const arrow = this.magenta("└─▶")
        const ref = this.cyan(`${fk.referencedTable}.${fk.referencedColumn}`)
        const onDelete = fk.onDelete !== "NO ACTION" ? this.yellow(` [${fk.onDelete}]`) : ""

        const content = ` ${arrow} ${ref}${onDelete}`
        lines.push(this.cyan("│") + this.padToWidth(content, tableWidth - 2) + this.cyan("│"))
      }
    }

    lines.push(this.cyan("└" + "─".repeat(tableWidth - 2) + "┘"))
    lines.push("")
  }

  lines.push(this.cyan("═".repeat(50)))
  lines.push(this.cyan(" RELATIONSHIPS "))
  lines.push(this.cyan("═".repeat(50)))

  for (const table of schema.tables) {
    if (table.foreignKeys) {
      for (const fk of table.foreignKeys) {
        lines.push(
          this.magenta(`  ${table.name}.${fk.column}`) +
            this.gray(" ──▶ ") +
            this.cyan(`${fk.referencedTable}.${fk.referencedColumn}`) +
            (fk.onDelete !== "NO ACTION" ? this.yellow(` (${fk.onDelete})`) : ""),
        )
      }
    }
  }

  return lines.join("\n")
}

renderDependencyTree(schema: DBSchema, maxDepth: number = 3): string {
  if (!schema.tables.length) return "Empty schema"

  const lines: string[] = []
  const visited = new Map<string, number>()

  const getDepth = (tableName: string): number => {
    if (visited.has(tableName)) return visited.get(tableName)!
    const table = schema.tables.find((t) => t.name === tableName)
    if (!table || !table.foreignKeys || table.foreignKeys.length === 0) {
      visited.set(tableName, 0)
      return 0
    }
    let maxChildDepth = 0
    for (const fk of table.foreignKeys) {
      maxChildDepth = Math.max(maxChildDepth, getDepth(fk.referencedTable))
    }
    visited.set(tableName, maxChildDepth + 1)
    return maxChildDepth + 1
  }

  for (const table of schema.tables) {
    getDepth(table.name)
  }

  const sortedTables = [...schema.tables].sort((a, b) => (visited.get(b.name) || 0) - (visited.get(a.name) || 0))

  const renderTable = (
    tableName: string,
    depth: number,
    prefix: string,
    isLast: boolean,
    siblingIndex: number,
    totalSiblings: number,
  ) => {
    if (depth > maxDepth) return

    const table = schema.tables.find((t) => t.name === tableName)
    if (!table) return

    const fkCount = table.foreignKeys?.length || 0
    const rowCount = table.rowCount || 0
    const meta = this.gray(`(${table.columns.length} cols, ${rowCount} rows)`)

    const icon = fkCount > 0 ? this.cyan("◉") : this.green("◈")
    const name = this.white(tableName)

    lines.push(`${prefix}${isLast ? "└─ " : "├─ "}${icon} ${name} ${meta}`)

    if (table.foreignKeys && table.foreignKeys.length > 0) {
      const newPrefix = prefix + (isLast ? "    " : "│   ")

      for (let i = 0; i < table.foreignKeys.length; i++) {
        const fk = table.foreignKeys[i]
        const isLastFk = i === table.foreignKeys.length - 1
        const fkPrefix = newPrefix + (isLastFk ? "    " : "│   ")

        const relIcon = this.magenta("→")
        const relTarget = this.cyan(fk.referencedTable)
        const relMeta = this.gray(`(${fk.column} → ${fk.referencedColumn})`)

        lines.push(`${fkPrefix}└─ ${relIcon} ${relTarget} ${relMeta}`)

        renderTable(fk.referencedTable, depth + 1, fkPrefix + "    ", true, 0, 0)
      }
    }
  }

  for (let i = 0; i < sortedTables.length; i++) {
    const table = sortedTables[i]
    if (table.foreignKeys?.length === 0) {
      const isLast = i === sortedTables.length - 1
      const meta = this.gray(`(${table.columns.length} cols, ${table.rowCount || 0} rows)`)
      lines.push(`${isLast ? "└─ " : "├─ "}${this.green("◈")} ${this.white(table.name)} ${meta}`)
    }
  }

  const rootTables = sortedTables.filter((t) => !t.foreignKeys || t.foreignKeys.length === 0)
  const dependentTables = sortedTables.filter((t) => t.foreignKeys && t.foreignKeys.length > 0)

  if (dependentTables.length > 0 && rootTables.length > 0) {
    lines.push("")
  }

  for (let i = 0; i < dependentTables.length; i++) {
    const table = dependentTables[i]
    const isLast = i === dependentTables.length - 1
    renderTable(table.name, 0, "", isLast, i, dependentTables.length)
  }

  lines.push("")

    lines.push(this.gray("Legend: ◉ Has FKs  ◈ No FKs  → References"))

    return lines.join("\n")
  }
}

export const tableRenderer = new TableRenderer()

import type { BoxRenderable, TextareaRenderable, KeyEvent, ScrollBoxRenderable } from "@opentui/core"
import fuzzysort from "fuzzysort"
import { firstBy } from "remeda"
import { createMemo, createResource, createEffect, onMount, onCleanup, Index, Show, createSignal } from "solid-js"
import { createStore } from "solid-js/store"
import { useSDK } from "@tui/context/sdk"
import { useSync } from "@tui/context/sync"
import { useTheme, selectedForeground } from "@tui/context/theme"
import { SplitBorder } from "@tui/component/border"
import { useCommandDialog } from "@tui/component/dialog-command"
import { useTerminalDimensions } from "@opentui/solid"
import { Locale } from "@/util/locale"
import type { PromptInfo } from "./history"
import { useFrecency } from "./frecency"

function removeLineRange(input: string) {
  const hashIndex = input.lastIndexOf("#")
  return hashIndex !== -1 ? input.substring(0, hashIndex) : input
}

function extractLineRange(input: string) {
  const hashIndex = input.lastIndexOf("#")
  if (hashIndex === -1) {
    return { baseQuery: input }
  }

  const baseName = input.substring(0, hashIndex)
  const linePart = input.substring(hashIndex + 1)
  const lineMatch = linePart.match(/^(\d+)(?:-(\d*))?$/)

  if (!lineMatch) {
    return { baseQuery: baseName }
  }

  const startLine = Number(lineMatch[1])
  const endLine = lineMatch[2] && startLine < Number(lineMatch[2]) ? Number(lineMatch[2]) : undefined

  return {
    lineRange: {
      baseName,
      startLine,
      endLine,
    },
    baseQuery: baseName,
  }
}

export type AutocompleteRef = {
  onInput: (value: string) => void
  onKeyDown: (e: KeyEvent) => void
  visible: false | "@" | "/"
}

export type AutocompleteOption = {
  display: string
  value?: string
  aliases?: string[]
  disabled?: boolean
  description?: string
  isDirectory?: boolean
  onSelect?: () => void
  path?: string
}

export function Autocomplete(props: {
  value: string
  sessionID?: string
  setPrompt: (input: (prompt: PromptInfo) => void) => void
  setExtmark: (partIndex: number, extmarkId: number) => void
  anchor: () => BoxRenderable
  input: () => TextareaRenderable
  ref: (ref: AutocompleteRef) => void
  fileStyleId: number
  agentStyleId: number
  promptPartTypeId: () => number
}) {
  const sdk = useSDK()
  const sync = useSync()
  const command = useCommandDialog()
  const { theme } = useTheme()
  const dimensions = useTerminalDimensions()
  const frecency = useFrecency()

  const [store, setStore] = createStore({
    index: 0,
    selected: 0,
    visible: false as AutocompleteRef["visible"],
    input: "keyboard" as "keyboard" | "mouse",
  })

  const [positionTick, setPositionTick] = createSignal(0)

  createEffect(() => {
    if (store.visible) {
      let lastPos = { x: 0, y: 0, width: 0 }
      const interval = setInterval(() => {
        const anchor = props.anchor()
        if (anchor.x !== lastPos.x || anchor.y !== lastPos.y || anchor.width !== lastPos.width) {
          lastPos = { x: anchor.x, y: anchor.y, width: anchor.width }
          setPositionTick((t) => t + 1)
        }
      }, 50)

      onCleanup(() => clearInterval(interval))
    }
  })

  const position = createMemo(() => {
    if (!store.visible) return { x: 0, y: 0, width: 0 }
    const dims = dimensions()
    positionTick()
    const anchor = props.anchor()
    const parent = anchor.parent
    const parentX = parent?.x ?? 0
    const parentY = parent?.y ?? 0

    return {
      x: anchor.x - parentX,
      y: anchor.y - parentY,
      width: anchor.width,
    }
  })

  const filter = createMemo(() => {
    if (!store.visible) return
    // Track props.value to make memo reactive to text changes
    props.value // <- there surely is a better way to do this, like making .input() reactive

    return props.input().getTextRange(store.index + 1, props.input().cursorOffset)
  })

  // When the filter changes due to how TUI works, the mousemove might still be triggered
  // via a synthetic event as the layout moves underneath the cursor. This is a workaround to make sure the input mode remains keyboard so
  // that the mouseover event doesn't trigger when filtering.
  createEffect(() => {
    filter()
    setStore("input", "keyboard")
  })

  function insertPart(text: string, part: PromptInfo["parts"][number]) {
    const input = props.input()
    const currentCursorOffset = input.cursorOffset

    const charAfterCursor = props.value.at(currentCursorOffset)
    const needsSpace = charAfterCursor !== " "
    const append = "@" + text + (needsSpace ? " " : "")

    input.cursorOffset = store.index
    const startCursor = input.logicalCursor
    input.cursorOffset = currentCursorOffset
    const endCursor = input.logicalCursor

    input.deleteRange(startCursor.row, startCursor.col, endCursor.row, endCursor.col)
    input.insertText(append)

    const virtualText = "@" + text
    const extmarkStart = store.index
    const extmarkEnd = extmarkStart + Bun.stringWidth(virtualText)

    const styleId = part.type === "file" ? props.fileStyleId : part.type === "agent" ? props.agentStyleId : undefined

    const extmarkId = input.extmarks.create({
      start: extmarkStart,
      end: extmarkEnd,
      virtual: true,
      styleId,
      typeId: props.promptPartTypeId(),
    })

    props.setPrompt((draft) => {
      if (part.type === "file") {
        const existingIndex = draft.parts.findIndex((p) => p.type === "file" && "url" in p && p.url === part.url)
        if (existingIndex !== -1) {
          const existing = draft.parts[existingIndex]
          if (
            part.source?.text &&
            existing &&
            "source" in existing &&
            existing.source &&
            "text" in existing.source &&
            existing.source.text
          ) {
            existing.source.text.start = extmarkStart
            existing.source.text.end = extmarkEnd
            existing.source.text.value = virtualText
          }
          return
        }
      }

      if (part.type === "file" && part.source?.text) {
        part.source.text.start = extmarkStart
        part.source.text.end = extmarkEnd
        part.source.text.value = virtualText
      } else if (part.type === "agent" && part.source) {
        part.source.start = extmarkStart
        part.source.end = extmarkEnd
        part.source.value = virtualText
      }
      const partIndex = draft.parts.length

    draft.parts.push(part)
    props.setExtmark(partIndex, extmarkId)
  })

  if (part.type === "file" && part.source && part.source.type === "file") {
    frecency.updateFrecency(part.source.path)
  }
}

const [files] = createResource(
  () => filter(),
  async (query) => {
    if (!store.visible || store.visible === "/") return []

    const { lineRange, baseQuery } = extractLineRange(query ?? "")

    // Get files from SDK
    const result = await sdk.client.find.files({
      query: baseQuery,
    })

    const options: AutocompleteOption[] = []

    // Add file options
    if (!result.error && result.data) {
      const sortedFiles = result.data.sort((a, b) => {
        const aScore = frecency.getFrecency(a)
        const bScore = frecency.getFrecency(b)
        if (aScore !== bScore) return bScore - aScore
        const aDepth = a.split("/").length
        const bDepth = b.split("/").length
        if (aDepth !== bDepth) return aDepth - bDepth
        return a.localeCompare(b)
      })

      const width = props.anchor().width - 4
      options.push(
        ...sortedFiles.map((item): AutocompleteOption => {
          let url = `file://${process.cwd()}/${item}`
          let filename = item
          if (lineRange && !item.endsWith("/")) {
            filename = `${item}#${lineRange.startLine}${lineRange.endLine ? `-${lineRange.endLine}` : ""}`
            const urlObj = new URL(url)
            urlObj.searchParams.set("start", String(lineRange.startLine))
            if (lineRange.endLine !== undefined) {
              urlObj.searchParams.set("end", String(lineRange.endLine))
            }
            url = urlObj.toString()
          }

          const isDir = item.endsWith("/")
          return {
            display: Locale.truncateMiddle(filename, width),
            value: filename,
            isDirectory: isDir,
            path: item,
            onSelect: () => {
              insertPart(filename, {
                type: "file",
                mime: "text/plain",
                filename,
                url,
                source: {
                  type: "file",
                  text: {
                    start: 0,
                    end: 0,
                    value: "",
                  },
                  path: item,
                },
              })
            },
          }
        }),
      )
    }

    return options
  },
  {
    initialValue: [],
  },
)

const mcpResources = createMemo(() => {
  if (!store.visible || store.visible === "/") return []

  const options: AutocompleteOption[] = []
  const width = props.anchor().width - 4

  for (const res of Object.values(sync.data.mcp_resource)) {
    const text = `${res.name} (${res.uri})`
    options.push({
      display: Locale.truncateMiddle(text, width),
      value: text,
      description: res.description,
      onSelect: () => {
        insertPart(res.name, {
          type: "file",
          mime: res.mimeType ?? "text/plain",
          filename: res.name,
          url: res.uri,
          source: {
            type: "resource",
            text: {
              start: 0,
              end: 0,
              value: "",
            },
            clientName: res.client,
            uri: res.uri,
          },
        })
      },
    })
  }

  return options
})

const agents = createMemo(() => {
  const agents = sync.data.agent
  return agents
    .filter((agent) => !agent.hidden && agent.mode !== "primary")
    .map(
      (agent): AutocompleteOption => ({
        display: "@" + agent.name,
        onSelect: () => {
          insertPart(agent.name, {
            type: "agent",
            name: agent.name,
            source: {
              start: 0,
              end: 0,
              value: "",
            },
          })
        },
      }),
    )
})

const commands = createMemo((): AutocompleteOption[] => {
  const results: AutocompleteOption[] = [...command.slashes()]

  for (const serverCommand of sync.data.command) {
    results.push({
      display: "/" + serverCommand.name + (serverCommand.mcp ? " (MCP)" : ""),
      description: serverCommand.description,
      onSelect: () => {
        const newText = "/" + serverCommand.name + " "
        const cursor = props.input().logicalCursor
        props.input().deleteRange(0, 0, cursor.row, cursor.col)
        props.input().insertText(newText)
        props.input().cursorOffset = Bun.stringWidth(newText)
      },
    })
  }

  results.sort((a, b) => a.display.localeCompare(b.display))

  const max = firstBy(results, [(x) => x.display.length, "desc"])?.display.length
  if (!max) return results
  return results.map((item) => ({
    ...item,
    display: item.display.padEnd(max + 2),
  }))
})

const options = createMemo((prev: AutocompleteOption[] | undefined) => {
  const filesValue = files()
  const agentsValue = agents()
  const commandsValue = commands()

  const mixed: AutocompleteOption[] =
    store.visible === "@" ? [...agentsValue, ...(filesValue || []), ...mcpResources()] : [...commandsValue]

  const currentFilter = filter()

  if (!currentFilter) {
    return mixed
  }

  if (files.loading && prev && prev.length > 0) {
    return prev
  }

  const result = fuzzysort.go(removeLineRange(currentFilter), mixed, {
    keys: [
      (obj) => removeLineRange((obj.value ?? obj.display).trimEnd()),
      "description",
      (obj) => obj.aliases?.join(" ") ?? "",
    ],
    limit: 10,
    scoreFn: (objResults) => {
      const displayResult = objResults[0]
      let score = objResults.score
      if (displayResult && displayResult.target.startsWith(store.visible + currentFilter)) {
        score *= 2

      }
      const frecencyScore = objResults.obj.path ? frecency.getFrecency(objResults.obj.path) : 0
      return score * (1 + frecencyScore)
    },
  })

  return result.map((arr) => arr.obj)
})

createEffect(() => {
  filter()
  setStore("selected", 0)
})

function move(direction: -1 | 1) {
  if (!store.visible) return
  if (!options().length) return
  let next = store.selected + direction
  if (next < 0) next = options().length - 1
  if (next >= options().length) next = 0
  moveTo(next)
}

function moveTo(next: number) {
  setStore("selected", next)
  if (!scroll) return
  const viewportHeight = Math.min(height(), options().length)
  const scrollBottom = scroll.scrollTop + viewportHeight
  if (next < scroll.scrollTop) {
    scroll.scrollBy(next - scroll.scrollTop)
  } else if (next + 1 > scrollBottom) {
    scroll.scrollBy(next + 1 - scrollBottom)
  }
}

function select() {
  const selected = options()[store.selected]
  if (!selected) return
  hide()
  selected.onSelect?.()
}

function expandDirectory() {
  const selected = options()[store.selected]
  if (!selected) return

  const input = props.input()
  const currentCursorOffset = input.cursorOffset

  const displayText = selected.display.trimEnd()
  const path = displayText.startsWith("@") ? displayText.slice(1) : displayText

  input.cursorOffset = store.index
  const startCursor = input.logicalCursor
  input.cursorOffset = currentCursorOffset
  const endCursor = input.logicalCursor

  input.deleteRange(startCursor.row, startCursor.col, endCursor.row, endCursor.col)
  input.insertText("@" + path)

  setStore("selected", 0)
}

function show(mode: "@" | "/") {
  command.keybinds(false)
  setStore({
    visible: mode,
    index: props.input().cursorOffset,
  })
}

function hide() {
  const text = props.input().plainText
  if (store.visible === "/" && !text.endsWith(" ") && text.startsWith("/")) {
    const cursor = props.input().logicalCursor
    props.input().deleteRange(0, 0, cursor.row, cursor.col)
    // Sync the prompt store immediately since onContentChange is async
    props.setPrompt((draft) => {
      draft.input = props.input().plainText
    })
  }
  command.keybinds(true)
  setStore("visible", false)
}

onMount(() => {
  props.ref({
    get visible() {
      return store.visible
    },
    onInput(value) {
      if (store.visible) {
        if (
          // Typed text before the trigger
          props.input().cursorOffset <= store.index ||
          // There is a space between the trigger and the cursor
          props.input().getTextRange(store.index, props.input().cursorOffset).match(/\s/) ||
          // "/<command>" is not the sole content
          (store.visible === "/" && value.match(/^\S+\s+\S+\s*$/))
        ) {
          hide()
        }
        return
      }

      // Check if autocomplete should reopen (e.g., after backspace deleted a space)
      const offset = props.input().cursorOffset
      if (offset === 0) return

      // Check for "/" at position 0 - reopen slash commands
      if (value.startsWith("/") && !value.slice(0, offset).match(/\s/)) {
        show("/")
        setStore("index", 0)
        return
      }

      // Check for "@" trigger - find the nearest "@" before cursor with no whitespace between
      const text = value.slice(0, offset)
      const idx = text.lastIndexOf("@")
      if (idx === -1) return

      const between = text.slice(idx)
      const before = idx === 0 ? undefined : value[idx - 1]
      if ((before === undefined || /\s/.test(before)) && !between.match(/\s/)) {
        show("@")
        setStore("index", idx)
      }
    },
    onKeyDown(e: KeyEvent) {
      if (store.visible) {
        const name = e.name?.toLowerCase()
        const ctrlOnly = e.ctrl && !e.meta && !e.shift
        const isNavUp = name === "up" || (ctrlOnly && name === "p")
        const isNavDown = name === "down" || (ctrlOnly && name === "n")

        if (isNavUp) {
          setStore("input", "keyboard")
          move(-1)
          e.preventDefault()
          return
        }
        if (isNavDown) {
          setStore("input", "keyboard")
          move(1)
          e.preventDefault()
          return
        }
        if (name === "escape") {
          hide()
          e.preventDefault()
          return
        }
        if (name === "return") {
          select()
          e.preventDefault()
          return
        }
        if (name === "tab") {
          const selected = options()[store.selected]
          if (selected?.isDirectory) {
            expandDirectory()
          } else {
            select()
          }
          e.preventDefault()
          return
        }
      }
      if (!store.visible) {
        if (e.name === "@") {
          const cursorOffset = props.input().cursorOffset
          const charBeforeCursor =
            cursorOffset === 0 ? undefined : props.input().getTextRange(cursorOffset - 1, cursorOffset)
          const canTrigger = charBeforeCursor === undefined || charBeforeCursor === "" || /\s/.test(charBeforeCursor)
          if (canTrigger) show("@")
        }

        if (e.name === "/") {
          if (props.input().cursorOffset === 0) show("/")
        }
      }
    },
  })
})

const height = createMemo(() => {
  const count = options().length || 1
  if (!store.visible) return Math.min(10, count)
  positionTick()
  return Math.min(10, count, Math.max(1, props.anchor().y))
})

let scroll: ScrollBoxRenderable

return (
  <box
    visible={store.visible !== false}
    position="absolute"
    top={position().y - height()}
    left={position().x}

      width={position().width}
      zIndex={100}
      {...SplitBorder}
      borderColor={theme.border}
    >
      <scrollbox
        ref={(r: ScrollBoxRenderable) => (scroll = r)}
        backgroundColor={theme.backgroundMenu}
        height={height()}
        scrollbarOptions={{ visible: false }}
      >
        <Index
          each={options()}
          fallback={
            <box paddingLeft={1} paddingRight={1}>
              <text fg={theme.textMuted}>No matching items</text>
            </box>
          }
        >
          {(option, index) => (
            <box
              paddingLeft={1}
              paddingRight={1}
              backgroundColor={index === store.selected ? theme.primary : undefined}
              flexDirection="row"
              onMouseMove={() => {
                setStore("input", "mouse")
              }}
              onMouseOver={() => {
                if (store.input !== "mouse") return
                moveTo(index)
              }}
              onMouseDown={() => {
                setStore("input", "mouse")
                moveTo(index)
              }}
              onMouseUp={() => select()}
            >
              <text fg={index === store.selected ? selectedForeground(theme) : theme.text} flexShrink={0}>
                {option().display}
              </text>
              <Show when={option().description}>
                <text fg={index === store.selected ? selectedForeground(theme) : theme.textMuted} wrapMode="none">
                  {option().description}
                </text>
              </Show>
            </box>
          )}
        </Index>
      </scrollbox>
    </box>
  )
}

import path from "path"
import { Global } from "@/global"
import { onMount } from "solid-js"
import { createStore, produce } from "solid-js/store"
import { clone } from "remeda"
import { createSimpleContext } from "../../context/helper"
import { appendFile, writeFile } from "fs/promises"
import type { AgentPart, FilePart, TextPart } from "@nikcli-ai/sdk/v2"

export type PromptInfo = {
  input: string
  mode?: "normal" | "shell"
  parts: (
    | Omit<FilePart, "id" | "messageID" | "sessionID">
    | Omit<AgentPart, "id" | "messageID" | "sessionID">
    | (Omit<TextPart, "id" | "messageID" | "sessionID"> & {
        source?: {
          text: {
            start: number
            end: number
            value: string
          }
        }
      })
  )[]
}

const MAX_HISTORY_ENTRIES = 50

export const { use: usePromptHistory, provider: PromptHistoryProvider } = createSimpleContext({
  name: "PromptHistory",
  init: () => {
    const historyFile = Bun.file(path.join(Global.Path.state, "prompt-history.jsonl"))
    onMount(async () => {
      const text = await historyFile.text().catch(() => "")
      const lines = text
        .split("\n")
        .filter(Boolean)
        .map((line) => {
          try {
            return JSON.parse(line)
          } catch {
            return null
          }
        })
        .filter((line): line is PromptInfo => line !== null)
        .slice(-MAX_HISTORY_ENTRIES)

      setStore("history", lines)

      // Rewrite file with only valid entries to self-heal corruption
      if (lines.length > 0) {
        const content = lines.map((line) => JSON.stringify(line)).join("\n") + "\n"
        writeFile(historyFile.name!, content).catch(() => {})
      }
    })

    const [store, setStore] = createStore({
      index: 0,
      history: [] as PromptInfo[],
    })

    return {
      move(direction: 1 | -1, input: string) {
        if (!store.history.length) return undefined
        const current = store.history.at(store.index)
        if (!current) return undefined
        if (current.input !== input && input.length) return
        setStore(
          produce((draft) => {
            const next = store.index + direction
            if (Math.abs(next) > store.history.length) return
            if (next > 0) return
            draft.index = next
          }),
        )
        if (store.index === 0)
          return {
            input: "",
            parts: [],
          }
        return store.history.at(store.index)
      },
      append(item: PromptInfo) {
        const entry = clone(item)
        let trimmed = false
        setStore(
          produce((draft) => {
            draft.history.push(entry)
            if (draft.history.length > MAX_HISTORY_ENTRIES) {
              draft.history = draft.history.slice(-MAX_HISTORY_ENTRIES)
              trimmed = true
            }
            draft.index = 0
          }),
        )

        if (trimmed) {
          const content = store.history.map((line) => JSON.stringify(line)).join("\n") + "\n"
          writeFile(historyFile.name!, content).catch(() => {})
          return
        }

        appendFile(historyFile.name!, JSON.stringify(entry) + "\n").catch(() => {})
      },
    }
  },
})

import path from "path"
import { Global } from "@/global"
import { onMount } from "solid-js"
import { createStore } from "solid-js/store"
import { createSimpleContext } from "../../context/helper"
import { appendFile } from "fs/promises"

function calculateFrecency(entry?: { frequency: number; lastOpen: number }): number {
  if (!entry) return 0
  const daysSince = (Date.now() - entry.lastOpen) / 86400000 // ms per day
  const weight = 1 / (1 + daysSince)
  return entry.frequency * weight
}

const MAX_FRECENCY_ENTRIES = 1000

export const { use: useFrecency, provider: FrecencyProvider } = createSimpleContext({
  name: "Frecency",
  init: () => {
    const frecencyFile = Bun.file(path.join(Global.Path.state, "frecency.jsonl"))
    onMount(async () => {
      const text = await frecencyFile.text().catch(() => "")
      const lines = text
        .split("\n")
        .filter(Boolean)
        .map((line) => {
          try {
            return JSON.parse(line) as { path: string; frequency: number; lastOpen: number }
          } catch {
            return null
          }
        })
        .filter((line): line is { path: string; frequency: number; lastOpen: number } => line !== null)

      const latest = lines.reduce(
        (acc, entry) => {
          acc[entry.path] = entry
          return acc
        },
        {} as Record<string, { path: string; frequency: number; lastOpen: number }>,
      )

      const sorted = Object.values(latest)
        .sort((a, b) => b.lastOpen - a.lastOpen)
        .slice(0, MAX_FRECENCY_ENTRIES)

      setStore(
        "data",
        Object.fromEntries(
          sorted.map((entry) => [entry.path, { frequency: entry.frequency, lastOpen: entry.lastOpen }]),
        ),
      )

      if (sorted.length > 0) {
        const content = sorted.map((entry) => JSON.stringify(entry)).join("\n") + "\n"
        Bun.write(frecencyFile, content).catch(() => {})
      }
    })

    const [store, setStore] = createStore({
      data: {} as Record<string, { frequency: number; lastOpen: number }>,
    })

    function updateFrecency(filePath: string) {
      const absolutePath = path.resolve(process.cwd(), filePath)
      const newEntry = {
        frequency: (store.data[absolutePath]?.frequency || 0) + 1,
        lastOpen: Date.now(),
      }
      setStore("data", absolutePath, newEntry)
      appendFile(frecencyFile.name!, JSON.stringify({ path: absolutePath, ...newEntry }) + "\n").catch(() => {})

      if (Object.keys(store.data).length > MAX_FRECENCY_ENTRIES) {
        const sorted = Object.entries(store.data)
          .sort(([, a], [, b]) => b.lastOpen - a.lastOpen)
          .slice(0, MAX_FRECENCY_ENTRIES)
        setStore("data", Object.fromEntries(sorted))
        const content = sorted.map(([path, entry]) => JSON.stringify({ path, ...entry })).join("\n") + "\n"
        Bun.write(frecencyFile, content).catch(() => {})
      }
    }

    return {
      getFrecency: (filePath: string) => calculateFrecency(store.data[path.resolve(process.cwd(), filePath)]),
      updateFrecency,
      data: () => store.data,
    }
  },
})

import path from "path"
import { Global } from "@/global"
import { onMount } from "solid-js"
import { createStore, produce } from "solid-js/store"
import { clone } from "remeda"
import { createSimpleContext } from "../../context/helper"
import { appendFile, writeFile } from "fs/promises"
import type { PromptInfo } from "./history"

export type StashEntry = {
  input: string
  parts: PromptInfo["parts"]
  timestamp: number
}

const MAX_STASH_ENTRIES = 50

export const { use: usePromptStash, provider: PromptStashProvider } = createSimpleContext({
  name: "PromptStash",
  init: () => {
    const stashFile = Bun.file(path.join(Global.Path.state, "prompt-stash.jsonl"))
    onMount(async () => {
      const text = await stashFile.text().catch(() => "")
      const lines = text
        .split("\n")
        .filter(Boolean)
        .map((line) => {
          try {
            return JSON.parse(line)
          } catch {
            return null
          }
        })
        .filter((line): line is StashEntry => line !== null)
        .slice(-MAX_STASH_ENTRIES)

      setStore("entries", lines)

      // Rewrite file with only valid entries to self-heal corruption
      if (lines.length > 0) {
        const content = lines.map((line) => JSON.stringify(line)).join("\n") + "\n"
        writeFile(stashFile.name!, content).catch(() => {})
      }
    })

    const [store, setStore] = createStore({
      entries: [] as StashEntry[],
    })

    return {
      list() {
        return store.entries
      },
      push(entry: Omit<StashEntry, "timestamp">) {
        const stash = clone({ ...entry, timestamp: Date.now() })
        let trimmed = false
        setStore(
          produce((draft) => {
            draft.entries.push(stash)
            if (draft.entries.length > MAX_STASH_ENTRIES) {
              draft.entries = draft.entries.slice(-MAX_STASH_ENTRIES)
              trimmed = true
            }
          }),
        )

        if (trimmed) {
          const content = store.entries.map((line) => JSON.stringify(line)).join("\n") + "\n"
          writeFile(stashFile.name!, content).catch(() => {})
          return
        }

        appendFile(stashFile.name!, JSON.stringify(stash) + "\n").catch(() => {})
      },
      pop() {
        if (store.entries.length === 0) return undefined
        const entry = store.entries[store.entries.length - 1]
        setStore(
          produce((draft) => {
            draft.entries.pop()
          }),
        )
        const content =
          store.entries.length > 0 ? store.entries.map((line) => JSON.stringify(line)).join("\n") + "\n" : ""
        writeFile(stashFile.name!, content).catch(() => {})
        return entry
      },
      remove(index: number) {
        if (index < 0 || index >= store.entries.length) return
        setStore(
          produce((draft) => {
            draft.entries.splice(index, 1)
          }),
        )
        const content =
          store.entries.length > 0 ? store.entries.map((line) => JSON.stringify(line)).join("\n") + "\n" : ""
        writeFile(stashFile.name!, content).catch(() => {})
      },
    }
  },
})

