        break
      }
      setStore(
        "dbedit",
        request.sessionID,
        produce((draft) => {
          draft.splice(match.index, 0, request)
        }),
      )
      break
    }

    case "todo.updated":
      setStore("todo", event.properties.sessionID, event.properties.todos)
      break

    case "session.diff":
      setStore("session_diff", event.properties.sessionID, event.properties.diff)
      break

    case "session.deleted": {
      const result = Binary.search(store.session, event.properties.info.id, (s) => s.id)
      if (result.found) {
        setStore(
          "session",
          produce((draft) => {
            draft.splice(result.index, 1)
          }),
        )
      }
      break
    }
    case "session.updated": {
      const result = Binary.search(store.session, event.properties.info.id, (s) => s.id)
      if (result.found) {
        setStore("session", result.index, reconcile(event.properties.info))
        break
      }
      setStore(
        "session",
        produce((draft) => {
          draft.splice(result.index, 0, event.properties.info)
        }),
      )
      break
    }

    case "session.status": {
      setStore("session_status", event.properties.sessionID, event.properties.status)
      break
    }

    case "message.updated": {
      const messages = store.message[event.properties.info.sessionID]
      if (!messages) {
        setStore("message", event.properties.info.sessionID, [event.properties.info])
        break
      }
      const result = Binary.search(messages, event.properties.info.id, (m) => m.id)
      if (result.found) {
        setStore("message", event.properties.info.sessionID, result.index, reconcile(event.properties.info))
        break
      }
      setStore(
        "message",
        event.properties.info.sessionID,
        produce((draft) => {
          draft.splice(result.index, 0, event.properties.info)
        }),
      )
      const updated = store.message[event.properties.info.sessionID]
      if (updated.length > 100) {
        const oldest = updated[0]
        batch(() => {
          setStore(
            "message",
            event.properties.info.sessionID,
            produce((draft) => {
              draft.shift()
            }),
          )
          setStore(
            "part",
            produce((draft) => {
              delete draft[oldest.id]
            }),
          )
        })
      }
      break
    }
    case "message.removed": {
      const messages = store.message[event.properties.sessionID]
      const result = Binary.search(messages, event.properties.messageID, (m) => m.id)
      if (result.found) {
        setStore(
          "message",
          event.properties.sessionID,
          produce((draft) => {
            draft.splice(result.index, 1)
          }),
        )
      }
      break
    }
    case "message.part.updated": {
      const parts = store.part[event.properties.part.messageID]
      if (!parts) {
        setStore("part", event.properties.part.messageID, [event.properties.part])
        break
      }
      const result = Binary.search(parts, event.properties.part.id, (p) => p.id)
      if (result.found) {
        setStore("part", event.properties.part.messageID, result.index, reconcile(event.properties.part))
        break
      }
      setStore(
        "part",
        event.properties.part.messageID,
        produce((draft) => {
          draft.splice(result.index, 0, event.properties.part)
        }),
      )
      break
    }

    case "message.part.removed": {
      const parts = store.part[event.properties.messageID]
      const result = Binary.search(parts, event.properties.partID, (p) => p.id)
      if (result.found)
        setStore(
          "part",
          event.properties.messageID,
          produce((draft) => {
            draft.splice(result.index, 1)
          }),
        )
      break
    }

    case "file.edited": {
      const file = event.properties.file
      if (!isDBFile(file)) break
      const processSchema = async () => {
        try {
          let schema: DBSchema | null = null
          if (file.endsWith(".sql") || file.endsWith(".prisma")) {
            const content = readFileSync(file, "utf-8")
            schema = await createDBSchemaFromSQL(content)
          } else {
            schema = await readDBSchema(file)
          }
          if (schema?.tables && schema.tables.length > 0) {
            setStore("dbschema", file, schema)
          }
        } catch {
          // Silent fail - file might be invalid or still being written
        }
      }
      processSchema()
      break
    }

    case "lsp.updated": {
      sdk.client.lsp.status().then((x) => setStore("lsp", x.data!))
      break
    }

    case "vcs.branch.updated": {
      setStore("vcs", { branch: event.properties.branch })
      break
    }
  }
})

const exit = useExit()
const args = useArgs()

async function bootstrap() {
  console.log("bootstrapping")
  const start = Date.now() - 30 * 24 * 60 * 60 * 1000
  const sessionListPromise = sdk.client.session
    .list({ start: start })
    .then((x) => setStore("session", reconcile((x.data ?? []).toSorted((a, b) => a.id.localeCompare(b.id)))))

  // blocking - include session.list when continuing a session
  const blockingRequests: Promise<unknown>[] = [
    sdk.client.config.providers({}, { throwOnError: true }).then((x) => {
      batch(() => {
        setStore("provider", reconcile(x.data!.providers))
        setStore("provider_default", reconcile(x.data!.default))
      })
    }),
    sdk.client.provider.list({}, { throwOnError: true }).then((x) => {
      batch(() => {
        setStore("provider_next", reconcile(x.data!))
      })
    }),
    sdk.client.app.agents({}, { throwOnError: true }).then((x) => setStore("agent", reconcile(x.data ?? []))),

        sdk.client.config.get({}, { throwOnError: true }).then((x) => setStore("config", reconcile(x.data!))),
        ...(args.continue ? [sessionListPromise] : []),
      ]

      await Promise.all(blockingRequests)
        .then(() => {
          if (store.status !== "complete") setStore("status", "partial")
          // non-blocking
          Promise.all([
            ...(args.continue ? [] : [sessionListPromise]),
            sdk.client.command.list().then((x) => setStore("command", reconcile(x.data ?? []))),
            sdk.client.lsp.status().then((x) => setStore("lsp", reconcile(x.data!))),
            sdk.client.mcp.status().then((x) => setStore("mcp", reconcile(x.data!))),
            sdk.client.experimental.resource.list().then((x) => setStore("mcp_resource", reconcile(x.data ?? {}))),
            sdk.client.connectors.status().then((x) => setStore("connectors", reconcile(x.data ?? {}))),
            sdk.client.formatter.status().then((x) => setStore("formatter", reconcile(x.data!))),
            sdk.client.session.status().then((x) => {
              setStore("session_status", reconcile(x.data!))
            }),
            sdk.client.provider.auth().then((x) => setStore("provider_auth", reconcile(x.data ?? {}))),
            sdk.client.vcs.get().then((x) => setStore("vcs", reconcile(x.data))),
            sdk.client.path.get().then((x) => setStore("path", reconcile(x.data!))),
          ]).then(() => {
            setStore("status", "complete")
          })
        })
        .catch(async (e) => {
          Log.Default.error("tui bootstrap failed", {
            error: e instanceof Error ? e.message : String(e),
            name: e instanceof Error ? e.name : undefined,
            stack: e instanceof Error ? e.stack : undefined,
          })
          await exit(e)
        })
    }

    onMount(() => {
      bootstrap()
    })

    const fullSyncedSessions = new Set<string>()
    const result = {
      data: store,
      set: setStore,
      get status() {
        return store.status
      },
      get ready() {
        return store.status !== "loading"
      },
      session: {
        get(sessionID: string) {
          const match = Binary.search(store.session, sessionID, (s) => s.id)
          if (match.found) return store.session[match.index]
          return undefined
        },
        status(sessionID: string) {
          const session = result.session.get(sessionID)
          if (!session) return "idle"
          if (session.time.compacting) return "compacting"
          const messages = store.message[sessionID] ?? []
          const last = messages.at(-1)
          if (!last) return "idle"
          if (last.role === "user") return "working"
          return last.time.completed ? "idle" : "working"
        },
        async sync(sessionID: string) {
          if (fullSyncedSessions.has(sessionID)) return
          const [session, messages, todo, diff] = await Promise.all([
            sdk.client.session.get({ sessionID }, { throwOnError: true }),
            sdk.client.session.messages({ sessionID, limit: 100 }),
            sdk.client.session.todo({ sessionID }),
            sdk.client.session.diff({ sessionID }),
          ])
          setStore(
            produce((draft) => {
              const match = Binary.search(draft.session, sessionID, (s) => s.id)
              if (match.found) draft.session[match.index] = session.data!
              if (!match.found) draft.session.splice(match.index, 0, session.data!)
              draft.todo[sessionID] = todo.data ?? []
              draft.message[sessionID] = messages.data!.map((x) => x.info)
              for (const message of messages.data!) {
                draft.part[message.info.id] = message.parts
              }
              draft.session_diff[sessionID] = diff.data ?? []
            }),
          )
          fullSyncedSessions.add(sessionID)
        },
      },
      bootstrap,
    }
    return result
  },
})

import { useRenderer } from "@opentui/solid"
import { createSimpleContext } from "./helper"
import { FormatError, FormatUnknownError } from "@/cli/error"

export const { use: useExit, provider: ExitProvider } = createSimpleContext({
  name: "Exit",
  init: (input: { onExit?: () => Promise<void> }) => {
    const renderer = useRenderer()
    return async (reason?: any) => {
      // Reset window title before destroying renderer
      renderer.setTerminalTitle("")
      renderer.destroy()
      await input.onExit?.()
      if (reason) {
        const formatted = FormatError(reason) ?? FormatUnknownError(reason)
        if (formatted) {
          process.stderr.write(formatted + "\n")
        }
      }
      process.exit(0)
    }
  },
})

import { createStore } from "solid-js/store"
import { createSimpleContext } from "./helper"
import type { PromptInfo } from "../component/prompt/history"

export type HomeRoute = {
  type: "home"
  initialPrompt?: PromptInfo
}

export type SessionRoute = {
  type: "session"
  sessionID: string
  initialPrompt?: PromptInfo
}

export type Route = HomeRoute | SessionRoute

export const { use: useRoute, provider: RouteProvider } = createSimpleContext({
  name: "Route",
  init: () => {
    const [store, setStore] = createStore<Route>(
      process.env["NIKCLI_ROUTE"]
        ? JSON.parse(process.env["NIKCLI_ROUTE"])
        : {
            type: "home",
          },
    )

    return {
      get data() {
        return store
      },
      navigate(route: Route) {
        console.log("navigate", route)
        setStore(route)
      },
    }
  },
})

export type RouteContext = ReturnType<typeof useRoute>

export function useRouteData<T extends Route["type"]>(type: T) {
  const route = useRoute()
  return route.data as Extract<Route, { type: typeof type }>
}

import { createContext, Show, useContext, type ParentProps } from "solid-js"

export function createSimpleContext<T, Props extends Record<string, any>>(input: {
  name: string
  init: ((input: Props) => T) | (() => T)
}) {
  const ctx = createContext<T>()

  return {
    provider: (props: ParentProps<Props>) => {
      const init = input.init(props)
      return (
        // @ts-expect-error
        <Show when={init.ready === undefined || init.ready === true}>
          <ctx.Provider value={init}>{props.children}</ctx.Provider>
        </Show>
      )
    },
    use() {
      const value = useContext(ctx)
      if (!value) throw new Error(`${input.name} context must be used within a context provider`)
      return value
    },
  }
}

import { createStore } from "solid-js/store"
import { batch, createEffect, createMemo } from "solid-js"
import { useSync } from "@tui/context/sync"
import { useTheme } from "@tui/context/theme"
import { uniqueBy } from "remeda"
import path from "path"
import { Global } from "@/global"
import { iife } from "@/util/iife"
import { createSimpleContext } from "./helper"
import { useToast } from "../ui/toast"
import { Provider } from "@/provider/provider"
import { useArgs } from "./args"
import { useSDK } from "./sdk"
import { RGBA } from "@opentui/core"

export const { use: useLocal, provider: LocalProvider } = createSimpleContext({
  name: "Local",
  init: () => {
    const sync = useSync()
    const sdk = useSDK()
    const toast = useToast()

    function isModelValid(model: { providerID: string; modelID: string }) {
      const provider = sync.data.provider.find((x) => x.id === model.providerID)
      return !!provider?.models[model.modelID]
    }

    function getFirstValidModel(...modelFns: (() => { providerID: string; modelID: string } | undefined)[]) {
      for (const modelFn of modelFns) {
        const model = modelFn()
        if (!model) continue
        if (isModelValid(model)) return model
      }
    }

    const agent = iife(() => {
      const agents = createMemo(() => sync.data.agent.filter((x) => x.mode !== "subagent" && !x.hidden))
      const [agentStore, setAgentStore] = createStore<{
        current: string
      }>({
        current: agents()[0].name,
      })
      const { theme } = useTheme()
      const colors = createMemo(() => [
        theme.secondary,
        theme.accent,
        theme.success,
        theme.warning,
        theme.primary,
        theme.error,
      ])
      return {
        list() {
          return agents()
        },
        current() {
          return agents().find((x) => x.name === agentStore.current)!
        },
        set(name: string) {
          if (!agents().some((x) => x.name === name))
            return toast.show({
              variant: "warning",
              message: `Agent not found: ${name}`,
              duration: 3000,
            })
          setAgentStore("current", name)
        },
        move(direction: 1 | -1) {
          batch(() => {
            let next = agents().findIndex((x) => x.name === agentStore.current) + direction
            if (next < 0) next = agents().length - 1
            if (next >= agents().length) next = 0
            const value = agents()[next]
            setAgentStore("current", value.name)
          })
        },
        color(name: string) {
          const all = sync.data.agent
          const agent = all.find((x) => x.name === name)
          if (agent?.color) return RGBA.fromHex(agent.color)
          const index = all.findIndex((x) => x.name === name)
          if (index === -1) return colors()[0]
          return colors()[index % colors().length]
        },
      }
    })

    const model = iife(() => {
      const [modelStore, setModelStore] = createStore<{
        ready: boolean
        model: Record<
          string,
          {
            providerID: string
            modelID: string
          }
        >
        recent: {
          providerID: string
          modelID: string
        }[]
        favorite: {
          providerID: string
          modelID: string
        }[]
        variant: Record<string, string | undefined>
      }>({
        ready: false,
        model: {},
        recent: [],
        favorite: [],
        variant: {},
      })

      const file = Bun.file(path.join(Global.Path.state, "model.json"))
      const state = {
        pending: false,
      }

      function save() {
        if (!modelStore.ready) {
          state.pending = true
          return
        }
        state.pending = false
        Bun.write(
          file,
          JSON.stringify({
            recent: modelStore.recent,
            favorite: modelStore.favorite,
            variant: modelStore.variant,
          }),
        )
      }

      file
        .json()
        .then((x) => {
          if (Array.isArray(x.recent)) setModelStore("recent", x.recent)
          if (Array.isArray(x.favorite)) setModelStore("favorite", x.favorite)
          if (typeof x.variant === "object" && x.variant !== null) setModelStore("variant", x.variant)
        })
        .catch(() => {})
        .finally(() => {
          setModelStore("ready", true)
          if (state.pending) save()
        })

      const args = useArgs()
      const fallbackModel = createMemo(() => {
        if (args.model) {
          const { providerID, modelID } = Provider.parseModel(args.model)
          if (isModelValid({ providerID, modelID })) {
            return {
              providerID,
              modelID,
            }
          }
        }

        if (sync.data.config.model) {
          const { providerID, modelID } = Provider.parseModel(sync.data.config.model)
          if (isModelValid({ providerID, modelID })) {
            return {
              providerID,
              modelID,
            }
          }
        }

        for (const item of modelStore.recent) {
          if (isModelValid(item)) {
            return item
          }
        }

        const provider = sync.data.provider[0]
        if (!provider) return undefined
        const defaultModel = sync.data.provider_default[provider.id]
        const firstModel = Object.values(provider.models)[0]
        const model = defaultModel ?? firstModel?.id
        if (!model) return undefined
        return {
          providerID: provider.id,
          modelID: model,
        }
      })

      const currentModel = createMemo(() => {
        const a = agent.current()
        return (
          getFirstValidModel(
            () => modelStore.model[a.name],
            () => a.model,
            fallbackModel,
          ) ?? undefined
        )
      })

      return {

    current: currentModel,
    get ready() {
      return modelStore.ready
    },
    recent() {
      return modelStore.recent
    },
    favorite() {
      return modelStore.favorite
    },
    parsed: createMemo(() => {
      const value = currentModel()
      if (!value) {
        return {
          provider: "Connect a provider",
          model: "No provider selected",
          reasoning: false,
        }
      }
      const provider = sync.data.provider.find((x) => x.id === value.providerID)
      const info = provider?.models[value.modelID]
      return {
        provider: provider?.name ?? value.providerID,
        model: info?.name ?? value.modelID,
        reasoning: info?.capabilities?.reasoning ?? false,
      }
    }),
    cycle(direction: 1 | -1) {
      const current = currentModel()
      if (!current) return
      const recent = modelStore.recent
      const index = recent.findIndex((x) => x.providerID === current.providerID && x.modelID === current.modelID)
      if (index === -1) return
      let next = index + direction
      if (next < 0) next = recent.length - 1
      if (next >= recent.length) next = 0
      const val = recent[next]
      if (!val) return
      setModelStore("model", agent.current().name, { ...val })
    },
    cycleFavorite(direction: 1 | -1) {
      const favorites = modelStore.favorite.filter((item) => isModelValid(item))
      if (!favorites.length) {
        toast.show({
          variant: "info",
          message: "Add a favorite model to use this shortcut",
          duration: 3000,
        })
        return
      }
      const current = currentModel()
      let index = -1
      if (current) {
        index = favorites.findIndex((x) => x.providerID === current.providerID && x.modelID === current.modelID)
      }
      if (index === -1) {
        index = direction === 1 ? 0 : favorites.length - 1
      } else {
        index += direction
        if (index < 0) index = favorites.length - 1
        if (index >= favorites.length) index = 0
      }
      const next = favorites[index]
      if (!next) return
      setModelStore("model", agent.current().name, { ...next })
      const uniq = uniqueBy([next, ...modelStore.recent], (x) => `${x.providerID}/${x.modelID}`)
      if (uniq.length > 10) uniq.pop()
      setModelStore(
        "recent",
        uniq.map((x) => ({ providerID: x.providerID, modelID: x.modelID })),
      )
      save()
    },
    set(model: { providerID: string; modelID: string }, options?: { recent?: boolean }) {
      batch(() => {
        if (!isModelValid(model)) {
          toast.show({
            message: `Model ${model.providerID}/${model.modelID} is not valid`,
            variant: "warning",
            duration: 3000,
          })
          return
        }
        setModelStore("model", agent.current().name, model)
        if (options?.recent) {
          const uniq = uniqueBy([model, ...modelStore.recent], (x) => `${x.providerID}/${x.modelID}`)
          if (uniq.length > 10) uniq.pop()
          setModelStore(
            "recent",
            uniq.map((x) => ({ providerID: x.providerID, modelID: x.modelID })),
          )
          save()
        }
      })
    },
    toggleFavorite(model: { providerID: string; modelID: string }) {
      batch(() => {
        if (!isModelValid(model)) {
          toast.show({
            message: `Model ${model.providerID}/${model.modelID} is not valid`,
            variant: "warning",
            duration: 3000,
          })
          return
        }
        const exists = modelStore.favorite.some(
          (x) => x.providerID === model.providerID && x.modelID === model.modelID,
        )
        const next = exists
          ? modelStore.favorite.filter((x) => x.providerID !== model.providerID || x.modelID !== model.modelID)
          : [model, ...modelStore.favorite]
        setModelStore(
          "favorite",
          next.map((x) => ({ providerID: x.providerID, modelID: x.modelID })),
        )
        save()
      })
    },
    variant: {
      current() {
        const m = currentModel()
        if (!m) return undefined
        const key = `${m.providerID}/${m.modelID}`
        return modelStore.variant[key]
      },
      list() {
        const m = currentModel()
        if (!m) return []
        const provider = sync.data.provider.find((x) => x.id === m.providerID)
        const info = provider?.models[m.modelID]
        if (!info?.variants) return []
        return Object.keys(info.variants)
      },
      set(value: string | undefined) {
        const m = currentModel()
        if (!m) return
        const key = `${m.providerID}/${m.modelID}`
        setModelStore("variant", key, value)
        save()
      },
      cycle() {
        const variants = this.list()
        if (variants.length === 0) return
        const current = this.current()
        if (!current) {
          this.set(variants[0])
          return
        }
        const index = variants.indexOf(current)
        if (index === -1 || index === variants.length - 1) {
          this.set(undefined)
          return
        }
        this.set(variants[index + 1])
      },
    },
  }
})

const mcp = {
  isEnabled(name: string) {
    const status = sync.data.mcp[name]
    return status?.status === "connected"
  },
  async toggle(name: string) {
    const status = sync.data.mcp[name]
    if (status?.status === "connected") {
      // Disable: disconnect the MCP
      await sdk.client.mcp.disconnect({ name })
    } else {
      // Enable/Retry: connect the MCP (handles disabled, failed, and other states)
      await sdk.client.mcp.connect({ name })
    }
  },
}

const connectors = {
  isEnabled(name: string) {
    const entry = sync.data.config.connectors?.[name]
    if (!entry || typeof entry !== "object" || !("type" in entry)) return false
    return entry.enabled !== false
  },
  async toggle(name: string) {
    const entry = sync.data.config.connectors?.[name]
    if (!entry || typeof entry !== "object" || !("type" in entry)) {
      toast.show({
        variant: "warning",
        message: `Connector not found: ${name}`,
        duration: 3000,
      })
      return
    }
    const nextEnabled = entry.enabled === false
    const nextConfig = {
      ...sync.data.config,
      connectors: {
        ...(sync.data.config.connectors ?? {}),
        [name]: {
          ...entry,
          enabled: nextEnabled,

            },
          },
        }
        await sdk.client.config.update({ config: { connectors: nextConfig.connectors } })
        sync.set("config", nextConfig)
      },
      async auth(
        name: string,
        payload: {
          token?: string
          botToken?: string
          apiKey?: string
          teamId?: string
        },
      ) {
        await sdk.client.connectors.auth.set({ name, ...payload })
      },
      async logout(name: string) {
        await sdk.client.connectors.auth.remove({ name })
      },
    }

    // Automatically update model when agent changes
    createEffect(() => {
      const value = agent.current()
      if (value.model) {
        if (isModelValid(value.model))
          model.set({
            providerID: value.model.providerID,
            modelID: value.model.modelID,
          })
        else
          toast.show({
            variant: "warning",
            message: `Agent ${value.name}'s configured model ${value.model.providerID}/${value.model.modelID} is not valid`,
            duration: 3000,
          })
      }
    })

    const result = {
      model,
      agent,
      mcp,
      connectors,
    }
    return result
  },
})

import type { DBSchema, DBTable, DBColumn, DBForeignKey, DBIndex, TablePreview, QueryResult } from "./types"
import type { IDBConnection, ConnectionConfig } from "./connections"

export class PostgresConnection implements IDBConnection {
  readonly type = "postgres"
  private _config: ConnectionConfig
  private _pool: any = null

  constructor(config: ConnectionConfig) {
    this._config = config
  }

  get connected(): boolean {
    return this._pool !== null
  }

  private async _getPool(): Promise<any> {
    if (!this._pool) {
      const { default: pg } = await import("pg")
      const { Pool } = pg
      this._pool = new Pool({
        host: this._config.host,
        port: this._config.port || 5432,
        database: this._config.database,
        user: this._config.username,
        password: this._config.password,
      })
    }
    return this._pool
  }

  async getSchema(): Promise<DBSchema> {
    const pool = await this._getPool()
    const tables = await this._getPgTables(pool)
    const views = await this._getPgViews(pool)
    const indexes = await this._getPgIndexes(pool)
    return { tables, views, indexes }
  }

  private async _getPgTables(pool: any): Promise<DBTable[]> {
    const result = await pool.query(`
      SELECT table_name, table_schema
      FROM information_schema.tables
      WHERE table_schema = 'public' AND table_type = 'BASE TABLE'
      ORDER BY table_name
    `)

    const tables: DBTable[] = []
    for (const row of result.rows) {
      const tableName = row.table_name
      const columns = await this._getPgTableInfo(pool, tableName)
      const rowCount = await this._getPgRowCount(pool, tableName)
      const foreignKeys = await this._getPgForeignKeys(pool, tableName)

      tables.push({
        name: tableName,
        columns,
        primaryKey: columns.filter((c) => c.primaryKey).map((c) => c.name),
        foreignKeys,
        rowCount,
      })
    }
    return tables
  }

  private async _getPgTableInfo(pool: any, tableName: string): Promise<DBColumn[]> {
    const result = await pool.query(
      `
      SELECT column_name, data_type, is_nullable, column_default, is_identity
      FROM information_schema.columns
      WHERE table_name = $1
      ORDER BY ordinal_position
    `,
      [tableName],
    )

    const pkResult = await pool.query(
      `
      SELECT a.attname as column_name
      FROM pg_index i
      JOIN pg_attribute a ON a.attrelid = i.indrelid AND a.attnum = ANY(i.indkey)
      WHERE i.indrelid = $1::regclass AND i.indisprimary
    `,
      [tableName],
    )

    const pkColumns = new Set(pkResult.rows.map((r: any) => r.column_name))

    return result.rows.map((col: any) => ({
      name: col.column_name,
      type: col.data_type.toUpperCase(),
      notNull: col.is_nullable === "NO",
      defaultValue: col.column_default || undefined,
      primaryKey: pkColumns.has(col.column_name),
    }))
  }

  private async _getPgRowCount(pool: any, tableName: string): Promise<number> {
    try {
      const result = await pool.query(`SELECT COUNT(*) as count FROM ${tableName}`)
      return parseInt(result.rows[0].count) || 0
    } catch {
      return 0
    }
  }

  private async _getPgForeignKeys(pool: any, tableName: string): Promise<DBForeignKey[]> {
    const result = await pool.query(
      `
      SELECT
        kcu.column_name,
        ccu.table_name AS referenced_table,
        kcu.column_name AS referenced_column,
        rc.delete_rule AS on_delete
      FROM information_schema.table_constraints AS tc
      JOIN information_schema.key_column_usage AS kcu
        ON tc.constraint_name = kcu.constraint_name
        AND tc.table_schema = kcu.table_schema
      JOIN information_schema.constraint_column_usage AS ccu
        ON ccu.constraint_name = tc.constraint_name
        AND ccu.table_schema = tc.table_schema
      WHERE tc.constraint_type = 'FOREIGN KEY'
        AND tc.table_name = $1
    `,
      [tableName],
    )

    return result.rows.map((row: any) => ({
      table: tableName,
      column: row.column_name,
      referencedTable: row.referenced_table,
      referencedColumn: row.referenced_column,
      onDelete: this._mapPgOnDelete(row.on_delete),
    }))
  }

  private _mapPgOnDelete(rule: string): "CASCADE" | "RESTRICT" | "SET NULL" | "NO ACTION" {
    switch (rule) {
      case "CASCADE":
        return "CASCADE"
      case "RESTRICT":
        return "RESTRICT"
      case "SET NULL":
        return "SET NULL"
      default:
        return "NO ACTION"
    }
  }

  private async _getPgViews(pool: any): Promise<Array<{ name: string; sql: string }>> {
    const result = await pool.query(`
      SELECT table_name AS name, view_definition
      FROM information_schema.views
      WHERE table_schema = 'public'
      ORDER BY table_name
    `)

    return result.rows.map((row: any) => ({
      name: row.name,
      sql: row.view_definition || "",
    }))
  }

  private async _getPgIndexes(pool: any): Promise<DBIndex[]> {
    const result = await pool.query(`
      SELECT indexname, tablename, indexdef
      FROM pg_indexes
      WHERE schemaname = 'public'
      ORDER BY tablename, indexname
    `)

    return result.rows.map((row: any) => {
      const columns = this._extractPgIndexColumns(row.indexdef)
      return {
        name: row.indexname,
        tableName: row.tablename,
        columns,
        unique: row.indexdef.toUpperCase().includes("UNIQUE"),
      }
    })
  }

  private _extractPgIndexColumns(indexDef: string): string[] {
    const match = indexDef.match(/\(([^)]+)\)/)
    if (!match) return []
    return match[1].split(",").map((c) => c.trim())
  }

  async getTablePreview(tableName: string, limit: number = 10): Promise<TablePreview> {
    const pool = await this._getPool()
    const schema = await this.getSchema()
    const table = schema.tables.find((t) => t.name === tableName)

    if (!table) {
      return { tableName, columns: [], sampleData: [], rowCount: 0 }
    }

    const result = await pool.query(`SELECT * FROM ${tableName} LIMIT $1`, [limit])

    return {

      tableName,
      columns: table.columns,
      sampleData: result.rows as any[],
      rowCount: table.rowCount ?? 0,
    }
  }

  async executeQuery(sql: string): Promise<QueryResult> {
    const pool = await this._getPool()
    const startTime = Date.now()

    try {
      const isSelect = sql.trim().toUpperCase().startsWith("SELECT")

      if (isSelect) {
        const result = await pool.query(sql)
        const columns = result.fields.map((f: any) => f.name)

        return {
          columns,
          rows: result.rows as any[],
          rowCount: result.rowCount || 0,
          executionTime: Date.now() - startTime,
        }
      } else {
        const result = await pool.query(sql)
        return {
          columns: ["affected_rows"],
          rows: [{ affected_rows: result.rowCount || 0 }],
          rowCount: 1,
          executionTime: Date.now() - startTime,
        }
      }
    } catch (error) {
      throw new Error(`Query failed: ${error}`)
    }
  }

  async executeCommand(sql: string): Promise<void> {
    const pool = await this._getPool()
    await pool.query(sql)
  }

  async createTable(name: string, columns: DBColumn[], foreignKeys?: DBForeignKey[]): Promise<void> {
    const columnDefs = columns.map((col) => {
      let def = `${col.name} ${col.type}`
      if (col.notNull) def += " NOT NULL"
      if (col.defaultValue) def += ` DEFAULT ${col.defaultValue}`
      return def
    })

    const fkDefs =
      foreignKeys?.map(
        (fk) =>
          `FOREIGN KEY (${fk.column}) REFERENCES ${fk.referencedTable}(${fk.referencedColumn}) ON DELETE ${fk.onDelete}`,
      ) || []

    const pkColumns = columns.filter((c) => c.primaryKey).map((c) => c.name)
    const pkDef = pkColumns.length > 0 ? `, PRIMARY KEY (${pkColumns.join(", ")})` : ""

    const sql = `CREATE TABLE ${name} (${columnDefs.concat(fkDefs).join(", ")}${pkDef})`
    await this.executeCommand(sql)
  }

  async dropTable(name: string): Promise<void> {
    await this.executeCommand(`DROP TABLE IF EXISTS ${name}`)
  }

  async addColumn(tableName: string, column: DBColumn): Promise<void> {
    let sql = `ALTER TABLE ${tableName} ADD COLUMN ${column.name} ${column.type}`
    if (column.notNull) sql += " NOT NULL"
    if (column.defaultValue) sql += ` DEFAULT ${column.defaultValue}`
    await this.executeCommand(sql)
  }

  async dropColumn(tableName: string, columnName: string): Promise<void> {
    await this.executeCommand(`ALTER TABLE ${tableName} DROP COLUMN ${columnName}`)
  }

  async modifyColumn(tableName: string, columnName: string, newDef: DBColumn): Promise<void> {
    await this.executeCommand(`ALTER TABLE ${tableName} RENAME COLUMN ${columnName} TO ${newDef.name}`)
    if (newDef.type !== "TEXT") {
      await this.executeCommand(`ALTER TABLE ${tableName} ALTER COLUMN ${newDef.name} TYPE ${newDef.type}`)
    }
  }

  async getIndexes(): Promise<DBIndex[]> {
    return this._getPgIndexes(await this._getPool())
  }

  async createIndex(name: string, tableName: string, columns: string[], unique: boolean = false): Promise<void> {
    const uniqueStr = unique ? " UNIQUE" : ""
    const cols = columns.join(", ")
    await this.executeCommand(`CREATE${uniqueStr} INDEX IF NOT EXISTS ${name} ON ${tableName} (${cols})`)
  }

  async dropIndex(name: string): Promise<void> {
    await this.executeCommand(`DROP INDEX IF EXISTS ${name}`)
  }

  async beginTransaction(): Promise<void> {
    await this.executeCommand("BEGIN")
  }

  async commit(): Promise<void> {
    await this.executeCommand("COMMIT")
  }

  async rollback(): Promise<void> {
    await this.executeCommand("ROLLBACK")
  }

  async close(): Promise<void> {
    if (this._pool) {
      await this._pool.end()
      this._pool = null
    }
  }

  static async testConnection(config: ConnectionConfig): Promise<boolean> {
    try {
      const { default: pg } = await import("pg")
      const { Pool } = pg
      const pool = new Pool({
        host: config.host,
        port: config.port || 5432,
        database: config.database,
        user: config.username,
        password: config.password,
      })
      await pool.query("SELECT 1")
      await pool.end()
      return true
    } catch {
      return false
    }
  }
}

import type { DBSchema, DBTable, DBColumn, DBForeignKey, DBIndex, TablePreview, QueryResult } from "./types"
import type { IDBConnection, ConnectionConfig } from "./connections"

export class SQLiteConnection implements IDBConnection {
  readonly type = "sqlite"
  private _path: string
  private _db: any = null
  private _transactionMode = false

  constructor(config: ConnectionConfig) {
    this._path = config.path || ":memory:"
  }

  get connected(): boolean {
    return this._db !== null
  }

  private _getDb(): any {
    if (!this._db) {
      const bunSqlite = require("bun:sqlite")
      this._db = new bunSqlite.Database(this._path)
    }
    return this._db
  }

  async getSchema(): Promise<DBSchema> {
    const tables = this._getSqliteTables()
    const views = this._getSqliteViews()
    const indexes = this._getSqliteIndexes()
    return { tables, views, indexes }
  }

  private _getSqliteTables(): DBTable[] {
    const db = this._getDb()
    const tables: DBTable[] = []

    try {
      const sqliteMaster = db
        .prepare(
          `
        SELECT name, sql FROM sqlite_master 
        WHERE type='table' AND name NOT LIKE 'sqlite_%'
        ORDER BY name
      `,
        )
        .all()

      for (const row of sqliteMaster) {
        const tableName = row.name
        const columnsInfo = this._getTableInfo(tableName)
        const rowCount = this._getRowCount(tableName)

        tables.push({
          name: tableName,
          columns: columnsInfo,
          primaryKey: columnsInfo.filter((c: DBColumn) => c.primaryKey).map((c: DBColumn) => c.name),
          foreignKeys: this._getForeignKeys(tableName),
          rowCount,
          sql: row.sql ?? undefined,
        })
      }
    } catch {
      return []
    }

    return tables
  }

  private _getSqliteViews(): Array<{ name: string; sql: string }> {
    const db = this._getDb()
    try {
      const views = db
        .prepare(
          `
        SELECT name, sql FROM sqlite_master 
        WHERE type='view'
        ORDER BY name
      `,
        )
        .all()

      return views
        .filter((v: any): v is { name: string; sql: string } => v.sql !== null)
        .map((v: any) => ({ name: v.name, sql: v.sql }))
    } catch {
      return []
    }
  }

  private _getSqliteIndexes(): DBIndex[] {
    const db = this._getDb()
    try {
      const indexes = db
        .prepare(
          `
        SELECT name, tbl_name, sql FROM sqlite_master 
        WHERE type='index' AND name NOT LIKE 'sqlite_%autoindex_%'
      `,
        )
        .all()

      return indexes.map((idx: any) => ({
        name: idx.name,
        tableName: idx.tbl_name,
        columns: this._parseIndexColumns(idx.name),
        unique: idx.sql?.toUpperCase().includes("UNIQUE") ?? false,
      }))
    } catch {
      return []
    }
  }

  private _parseIndexColumns(indexName: string): string[] {
    const db = this._getDb()
    try {
      const info = db.prepare(`PRAGMA index_info('${indexName}')`).all()
      return info.map((c: any) => c.name)
    } catch {
      return []
    }
  }

  private _getTableInfo(tableName: string): DBColumn[] {
    const db = this._getDb()
    const info = db.prepare(`PRAGMA table_info('${tableName}')`).all()

    return info.map((col: any) => ({
      name: col.name,
      type: col.type || "TEXT",
      notNull: col.notnull > 0,
      defaultValue: col.dflt_value ?? undefined,
      primaryKey: col.pk > 0,
    }))
  }

  private _getForeignKeys(tableName: string): DBForeignKey[] {
    const db = this._getDb()
    try {
      const fkInfo = db.prepare(`PRAGMA foreign_key_list('${tableName}')`).all()

      return fkInfo.map((fk: any) => ({
        table: tableName,
        column: fk.from,
        referencedTable: fk.table,
        referencedColumn: fk.to,
        onDelete: (fk.on_delete?.toUpperCase() as "CASCADE" | "RESTRICT" | "SET NULL" | "NO ACTION") || "NO ACTION",
      }))
    } catch {
      return []
    }
  }

  private _getRowCount(tableName: string): number {
    const db = this._getDb()
    const result = db.prepare(`SELECT COUNT(*) as count FROM '${tableName}'`).get()
    return result?.count ?? 0
  }

  async getTablePreview(tableName: string, limit: number = 10): Promise<TablePreview> {
    const db = this._getDb()
    const schema = await this.getSchema()
    const table = schema.tables.find((t) => t.name === tableName)

    if (!table) {
      return { tableName, columns: [], sampleData: [], rowCount: 0 }
    }

    const data = db.prepare(`SELECT * FROM '${tableName}' LIMIT ${limit}`).all()

    return {
      tableName,
      columns: table.columns,
      sampleData: data as any[],
      rowCount: table.rowCount ?? 0,
    }
  }

  async executeQuery(sql: string): Promise<QueryResult> {
    const db = this._getDb()
    const startTime = Date.now()

    try {
      const isSelect = sql.trim().toUpperCase().startsWith("SELECT")

      if (isSelect) {
        const result = db.prepare(sql).all()
        const columns = result.length > 0 ? Object.keys(result[0]) : []

        return {
          columns,
          rows: result as any[],
          rowCount: result.length,
          executionTime: Date.now() - startTime,
        }
      } else {
        db.prepare(sql).run()
        return {
          columns: ["changes"],
          rows: [{ changes: 0 }],
          rowCount: 1,

          executionTime: Date.now() - startTime,
        }
      }
    } catch (error) {
      throw new Error(`Query failed: ${error}`)
    }
  }

  async executeCommand(sql: string): Promise<void> {
    const db = this._getDb()
    db.prepare(sql).run()
  }

  async createTable(name: string, columns: DBColumn[], foreignKeys?: DBForeignKey[]): Promise<void> {
    const columnDefs = columns.map((col) => {
      let def = `${col.name} ${col.type}`
      if (col.notNull) def += " NOT NULL"
      if (col.defaultValue) def += ` DEFAULT ${col.defaultValue}`
      if (col.primaryKey) def += " PRIMARY KEY"
      return def
    })

    const fkDefs =
      foreignKeys?.map(
        (fk) =>
          `FOREIGN KEY (${fk.column}) REFERENCES ${fk.referencedTable}(${fk.referencedColumn}) ON DELETE ${fk.onDelete}`,
      ) || []

    const sql = `CREATE TABLE ${name} (${columnDefs.concat(fkDefs).join(", ")})`
    await this.executeCommand(sql)
  }

  async dropTable(name: string): Promise<void> {
    await this.executeCommand(`DROP TABLE IF EXISTS ${name}`)
  }

  async addColumn(tableName: string, column: DBColumn): Promise<void> {
    let sql = `ALTER TABLE ${tableName} ADD COLUMN ${column.name} ${column.type}`
    if (column.notNull) sql += " NOT NULL"
    if (column.defaultValue) sql += ` DEFAULT ${column.defaultValue}`
    await this.executeCommand(sql)
  }

  async dropColumn(tableName: string, columnName: string): Promise<void> {
    await this.executeCommand(`ALTER TABLE ${tableName} DROP COLUMN ${columnName}`)
  }

  async modifyColumn(tableName: string, columnName: string, newDef: DBColumn): Promise<void> {
    await this.executeCommand(`ALTER TABLE ${tableName} RENAME COLUMN ${columnName} TO ${newDef.name}`)
    if (newDef.type !== "TEXT") {
      const db = this._getDb()
      db.prepare(`ALTER TABLE ${tableName} ALTER COLUMN ${newDef.name} TYPE ${newDef.type}`).run()
    }
  }

  async getIndexes(): Promise<DBIndex[]> {
    return this._getSqliteIndexes()
  }

  async createIndex(name: string, tableName: string, columns: string[], unique: boolean = false): Promise<void> {
    const uniqueStr = unique ? " UNIQUE" : ""
    const cols = columns.join(", ")
    await this.executeCommand(`CREATE${uniqueStr} INDEX IF NOT EXISTS ${name} ON ${tableName} (${cols})`)
  }

  async dropIndex(name: string): Promise<void> {
    await this.executeCommand(`DROP INDEX IF EXISTS ${name}`)
  }

  async beginTransaction(): Promise<void> {
    this._transactionMode = true
    await this.executeCommand("BEGIN TRANSACTION")
  }

  async commit(): Promise<void> {
    await this.executeCommand("COMMIT")
    this._transactionMode = false
  }

  async rollback(): Promise<void> {
    await this.executeCommand("ROLLBACK")
    this._transactionMode = false
  }

  close(): void {
    if (this._db) {
      this._db.close()
      this._db = null
    }
  }

  static testConnection(path: string): boolean {
    try {
      const bunSqlite = require("bun:sqlite")
      const db = new bunSqlite.Database(path)
      db.close()
      return true
    } catch {
      return false
    }
  }
}

import type { DBSchema, DBTable, DBColumn, DBForeignKey, DBIndex, TablePreview, QueryResult } from "./types"

export interface IDBConnection {
  readonly type: string
  readonly connected: boolean
  getSchema(): Promise<DBSchema>
  getTablePreview(tableName: string, limit?: number): Promise<TablePreview>
  executeQuery(sql: string): Promise<QueryResult>
  executeCommand(sql: string): Promise<void>
  createTable(name: string, columns: DBColumn[], foreignKeys?: DBForeignKey[]): Promise<void>
  dropTable(name: string): Promise<void>
  addColumn(tableName: string, column: DBColumn): Promise<void>
  dropColumn(tableName: string, columnName: string): Promise<void>
  modifyColumn(tableName: string, columnName: string, newDef: DBColumn): Promise<void>
  getIndexes(): Promise<DBIndex[]>
  createIndex(name: string, tableName: string, columns: string[], unique?: boolean): Promise<void>
  dropIndex(name: string): Promise<void>
  beginTransaction(): Promise<void>
  commit(): Promise<void>
  rollback(): Promise<void>
  close(): void
}

export type ConnectionFactory = (config: ConnectionConfig) => Promise<IDBConnection>

export interface ConnectionConfig {
  type: string
  path?: string
  host?: string
  port?: number
  database?: string
  username?: string
  password?: string
}

export function parseConnectionString(connStr: string): ConnectionConfig {
  if (
    connStr.startsWith("sqlite://") ||
    (!connStr.includes("://") &&
      (connStr.endsWith(".db") || connStr.endsWith(".sqlite") || connStr.endsWith(".sqlite3")))
  ) {
    const path = connStr.startsWith("sqlite://") ? connStr.replace("sqlite://", "") : connStr.replace("file:", "")
    return { type: "sqlite", path }
  }

  if (connStr.startsWith("postgres://") || connStr.startsWith("postgresql://")) {
    const url = new URL(connStr)
    return {
      type: "postgres",
      host: url.hostname,
      port: parseInt(url.port || "5432"),
      database: url.pathname.slice(1) || undefined,
      username: url.username,
      password: url.password,
    }
  }

  if (connStr.startsWith("mysql://")) {
    const url = new URL(connStr)
    return {
      type: "mysql",
      host: url.hostname,
      port: parseInt(url.port || "3306"),
      database: url.pathname.slice(1) || undefined,
      username: url.username,
      password: url.password,
    }
  }

  if (connStr.startsWith("duckdb://")) {
    return { type: "duckdb", path: connStr.replace("duckdb://", "") }
  }

  return { type: "sqlite", path: connStr }
}

import type { DBSchema, DBTable, DBColumn, DBForeignKey, DBIndex, TablePreview, QueryResult } from "./types"
import type { IDBConnection, ConnectionConfig } from "./connections"

export class MySQLConnection implements IDBConnection {
  readonly type = "mysql"
  private _config: ConnectionConfig
  private _connection: any = null

  constructor(config: ConnectionConfig) {
    this._config = config
  }

  get connected(): boolean {
    return this._connection !== null
  }

  private async _getConnection(): Promise<any> {
    if (!this._connection) {
      const mysql = await import("mysql2/promise")
      this._connection = await mysql.default.createConnection({
        host: this._config.host,
        port: this._config.port || 3306,
        database: this._config.database,
        user: this._config.username,
        password: this._config.password,
      })
    }
    return this._connection
  }

  async getSchema(): Promise<DBSchema> {
    const conn = await this._getConnection()
    const tables = await this._getMySQLTables(conn)
    const views = await this._getMySQLViews(conn)
    const indexes = await this._getMySQLIndexes(conn)
    return { tables, views, indexes }
  }

  private async _getMySQLTables(conn: any): Promise<DBTable[]> {
    const [rows] = await conn.query(`
      SELECT table_name
      FROM information_schema.tables
      WHERE table_schema = DATABASE() AND table_type = 'BASE TABLE'
      ORDER BY table_name
    `)

    const tables: DBTable[] = []
    for (const row of rows as any[]) {
      const tableName = row.TABLE_NAME
      const columns = await this._getMySQLTableInfo(conn, tableName)
      const rowCount = await this._getMySQLRowCount(conn, tableName)
      const foreignKeys = await this._getMySQLForeignKeys(conn, tableName)

      tables.push({
        name: tableName,
        columns,
        primaryKey: columns.filter((c) => c.primaryKey).map((c) => c.name),
        foreignKeys,
        rowCount,
      })
    }
    return tables
  }

  private async _getMySQLTableInfo(conn: any, tableName: string): Promise<DBColumn[]> {
    const [rows] = await conn.query(
      `
      SELECT column_name, data_type, is_nullable, column_default, extra
      FROM information_schema.columns
      WHERE table_schema = DATABASE() AND table_name = ?
      ORDER BY ordinal_position
    `,
      [tableName],
    )

    const pkResult = await conn.query(
      `
      SELECT column_name
      FROM information_schema.key_column_usage
      WHERE table_schema = DATABASE() AND table_name = ? AND constraint_name = 'PRIMARY'
    `,
      [tableName],
    )

    const pkColumns = new Set((pkResult[0] as any[]).map((r: any) => r.column_name))

    return (rows as any[]).map((col: any) => ({
      name: col.COLUMN_NAME,
      type: col.DATA_TYPE.toUpperCase(),
      notNull: col.IS_NULLABLE === "NO",
      defaultValue: col.COLUMN_DEFAULT || undefined,
      primaryKey: pkColumns.has(col.COLUMN_NAME),
    }))
  }

  private async _getMySQLRowCount(conn: any, tableName: string): Promise<number> {
    try {
      const [rows] = await conn.query(`SELECT COUNT(*) as count FROM ${tableName}`)
      return (rows as any[])[0]?.count || 0
    } catch {
      return 0
    }
  }

  private async _getMySQLForeignKeys(conn: any, tableName: string): Promise<DBForeignKey[]> {
    const [rows] = await conn.query(
      `
      SELECT
        column_name,
        referenced_table_name,
        referenced_column_name,
        delete_rule
      FROM information_schema.key_column_usage
      WHERE table_schema = DATABASE()
        AND table_name = ?
        AND referenced_table_name IS NOT NULL
    `,
      [tableName],
    )

    return (rows as any[]).map((row: any) => ({
      table: tableName,
      column: row.COLUMN_NAME,
      referencedTable: row.REFERENCED_TABLE_NAME,
      referencedColumn: row.REFERENCED_COLUMN_NAME,
      onDelete: this._mapMySQLOnDelete(row.DELETE_RULE),
    }))
  }

  private _mapMySQLOnDelete(rule: string): "CASCADE" | "RESTRICT" | "SET NULL" | "NO ACTION" {
    switch (rule) {
      case "CASCADE":
        return "CASCADE"
      case "RESTRICT":
        return "RESTRICT"
      case "SET NULL":
        return "SET NULL"
      default:
        return "NO ACTION"
    }
  }

  private async _getMySQLViews(conn: any): Promise<Array<{ name: string; sql: string }>> {
    const [rows] = await conn.query(`
      SELECT table_name AS name, view_definition
      FROM information_schema.views
      WHERE table_schema = DATABASE()
      ORDER BY table_name
    `)

    return (rows as any[]).map((row: any) => ({
      name: row.name,
      sql: row.view_definition || "",
    }))
  }

  private async _getMySQLIndexes(conn: any): Promise<DBIndex[]> {
    const [rows] = await conn.query(`
      SELECT index_name, table_name, non_unique, index_columns
      FROM information_schema.statistics
      WHERE table_schema = DATABASE()
      ORDER BY table_name, index_name
    `)

    const indexMap = new Map<string, DBIndex>()
    for (const row of rows as any[]) {
      const key = `${row.TABLE_NAME}_${row.INDEX_NAME}`
      if (!indexMap.has(key)) {
        indexMap.set(key, {
          name: row.INDEX_NAME,
          tableName: row.TABLE_NAME,
          columns: [],
          unique: row.NON_UNIQUE === 0,
        })
      }
      indexMap.get(key)!.columns.push(row.COLUMN_NAME)
    }

    return Array.from(indexMap.values())
  }

  async getTablePreview(tableName: string, limit: number = 10): Promise<TablePreview> {
    const conn = await this._getConnection()
    const schema = await this.getSchema()
    const table = schema.tables.find((t) => t.name === tableName)

    if (!table) {
      return { tableName, columns: [], sampleData: [], rowCount: 0 }
    }

    const [rows] = await conn.query(`SELECT * FROM ${tableName} LIMIT ?`, [limit])

    return {
      tableName,
      columns: table.columns,
      sampleData: rows as any[],
      rowCount: table.rowCount ?? 0,
    }
  }

  async executeQuery(sql: string): Promise<QueryResult> {
    const conn = await this._getConnection()
    const startTime = Date.now()

    try {
      const isSelect = sql.trim().toUpperCase().startsWith("SELECT")

      if (isSelect) {
        const [rows, fields] = await conn.query(sql)
        const columns = fields ? fields.map((f: any) => f.name) : []

        return {
          columns,
          rows: rows as any[],
          rowCount: Array.isArray(rows) ? rows.length : 0,
          executionTime: Date.now() - startTime,
        }
      } else {
        const [result] = await conn.query(sql)
        return {
          columns: ["affected_rows"],
          rows: [{ affected_rows: (result as any).affectedRows || 0 }],
          rowCount: 1,
          executionTime: Date.now() - startTime,
        }
      }
    } catch (error) {
      throw new Error(`Query failed: ${error}`)
    }
  }

  async executeCommand(sql: string): Promise<void> {
    const conn = await this._getConnection()
    await conn.query(sql)
  }

  async createTable(name: string, columns: DBColumn[], foreignKeys?: DBForeignKey[]): Promise<void> {
    const columnDefs = columns.map((col) => {
      let def = `${col.name} ${col.type}`
      if (col.notNull) def += " NOT NULL"
      if (col.defaultValue) def += ` DEFAULT ${col.defaultValue}`
      return def
    })

    const fkDefs =
      foreignKeys?.map(
        (fk) =>
          `FOREIGN KEY (${fk.column}) REFERENCES ${fk.referencedTable}(${fk.referencedColumn}) ON DELETE ${fk.onDelete}`,
      ) || []

    const pkColumns = columns.filter((c) => c.primaryKey).map((c) => c.name)
    const pkDef = pkColumns.length > 0 ? `, PRIMARY KEY (${pkColumns.join(", ")})` : ""

    const sql = `CREATE TABLE ${name} (${columnDefs.concat(fkDefs).join(", ")}${pkDef})`
    await this.executeCommand(sql)
  }

  async dropTable(name: string): Promise<void> {
    await this.executeCommand(`DROP TABLE IF EXISTS ${name}`)
  }

  async addColumn(tableName: string, column: DBColumn): Promise<void> {
    let sql = `ALTER TABLE ${tableName} ADD COLUMN ${column.name} ${column.type}`
    if (column.notNull) sql += " NOT NULL"
    if (column.defaultValue) sql += ` DEFAULT ${column.defaultValue}`
    await this.executeCommand(sql)
  }

  async dropColumn(tableName: string, columnName: string): Promise<void> {
    await this.executeCommand(`ALTER TABLE ${tableName} DROP COLUMN ${columnName}`)
  }

  async modifyColumn(tableName: string, columnName: string, newDef: DBColumn): Promise<void> {
    await this.executeCommand(`ALTER TABLE ${tableName} CHANGE ${columnName} ${newDef.name} ${newDef.type}`)
  }

  async getIndexes(): Promise<DBIndex[]> {
    return this._getMySQLIndexes(await this._getConnection())
  }

  async createIndex(name: string, tableName: string, columns: string[], unique: boolean = false): Promise<void> {
    const uniqueStr = unique ? " UNIQUE" : ""
    const cols = columns.join(", ")
    await this.executeCommand(`CREATE${uniqueStr} INDEX ${name} ON ${tableName} (${cols})`)
  }

  async dropIndex(name: string): Promise<void> {
    await this.executeCommand(`DROP INDEX IF EXISTS ${name}`)
  }

  async beginTransaction(): Promise<void> {
    const conn = await this._getConnection()
    await conn.beginTransaction()
  }

  async commit(): Promise<void> {
    const conn = await this._getConnection()
    await conn.commit()
  }

  async rollback(): Promise<void> {
    const conn = await this._getConnection()
    await conn.rollback()
  }

  async close(): Promise<void> {
    if (this._connection) {
      await this._connection.end()
      this._connection = null
    }
  }

  static async testConnection(config: ConnectionConfig): Promise<boolean> {
    try {
      const mysql = await import("mysql2/promise")
      const conn = await mysql.default.createConnection({
        host: config.host,
        port: config.port || 3306,
        database: config.database,
        user: config.username,
        password: config.password,
      })
      await conn.query("SELECT 1")
      await conn.end()
      return true
    } catch {
      return false
    }
  }
}

import type { IDBConnection, ConnectionConfig } from "./connections"
import { parseConnectionString } from "./connections"
import { SQLiteConnection } from "./sqlite-connection"
import { PostgresConnection } from "./postgres-connection"
import { MySQLConnection } from "./mysql-connection"

export class ConnectionFactory {
  private static _instances = new Map<string, IDBConnection>()

  static async create(config: string | ConnectionConfig): Promise<IDBConnection> {
    const resolvedConfig = typeof config === "string" ? parseConnectionString(config) : config

    const key = this._getConnectionKey(resolvedConfig)
    if (this._instances.has(key)) {
      const existing = this._instances.get(key)!
      if (existing.connected) {
        return existing
      }
    }

    let connection: IDBConnection

    switch (resolvedConfig.type) {
      case "postgres":
        connection = new PostgresConnection(resolvedConfig)
        break
      case "mysql":
        connection = new MySQLConnection(resolvedConfig)
        break
      case "sqlite":
      default:
        connection = new SQLiteConnection(resolvedConfig)
        break
    }

    this._instances.set(key, connection)
    return connection
  }

  private static _getConnectionKey(config: ConnectionConfig): string {
    if (config.path) return `sqlite:${config.path}`
    return `${config.type}://${config.host}:${config.port}/${config.database}`
  }

  static async get(key: string): Promise<IDBConnection | undefined> {
    return this._instances.get(key)
  }

  static async close(key: string): Promise<void> {
    const conn = this._instances.get(key)
    if (conn) {
      conn.close()
      this._instances.delete(key)
    }
  }

  static async closeAll(): Promise<void> {
    for (const conn of this._instances.values()) {
      conn.close()
    }
    this._instances.clear()
  }
}

export function createConnection(connStr: string): Promise<IDBConnection> {
  return ConnectionFactory.create(connStr)
}

export { parseConnectionString }

export function getConnection(key: string): Promise<IDBConnection | undefined> {
  return ConnectionFactory.get(key)
}

export function closeConnection(key: string): Promise<void> {
  return ConnectionFactory.close(key)
}

import type { DBSchema, DBTable, DBColumn, TablePreview, QueryResult } from "./types"
import { detectDBType } from "./types"

export class DBConnection {
  private _path: string
  private _dbType: ReturnType<typeof detectDBType>
  private _db: any = null

  constructor(path: string) {
    this._path = path
    this._dbType = detectDBType(path)
  }

  get type() { return this._dbType }
  get path() { return this._path }

  private _getDb(): any {
    if (!this._db) {
      const bunSqlite = require("bun:sqlite")
      this._db = new bunSqlite.Database(this._path)
    }
    return this._db
  }

  getSchema(): DBSchema {
    return this._getSqliteSchema()
  }

  private _getSqliteSchema(): DBSchema {
    const tables = this._getSqliteTables()
    const views = this._getSqliteViews()
    const indexes = this._getSqliteIndexes()
    return { tables, views, indexes }
  }

  private _getSqliteTables(): DBTable[] {
    const db = this._getDb()
    const tables: DBTable[] = []

    try {
      const sqliteMaster = db.prepare(`
        SELECT name, sql FROM sqlite_master 
        WHERE type='table' AND name NOT LIKE 'sqlite_%'
        ORDER BY name
      `).all()

      for (const row of sqliteMaster) {
        const tableName = row.name
        const columnsInfo = this._getTableInfo(tableName)
        const rowCount = this._getRowCount(tableName)

        tables.push({
          name: tableName,
          columns: columnsInfo,
          primaryKey: columnsInfo.filter((c: DBColumn) => c.primaryKey).map((c: DBColumn) => c.name),
          foreignKeys: this._getForeignKeys(tableName),
          rowCount,
          sql: row.sql ?? undefined,
        })
      }
    } catch {
      return []
    }

    return tables
  }

  private _getSqliteViews(): Array<{ name: string; sql: string }> {
    const db = this._getDb()
    try {
      const views = db.prepare(`
        SELECT name, sql FROM sqlite_master 
        WHERE type='view'
        ORDER BY name
      `).all()

      return views
        .filter((v: any): v is { name: string; sql: string } => v.sql !== null)
        .map((v: any) => ({ name: v.name, sql: v.sql }))
    } catch {
      return []
    }
  }

  private _getSqliteIndexes(): Array<{ name: string; tableName: string; columns: string[]; unique: boolean }> {
    const db = this._getDb()
    try {
      const indexes = db.prepare(`
        SELECT name, tbl_name, sql FROM sqlite_master 
        WHERE type='index' AND name NOT LIKE 'sqlite_%autoindex_%'
      `).all()

      return indexes.map((idx: any) => ({
        name: idx.name,
        tableName: idx.tbl_name,
        columns: this._parseIndexColumns(idx.name),
        unique: idx.sql?.toUpperCase().includes("UNIQUE") ?? false,
      }))
    } catch {
      return []
    }
  }

  private _parseIndexColumns(indexName: string): string[] {
    const db = this._getDb()
    try {
      const info = db.prepare(`PRAGMA index_info('${indexName}')`).all()
      return info.map((c: any) => c.name)
    } catch {
      return []
    }
  }

  private _getTableInfo(tableName: string): DBColumn[] {
    const db = this._getDb()
    const info = db.prepare(`PRAGMA table_info('${tableName}')`).all()

    return info.map((col: any) => ({
      name: col.name,
      type: col.type || "TEXT",
      notNull: col.notnull > 0,
      defaultValue: col.dflt_value ?? undefined,
      primaryKey: col.pk > 0,
    }))
  }

  private _getForeignKeys(tableName: string): Array<{
    table: string
    column: string
    referencedTable: string
    referencedColumn: string
    onDelete: "CASCADE" | "RESTRICT" | "SET NULL" | "NO ACTION"
  }> {
    const db = this._getDb()
    try {
      const fkInfo = db.prepare(`PRAGMA foreign_key_list('${tableName}')`).all()

      return fkInfo.map((fk: any) => ({
        table: tableName,
        column: fk.from,
        referencedTable: fk.table,
        referencedColumn: fk.to,
        onDelete: (fk.on_delete?.toUpperCase() as "CASCADE" | "RESTRICT" | "SET NULL" | "NO ACTION") || "NO ACTION",
      }))
    } catch {
      return []
    }
  }

  private _getRowCount(tableName: string): number {
    const db = this._getDb()
    const result = db.prepare(`SELECT COUNT(*) as count FROM '${tableName}'`).get()
    return result?.count ?? 0
  }

  getTablePreview(tableName: string, limit: number = 10): TablePreview {
    const db = this._getDb()
    const schema = this.getSchema()
    const table = schema.tables.find((t) => t.name === tableName)

    if (!table) {
      return { tableName, columns: [], sampleData: [], rowCount: 0 }
    }

    const data = db.prepare(`SELECT * FROM '${tableName}' LIMIT ${limit}`).all()

    return {
      tableName,
      columns: table.columns,
      sampleData: data as any[],
      rowCount: table.rowCount ?? 0,
    }
  }

  executeQuery(sql: string): QueryResult {
    const db = this._getDb()
    const startTime = Date.now()

    try {
      const isSelect = sql.trim().toUpperCase().startsWith("SELECT")

      if (isSelect) {
        const result = db.prepare(sql).all()
        const columns = result.length > 0 ? Object.keys(result[0]) : []

        return {
          columns,
          rows: result as any[],
          rowCount: result.length,
          executionTime: Date.now() - startTime,
        }
      } else {
        db.prepare(sql).run()
        return {
          columns: ["changes"],
          rows: [{ changes: 0 }],
          rowCount: 1,
          executionTime: Date.now() - startTime,
        }
      }

    } catch (error) {
      throw new Error(`Query failed: ${error}`)
    }
  }

  close(): void {
    if (this._db) {
      this._db.close()
      this._db = null
    }
  }

  static testConnection(path: string): boolean {
    try {
      const bunSqlite = require("bun:sqlite")
      const db = new bunSqlite.Database(path)
      db.close()
      return true
    } catch {
      return false
    }
  }
}

import { DBConnection } from "./db-connection"
import type { DBSchema, TablePreview, TableChange, DBColumn } from "./types"

export class DBPreviewGenerator {
  private _connection: DBConnection | null = null

  constructor(connection: DBConnection) {
    this._connection = connection
  }

  generateSchemaPreview(): TablePreview[] {
    if (!this._connection) {
      return []
    }

    try {
      const schema = this._connection.getSchema()
      return schema.tables.map((table) => ({
        tableName: table.name,
        columns: table.columns,
        sampleData: [],
        rowCount: table.rowCount || 0,
      }))
    } catch {
      return []
    }
  }

  generateTablePreviews(limit: number = 10): TablePreview[] {
    if (!this._connection) {
      return []
    }

    try {
      const schema = this._connection.getSchema()
      return schema.tables.map((table) => {
        const preview = this._connection!.getTablePreview(table.name, limit)
        return preview
      })
    } catch {
      return []
    }
  }

  generateSchemaDiff(oldSchema: DBSchema, newSchema: DBSchema): TableChange[] {
    const changes: TableChange[] = []

    for (const newTable of newSchema.tables) {
      const oldTable = oldSchema.tables.find((t) => t.name === newTable.name)
      if (!oldTable) {
        changes.push({
          type: "add_table",
          tableName: newTable.name,
          newDefinition: {
            name: newTable.name,
            type: "TABLE" as const,
            notNull: false,
            primaryKey: false,
          },
        })
      }
    }

    for (const oldTable of oldSchema.tables) {
      const newTable = newSchema.tables.find((t) => t.name === oldTable.name)
      if (!newTable) {
        changes.push({
          type: "drop_table",
          tableName: oldTable.name,
          oldDefinition: {
            name: oldTable.name,
            type: "TABLE" as const,
            notNull: false,
            primaryKey: false,
          },
        })
      }
    }

    for (const newTable of newSchema.tables) {
      const oldTable = oldSchema.tables.find((t) => t.name === newTable.name)
      if (oldTable) {
        for (const newCol of newTable.columns) {
          const oldCol = oldTable.columns.find((c) => c.name === newCol.name)
          if (!oldCol) {
            changes.push({
              type: "add_column",
              tableName: newTable.name,
              columnName: newCol.name,
              newDefinition: newCol,
            })
          }
        }

        for (const oldCol of oldTable.columns) {
          const newCol = newTable.columns.find((c) => c.name === oldCol.name)
          if (!newCol) {
            changes.push({
              type: "drop_column",
              tableName: newTable.name,
              columnName: oldCol.name,
              oldDefinition: oldCol,
            })
          }
        }
      }
    }

    return changes
  }

  generateSQLPreview(changes: TableChange[]): string {
    const statements: string[] = []

    for (const change of changes) {
      switch (change.type) {
        case "add_table":
          if ((change.newDefinition as unknown as { sql?: string })?.sql) {
            statements.push((change.newDefinition as unknown as { sql: string }).sql)
          } else {
            const columns =
              (
                change.newDefinition as unknown as { columns?: Array<{ name: string; type: string; notNull: boolean }> }
              )?.columns
                ?.map((c) => `${c.name} ${c.type}${c.notNull ? " NOT NULL" : ""}`)
                .join(", ") ?? ""
            statements.push(`CREATE TABLE ${change.tableName} (${columns});`)
          }
          break

        case "drop_table":
          statements.push(`DROP TABLE IF EXISTS ${change.tableName};`)
          break

        case "add_column":
          if (change.newDefinition) {
            const { name, type, notNull, defaultValue } = change.newDefinition
            const parts = [`${name} ${type}`]
            if (notNull) parts.push("NOT NULL")
            if (defaultValue !== undefined) parts.push(`DEFAULT ${defaultValue}`)
            statements.push(`ALTER TABLE ${change.tableName} ADD COLUMN ${parts.join(" ")};`)
          }
          break

        case "drop_column":
          statements.push(`-- Cannot drop column directly in SQLite`)
          statements.push(`-- Table ${change.tableName} column ${change.columnName} would be dropped`)
          break

        case "modify_column":
          statements.push(`-- Column modification requires table recreation`)
          statements.push(`-- ${change.tableName}.${change.columnName}`)
          break
      }
    }

    return statements.join("\n")
  }

  previewFromSQL(sql: string): TablePreview | null {
    if (!this._connection) {
      return null
    }

    try {
      const result = this._connection.executeQuery(sql)

      if (result.columns.length === 0) {
        return null
      }

      const columns: Array<{ name: string; type: string; notNull: boolean; primaryKey: boolean }> = result.columns.map(
        (name) => ({
          name,
          type: "TEXT",
          notNull: false,
          primaryKey: false,
        }),
      )

      return {
        tableName: "Query Result",
        columns,
        sampleData: result.rows.slice(0, 10),
        rowCount: result.rowCount,
      }
    } catch {
      return null
    }
  }

  async previewFromFile(filePath: string): Promise<TablePreview[]> {
    const connection = new DBConnection(filePath)

    try {
      const schema = connection.getSchema()
      return schema.tables.map((table) => connection.getTablePreview(table.name, 10))
    } catch {
      return []
    }

import { createSignal, createMemo, onMount, onCleanup } from "solid-js"
import { createStore, reconcile } from "solid-js/store"
import type { TableColumn, TableRow, TableStyle, TableActions, TableState } from "./types"
import { TableStateManager } from "./table-state"

export interface UseTableOptions {
  columns: TableColumn[]
  rows: TableRow[]
  rowKey?: string
  selection?: "none" | "single" | "multiple"
  showHeader?: boolean
  showRowNumbers?: boolean
  striped?: boolean
  compact?: boolean
  style?: TableStyle
  pageSize?: number
}

export function useTable(options: UseTableOptions) {
  const [state, setState] = createStore<TableState>({
    data: options.rows,
    filteredData: options.rows,
    selectedRow: null,
    sortColumn: null,
    sortDirection: "asc",
    filterQuery: "",
    page: 1,
    pageSize: options.pageSize ?? 50,
  })

  const stateManager = new TableStateManager()
  stateManager.setData(options.rows)
  if (options.pageSize) {
    stateManager.setPageSize(options.pageSize)
  }

  const columns = createMemo(() => options.columns)
  const rows = createMemo(() => stateManager.getVisibleRows())

  const actions: TableActions = {
    setData: (cols: TableColumn[], newRows: TableRow[]) => {
      stateManager.setData(newRows)
      setState({ data: newRows, filteredData: newRows, page: 1 })
    },
    selectRow: (index: number | null) => {
      setState({ selectedRow: index })
    },
    sortBy: (columnId: string) => {
      stateManager.setSort(columnId)
      setState({
        sortColumn: stateManager.sortColumn,
        sortDirection: stateManager.sortDirection,
      })
    },
    filter: (query: string) => {
      stateManager.setFilter(query)
      setState({ filterQuery: query })
    },
    setPage: (page: number) => {
      stateManager.setPage(page)
      setState({ page })
    },
    nextPage: () => {
      if (stateManager.nextPage()) {
        setState({ page: stateManager.page })
      }
    },
    prevPage: () => {
      if (stateManager.prevPage()) {
        setState({ page: stateManager.page })
      }
    },
  }

  const selection = createMemo(() => ({
    selected: state.selectedRow,
    total: rows().length,
    hasSelection: state.selectedRow !== null,
  }))

  const pagination = createMemo(() => ({
    page: stateManager.page,
    pageSize: stateManager.pageSize,
    totalPages: stateManager.getTotalPages(),
    totalRows: stateManager.getTotalRows(),
    hasNext: stateManager.nextPage() !== false,
    hasPrev: stateManager.page > 1,
  }))

  const sort = createMemo(() => ({
    column: stateManager.sortColumn,
    direction: stateManager.sortDirection,
  }))

  return {
    columns,
    rows,
    state,
    actions,
    selection,
    pagination,
    sort,
    stateManager,
  }
}

import type { TableColumn, TableRow } from "./types"

export interface TableEventData {
  row: TableRow
  index: number
}

export interface TableSortEventData {
  column: TableColumn
  direction: "asc" | "desc"
}

export interface TableCellEditEventData {
  row: TableRow
  column: TableColumn
  oldValue: any
  newValue: any
}

export interface TableScrollEventData {
  scrollTop: number
  scrollLeft: number
  visibleStart: number
  visibleEnd: number
}

export const TableEvents = {
  ROW_SELECTED: "table.row.selected" as const,
  ROW_ACTIVATED: "table.row.activated" as const,
  COLUMN_SORTED: "table.column.sorted" as const,
  CELL_EDITED: "table.cell.edited" as const,
  SCROLLED: "table.scrolled" as const,
  FILTER_CHANGED: "table.filter.changed" as const,
  PAGINATION_CHANGED: "table.pagination.changed" as const,
}

export type TableEventType =
  | typeof TableEvents.ROW_SELECTED
  | typeof TableEvents.ROW_ACTIVATED
  | typeof TableEvents.COLUMN_SORTED
  | typeof TableEvents.CELL_EDITED
  | typeof TableEvents.SCROLLED
  | typeof TableEvents.FILTER_CHANGED
  | typeof TableEvents.PAGINATION_CHANGED

export interface TableEventMap {
  [TableEvents.ROW_SELECTED]: TableEventData
  [TableEvents.ROW_ACTIVATED]: TableEventData
  [TableEvents.COLUMN_SORTED]: TableSortEventData
  [TableEvents.CELL_EDITED]: TableCellEditEventData
  [TableEvents.SCROLLED]: TableScrollEventData
  [TableEvents.FILTER_CHANGED]: { query: string; filteredCount: number; totalCount: number }
  [TableEvents.PAGINATION_CHANGED]: { page: number; pageSize: number; totalPages: number }
}

import type { TableRow } from "./types"

export class TableSelectionManager {
  private _table: any
  private _selectionMode: "none" | "single" | "multiple"
  private _selectedIndices: Set<number> = new Set()
  private _focusedIndex: number = 0
  private _onSelectionChange?: (indices: number[]) => void

  constructor(table: any, mode: "none" | "single" | "multiple", onSelectionChange?: (indices: number[]) => void) {
    this._table = table
    this._selectionMode = mode
    this._onSelectionChange = onSelectionChange
  }

  get selectionMode(): "none" | "single" | "multiple" {
    return this._selectionMode
  }

  get selectedIndices(): number[] {
    return Array.from(this._selectedIndices).sort((a, b) => a - b)
  }

  get selectedCount(): number {
    return this._selectedIndices.size
  }

  get hasSelection(): boolean {
    return this._selectedIndices.size > 0
  }

  get focusedIndex(): number {
    return this._focusedIndex
  }

  setFocusedIndex(index: number) {
    this._focusedIndex = index
    this._table.requestRender()
  }

  setSelectedIndex(index: number | null) {
    this._selectedIndices.clear()
    if (index !== null) {
      this._selectedIndices.add(index)
      this._focusedIndex = index
    }
    this._onSelectionChange?.(this.selectedIndices)
    this._table.requestRender()
  }

  addSelection(index: number) {
    if (this._selectionMode === "multiple") {
      if (this._selectedIndices.has(index)) {
        this._selectedIndices.delete(index)
      } else {
        this._selectedIndices.add(index)
      }
      this._onSelectionChange?.(this.selectedIndices)
      this._table.requestRender()
    }
  }

  selectRange(endIndex: number) {
    if (this._selectionMode !== "multiple") return

    const start = Math.min(this._focusedIndex, endIndex)
    const end = Math.max(this._focusedIndex, endIndex)

    for (let i = start; i <= end; i++) {
      this._selectedIndices.add(i)
    }
    this._onSelectionChange?.(this.selectedIndices)
    this._table.requestRender()
  }

  clearSelection() {
    this._selectedIndices.clear()
    this._onSelectionChange?.([])
    this._table.requestRender()
  }

  selectAll() {
    if (this._selectionMode !== "multiple") return

    const rowCount = this._table.getVisibleRowCount()
    for (let i = 0; i < rowCount; i++) {
      this._selectedIndices.add(i)
    }
    this._onSelectionChange?.(this.selectedIndices)
    this._table.requestRender()
  }

  moveUp(count: number = 1) {
    this._focusedIndex = Math.max(0, this._focusedIndex - count)
    this._table.requestRender()
  }

  moveDown(count: number = 1) {
    const max = this._table.getVisibleRowCount() - 1
    this._focusedIndex = Math.min(max, this._focusedIndex + count)
    this._table.requestRender()
  }

  moveLeft(count: number = 1) {
    const columnCount = this._table.getColumnCount()
    this._focusedIndex = Math.max(0, this._focusedIndex - count)
    return columnCount
  }

  moveRight(count: number = 1) {
    const columnCount = this._table.getColumnCount()
    this._focusedIndex = Math.min(this._focusedIndex + count, columnCount - 1)
    return columnCount
  }

  getSelectedRow(): TableRow | null {
    if (this._selectedIndices.size === 0) return null
    return this._table.getRowAt(Array.from(this._selectedIndices)[0])
  }

  getSelectedRows(): TableRow[] {
    return this.selectedIndices.map((i) => this._table.getRowAt(i)).filter(Boolean)
  }

  isSelected(index: number): boolean {
    return this._selectedIndices.has(index)
  }

  isFocused(index: number): boolean {
    return this._focusedIndex === index
  }

  isSelectedOrFocused(index: number): boolean {
    return this.isSelected(index) || this.isFocused(index)
  }
}

import type { TableColumn } from "./types"

export interface ColumnLayout {
  index: number
  id: string
  x: number
  width: number
  visibleWidth: number
}

export interface RowLayout {
  index: number
  y: number
  height: number
}

export class TableLayoutEngine {
  private _columns: TableColumn[]
  private _columnLayouts: ColumnLayout[] = []
  private _totalWidth: number = 0
  private _contentWidth: number = 0
  private _rowHeight: number = 1
  private _headerHeight: number = 1

  constructor(columns: TableColumn[], rowHeight: number = 1, headerHeight: number = 1) {
    this._columns = columns
    this._rowHeight = rowHeight
    this._headerHeight = headerHeight
  }

  get columns(): TableColumn[] {
    return this._columns
  }

  get columnLayouts(): ColumnLayout[] {
    return this._columnLayouts
  }

  get totalWidth(): number {
    return this._totalWidth
  }

  get contentWidth(): number {
    return this._contentWidth
  }

  get rowHeight(): number {
    return this._rowHeight
  }

  get headerHeight(): number {
    return this._headerHeight
  }

  calculateColumnWidths(availableWidth: number): void {
    this._columnLayouts = []
    this._totalWidth = 0
    this._contentWidth = 0

    let fixedWidth = 0
    let percentColumns: { column: TableColumn; weight: number }[] = []

    for (const column of this._columns) {
      if (typeof column.width === "number") {
        const width = Math.max(column.minWidth || 3, column.width)
        fixedWidth += width
      } else if (typeof column.width === "string" && column.width.endsWith("%")) {
        const weight = parseFloat(column.width) / 100
        percentColumns.push({ column, weight })
      }
    }

    const remainingWidth = Math.max(0, availableWidth - fixedWidth)

    let usedPercent = 0
    for (const { column, weight } of percentColumns) {
      const maxWidth = column.maxWidth || Infinity
      const targetWidth = Math.floor(remainingWidth * weight)
      const actualWidth = Math.min(targetWidth, maxWidth)
      usedPercent += weight
    }

    if (percentColumns.length > 0 && remainingWidth > 0) {
      const availableForPercent = remainingWidth
      let currentX = 0

      for (let i = 0; i < this._columns.length; i++) {
        const column = this._columns[i]
        let width: number

        if (typeof column.width === "number") {
          width = Math.max(column.minWidth || 3, column.width)
        } else if (typeof column.width === "string" && column.width.endsWith("%")) {
          const weight = parseFloat(column.width) / 100
          width = Math.floor(availableForPercent * weight)
          width = Math.max(column.minWidth || 3, Math.min(width, column.maxWidth || Infinity))
        } else {
          width = 3
        }

        this._columnLayouts.push({
          index: i,
          id: column.id,
          x: currentX,
          width: width,
          visibleWidth: width,
        })

        currentX += width
        this._contentWidth += width
      }
    } else {
      let currentX = 0
      for (let i = 0; i < this._columns.length; i++) {
        const column = this._columns[i]
        const width = typeof column.width === "number" ? Math.max(column.minWidth || 3, column.width) : 10

        this._columnLayouts.push({
          index: i,
          id: column.id,
          x: currentX,
          width: width,
          visibleWidth: width,
        })

        currentX += width
        this._contentWidth += width
      }
    }

    this._totalWidth = this._contentWidth
  }

  getColumnPosition(columnIndex: number): ColumnLayout | null {
    if (columnIndex < 0 || columnIndex >= this._columnLayouts.length) return null
    return this._columnLayouts[columnIndex]
  }

  getColumnById(columnId: string): ColumnLayout | null {
    return this._columnLayouts.find((c) => c.id === columnId) || null
  }

  getCellPosition(
    rowIndex: number,
    columnIndex: number,
  ): { x: number; y: number; width: number; height: number } | null {
    const column = this.getColumnPosition(columnIndex)
    if (!column) return null

    return {
      x: column.x,
      y: this._headerHeight + rowIndex * this._rowHeight,
      width: column.width,
      height: this._rowHeight,
    }
  }

  getVisibleRowRange(viewportHeight: number, scrollY: number): [start: number, end: number] {
    const contentHeight = this._headerHeight + this._rowHeight
    const availableHeight = viewportHeight - this._headerHeight

    const startRow = Math.floor(scrollY / this._rowHeight)
    const visibleRows = Math.ceil(availableHeight / this._rowHeight) + 1
    const endRow = Math.min(startRow + visibleRows, Infinity)

    return [startRow, endRow]
  }

  getVisibleColumnRange(viewportWidth: number, scrollX: number): [start: number, end: number] {
    let accumulatedWidth = 0
    let startCol = 0
    let endCol = this._columnLayouts.length

    for (let i = 0; i < this._columnLayouts.length; i++) {
      const col = this._columnLayouts[i]
      const colEnd = col.x + col.width

      if (colEnd <= scrollX) {
        startCol = i + 1
      }
      if (col.x < scrollX + viewportWidth) {
        endCol = i + 1
      }
    }

    return [startCol, endCol]
  }

  getRowY(rowIndex: number): number {
    return this._headerHeight + rowIndex * this._rowHeight
  }

  getTotalHeight(rowCount: number): number {
    return this._headerHeight + rowCount * this._rowHeight
  }

  calculateContentHeight(rowCount: number): number {
    return rowCount * this._rowHeight
  }

  getColumnCount(): number {
    return this._columns.length
  }
}

export const TableFormatters = {
  date(value: Date | string, format: "short" | "long" = "short"): string {
    if (value === null || value === undefined) return "-"

    const date = typeof value === "string" ? new Date(value) : value

    if (isNaN(date.getTime())) return String(value)

    if (format === "short") {
      return date.toLocaleDateString("en-US", {
        year: "numeric",
        month: "short",
        day: "numeric",
      })
    }

    return date.toLocaleString("en-US", {
      year: "numeric",
      month: "short",
      day: "numeric",
      hour: "2-digit",
      minute: "2-digit",
    })
  },

  time(value: Date | string | number, format: "short" | "long" = "short"): string {
    if (value === null || value === undefined) return "-"

    let date: Date

    if (typeof value === "number") {
      date = new Date(value)
    } else if (typeof value === "string") {
      date = new Date(value)
    } else {
      date = value
    }

    if (isNaN(date.getTime())) return String(value)

    if (format === "short") {
      return date.toLocaleTimeString("en-US", {
        hour: "2-digit",
        minute: "2-digit",
      })
    }

    return date.toLocaleTimeString("en-US", {
      hour: "2-digit",
      minute: "2-digit",
      second: "2-digit",
    })
  },

  number(value: number | null | undefined, options?: Intl.NumberFormatOptions): string {
    if (value === null || value === undefined) return "-"
    return new Intl.NumberFormat("en-US", options).format(value)
  },

  currency(value: number | null | undefined, currency: string = "USD"): string {
    if (value === null || value === undefined) return "-"
    return new Intl.NumberFormat("en-US", {
      style: "currency",
      currency,
    }).format(value)
  },

  percent(value: number | null | undefined, decimals: number = 0): string {
    if (value === null || value === undefined) return "-"
    return `${value.toFixed(decimals)}%`
  },

  boolean(value: boolean | null | undefined, trueText: string = "✓", falseText: string = " "): string {
    if (value === null || value === undefined) return "-"
    return value ? trueText : falseText
  },

  yesno(value: boolean | null | undefined): string {
    if (value === null || value === undefined) return "-"
    return value ? "Yes" : "No"
  },

  onoff(value: boolean | null | undefined): string {
    if (value === null || value === undefined) return "-"
    return value ? "On" : "Off"
  },

  truncate(value: any, maxLength: number, ellipsis: string = "…"): string {
    if (value === null || value === undefined) return "-"
    const str = String(value)
    if (str.length <= maxLength) return str
    return str.slice(0, maxLength - 1) + ellipsis
  },

  null(value: any, placeholder: string = "-"): string {
    return value === null || value === undefined ? placeholder : String(value)
  },

  default(value: any, defaultValue: string = "-"): string {
    return value === null || value === undefined || value === "" ? defaultValue : String(value)
  },

  upper(value: any): string {
    return value === null || value === undefined ? "-" : String(value).toUpperCase()
  },

  lower(value: any): string {
    return value === null || value === undefined ? "-" : String(value).toLowerCase()
  },

  title(value: any): string {
    if (value === null || value === undefined) return "-"
    return String(value)
      .split(" ")
      .map((word) => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase())
      .join(" ")
  },

  bytes(value: number | null | undefined): string {
    if (value === null || value === undefined) return "-"

    const units = ["B", "KB", "MB", "GB", "TB"]
    let unitIndex = 0
    let size = value

    while (size >= 1024 && unitIndex < units.length - 1) {
      size /= 1024
      unitIndex++
    }

    return `${size.toFixed(unitIndex > 0 ? 1 : 0)} ${units[unitIndex]}`
  },

  duration(value: number | null | undefined): string {
    if (value === null || value === undefined) return "-"

    const seconds = Math.floor(value / 1000)
    const minutes = Math.floor(seconds / 60)
    const hours = Math.floor(minutes / 60)
    const days = Math.floor(hours / 24)

    if (days > 0) return `${days}d ${hours % 24}h`
    if (hours > 0) return `${hours}h ${minutes % 60}m`
    if (minutes > 0) return `${minutes}m ${seconds % 60}s`
    return `${seconds}s`
  },

  relativeTime(value: Date | string | number): string {
    if (value === null || value === undefined) return "-"

    const date = typeof value === "number" ? new Date(value) : new Date(value)
    const now = new Date()
    const diffMs = now.getTime() - date.getTime()
    const diffSec = Math.floor(diffMs / 1000)
    const diffMin = Math.floor(diffSec / 60)
    const diffHour = Math.floor(diffMin / 60)
    const diffDay = Math.floor(diffHour / 24)

    if (diffSec < 0) return "future"
    if (diffSec < 60) return "just now"
    if (diffMin < 60) return `${diffMin}m ago`
    if (diffHour < 24) return `${diffHour}h ago`
    if (diffDay < 7) return `${diffDay}d ago`
    if (diffDay < 30) return `${Math.floor(diffDay / 7)}w ago`

    return date.toLocaleDateString()
  },

  json(value: any, indent: number = 2): string {
    if (value === null || value === undefined) return "-"
    if (typeof value === "string") {
      try {
        value = JSON.parse(value)
      } catch {
        return value
      }
    }
    return JSON.stringify(value, null, indent)
  },

  array(value: any[] | null | undefined, separator: string = ", "): string {
    if (value === null || value === undefined) return "-"
    if (!Array.isArray(value)) return String(value)
    return value.map(String).join(separator)
  },

  enum<T extends string>(value: T | null | undefined, mapping: Record<T, string>): string {
    if (value === null || value === undefined) return "-"
    return mapping[value] || String(value)
  },
}

import { createMemo } from "solid-js"
import { createStore } from "solid-js/store"
import type { DBEditRequest } from "../db/types"

export type DBEditStage = "preview" | "edit" | "reject"

export interface UseDBEditOptions {
  request: DBEditRequest
  onAccept: (modified?: DBEditRequest) => void
  onReject: (message?: string) => void
  onModify: (modified: DBEditRequest) => void
}

export function useDBEdit(options: UseDBEditOptions) {
  const [state, setState] = createStore<{
    current: DBEditStage
    modifiedRequest: DBEditRequest | null
    rejectMessage: string
  }>({
    current: "preview",
    modifiedRequest: null,
    rejectMessage: "",
  })

  const request = createMemo(() => options.request)

  const preview = createMemo(() => request().preview)

  const changes = createMemo(() => request().changes)

  const schema = createMemo(() => request().schema)

  const sql = createMemo(() => request().sql ?? "")

  const canEdit = createMemo(() => request().type === "db_create")

  const accept = () => {
    options.onAccept(state.modifiedRequest ?? undefined)
  }

  const reject = (message?: string) => {
    setState({ current: "reject" })
    if (message) {
      setState({ rejectMessage: message })
      options.onReject(message)
    } else {
      options.onReject()
    }
  }

  const modify = (modified: DBEditRequest) => {
    setState({ modifiedRequest: modified, current: "edit" })
    options.onModify(modified)
  }

  const backToPreview = () => {
    setState({ current: "preview" })
  }

  return {
    state,
    request,
    preview,
    changes,
    schema,
    sql,
    canEdit,
    accept,
    reject,
    modify,
    backToPreview,
    setRejectMessage: (msg: string) => setState({ rejectMessage: msg }),
  }
}

import { BoxRenderable, type BoxOptions, type RenderContext, OptimizedBuffer, RGBA } from "@opentui/core"
import { TableEvents, type TableEventMap } from "./table-events"
import { TableSelectionManager } from "./table-selection-manager"
import { TableLayoutEngine } from "./table-layout-engine"
import { TableStateManager } from "./table-state"
import type { TableColumn, TableRow, TableStyle } from "./types"

export interface TableRenderableOptions extends BoxOptions {
  columns: TableColumn[]
  rows: TableRow[]
  selection?: "none" | "single" | "multiple"
  showHeader?: boolean
  showRowNumbers?: boolean
  striped?: boolean
  compact?: boolean
  style?: TableStyle
  onRowSelect?: (row: TableRow, index: number) => void
  onRowActivate?: (row: TableRow, index: number) => void
  onSort?: (column: TableColumn, direction: "asc" | "desc") => void
}

export class TableRenderable extends BoxRenderable {
  private _columns: TableColumn[]
  private _rows: TableRow[]
  private _selectionMode: "none" | "single" | "multiple"
  private _showHeader: boolean
  private _showRowNumbers: boolean
  private _striped: boolean
  private _compact: boolean
  private _style: TableStyle

  private _selectionManager: TableSelectionManager
  private _layoutEngine: TableLayoutEngine
  private _state: TableStateManager

  private _scrollY: number = 0
  private _scrollX: number = 0
  private _hasFocus: boolean = false

  private _onRowSelect?: (row: TableRow, index: number) => void
  private _onRowActivate?: (row: TableRow, index: number) => void
  private _onSort?: (column: TableColumn, direction: "asc" | "desc") => void

  private _tableEventListeners: Map<keyof TableEventMap, Set<(...args: any[]) => void>> = new Map()

  constructor(ctx: RenderContext, options: TableRenderableOptions) {
    super(ctx, {
      border: true,
      overflow: "hidden",
      ...options,
    })

    this._columns = options.columns
    this._rows = options.rows
    this._selectionMode = options.selection || "single"
    this._showHeader = options.showHeader !== false
    this._showRowNumbers = options.showRowNumbers || false
    this._striped = options.striped !== false
    this._compact = options.compact || false
    this._style = options.style || {}

    this._onRowSelect = options.onRowSelect
    this._onRowActivate = options.onRowActivate
    this._onSort = options.onSort

    const rowHeight = this._compact ? 1 : 1
    const headerHeight = this._showHeader ? 1 : 0

    this._selectionManager = new TableSelectionManager(this, this._selectionMode, (indices) => {
      if (indices.length === 1) {
        const row = this.getRowAt(indices[0])
        if (row) {
          this._onRowSelect?.(row, indices[0])
          this._emitTableEvent(TableEvents.ROW_SELECTED, { row, index: indices[0] })
        }
      }
    })

    this._layoutEngine = new TableLayoutEngine(this._columns, rowHeight, headerHeight)
    this._layoutEngine.calculateColumnWidths(this.width)

    this._state = new TableStateManager()
    this._state.setData(this._rows)
  }

  get columns(): TableColumn[] {
    return this._columns
  }

  get rows(): TableRow[] {
    return this._state.getVisibleRows()
  }

  get totalRows(): number {
    return this._rows.length
  }

  get totalColumns(): number {
    return this._columns.length
  }

  get selectedRow(): number | null {
    return this._selectionManager.selectedIndices[0] ?? null
  }

  get selectedRows(): TableRow[] {
    return this._selectionManager.getSelectedRows()
  }

  get sortColumn(): string | null {
    return this._state.sortColumn
  }

  get sortDirection(): "asc" | "desc" {
    return this._state.sortDirection
  }

  setData(columns: TableColumn[], rows: TableRow[]): void {
    this._columns = columns
    this._rows = rows
    this._layoutEngine = new TableLayoutEngine(this._columns, this._compact ? 1 : 1, this._showHeader ? 1 : 0)
    this._layoutEngine.calculateColumnWidths(this.width)
    this._state.setData(rows)
    this.requestRender()
  }

  setSelectedRow(index: number | null): void {
    this._selectionManager.setSelectedIndex(index)
    this.requestRender()
  }

  sortBy(columnId: string, direction?: "asc" | "desc"): void {
    this._state.setSort(columnId, direction)
    const column = this._columns.find((c) => c.id === columnId)
    if (column) {
      this._onSort?.(column, this._state.sortDirection)
      this._emitTableEvent(TableEvents.COLUMN_SORTED, { column, direction: this._state.sortDirection })
    }
    this.requestRender()
  }

  filter(query: string): void {
    this._state.setFilter(query)
    this._emitTableEvent(TableEvents.FILTER_CHANGED, {
      query,
      filteredCount: this._state.getFilteredRows(),
      totalCount: this._state.getTotalRows(),
    })
    this.requestRender()
  }

  setPage(page: number): void {
    this._state.setPage(page)
    this._emitTableEvent(TableEvents.PAGINATION_CHANGED, this._state.getPaginationState())
    this.requestRender()
  }

  nextPage(): boolean {
    const result = this._state.nextPage()
    if (result) {
      this._emitTableEvent(TableEvents.PAGINATION_CHANGED, this._state.getPaginationState())
      this.requestRender()
    }
    return result
  }

  prevPage(): boolean {
    const result = this._state.prevPage()
    if (result) {
      this._emitTableEvent(TableEvents.PAGINATION_CHANGED, this._state.getPaginationState())
      this.requestRender()
    }
    return result
  }

  scrollToRow(rowIndex: number): void {
    const targetY = this._layoutEngine.getRowY(rowIndex)
    const viewportHeight = this.height - this._layoutEngine.headerHeight

    if (targetY < this._scrollY) {
      this._scrollY = targetY
    } else if (targetY + this._layoutEngine.rowHeight > this._scrollY + viewportHeight) {
      this._scrollY = targetY - viewportHeight + this._layoutEngine.rowHeight
    }

    this.requestRender()
  }

  scrollToColumn(columnIndex: number): void {
    const column = this._layoutEngine.getColumnPosition(columnIndex)
    if (!column) return

    const viewportWidth = this.width

    if (column.x < this._scrollX) {
      this._scrollX = column.x
    } else if (column.x + column.width > this._scrollX + viewportWidth) {
      this._scrollX = column.x - viewportWidth + column.width
    }

  this.requestRender()
}

getRowAt(index: number): TableRow | null {
  const visibleRows = this._state.getVisibleRows()
  if (index < 0 || index >= visibleRows.length) return null
  return visibleRows[index]
}

getColumnAt(index: number): TableColumn | null {
  if (index < 0 || index >= this._columns.length) return null
  return this._columns[index]
}

getVisibleRowCount(): number {
  return this._state.getVisibleRows().length
}

getColumnCount(): number {
  return this._columns.length
}

hasFocus(): boolean {
  return this._hasFocus
}

private _emitTableEvent<EventType extends keyof TableEventMap>(
  event: EventType,
  data: TableEventMap[EventType],
): void {
  this._tableEventListeners.get(event)?.forEach((handler) => handler(data))
}

protected override renderSelf(buffer: OptimizedBuffer): void {
  super.renderSelf(buffer)

  const theme = this._getThemeColors()
  const visibleRows = this._state.getVisibleRows()
  const visibleRange = this._layoutEngine.getVisibleRowRange(this.height, this._scrollY)
  const visibleColumnRange = this._layoutEngine.getVisibleColumnRange(this.width, this._scrollX)

  const startRow = Math.max(0, visibleRange[0])
  const endRow = Math.min(visibleRows.length, visibleRange[1])
  const startCol = visibleColumnRange[0]
  const endCol = visibleColumnRange[1]

  if (this._showHeader) {
    this._renderHeader(buffer, theme, startCol, endCol)
  }

  for (let rowIdx = startRow; rowIdx < endRow; rowIdx++) {
    const row = visibleRows[rowIdx]
    if (!row) continue

    const globalRowIndex = this._rows.indexOf(row)
    const isSelected = this._selectionManager.isSelected(globalRowIndex)
    const isFocused = this._selectionManager.isFocused(globalRowIndex)
    const isEven = globalRowIndex % 2 === 0

    this._renderRow(
      buffer,
      row,
      globalRowIndex,
      rowIdx - startRow,
      isSelected,
      isFocused,
      isEven,
      theme,
      startCol,
      endCol,
    )
  }

  if (this._hasFocus) {
    this._renderFocusIndicator(buffer, theme)
  }

  this._renderScrollbar(buffer, theme, visibleRows.length, startRow, endRow)
}

private _renderHeader(buffer: OptimizedBuffer, theme: any, startCol: number, endCol: number): void {
  const headerY = this.y
  const headerBg = this._parseColor(this._style.headerBg, theme.backgroundElement)
  const headerFg = this._parseColor(this._style.headerFg, theme.text)

  for (let colIdx = startCol; colIdx < endCol; colIdx++) {
    const column = this._columns[colIdx]
    const layout = this._layoutEngine.getColumnPosition(colIdx)
    if (!layout) continue

    const cellX = this.x + layout.x - this._scrollX
    const cellWidth = Math.min(layout.width, this.width - layout.x + this._scrollX)

    const isSorted = this._state.sortColumn === column.id
    const sortIndicator = isSorted ? (this._state.sortDirection === "asc" ? " ▲" : " ▼") : ""

    const title = column.title + sortIndicator
    const truncatedTitle = title.length > cellWidth - 1 ? title.slice(0, cellWidth - 2) + "…" : title

    if (headerBg) {
      buffer.fillRect(cellX, headerY, cellWidth, 1, headerBg)
    }

    const align = column.align || "left"
    const textX = this._calculateTextX(truncatedTitle, cellX, cellWidth, align)

    if (headerFg) {
      buffer.drawText(truncatedTitle, textX, headerY, headerFg)
    }
  }
}

private _renderRow(
  buffer: OptimizedBuffer,
  row: TableRow,
  globalIndex: number,
  displayIndex: number,
  isSelected: boolean,
  isFocused: boolean,
  isEven: boolean,
  theme: any,
  startCol: number,
  endCol: number,
): void {
  const rowY = this.y + this._layoutEngine.headerHeight + displayIndex * this._layoutEngine.rowHeight

  let rowBg: RGBA | undefined
  let rowFg: RGBA | undefined

  if (isSelected) {
    rowBg = this._parseColor(this._style.selectedBg, theme.primary)
    rowFg = this._parseColor(this._style.selectedFg, "#ffffff")
  } else if (isFocused) {
    rowBg = this._parseColor(this._style.selectedBg, theme.backgroundElement)
    rowFg = this._parseColor(this._style.selectedFg, theme.text)
  } else {
    rowBg = this._parseColor(
      this._striped && !isEven ? this._style.rowOddBg : this._style.rowEvenBg,
      isEven ? undefined : theme.backgroundElement,
    )
    rowFg = this._parseColor(undefined, theme.text)
  }

  if (rowBg) {
    for (let colIdx = startCol; colIdx < endCol; colIdx++) {
      const layout = this._layoutEngine.getColumnPosition(colIdx)
      if (!layout) continue

      const cellX = this.x + layout.x - this._scrollX
      const cellWidth = Math.min(layout.width, this.width - layout.x + this._scrollX)

      buffer.fillRect(cellX, rowY, cellWidth, this._layoutEngine.rowHeight, rowBg)
    }
  }

  for (let colIdx = startCol; colIdx < endCol; colIdx++) {
    const column = this._columns[colIdx]
    const layout = this._layoutEngine.getColumnPosition(colIdx)
    if (!layout) continue

    const cellX = this.x + layout.x - this._scrollX
    const cellWidth = Math.min(layout.width, this.width - layout.x + this._scrollX)

    let value = row[column.id]
    if (column.formatter) {
      value = column.formatter(value)
    }
    const cellText = String(value ?? "")
    const truncatedText = cellText.length > cellWidth - 1 ? cellText.slice(0, cellWidth - 2) + "…" : cellText

    const align = column.align || "left"
    const textX = this._calculateTextX(truncatedText, cellX, cellWidth, align)

    if (rowFg) {
      buffer.drawText(truncatedText, textX, rowY, rowFg)
    }
  }

  if (this._showRowNumbers) {
    const numX = this.x + 1 - this._scrollX
    const numFg = this._parseColor(undefined, theme.textMuted)
    if (numFg) {
      buffer.drawText(String(globalIndex + 1).padStart(3), numX, rowY, numFg)
    }
  }
}

private _renderFocusIndicator(buffer: OptimizedBuffer, theme: any): void {
  const focusedIndex = this._selectionManager.focusedIndex
  if (focusedIndex < 0) return

  const visibleRows = this._state.getVisibleRows()
  if (focusedIndex >= visibleRows.length) return

  const rowY = this.y + this._layoutEngine.headerHeight + focusedIndex * this._layoutEngine.rowHeight
  const focusBg = this._parseColor(undefined, theme.borderActive)

  if (focusBg) {
    for (let colIdx = 0; colIdx < this._columns.length; colIdx++) {
      const layout = this._layoutEngine.getColumnPosition(colIdx)

        if (!layout) continue

        const cellX = this.x + layout.x - this._scrollX
        const cellWidth = Math.min(layout.width, this.width - layout.x + this._scrollX)

        buffer.fillRect(cellX, rowY, cellWidth, this._layoutEngine.rowHeight, focusBg)
      }
    }
  }

  private _renderScrollbar(
    buffer: OptimizedBuffer,
    theme: any,
    totalRows: number,
    startRow: number,
    endRow: number,
  ): void {
    if (totalRows <= 0) return

    const scrollbarX = this.x + this.width - 1
    const scrollbarHeight = this.height - 2
    const trackBg = this._parseColor(undefined, theme.backgroundElement)
    const thumbBg = this._parseColor(undefined, theme.textMuted)

    const thumbHeight = Math.max(1, Math.floor(((endRow - startRow) / totalRows) * scrollbarHeight))
    const thumbY = this.y + 1 + Math.floor((startRow / totalRows) * scrollbarHeight)

    if (trackBg) {
      buffer.fillRect(scrollbarX, this.y + 1, 1, scrollbarHeight, trackBg)
    }

    if (thumbBg) {
      buffer.fillRect(scrollbarX, thumbY, 1, thumbHeight, thumbBg)
    }
  }

  private _calculateTextX(text: string, cellX: number, cellWidth: number, align: string): number {
    const textLength = text.length
    const padding = 1

    switch (align) {
      case "right":
        return cellX + cellWidth - textLength - padding
      case "center":
        return cellX + Math.floor((cellWidth - textLength) / 2)
      default:
        return cellX + padding
    }
  }

  private _parseColor(color: string | RGBA | undefined, fallback: string): RGBA | undefined {
    if (!color) {
      return RGBA.fromHex(fallback) || undefined
    }
    if (color instanceof RGBA) {
      return color
    }
    return RGBA.fromHex(color) || RGBA.fromHex(fallback) || undefined
  }

  private _getThemeColors(): any {
    return {
      background: "#1a1b26",
      backgroundElement: "#1f2335",
      backgroundPanel: "#24283b",
      text: "#c0caf5",
      textMuted: "#565f89",
      primary: "#7aa2f7",
      success: "#9ece6a",
      warning: "#e0af68",
      error: "#f7768e",
      border: "#414868",
      borderActive: "#7aa2f7",
    }
  }
}

import type { TableRow, SortDirection } from "./types"

export class TableStateManager {
  private _sortColumn: string | null = null
  private _sortDirection: SortDirection = "asc"
  private _filterQuery: string = ""
  private _page: number = 1
  private _pageSize: number = 50
  private _originalData: TableRow[] = []

  get sortColumn(): string | null {
    return this._sortColumn
  }

  get sortDirection(): SortDirection {
    return this._sortDirection
  }

  get filterQuery(): string {
    return this._filterQuery
  }

  get page(): number {
    return this._page
  }

  get pageSize(): number {
    return this._pageSize
  }

  get isSorted(): boolean {
    return this._sortColumn !== null
  }

  get isFiltered(): boolean {
    return this._filterQuery.length > 0
  }

  get isPaginated(): boolean {
    return this._pageSize > 0
  }

  setData(data: TableRow[]): void {
    this._originalData = data
  }

  setSort(columnId: string, direction?: SortDirection): void {
    if (this._sortColumn === columnId) {
      this._sortDirection = this._sortDirection === "asc" ? "desc" : "asc"
    } else {
      this._sortColumn = columnId
      this._sortDirection = direction || "asc"
    }
  }

  clearSort(): void {
    this._sortColumn = null
    this._sortDirection = "asc"
  }

  setFilter(query: string): void {
    this._filterQuery = query
    this._page = 1
  }

  clearFilter(): void {
    this._filterQuery = ""
    this._page = 1
  }

  setPage(page: number): void {
    this._page = Math.max(1, page)
  }

  setPageSize(size: number): void {
    this._pageSize = Math.max(1, size)
    this._page = 1
  }

  nextPage(): boolean {
    const maxPage = this.getTotalPages()
    if (this._page < maxPage) {
      this._page++
      return true
    }
    return false
  }

  prevPage(): boolean {
    if (this._page > 1) {
      this._page--
      return true
    }
    return false
  }

  firstPage(): void {
    this._page = 1
  }

  lastPage(): void {
    this._page = this.getTotalPages()
  }

  getTotalPages(): number {
    const filtered = this._applyFilter(this._originalData)
    if (!this.isPaginated) return 1
    return Math.ceil(filtered.length / this._pageSize)
  }

  getTotalRows(): number {
    return this._originalData.length
  }

  getFilteredRows(): number {
    return this._applyFilter(this._originalData).length
  }

  getVisibleRows(): TableRow[] {
    let result = this._originalData

    result = this._applyFilter(result)
    result = this._applySort(result)

    if (this.isPaginated) {
      const start = (this._page - 1) * this._pageSize
      const end = start + this._pageSize
      result = result.slice(start, end)
    }

    return result
  }

  getAllRows(): TableRow[] {
    let result = this._originalData
    result = this._applyFilter(result)
    result = this._applySort(result)
    return result
  }

  private _applyFilter(rows: TableRow[]): TableRow[] {
    if (!this._filterQuery) return rows

    const query = this._filterQuery.toLowerCase()
    return rows.filter((row) => {
      const values = Object.values(row).map((v) => String(v).toLowerCase())
      return values.some((v) => v.includes(query))
    })
  }

  private _applySort(rows: TableRow[]): TableRow[] {
    if (!this._sortColumn) return rows

    return [...rows].sort((a, b) => {
      const aVal = a[this._sortColumn!]
      const bVal = b[this._sortColumn!]

      let comparison = 0

      if (aVal === null || aVal === undefined) {
        comparison = -1
      } else if (bVal === null || bVal === undefined) {
        comparison = 1
      } else if (typeof aVal === "number" && typeof bVal === "number") {
        comparison = aVal - bVal
      } else {
        const aStr = String(aVal).toLowerCase()
        const bStr = String(bVal).toLowerCase()
        comparison = aStr.localeCompare(bStr)
      }

      return this._sortDirection === "asc" ? comparison : -comparison
    })
  }

  getSortState(): { column: string | null; direction: SortDirection } {
    return {
      column: this._sortColumn,
      direction: this._sortDirection,
    }
  }

  getPaginationState(): { page: number; pageSize: number; totalPages: number; totalRows: number } {
    return {
      page: this._page,
      pageSize: this._pageSize,
      totalPages: this.getTotalPages(),
      totalRows: this._originalData.length,
    }
  }

  reset(): void {
    this._sortColumn = null
    this._sortDirection = "asc"
    this._filterQuery = ""
    this._page = 1
  }
}

